        defer list.deinit(self.alloc);
        try list.appendSlice(self.alloc, graph_metric_key_prefix);
        for (parts) |part| try internal_keys.appendEncodedComponent(&list, self.alloc, part);
        return try list.toOwnedSlice(self.alloc);
    }

