    fn cloneGraphMetricBuildJobAlloc(self: *GraphIndex, job: GraphMetricBuildJob) !GraphMetricBuildJob {
        var cloned = job;
        cloned.worker_id = try self.alloc.dupe(u8, job.worker_id);
        errdefer self.alloc.free(cloned.worker_id);
        cloned.last_error = try self.alloc.dupe(u8, job.last_error);
        errdefer self.alloc.free(cloned.last_error);
        cloned.cursor = try self.alloc.dupe(u8, job.cursor);
        return cloned;
    }

