    pub fn graphMetricBuildPageSnapshotForTest(
        self: *GraphIndex,
        metric_name: []const u8,
        job_id: u64,
        phase: GraphMetricBuildPhase,
        iteration: u32,
        page_id: u64,
    ) !?GraphMetricBuildPageSnapshotForTest {
        var txn = try self.beginReadReverseTxn();
        defer txn.abort();
        const page = try self.metricBuildPage(&txn, metric_name, job_id, phase, iteration, page_id) orelse return null;
        return .{
            .state = page.state,
            .worker_id_hash = std.hash.Wyhash.hash(0, page.worker_id),
            .attempt = page.attempt,
            .completed_units = page.completed_units,
            .total_units = page.total_units,
            .output_fingerprint = page.output_fingerprint,
        };
    }

