    fn acquireGraphMetricBuildLease(
        self: *GraphIndex,
        metric_name: []const u8,
        target_generation: u64,
    ) !void {
        const now_ms = @divTrunc(platform_time.realtimeNs(), std.time.ns_per_ms);
        var batch = try self.beginWriteReverseBatch();
        errdefer batch.abort();

        const key = try self.graphMetricBuildLeaseKeyAlloc(metric_name);
        defer self.alloc.free(key);
        if (batch.get(key)) |raw| {
            if (decodeGraphMetricBuildLease(raw)) |lease| {
                if (lease.lease_expires_at_ms > now_ms) return error.GraphMetricBuildAlreadyRunning;
            }
        } else |err| switch (err) {
            error.NotFound => {},
            else => return err,
        }

        const lease = GraphMetricBuildLease{
            .job_id = graphMetricBuildJobId(metric_name, target_generation, now_ms),
            .target_generation = target_generation,
            .started_at_ms = now_ms,
            .lease_expires_at_ms = now_ms + graph_metric_local_build_lease_ms,
            .phase = .prepare_generation,
            .iteration = 0,
            .worker_id = graph_metric_local_build_worker_id,
        };
        const encoded = try self.alloc.alloc(u8, graphMetricBuildLeaseEncodedLen(lease));
        defer self.alloc.free(encoded);
        encodeGraphMetricBuildLease(lease, encoded);
        try batch.put(key, encoded);
        try self.putGraphMetricBuildJobInBatch(&batch, metric_name, .{
            .job_id = lease.job_id,
            .target_generation = target_generation,
            .score_generation = target_generation,
            .started_at_ms = lease.started_at_ms,
            .updated_at_ms = now_ms,
            .lease_expires_at_ms = lease.lease_expires_at_ms,
            .phase = lease.phase,
            .iteration = lease.iteration,
            .worker_id = lease.worker_id,
        });
        const cfg = self.metricConfig(metric_name) orelse return error.MetricNotReady;
        try self.planGraphMetricBuildManifestInBatch(&batch, metric_name, cfg, .{
            .job_id = lease.job_id,
            .target_generation = target_generation,
            .score_generation = target_generation,
            .started_at_ms = lease.started_at_ms,
            .updated_at_ms = now_ms,
            .lease_expires_at_ms = lease.lease_expires_at_ms,
            .phase = lease.phase,
            .iteration = lease.iteration,
            .worker_id = lease.worker_id,
        });
        try batch.commit();
    }

    fn ensureGraphMetricBuildManifestForJob(
        self: *GraphIndex,
        metric_name: []const u8,
        job: GraphMetricBuildJob,
    ) !void {
        const cfg = self.metricConfig(metric_name) orelse return error.MetricNotReady;
        var batch = try self.beginWriteReverseBatch();
        errdefer batch.abort();
        try self.planGraphMetricBuildManifestInBatch(&batch, metric_name, cfg, job);
        try batch.commit();
    }

    fn planGraphMetricBuildManifestInBatch(
        self: *GraphIndex,
        batch: anytype,
        metric_name: []const u8,
        cfg: GraphMetricConfig,
        job: GraphMetricBuildJob,
    ) !void {
        const phases = graphMetricBuildManifestPhases(cfg.kind);
        var degree_scan_keys = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (degree_scan_keys.items) |key| self.alloc.free(key);
            degree_scan_keys.deinit(self.alloc);
        }
        var degree_node_keys = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (degree_node_keys.items) |key| self.alloc.free(key);
            degree_node_keys.deinit(self.alloc);
        }
        if (cfg.kind == .degree or graphMetricKindUsesIterativeBuild(cfg.kind)) {
            try self.collectReverseEdgeKeysForIndexInBatch(batch, &degree_scan_keys);
            try self.collectGraphNodeKeysInBatch(batch, &degree_node_keys);
        }
        const degree_scan_page_count = if (cfg.kind == .degree or graphMetricKindUsesIterativeBuild(cfg.kind))
            graphMetricDegreeScanPageCount(degree_scan_keys.items.len)
        else
            0;
        const degree_reduce_page_count = if (cfg.kind == .degree or graphMetricKindUsesIterativeBuild(cfg.kind))
            graphMetricDegreeReducePageCount(degree_node_keys.items.len)
        else
            0;
        const cleanup_page_count = graphMetricBuildCleanupPageCount(cfg.kind);
        var planned_page_count: usize = 0;
        for (phases) |phase| {
            planned_page_count += graphMetricBuildPlannedPageCountForPhase(cfg.kind, phase, degree_scan_page_count, degree_reduce_page_count, cleanup_page_count);
        }
        const manifest = GraphMetricBuildManifest{
            .job_id = job.job_id,
            .target_generation = job.target_generation,
            .score_generation = job.score_generation,
            .config_fingerprint = graphMetricConfigFingerprint(cfg),
            .planned_at_ms = if (job.started_at_ms != 0) job.started_at_ms else @divTrunc(platform_time.realtimeNs(), std.time.ns_per_ms),
            .edge_count = self.edge_count,
            .node_count = self.node_count,
            .phase_count = phases.len,
            .page_count = planned_page_count,
        };
        if (try self.metricBuildManifest(batch, metric_name, job.job_id)) |existing| {
            if (existing.target_generation != manifest.target_generation or
                existing.score_generation != manifest.score_generation or
                existing.config_fingerprint != manifest.config_fingerprint)
            {
                return error.InvalidGraphMetricBuildManifest;
            }
            if (existing.page_count != manifest.page_count) return;
        } else {
            try self.putGraphMetricBuildManifestInBatch(batch, metric_name, manifest);
        }
        for (phases, 0..) |phase, i| {
            if (cfg.kind == .degree and phase == .scan_edges_and_out_degree) {
                const output_prefix = try self.graphMetricBuildDegreePartialPrefixAlloc(metric_name, job.job_id);
                defer self.alloc.free(output_prefix);
                for (0..degree_scan_page_count) |scan_page_idx| {
                    const start = scan_page_idx * graph_metric_build_target_scan_page_units;
                    const end = @min(start + graph_metric_build_target_scan_page_units, degree_scan_keys.items.len);
                    const range_lower = if (start < degree_scan_keys.items.len) degree_scan_keys.items[start] else "";
                    const range_upper = if (end < degree_scan_keys.items.len) degree_scan_keys.items[end] else "";
                    const page_id: u64 = 1 + @as(u64, @intCast(scan_page_idx));
                    if (try self.metricBuildPage(batch, metric_name, job.job_id, phase, 0, page_id)) |_| continue;
                    try self.putGraphMetricBuildPageInBatch(batch, metric_name, .{
                        .job_id = job.job_id,
                        .phase = phase,
                        .iteration = 0,
                        .page_id = page_id,
                        .state = .pending,
                        .range_kind = .reverse_edges,
                        .range_lower = range_lower,
                        .range_upper = range_upper,
                        .output_prefix = output_prefix,
                        .worker_id = "",
                        .total_units = @intCast(end - start),
                    });
                }
                continue;
            }
            if (cfg.kind == .degree and phase == .reduce_ranks) {
                const output_prefix = try self.graphMetricScorePrefixAlloc(metric_name, job.score_generation);
                defer self.alloc.free(output_prefix);
                for (0..degree_reduce_page_count) |reduce_page_idx| {
                    const start = reduce_page_idx * graph_metric_build_target_reduce_page_units;
                    const end = @min(start + graph_metric_build_target_reduce_page_units, degree_node_keys.items.len);
                    const range_lower = if (start < degree_node_keys.items.len) degree_node_keys.items[start] else "";
                    const range_upper = if (end < degree_node_keys.items.len) degree_node_keys.items[end] else "";
                    const page_id: u64 = 2 + @as(u64, @intCast(reduce_page_idx));
                    if (try self.metricBuildPage(batch, metric_name, job.job_id, phase, 0, page_id)) |_| continue;
                    try self.putGraphMetricBuildPageInBatch(batch, metric_name, .{
                        .job_id = job.job_id,
                        .phase = phase,
                        .iteration = 0,
                        .page_id = page_id,
                        .state = .pending,
                        .range_kind = .nodes,
                        .range_lower = range_lower,
                        .range_upper = range_upper,
                        .output_prefix = output_prefix,
                        .worker_id = "",
                        .total_units = @intCast(end - start),
                    });
                }
                continue;
            }
            if (graphMetricKindUsesIterativeBuild(cfg.kind)) {
                const page_count = graphMetricBuildPlannedPageCountForPhase(cfg.kind, phase, degree_scan_page_count, degree_reduce_page_count, cleanup_page_count);
                const range_kind = graphMetricBuildManifestPhaseRangeKind(phase);
                if (range_kind == .reverse_edges or range_kind == .nodes) {
                    const keys = if (range_kind == .reverse_edges) degree_scan_keys.items else degree_node_keys.items;
                    const page_units = if (range_kind == .reverse_edges) graph_metric_build_target_scan_page_units else graph_metric_build_target_reduce_page_units;
                    const output_prefix = try self.graphMetricBuildJobNamespacePrefixAlloc(metric_name, job.job_id);
                    defer self.alloc.free(output_prefix);
                    for (0..page_count) |page_idx| {
                        const start = page_idx * page_units;
                        const end = @min(start + page_units, keys.len);
                        const range_lower = if (start < keys.len) keys[start] else "";
                        const range_upper = if (end < keys.len) keys[end] else "";
                        const page_id: u64 = @as(u64, @intCast(i)) + @as(u64, @intCast(page_idx));
                        if (try self.metricBuildPage(batch, metric_name, job.job_id, phase, 0, page_id)) |_| continue;
                        try self.putGraphMetricBuildPageInBatch(batch, metric_name, .{
                            .job_id = job.job_id,
                            .phase = phase,
                            .iteration = 0,
                            .page_id = page_id,
                            .state = .pending,
                            .range_kind = range_kind,
                            .range_lower = range_lower,
                            .range_upper = range_upper,
                            .output_prefix = output_prefix,
                            .worker_id = "",
                            .total_units = @intCast(end - start),
                        });
                    }
                    continue;
                }
            }
            if (cfg.kind == .degree and phase == .cleanup_old_generations) {
                const degree_partial_prefix = try self.graphMetricBuildDegreePartialPrefixAlloc(metric_name, job.job_id);
                defer self.alloc.free(degree_partial_prefix);
                const job_namespace_prefix = try self.graphMetricBuildJobNamespacePrefixAlloc(metric_name, job.job_id);
                defer self.alloc.free(job_namespace_prefix);
                const cleanup_prefixes = [_][]const u8{
                    degree_partial_prefix,
                    job_namespace_prefix,
                };
                for (cleanup_prefixes, 0..) |output_prefix, cleanup_page_idx| {
                    const page_id: u64 = @intCast(cleanup_page_idx);
                    if (try self.metricBuildPage(batch, metric_name, job.job_id, phase, 0, page_id)) |_| continue;
                    try self.putGraphMetricBuildPageInBatch(batch, metric_name, .{
                        .job_id = job.job_id,
                        .phase = phase,
                        .iteration = 0,
                        .page_id = page_id,
                        .state = .pending,
                        .range_kind = .job_control,
                        .output_prefix = output_prefix,
                        .worker_id = "",
                        .total_units = 1,
                    });
                }
                continue;
            }
            if (cfg.kind == .pagerank and phase == .cleanup_old_generations) {
                const out_degree_partial_prefix = try self.graphMetricBuildPageRankOutDegreePartialPrefixAlloc(metric_name, job.job_id);
                defer self.alloc.free(out_degree_partial_prefix);
                const node_partial_prefix = try self.graphMetricBuildPageRankNodePartialPrefixAlloc(metric_name, job.job_id);
                defer self.alloc.free(node_partial_prefix);
                const job_namespace_prefix = try self.graphMetricBuildJobNamespacePrefixAlloc(metric_name, job.job_id);
                defer self.alloc.free(job_namespace_prefix);
                const cleanup_prefixes = [_][]const u8{
                    out_degree_partial_prefix,
                    node_partial_prefix,
                    job_namespace_prefix,
                };
                for (cleanup_prefixes, 0..) |output_prefix, cleanup_page_idx| {
                    const page_id: u64 = @intCast(cleanup_page_idx);
                    if (try self.metricBuildPage(batch, metric_name, job.job_id, phase, 0, page_id)) |_| continue;
                    try self.putGraphMetricBuildPageInBatch(batch, metric_name, .{
                        .job_id = job.job_id,
                        .phase = phase,
                        .iteration = 0,
                        .page_id = page_id,
                        .state = .pending,
                        .range_kind = .job_control,
                        .output_prefix = output_prefix,
                        .worker_id = "",
                        .total_units = 1,
                    });
                }
                continue;
            }
            if ((cfg.kind == .hits_authority or cfg.kind == .hits_hub) and phase == .cleanup_old_generations) {
                const hub_raw_prefix = try self.graphMetricBuildHitsHubRawNamespacePrefixAlloc(metric_name, job.job_id);
                defer self.alloc.free(hub_raw_prefix);
                const hub_raw_summary_prefix = try self.graphMetricBuildHitsHubRawSummaryNamespacePrefixAlloc(metric_name, job.job_id);
                defer self.alloc.free(hub_raw_summary_prefix);
                const hits_rank_prefix = try self.graphMetricBuildHitsRankNamespacePrefixAlloc(metric_name, job.job_id);
                defer self.alloc.free(hits_rank_prefix);
                const job_namespace_prefix = try self.graphMetricBuildJobNamespacePrefixAlloc(metric_name, job.job_id);
                defer self.alloc.free(job_namespace_prefix);
                const cleanup_prefixes = [_][]const u8{
                    hub_raw_prefix,
                    hub_raw_summary_prefix,
                    hits_rank_prefix,
                    job_namespace_prefix,
                };
                for (cleanup_prefixes, 0..) |output_prefix, cleanup_page_idx| {
                    const page_id: u64 = @intCast(cleanup_page_idx);
                    if (try self.metricBuildPage(batch, metric_name, job.job_id, phase, 0, page_id)) |_| continue;
                    try self.putGraphMetricBuildPageInBatch(batch, metric_name, .{
                        .job_id = job.job_id,
                        .phase = phase,
                        .iteration = 0,
                        .page_id = page_id,
                        .state = .pending,
                        .range_kind = .job_control,
                        .output_prefix = output_prefix,
                        .worker_id = "",
                        .total_units = 1,
                    });
                }
                continue;
            }
            const page_id: u64 = @intCast(i);
            if (try self.metricBuildPage(batch, metric_name, job.job_id, phase, 0, page_id)) |_| continue;
            const range_kind = graphMetricBuildManifestPhaseRangeKind(phase);
            const range_lower = if (range_kind == .reverse_edges) try self.firstReverseEdgeKeyForIndexInBatch(batch) else "";
            defer if (range_kind == .reverse_edges and range_lower.len > 0) self.alloc.free(range_lower);
            const output_prefix = if (cfg.kind == .degree and phase == .reduce_ranks)
                try self.graphMetricScorePrefixAlloc(metric_name, job.score_generation)
            else if (phase == .scan_edges_and_out_degree)
                try self.graphMetricScorePrefixAlloc(metric_name, job.score_generation)
            else
                "";
            defer if (output_prefix.len > 0) self.alloc.free(output_prefix);
            try self.putGraphMetricBuildPageInBatch(batch, metric_name, .{
                .job_id = job.job_id,
                .phase = phase,
                .iteration = 0,
                .page_id = page_id,
                .state = .pending,
                .range_kind = range_kind,
                .range_lower = range_lower,
                .range_upper = "",
                .output_prefix = output_prefix,
                .worker_id = "",
                .total_units = graphMetricBuildManifestPhaseUnits(phase, self.edge_count, self.node_count),
            });
        }
    }

    fn planGraphMetricIterationPagesInBatch(
        self: *GraphIndex,
        batch: anytype,
        metric_name: []const u8,
        kind: GraphMetricKind,
        job: GraphMetricBuildJob,
        iteration: u32,
    ) !void {
        var reverse_edge_keys = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (reverse_edge_keys.items) |key| self.alloc.free(key);
            reverse_edge_keys.deinit(self.alloc);
        }
        var node_keys = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (node_keys.items) |key| self.alloc.free(key);
            node_keys.deinit(self.alloc);
        }
        try self.collectReverseEdgeKeysForIndexInBatch(batch, &reverse_edge_keys);
        try self.collectGraphNodeKeysInBatch(batch, &node_keys);

        const reverse_page_count = graphMetricDegreeScanPageCount(reverse_edge_keys.items.len);
        const node_page_count = graphMetricDegreeReducePageCount(node_keys.items.len);
        const output_prefix = try self.graphMetricBuildJobNamespacePrefixAlloc(metric_name, job.job_id);
        defer self.alloc.free(output_prefix);
        const iterative_planned_phases = [_]GraphMetricBuildPhase{
            .iterate_contributions,
            .reduce_ranks,
            .check_convergence,
        };
        const hits_planned_phases = [_]GraphMetricBuildPhase{
            .iterate_contributions,
            .reduce_ranks,
            .hits_hub_contributions,
            .hits_hub_reduce_ranks,
            .check_convergence,
        };
        const planned_phases: []const GraphMetricBuildPhase = switch (kind) {
            .hits_authority, .hits_hub => hits_planned_phases[0..],
            else => iterative_planned_phases[0..],
        };
        var created_pages: usize = 0;
        for (planned_phases) |phase| {
            const range_kind = graphMetricBuildManifestPhaseRangeKind(phase);
            const keys = if (range_kind == .reverse_edges) reverse_edge_keys.items else node_keys.items;
            const page_units = if (range_kind == .reverse_edges) graph_metric_build_target_scan_page_units else graph_metric_build_target_reduce_page_units;
            const page_count = if (range_kind == .reverse_edges) reverse_page_count else node_page_count;
            const page_id_base = graphMetricBuildPhasePageIdBase(kind, phase);
            for (0..page_count) |page_idx| {
                const start = page_idx * page_units;
                const end = @min(start + page_units, keys.len);
                const range_lower = if (start < keys.len) keys[start] else "";
                const range_upper = if (end < keys.len) keys[end] else "";
                const page_id = page_id_base + @as(u64, @intCast(page_idx));
                if (try self.metricBuildPage(batch, metric_name, job.job_id, phase, iteration, page_id)) |_| continue;
                try self.putGraphMetricBuildPageInBatch(batch, metric_name, .{
                    .job_id = job.job_id,
                    .phase = phase,
                    .iteration = iteration,
                    .page_id = page_id,
                    .state = .pending,
                    .range_kind = range_kind,
                    .range_lower = range_lower,
                    .range_upper = range_upper,
                    .output_prefix = output_prefix,
                    .worker_id = "",
                    .total_units = @intCast(end - start),
                });
                created_pages += 1;
            }
        }
        if (created_pages != 0) {
            var manifest = try self.metricBuildManifest(batch, metric_name, job.job_id) orelse return error.GraphMetricBuildManifestNotFound;
            manifest.page_count += created_pages;
            try self.putGraphMetricBuildManifestInBatch(batch, metric_name, manifest);
        }
    }

    fn planPageRankIterationPagesInBatch(
        self: *GraphIndex,
        batch: anytype,
        metric_name: []const u8,
        job: GraphMetricBuildJob,
        iteration: u32,
    ) !void {
        try self.planGraphMetricIterationPagesInBatch(batch, metric_name, .pagerank, job, iteration);
    }

    fn graphMetricDegreeScanPageCount(edge_key_count: usize) usize {
        if (edge_key_count == 0) return 1;
        return std.math.divCeil(usize, edge_key_count, graph_metric_build_target_scan_page_units) catch 1;
    }

    fn graphMetricDegreeReducePageCount(node_key_count: usize) usize {
        if (node_key_count == 0) return 1;
        return std.math.divCeil(usize, node_key_count, graph_metric_build_target_reduce_page_units) catch 1;
    }

    pub fn graphMetricPlannedBuildControlRecordEstimate(self: *GraphIndex, cfg: GraphMetricConfig) usize {
        const edge_count = std.math.cast(usize, self.edge_count) orelse std.math.maxInt(usize);
        const node_count = std.math.cast(usize, self.node_count) orelse std.math.maxInt(usize);
        const reverse_edge_page_count = if (cfg.kind == .degree or graphMetricKindUsesIterativeBuild(cfg.kind))
            graphMetricDegreeScanPageCount(edge_count)
        else
            0;
        const node_page_count = if (cfg.kind == .degree or graphMetricKindUsesIterativeBuild(cfg.kind))
            graphMetricDegreeReducePageCount(node_count)
        else
            0;
        const cleanup_page_count = graphMetricBuildCleanupPageCount(cfg.kind);
        var planned_page_count: usize = 0;
        for (graphMetricBuildManifestPhases(cfg.kind)) |phase| {
            planned_page_count +|= graphMetricBuildPlannedPageCountForPhase(cfg.kind, phase, reverse_edge_page_count, node_page_count, cleanup_page_count);
        }
        return planned_page_count +| 1;
    }

    fn graphMetricKindUsesIterativeBuild(kind: GraphMetricKind) bool {
        return switch (kind) {
            .pagerank,
            .eigenvector,
            .hits_authority,
            .hits_hub,
            => true,
            .degree => false,
        };
    }

    fn graphMetricKindUsesPlannedIterativeRunner(kind: GraphMetricKind) bool {
        return switch (kind) {
            .pagerank,
            .eigenvector,
            .hits_authority,
            .hits_hub,
            => true,
            .degree,
            => false,
        };
    }

    fn graphMetricBuildPlannedPageCountForPhase(
        kind: GraphMetricKind,
        phase: GraphMetricBuildPhase,
        reverse_edge_page_count: usize,
        node_page_count: usize,
        cleanup_page_count: usize,
    ) usize {
        return switch (kind) {
            .degree => switch (phase) {
                .scan_edges_and_out_degree => reverse_edge_page_count,
                .reduce_ranks => node_page_count,
                .cleanup_old_generations => cleanup_page_count,
                else => 1,
            },
            .pagerank,
            .eigenvector,
            .hits_authority,
            .hits_hub,
            => switch (phase) {
                .scan_edges_and_out_degree,
                .iterate_contributions,
                .hits_hub_contributions,
                => reverse_edge_page_count,
                .initialize_ranks,
                .reduce_ranks,
                .hits_hub_reduce_ranks,
                .check_convergence,
                => node_page_count,
                .cleanup_old_generations => cleanup_page_count,
                else => 1,
            },
        };
    }

    fn graphMetricBuildPhasePageIdBase(kind: GraphMetricKind, phase: GraphMetricBuildPhase) u64 {
        const phases = graphMetricBuildManifestPhases(kind);
        for (phases, 0..) |candidate, i| {
            if (candidate == phase) return @intCast(i);
        }
        return 0;
    }

    fn graphMetricBuildPhasePublishIteration(kind: GraphMetricKind, phase: GraphMetricBuildPhase, publish_iteration: u32) u32 {
        if (!graphMetricKindIsIterative(kind)) return publish_iteration;
        return switch (phase) {
            .prepare_generation,
            .scan_edges_and_out_degree,
            .initialize_ranks,
            => 0,
            .iterate_contributions,
            .reduce_ranks,
            .hits_hub_contributions,
            .hits_hub_reduce_ranks,
            .check_convergence,
            => publish_iteration,
            else => 0,
        };
    }

    fn graphMetricBuildCleanupPageCount(kind: GraphMetricKind) usize {
        return switch (kind) {
            .degree => 2,
            .pagerank => 3,
            .eigenvector,
            => 1,
            .hits_authority,
            .hits_hub,
            => 4,
        };
    }

    fn graphMetricBuildCleanupPageIsFinal(kind: GraphMetricKind, page: GraphMetricBuildPage) bool {
        if (page.output_prefix.len == 0) return true;
        const cleanup_page_count = graphMetricBuildCleanupPageCount(kind);
        if (cleanup_page_count == 0) return true;
        return page.page_id + 1 >= cleanup_page_count;
    }

    fn graphMetricBuildCleanupPagePrefixAlloc(
        self: *GraphIndex,
        metric_name: []const u8,
        kind: GraphMetricKind,
        job_id: u64,
        page: GraphMetricBuildPage,
    ) ![]u8 {
        if (graphMetricBuildCleanupPageIsFinal(kind, page)) {
            return try self.graphMetricBuildJobNamespacePrefixAlloc(metric_name, job_id);
        }
        return switch (kind) {
            .degree => try self.graphMetricBuildDegreePartialPrefixAlloc(metric_name, job_id),
            .pagerank => switch (page.page_id) {
                0 => try self.graphMetricBuildPageRankOutDegreePartialPrefixAlloc(metric_name, job_id),
                1 => try self.graphMetricBuildPageRankNodePartialPrefixAlloc(metric_name, job_id),
                else => try self.graphMetricBuildJobNamespacePrefixAlloc(metric_name, job_id),
            },
            .hits_authority,
            .hits_hub,
            => switch (page.page_id) {
                0 => try self.graphMetricBuildHitsHubRawNamespacePrefixAlloc(metric_name, job_id),
                1 => try self.graphMetricBuildHitsHubRawSummaryNamespacePrefixAlloc(metric_name, job_id),
                2 => try self.graphMetricBuildHitsRankNamespacePrefixAlloc(metric_name, job_id),
                else => try self.graphMetricBuildJobNamespacePrefixAlloc(metric_name, job_id),
            },
            .eigenvector,
            => try self.graphMetricBuildJobNamespacePrefixAlloc(metric_name, job_id),
        };
    }

    fn collectReverseEdgeKeysForIndexInBatch(
        self: *GraphIndex,
        batch: anytype,
        out: *std.ArrayListUnmanaged([]u8),
    ) !void {
        var cur = try batch.openCursor();
        defer cur.close();
        var entry_opt = try cur.first();
        while (entry_opt) |entry| : (entry_opt = try cur.next()) {
            if (std.mem.startsWith(u8, entry.key, graph_meta_prefix)) continue;
            var parsed = (try parseReverseEdgeKeyAlloc(self.alloc, entry.key)) orelse continue;
            defer parsed.deinit(self.alloc);
            if (!std.mem.eql(u8, parsed.index_name, self.index_name)) continue;
            try out.append(self.alloc, try self.alloc.dupe(u8, entry.key));
        }
    }

    fn collectGraphNodeKeysInBatch(
        self: *GraphIndex,
        batch: anytype,
        out: *std.ArrayListUnmanaged([]u8),
    ) !void {
        const prefix = "meta:node_ref:";
        var cur = try batch.openCursor();
        defer cur.close();
        var entry_opt = try cur.seekAtOrAfter(prefix);
        while (entry_opt) |entry| : (entry_opt = try cur.next()) {
            if (!std.mem.startsWith(u8, entry.key, prefix)) break;
            try out.append(self.alloc, try self.alloc.dupe(u8, entry.key[prefix.len..]));
        }
    }

    fn firstReverseEdgeKeyForIndexInBatch(self: *GraphIndex, batch: anytype) ![]u8 {
        var cur = try batch.openCursor();
        defer cur.close();
        var entry_opt = try cur.first();
        while (entry_opt) |entry| : (entry_opt = try cur.next()) {
            if (std.mem.startsWith(u8, entry.key, graph_meta_prefix)) continue;
            var parsed = (try parseReverseEdgeKeyAlloc(self.alloc, entry.key)) orelse continue;
            defer parsed.deinit(self.alloc);
            if (!std.mem.eql(u8, parsed.index_name, self.index_name)) continue;
            return try self.alloc.dupe(u8, entry.key);
        }
        return "";
    }

    fn claimGraphMetricBuildPage(
        self: *GraphIndex,
        metric_name: []const u8,
        job_id: u64,
        phase: GraphMetricBuildPhase,
        iteration: u32,
        page_id: u64,
        worker_id: []const u8,
    ) !?GraphMetricBuildPage {
        const now_ms = @divTrunc(platform_time.realtimeNs(), std.time.ns_per_ms);
        return try self.claimGraphMetricBuildPageAt(metric_name, job_id, phase, iteration, page_id, worker_id, now_ms);
    }

    fn claimNextGraphMetricBuildPage(
        self: *GraphIndex,
        metric_name: []const u8,
        job_id: u64,
        phase: GraphMetricBuildPhase,
        iteration: u32,
        worker_id: []const u8,
    ) !?GraphMetricBuildPage {
        const now_ms = @divTrunc(platform_time.realtimeNs(), std.time.ns_per_ms);
        return try self.claimNextGraphMetricBuildPageAt(metric_name, job_id, phase, iteration, worker_id, now_ms);
    }

    pub fn claimNextGraphMetricBuildPageAt(
        self: *GraphIndex,
        metric_name: []const u8,
        job_id: u64,
        phase: GraphMetricBuildPhase,
        iteration: u32,
        worker_id: []const u8,
        now_ms: u64,
    ) !?GraphMetricBuildPage {
        if (worker_id.len == 0) return error.InvalidGraphMetricBuildWorker;
        var candidate_page_id: ?u64 = null;
        var batch = try self.beginWriteReverseBatch();
        errdefer batch.abort();
        {
            const prefix = try self.graphMetricBuildPagePrefixAlloc(metric_name, job_id, phase, iteration);
            defer self.alloc.free(prefix);
            var cur = try batch.openCursor();
            defer cur.close();
            var entry_opt = try cur.seekAtOrAfter(prefix);
            while (entry_opt) |entry| : (entry_opt = try cur.next()) {
                if (!std.mem.startsWith(u8, entry.key, prefix)) break;
                const page = decodeGraphMetricBuildPage(entry.value) orelse return error.InvalidGraphMetricBuildPage;
                if (page.job_id != job_id or page.phase != phase or page.iteration != iteration) return error.InvalidGraphMetricBuildPage;
                const eligible = switch (page.state) {
                    .pending, .failed => true,
                    .leased => page.lease_expires_at_ms <= now_ms or std.mem.eql(u8, page.worker_id, worker_id),
                    .complete => false,
                };
                if (!eligible) continue;
                if (page.attempt >= graph_metric_build_max_page_attempts) continue;
                candidate_page_id = page.page_id;
                break;
            }
        }
        const page_id = candidate_page_id orelse {
            try batch.commit();
            return null;
        };
        const claimed = try self.claimGraphMetricBuildPageInBatch(&batch, metric_name, job_id, phase, iteration, page_id, worker_id, now_ms);
        try batch.commit();
        return claimed;
    }

    fn claimGraphMetricBuildPageAt(
        self: *GraphIndex,
        metric_name: []const u8,
        job_id: u64,
        phase: GraphMetricBuildPhase,
        iteration: u32,
        page_id: u64,
        worker_id: []const u8,
        now_ms: u64,
    ) !?GraphMetricBuildPage {
        if (worker_id.len == 0) return error.InvalidGraphMetricBuildWorker;
        var batch = try self.beginWriteReverseBatch();
        errdefer batch.abort();
        const claimed = try self.claimGraphMetricBuildPageInBatch(&batch, metric_name, job_id, phase, iteration, page_id, worker_id, now_ms);
        try batch.commit();
        return claimed;
    }

    fn claimGraphMetricBuildPageInBatch(
        self: *GraphIndex,
        batch: anytype,
        metric_name: []const u8,
        job_id: u64,
        phase: GraphMetricBuildPhase,
        iteration: u32,
        page_id: u64,
        worker_id: []const u8,
        now_ms: u64,
    ) !?GraphMetricBuildPage {
        var page = try self.metricBuildPage(batch, metric_name, job_id, phase, iteration, page_id) orelse return error.GraphMetricBuildPageNotFound;
        switch (page.state) {
            .complete => {
                return null;
            },
            .leased => {
                if (page.lease_expires_at_ms > now_ms and !std.mem.eql(u8, page.worker_id, worker_id)) {
                    return null;
                }
                if (page.lease_expires_at_ms > now_ms and std.mem.eql(u8, page.worker_id, worker_id)) {
                    page.worker_id = worker_id;
                    page.lease_expires_at_ms = now_ms + graph_metric_local_build_lease_ms;
                    page.last_error = "";
                    try self.putGraphMetricBuildPageInBatch(batch, metric_name, page);
                    return page;
                }
            },
            .pending, .failed => {},
        }
        if (page.attempt >= graph_metric_build_max_page_attempts) {
            return null;
        }
        page.state = .leased;
        page.worker_id = worker_id;
        page.lease_expires_at_ms = now_ms + graph_metric_local_build_lease_ms;
        page.attempt += 1;
        page.cursor = "";
        page.completed_units = 0;
        page.last_error = "";
        page.output_fingerprint = 0;
        page.max_delta = 0.0;
        page.total_delta = 0.0;
        page.rank_sum = 0.0;
        page.converged = false;
        try self.putGraphMetricBuildPageInBatch(batch, metric_name, page);
        return page;
    }

    fn updateGraphMetricBuildPageProgress(
        self: *GraphIndex,
        metric_name: []const u8,
        job_id: u64,
        phase: GraphMetricBuildPhase,
        iteration: u32,
        page_id: u64,
        worker_id: []const u8,
        cursor: []const u8,
        completed_units: u64,
        total_units: u64,
    ) !GraphMetricBuildPage {
        return try self.updateGraphMetricBuildPageProgressForAttempt(metric_name, job_id, phase, iteration, page_id, worker_id, 0, cursor, completed_units, total_units);
    }

    pub fn updateGraphMetricBuildPageProgressForAttempt(
        self: *GraphIndex,
        metric_name: []const u8,
        job_id: u64,
        phase: GraphMetricBuildPhase,
        iteration: u32,
        page_id: u64,
        worker_id: []const u8,
        expected_attempt: u64,
        cursor: []const u8,
        completed_units: u64,
        total_units: u64,
    ) !GraphMetricBuildPage {
        var batch = try self.beginWriteReverseBatch();
        errdefer batch.abort();
        var page = try self.metricBuildPage(&batch, metric_name, job_id, phase, iteration, page_id) orelse return error.GraphMetricBuildPageNotFound;
        if (page.state != .leased or !std.mem.eql(u8, page.worker_id, worker_id)) return error.GraphMetricBuildPageNotLeased;
        if (expected_attempt != 0 and page.attempt != expected_attempt) return error.GraphMetricBuildPageNotLeased;
        if (total_units != 0 and completed_units > total_units) return error.InvalidGraphMetricBuildProgress;
        page.cursor = cursor;
        page.completed_units = completed_units;
        page.total_units = if (total_units != 0) total_units else page.total_units;
        page.last_error = "";
        try self.putGraphMetricBuildPageInBatch(&batch, metric_name, page);

        if (try self.metricBuildJob(&batch, metric_name)) |existing_job| {
            if (existing_job.job_id == job_id and existing_job.phase == phase and existing_job.iteration == iteration) {
                var job = existing_job;
                job.cursor = cursor;
                job.completed_units = completed_units;
                job.total_units = page.total_units;
                job.updated_at_ms = @divTrunc(platform_time.realtimeNs(), std.time.ns_per_ms);
                try self.putGraphMetricBuildJobInBatch(&batch, metric_name, job);
            }
        }

        try batch.commit();
        return page;
    }

    fn updateGraphMetricBuildConvergencePageProgressForAttempt(
        self: *GraphIndex,
        metric_name: []const u8,
        job_id: u64,
        iteration: u32,
        page_id: u64,
        worker_id: []const u8,
        expected_attempt: u64,
        cursor: []const u8,
        completed_units: u64,
        total_units: u64,
        max_delta: f64,
        total_delta: f64,
        rank_sum: f64,
    ) !GraphMetricBuildPage {
        var batch = try self.beginWriteReverseBatch();
        errdefer batch.abort();
        var page = try self.metricBuildPage(&batch, metric_name, job_id, .check_convergence, iteration, page_id) orelse return error.GraphMetricBuildPageNotFound;
        if (page.state != .leased or !std.mem.eql(u8, page.worker_id, worker_id)) return error.GraphMetricBuildPageNotLeased;
        if (expected_attempt != 0 and page.attempt != expected_attempt) return error.GraphMetricBuildPageNotLeased;
        if (total_units != 0 and completed_units > total_units) return error.InvalidGraphMetricBuildProgress;
        if (!std.math.isFinite(max_delta) or !std.math.isFinite(total_delta) or !std.math.isFinite(rank_sum)) return error.InvalidGraphMetricScore;
        page.cursor = cursor;
        page.completed_units = completed_units;
        page.total_units = if (total_units != 0) total_units else page.total_units;
        page.last_error = "";
        page.max_delta = max_delta;
        page.total_delta = total_delta;
        page.rank_sum = rank_sum;
        page.converged = false;
        try self.putGraphMetricBuildPageInBatch(&batch, metric_name, page);

        if (try self.metricBuildJob(&batch, metric_name)) |existing_job| {
            if (existing_job.job_id == job_id and existing_job.phase == .check_convergence and existing_job.iteration == iteration) {
                var job = existing_job;
                job.cursor = cursor;
                job.completed_units = completed_units;
                job.total_units = page.total_units;
                job.updated_at_ms = @divTrunc(platform_time.realtimeNs(), std.time.ns_per_ms);
                try self.putGraphMetricBuildJobInBatch(&batch, metric_name, job);
            }
        }

        try batch.commit();
        return page;
    }

    fn completeGraphMetricBuildPage(
        self: *GraphIndex,
        metric_name: []const u8,
        job_id: u64,
        phase: GraphMetricBuildPhase,
        iteration: u32,
        page_id: u64,
        worker_id: []const u8,
        completed_units: u64,
        output_fingerprint: u64,
    ) !GraphMetricBuildPage {
        return try self.completeGraphMetricBuildPageForAttempt(metric_name, job_id, phase, iteration, page_id, worker_id, 0, completed_units, output_fingerprint);
    }

    pub fn completeGraphMetricBuildPageForAttempt(
        self: *GraphIndex,
        metric_name: []const u8,
        job_id: u64,
        phase: GraphMetricBuildPhase,
        iteration: u32,
        page_id: u64,
        worker_id: []const u8,
        expected_attempt: u64,
        completed_units: u64,
        output_fingerprint: u64,
    ) !GraphMetricBuildPage {
        return try self.completeGraphMetricBuildPageWithConvergenceForAttempt(metric_name, job_id, phase, iteration, page_id, worker_id, expected_attempt, completed_units, output_fingerprint, 0.0, 0.0, 0.0, false);
    }

    fn completeGraphMetricBuildConvergencePage(
        self: *GraphIndex,
        metric_name: []const u8,
        job_id: u64,
        iteration: u32,
        page_id: u64,
        worker_id: []const u8,
        completed_units: u64,
        output_fingerprint: u64,
        max_delta: f64,
        total_delta: f64,
        rank_sum: f64,
        converged: bool,
    ) !GraphMetricBuildPage {
        return try self.completeGraphMetricBuildConvergencePageForAttempt(metric_name, job_id, iteration, page_id, worker_id, 0, completed_units, output_fingerprint, max_delta, total_delta, rank_sum, converged);
    }

    fn completeGraphMetricBuildConvergencePageForAttempt(
        self: *GraphIndex,
        metric_name: []const u8,
        job_id: u64,
        iteration: u32,
        page_id: u64,
        worker_id: []const u8,
        expected_attempt: u64,
        completed_units: u64,
        output_fingerprint: u64,
        max_delta: f64,
        total_delta: f64,
        rank_sum: f64,
        converged: bool,
    ) !GraphMetricBuildPage {
        return try self.completeGraphMetricBuildPageWithConvergenceForAttempt(metric_name, job_id, .check_convergence, iteration, page_id, worker_id, expected_attempt, completed_units, output_fingerprint, max_delta, total_delta, rank_sum, converged);
    }

    fn completeGraphMetricBuildPageWithConvergenceForAttempt(
        self: *GraphIndex,
        metric_name: []const u8,
        job_id: u64,
        phase: GraphMetricBuildPhase,
        iteration: u32,
        page_id: u64,
        worker_id: []const u8,
        expected_attempt: u64,
        completed_units: u64,
        output_fingerprint: u64,
        max_delta: f64,
        total_delta: f64,
        rank_sum: f64,
        converged: bool,
    ) !GraphMetricBuildPage {
        var batch = try self.beginWriteReverseBatch();
        errdefer batch.abort();
        var page = try self.metricBuildPage(&batch, metric_name, job_id, phase, iteration, page_id) orelse return error.GraphMetricBuildPageNotFound;
        if (page.state == .complete) {
            if (expected_attempt != 0 and page.attempt != expected_attempt) return error.GraphMetricBuildPageNotLeased;
            if (page.output_fingerprint != output_fingerprint) return error.GraphMetricBuildPageOutputMismatch;
            page.worker_id = "";
            page.cursor = "";
            page.last_error = "";
            try batch.commit();
            return page;
        }
        if (page.state != .leased or !std.mem.eql(u8, page.worker_id, worker_id)) return error.GraphMetricBuildPageNotLeased;
        if (expected_attempt != 0 and page.attempt != expected_attempt) return error.GraphMetricBuildPageNotLeased;
        page.state = .complete;
        page.worker_id = worker_id;
        page.lease_expires_at_ms = 0;
        page.completed_units = completed_units;
        page.cursor = "";
        page.last_error = "";
        page.output_fingerprint = output_fingerprint;
        page.max_delta = max_delta;
        page.total_delta = total_delta;
        page.rank_sum = rank_sum;
        page.converged = converged;
        try self.putGraphMetricBuildPageInBatch(&batch, metric_name, page);
        try batch.commit();
        return page;
    }

    fn failGraphMetricBuildPage(
        self: *GraphIndex,
        metric_name: []const u8,
        job_id: u64,
        phase: GraphMetricBuildPhase,
        iteration: u32,
        page_id: u64,
        worker_id: []const u8,
        last_error: []const u8,
    ) !GraphMetricBuildPage {
        return try self.failGraphMetricBuildPageForAttempt(metric_name, job_id, phase, iteration, page_id, worker_id, 0, last_error);
    }

    fn failGraphMetricBuildPageForAttempt(
        self: *GraphIndex,
        metric_name: []const u8,
        job_id: u64,
        phase: GraphMetricBuildPhase,
        iteration: u32,
        page_id: u64,
        worker_id: []const u8,
        expected_attempt: u64,
        last_error: []const u8,
    ) !GraphMetricBuildPage {
        var batch = try self.beginWriteReverseBatch();
        errdefer batch.abort();
        var page = try self.metricBuildPage(&batch, metric_name, job_id, phase, iteration, page_id) orelse return error.GraphMetricBuildPageNotFound;
        if (page.state != .leased or !std.mem.eql(u8, page.worker_id, worker_id)) return error.GraphMetricBuildPageNotLeased;
        if (expected_attempt != 0 and page.attempt != expected_attempt) return error.GraphMetricBuildPageNotLeased;
        page.state = .failed;
        page.worker_id = worker_id;
        page.lease_expires_at_ms = 0;
        page.last_error = last_error;
        try self.putGraphMetricBuildPageInBatch(&batch, metric_name, page);
        try batch.commit();
        return page;
    }

    fn validateGraphMetricBuildPageExecutionLease(_: *GraphIndex, claimed: GraphMetricBuildPage, current: GraphMetricBuildPage) !void {
        if (current.state != .leased) return error.GraphMetricBuildPageNotLeased;
        if (!std.mem.eql(u8, current.worker_id, claimed.worker_id)) return error.GraphMetricBuildPageNotLeased;
        if (current.attempt != claimed.attempt) return error.GraphMetricBuildPageNotLeased;
    }

    fn summarizeGraphMetricBuildPhase(
        self: *GraphIndex,
        metric_name: []const u8,
        job_id: u64,
        phase: GraphMetricBuildPhase,
        iteration: u32,
    ) !GraphMetricBuildPhaseSummary {
        var batch = try self.beginWriteReverseBatch();
        errdefer batch.abort();
        const job = try self.metricBuildJob(&batch, metric_name) orelse return error.GraphMetricBuildJobNotFound;
        if (job.job_id != job_id) return error.GraphMetricBuildJobMismatch;
        const cfg = self.metricConfig(metric_name) orelse return error.MetricNotReady;
        const summary = try self.summarizeGraphMetricBuildPhaseInBatch(&batch, metric_name, cfg, job, phase, iteration);
        try batch.commit();
        return summary;
    }

    fn summarizeGraphMetricBuildPhaseInBatch(
        self: *GraphIndex,
        batch: anytype,
        metric_name: []const u8,
        cfg: GraphMetricConfig,
        job: GraphMetricBuildJob,
        phase: GraphMetricBuildPhase,
        iteration: u32,
    ) !GraphMetricBuildPhaseSummary {
        var expected_pages: u64 = 0;
        var completed_pages: u64 = 0;
        var failed_pages: u64 = 0;
        var completed_units: u64 = 0;
        var total_units: u64 = 0;
        var output_fingerprint: u64 = 0;
        var max_delta: f64 = 0.0;
        var total_delta: f64 = 0.0;
        var rank_sum: f64 = 0.0;
        var all_completed_pages_converged = true;
        var page_found = false;
        const page_prefix = try self.graphMetricBuildPagePrefixAlloc(metric_name, job.job_id, phase, iteration);
        defer self.alloc.free(page_prefix);
        var cur = try batch.openCursor();
        defer cur.close();
        var entry_opt = try cur.seekAtOrAfter(page_prefix);
        while (entry_opt) |entry| : (entry_opt = try cur.next()) {
            if (!std.mem.startsWith(u8, entry.key, page_prefix)) break;
            const page = decodeGraphMetricBuildPage(entry.value) orelse return error.InvalidGraphMetricBuildPage;
            if (page.job_id != job.job_id or page.phase != phase or page.iteration != iteration) return error.InvalidGraphMetricBuildPage;
            expected_pages += 1;
            page_found = true;
            total_units += page.total_units;
            completed_units += page.completed_units;
            switch (page.state) {
                .complete => {
                    completed_pages += 1;
                    output_fingerprint ^= page.output_fingerprint;
                    max_delta = @max(max_delta, page.max_delta);
                    total_delta += page.total_delta;
                    rank_sum += page.rank_sum;
                    all_completed_pages_converged = all_completed_pages_converged and page.converged;
                },
                .failed => failed_pages += 1,
                .pending, .leased => {},
            }
        }
        if (!page_found) return error.GraphMetricBuildPhaseNotFound;
        const state: GraphMetricBuildPhaseState = if (failed_pages != 0)
            .failed
        else if (completed_pages == expected_pages)
            .complete
        else
            .pending;
        const summary = GraphMetricBuildPhaseSummary{
            .job_id = job.job_id,
            .phase = phase,
            .iteration = iteration,
            .state = state,
            .expected_pages = expected_pages,
            .completed_pages = completed_pages,
            .failed_pages = failed_pages,
            .completed_units = completed_units,
            .total_units = total_units,
            .output_fingerprint = output_fingerprint,
            .max_delta = max_delta,
            .total_delta = total_delta,
            .rank_sum = rank_sum,
            .converged = phase == .check_convergence and state == .complete and all_completed_pages_converged and total_delta <= cfg.tolerance,
        };
        try self.putGraphMetricBuildPhaseSummaryInBatch(batch, metric_name, summary);
        return summary;
    }

    fn graphMetricBuildPhaseHasExhaustedPage(
        self: *GraphIndex,
        metric_name: []const u8,
        job_id: u64,
        phase: GraphMetricBuildPhase,
        iteration: u32,
        now_ms: u64,
    ) !bool {
        var txn = try self.beginReadReverseTxn();
        defer txn.abort();
        const page_prefix = try self.graphMetricBuildPagePrefixAlloc(metric_name, job_id, phase, iteration);
        defer self.alloc.free(page_prefix);
        var cur = try txn.openCursor();
        defer cur.close();
        var entry_opt = try cur.seekAtOrAfter(page_prefix);
        while (entry_opt) |entry| : (entry_opt = try cur.next()) {
            if (!std.mem.startsWith(u8, entry.key, page_prefix)) break;
            const page = decodeGraphMetricBuildPage(entry.value) orelse return error.InvalidGraphMetricBuildPage;
            if (page.job_id != job_id or page.phase != phase or page.iteration != iteration) return error.InvalidGraphMetricBuildPage;
            switch (page.state) {
                .failed => if (page.attempt >= graph_metric_build_max_page_attempts) return true,
                .leased => if (page.attempt >= graph_metric_build_max_page_attempts and page.lease_expires_at_ms <= now_ms) return true,
                .pending, .complete => {},
            }
        }
        return false;
    }

    fn advanceGraphMetricBuildPhaseIfReady(
        self: *GraphIndex,
        metric_name: []const u8,
        job_id: u64,
        phase: GraphMetricBuildPhase,
        iteration: u32,
    ) !bool {
        var batch = try self.beginWriteReverseBatch();
        errdefer batch.abort();
        var job = try self.metricBuildJob(&batch, metric_name) orelse return error.GraphMetricBuildJobNotFound;
        if (job.job_id != job_id) return error.GraphMetricBuildJobMismatch;
        const cfg = self.metricConfig(metric_name) orelse return error.MetricNotReady;
        const summary = try self.summarizeGraphMetricBuildPhaseInBatch(&batch, metric_name, cfg, job, phase, iteration);
        if (summary.state != .complete) {
            try batch.commit();
            return false;
        }
        if (graphMetricKindUsesPlannedIterativeRunner(cfg.kind) and phase == .check_convergence and !summary.converged and @as(u64, iteration) + 1 < cfg.max_iterations) {
            const iteration_summary = GraphMetricBuildIterationSummary{
                .job_id = job.job_id,
                .iteration = iteration,
                .expected_pages = summary.expected_pages,
                .completed_pages = summary.completed_pages,
                .max_delta = summary.max_delta,
                .total_delta = summary.total_delta,
                .rank_sum = summary.rank_sum,
                .converged = false,
                .fixed_iteration_limit = false,
                .output_fingerprint = summary.output_fingerprint,
            };
            try self.putGraphMetricBuildIterationSummaryInBatch(&batch, metric_name, iteration_summary);
            const next_iteration = iteration + 1;
            try self.planGraphMetricIterationPagesInBatch(&batch, metric_name, cfg.kind, job, next_iteration);
            job.phase = .iterate_contributions;
            job.iteration = next_iteration;
            job.updated_at_ms = @divTrunc(platform_time.realtimeNs(), std.time.ns_per_ms);
            job.completed_units = summary.completed_units;
            job.total_units = summary.total_units;
            try self.putGraphMetricBuildJobInBatch(&batch, metric_name, job);

            const lease_key = try self.graphMetricBuildLeaseKeyAlloc(metric_name);
            defer self.alloc.free(lease_key);
            if (batch.get(lease_key)) |raw| {
                if (decodeGraphMetricBuildLease(raw)) |lease| {
                    if (lease.job_id == job.job_id) {
                        var updated_lease = lease;
                        updated_lease.phase = .iterate_contributions;
                        updated_lease.iteration = next_iteration;
                        const encoded = try self.alloc.alloc(u8, graphMetricBuildLeaseEncodedLen(updated_lease));
                        defer self.alloc.free(encoded);
                        encodeGraphMetricBuildLease(updated_lease, encoded);
                        try batch.put(lease_key, encoded);
                    }
                }
            } else |err| switch (err) {
                error.NotFound => {},
                else => return err,
            }
            try batch.commit();
            return true;
        }
        if (graphMetricKindUsesPlannedIterativeRunner(cfg.kind) and phase == .check_convergence) {
            const iteration_summary = GraphMetricBuildIterationSummary{
                .job_id = job.job_id,
                .iteration = iteration,
                .expected_pages = summary.expected_pages,
                .completed_pages = summary.completed_pages,
                .max_delta = summary.max_delta,
                .total_delta = summary.total_delta,
                .rank_sum = summary.rank_sum,
                .converged = summary.converged,
                .fixed_iteration_limit = !summary.converged and @as(u64, iteration) + 1 >= cfg.max_iterations,
                .output_fingerprint = summary.output_fingerprint,
            };
            try self.putGraphMetricBuildIterationSummaryInBatch(&batch, metric_name, iteration_summary);
        }
        const next_phase = graphMetricBuildManifestNextPhase(cfg.kind, phase) orelse {
            try batch.commit();
            return false;
        };
        if ((cfg.kind == .hits_authority or cfg.kind == .hits_hub) and next_phase == .hits_hub_contributions) {
            const hub_raw_prefix = try self.graphMetricBuildHitsHubRawPrefixAlloc(metric_name, job.job_id, iteration);
            defer self.alloc.free(hub_raw_prefix);
            _ = try self.deleteKeysWithPrefixInBatch(&batch, hub_raw_prefix);
            const hub_raw_summary_key = try self.graphMetricBuildHitsHubRawSummaryKeyAlloc(metric_name, job.job_id, iteration);
            defer self.alloc.free(hub_raw_summary_key);
            batch.delete(hub_raw_summary_key) catch |err| switch (err) {
                error.NotFound => {},
                else => return err,
            };
        }
        job.phase = next_phase;
        job.iteration = iteration;
        job.updated_at_ms = @divTrunc(platform_time.realtimeNs(), std.time.ns_per_ms);
        job.completed_units = summary.completed_units;
        job.total_units = summary.total_units;
        try self.putGraphMetricBuildJobInBatch(&batch, metric_name, job);

        const lease_key = try self.graphMetricBuildLeaseKeyAlloc(metric_name);
        defer self.alloc.free(lease_key);
        if (batch.get(lease_key)) |raw| {
            if (decodeGraphMetricBuildLease(raw)) |lease| {
                if (lease.job_id == job.job_id) {
                    var updated_lease = lease;
                    updated_lease.phase = next_phase;
                    updated_lease.iteration = iteration;
                    const encoded = try self.alloc.alloc(u8, graphMetricBuildLeaseEncodedLen(updated_lease));
                    defer self.alloc.free(encoded);
                    encodeGraphMetricBuildLease(updated_lease, encoded);
                    try batch.put(lease_key, encoded);
                }
            }
        } else |err| switch (err) {
            error.NotFound => {},
            else => return err,
        }
        try batch.commit();
        return true;
    }

    fn recordGraphMetricBuildIterationSummaryFromCheckPhase(
        self: *GraphIndex,
        metric_name: []const u8,
        job_id: u64,
        iteration: u32,
    ) !GraphMetricBuildIterationSummary {
        var batch = try self.beginWriteReverseBatch();
        errdefer batch.abort();
        const job = try self.metricBuildJob(&batch, metric_name) orelse return error.GraphMetricBuildJobNotFound;
        if (job.job_id != job_id) return error.GraphMetricBuildJobMismatch;
        const cfg = self.metricConfig(metric_name) orelse return error.MetricNotReady;
        const phase_summary = try self.summarizeGraphMetricBuildPhaseInBatch(&batch, metric_name, cfg, job, .check_convergence, iteration);
        if (phase_summary.state != .complete) return error.GraphMetricBuildIterationNotComplete;
        const iteration_summary = GraphMetricBuildIterationSummary{
            .job_id = job.job_id,
            .iteration = iteration,
            .expected_pages = phase_summary.expected_pages,
            .completed_pages = phase_summary.completed_pages,
            .max_delta = phase_summary.max_delta,
            .total_delta = phase_summary.total_delta,
            .rank_sum = phase_summary.rank_sum,
            .converged = phase_summary.converged,
            .fixed_iteration_limit = !phase_summary.converged and @as(u64, iteration) + 1 >= cfg.max_iterations,
            .output_fingerprint = phase_summary.output_fingerprint,
        };
        try self.putGraphMetricBuildIterationSummaryInBatch(&batch, metric_name, iteration_summary);
        try batch.commit();
        return iteration_summary;
    }

    fn verifyGraphMetricBuildPublishReady(
        self: *GraphIndex,
        metric_name: []const u8,
        job_id: u64,
    ) !GraphMetricBuildPublishVerification {
        var batch = try self.beginWriteReverseBatch();
        errdefer batch.abort();
        const job = try self.metricBuildJob(&batch, metric_name) orelse return error.GraphMetricBuildJobNotFound;
        if (job.job_id != job_id) return error.GraphMetricBuildJobMismatch;
        if (job.phase != .publish_generation) return error.GraphMetricBuildPublishNotReady;
        const cfg = self.metricConfig(metric_name) orelse return error.MetricNotReady;
        const manifest = try self.metricBuildManifest(&batch, metric_name, job.job_id) orelse return error.GraphMetricBuildManifestNotFound;
        const expected_config_fingerprint = graphMetricConfigFingerprint(cfg);
        const phases = graphMetricBuildManifestPhases(cfg.kind);
        if (manifest.job_id != job.job_id or
            manifest.target_generation != job.target_generation or
            manifest.score_generation != job.score_generation or
            manifest.config_fingerprint != expected_config_fingerprint or
            manifest.phase_count != phases.len or
            manifest.page_count < phases.len)
        {
            return error.InvalidGraphMetricBuildManifest;
        }

        var expected_phases: u64 = 0;
        var completed_phases: u64 = 0;
        var expected_pages: u64 = 0;
        var completed_pages: u64 = 0;
        var output_fingerprint: u64 = 0;
        var check_phase_summary: ?GraphMetricBuildPhaseSummary = null;
        for (phases) |phase| {
            if (phase == .publish_generation) break;
            const phase_iteration = graphMetricBuildPhasePublishIteration(cfg.kind, phase, job.iteration);
            const summary = try self.summarizeGraphMetricBuildPhaseInBatch(&batch, metric_name, cfg, job, phase, phase_iteration);
            expected_phases += 1;
            expected_pages += summary.expected_pages;
            completed_pages += summary.completed_pages;
            output_fingerprint ^= summary.output_fingerprint;
            if (summary.state != .complete) return error.GraphMetricBuildPublishNotReady;
            completed_phases += 1;
            if (phase == .check_convergence) check_phase_summary = summary;
        }

        var converged = false;
        var fixed_iteration_limit = false;
        var max_delta: f64 = 0.0;
        var total_delta: f64 = 0.0;
        var rank_sum: f64 = 0.0;
        if (graphMetricKindIsIterative(cfg.kind)) {
            const summary = check_phase_summary orelse return error.GraphMetricBuildPublishNotReady;
            const iteration_summary = GraphMetricBuildIterationSummary{
                .job_id = job.job_id,
                .iteration = job.iteration,
                .expected_pages = summary.expected_pages,
                .completed_pages = summary.completed_pages,
                .max_delta = summary.max_delta,
                .total_delta = summary.total_delta,
                .rank_sum = summary.rank_sum,
                .converged = summary.converged,
                .fixed_iteration_limit = !summary.converged and @as(u64, job.iteration) + 1 >= cfg.max_iterations,
                .output_fingerprint = summary.output_fingerprint,
            };
            try self.putGraphMetricBuildIterationSummaryInBatch(&batch, metric_name, iteration_summary);
            converged = iteration_summary.converged;
            fixed_iteration_limit = iteration_summary.fixed_iteration_limit;
            max_delta = iteration_summary.max_delta;
            total_delta = iteration_summary.total_delta;
            rank_sum = iteration_summary.rank_sum;
        }

        try batch.commit();
        return .{
            .job_id = job.job_id,
            .target_generation = job.target_generation,
            .score_generation = job.score_generation,
            .config_fingerprint = expected_config_fingerprint,
            .iteration = job.iteration,
            .expected_phases = expected_phases,
            .completed_phases = completed_phases,
            .expected_pages = expected_pages,
            .completed_pages = completed_pages,
            .output_fingerprint = output_fingerprint,
            .converged = converged,
            .fixed_iteration_limit = fixed_iteration_limit,
            .max_delta = max_delta,
            .total_delta = total_delta,
            .rank_sum = rank_sum,
        };
    }

    fn releaseGraphMetricBuildLease(self: *GraphIndex, metric_name: []const u8) !void {
        var batch = try self.beginWriteReverseBatch();
        errdefer batch.abort();
        const key = try self.graphMetricBuildLeaseKeyAlloc(metric_name);
        defer self.alloc.free(key);
        batch.delete(key) catch |err| switch (err) {
            error.NotFound => {},
            else => return err,
        };
        try batch.commit();
    }

    fn updateGraphMetricBuildLeaseProgress(
        self: *GraphIndex,
        metric_name: []const u8,
        phase: GraphMetricBuildPhase,
        iteration: u32,
    ) !void {
        try self.updateGraphMetricBuildLeaseProgressWithCursor(metric_name, phase, iteration, "", 0, 0);
    }

    fn updateGraphMetricBuildLeaseProgressWithCursor(
        self: *GraphIndex,
        metric_name: []const u8,
        phase: GraphMetricBuildPhase,
        iteration: u32,
        cursor: []const u8,
        completed_units: u64,
        total_units: u64,
    ) !void {
        var batch = try self.beginWriteReverseBatch();
        errdefer batch.abort();
        const key = try self.graphMetricBuildLeaseKeyAlloc(metric_name);
        defer self.alloc.free(key);
        const raw = batch.get(key) catch |err| switch (err) {
            error.NotFound => return,
            else => return err,
        };
        var lease = decodeGraphMetricBuildLease(raw) orelse return;
        lease.phase = phase;
        lease.iteration = iteration;
        const now_ms = @divTrunc(platform_time.realtimeNs(), std.time.ns_per_ms);
        const encoded = try self.alloc.alloc(u8, graphMetricBuildLeaseEncodedLen(lease));
        defer self.alloc.free(encoded);
        encodeGraphMetricBuildLease(lease, encoded);
        try batch.put(key, encoded);
        try self.putGraphMetricBuildJobInBatch(&batch, metric_name, .{
            .job_id = lease.job_id,
            .target_generation = lease.target_generation,
            .score_generation = lease.target_generation,
            .started_at_ms = lease.started_at_ms,
            .updated_at_ms = now_ms,
            .lease_expires_at_ms = lease.lease_expires_at_ms,
            .phase = phase,
            .iteration = iteration,
            .worker_id = lease.worker_id,
            .cursor = cursor,
            .completed_units = completed_units,
            .total_units = total_units,
        });
        try batch.commit();
    }

    fn completeGraphMetricBuildJob(self: *GraphIndex, metric_name: []const u8) !void {
        var batch = try self.beginWriteReverseBatch();
        errdefer batch.abort();
        const job = try self.metricBuildJob(&batch, metric_name) orelse {
            try batch.commit();
            return;
        };
        try self.putGraphMetricBuildJobInBatch(&batch, metric_name, .{
            .job_id = job.job_id,
            .target_generation = job.target_generation,
            .score_generation = job.score_generation,
            .started_at_ms = job.started_at_ms,
            .updated_at_ms = @divTrunc(platform_time.realtimeNs(), std.time.ns_per_ms),
            .lease_expires_at_ms = 0,
            .phase = .complete,
            .iteration = job.iteration,
            .worker_id = job.worker_id,
            .cursor = job.cursor,
            .completed_units = if (job.total_units != 0) job.total_units else job.completed_units,
            .total_units = job.total_units,
        });
        try batch.commit();
    }

    fn putGraphMetricBuildJobInBatch(
        self: *GraphIndex,
        batch: anytype,
        metric_name: []const u8,
        job: GraphMetricBuildJob,
    ) !void {
        const job_key = try self.graphMetricBuildJobKeyAlloc(metric_name);
        defer self.alloc.free(job_key);
        const encoded = try self.alloc.alloc(u8, graphMetricBuildJobEncodedLen(job));
        defer self.alloc.free(encoded);
        encodeGraphMetricBuildJob(job, encoded);
        try batch.put(job_key, encoded);
    }

    fn putGraphMetricBuildManifestInBatch(
        self: *GraphIndex,
        batch: anytype,
        metric_name: []const u8,
        manifest: GraphMetricBuildManifest,
    ) !void {
        const manifest_key = try self.graphMetricBuildManifestKeyAlloc(metric_name, manifest.job_id);
        defer self.alloc.free(manifest_key);
        var encoded: [graph_metric_build_manifest_encoded_len]u8 = undefined;
        encodeGraphMetricBuildManifest(manifest, &encoded);
        try batch.put(manifest_key, &encoded);
    }

    pub fn invalidateGraphMetricBuildManifestConfigFingerprintForTest(
        self: *GraphIndex,
        metric_name: []const u8,
        job_id: u64,
    ) !void {
        var batch = try self.beginWriteReverseBatch();
        errdefer batch.abort();
        var manifest = try self.metricBuildManifest(&batch, metric_name, job_id) orelse return error.GraphMetricBuildManifestNotFound;
        manifest.config_fingerprint +%= 1;
        try self.putGraphMetricBuildManifestInBatch(&batch, metric_name, manifest);
        try batch.commit();
    }

    fn putGraphMetricBuildPageInBatch(
        self: *GraphIndex,
        batch: anytype,
        metric_name: []const u8,
