    fn encodeGraphMetricBuildPage(page: GraphMetricBuildPage, out: []u8) void {
        std.debug.assert(out.len == graphMetricBuildPageEncodedLen(page));
        var offset: usize = 0;
        inline for (.{
            @as(u64, 3),
            page.job_id,
            @as(u64, @intFromEnum(page.phase)),
            @as(u64, page.iteration),
            page.page_id,
            @as(u64, @intFromEnum(page.state)),
            page.lease_expires_at_ms,
            page.attempt,
            page.completed_units,
            page.total_units,
            page.output_fingerprint,
            @as(u64, page.worker_id.len),
            @as(u64, page.cursor.len),
            @as(u64, page.last_error.len),
            @as(u64, @bitCast(page.max_delta)),
            @as(u64, @bitCast(page.total_delta)),
            @as(u64, @bitCast(page.rank_sum)),
            if (page.converged) @as(u64, 1) else @as(u64, 0),
            @as(u64, @intFromEnum(page.range_kind)),
            @as(u64, page.range_lower.len),
            @as(u64, page.range_upper.len),
            @as(u64, page.output_prefix.len),
        }) |value| {
            std.mem.writeInt(u64, out[offset..][0..8], value, .little);
            offset += 8;
        }
        @memcpy(out[offset..][0..page.worker_id.len], page.worker_id);
        offset += page.worker_id.len;
        @memcpy(out[offset..][0..page.cursor.len], page.cursor);
        offset += page.cursor.len;
        @memcpy(out[offset..][0..page.last_error.len], page.last_error);
        offset += page.last_error.len;
        @memcpy(out[offset..][0..page.range_lower.len], page.range_lower);
        offset += page.range_lower.len;
        @memcpy(out[offset..][0..page.range_upper.len], page.range_upper);
        offset += page.range_upper.len;
        @memcpy(out[offset..][0..page.output_prefix.len], page.output_prefix);
    }

    fn decodeGraphMetricBuildPage(raw: []const u8) ?GraphMetricBuildPage {
        if (raw.len < graph_metric_build_page_v1_header_len) return null;
        var offset: usize = 0;
        const version = std.mem.readInt(u64, raw[offset..][0..8], .little);
        offset += 8;
        if (version != 1 and version != 2 and version != 3) return null;
        if (version == 2 and raw.len < graph_metric_build_page_v2_header_len) return null;
        if (version == 3 and raw.len < graph_metric_build_page_header_len) return null;
        const job_id = std.mem.readInt(u64, raw[offset..][0..8], .little);
        offset += 8;
        const phase_raw = std.mem.readInt(u64, raw[offset..][0..8], .little);
        offset += 8;
        const phase = graphMetricBuildPhaseFromRaw(phase_raw) orelse return null;
        const iteration_raw = std.mem.readInt(u64, raw[offset..][0..8], .little);
        offset += 8;
        if (iteration_raw > std.math.maxInt(u32)) return null;
        const page_id = std.mem.readInt(u64, raw[offset..][0..8], .little);
        offset += 8;
        const state_raw = std.mem.readInt(u64, raw[offset..][0..8], .little);
        offset += 8;
        const state: GraphMetricBuildPageState = switch (state_raw) {
            @intFromEnum(GraphMetricBuildPageState.pending) => .pending,
            @intFromEnum(GraphMetricBuildPageState.leased) => .leased,
            @intFromEnum(GraphMetricBuildPageState.complete) => .complete,
            @intFromEnum(GraphMetricBuildPageState.failed) => .failed,
            else => return null,
        };
        const lease_expires_at_ms = std.mem.readInt(u64, raw[offset..][0..8], .little);
        offset += 8;
        const attempt = std.mem.readInt(u64, raw[offset..][0..8], .little);
        offset += 8;
        const completed_units = std.mem.readInt(u64, raw[offset..][0..8], .little);
        offset += 8;
        const total_units = std.mem.readInt(u64, raw[offset..][0..8], .little);
        offset += 8;
        const output_fingerprint = std.mem.readInt(u64, raw[offset..][0..8], .little);
        offset += 8;
        const worker_id_len: usize = @intCast(std.mem.readInt(u64, raw[offset..][0..8], .little));
        offset += 8;
        const cursor_len: usize = @intCast(std.mem.readInt(u64, raw[offset..][0..8], .little));
        offset += 8;
        const last_error_len: usize = @intCast(std.mem.readInt(u64, raw[offset..][0..8], .little));
        offset += 8;
        const max_delta = if (version >= 2) blk: {
            const value = @as(f64, @bitCast(std.mem.readInt(u64, raw[offset..][0..8], .little)));
            offset += 8;
            break :blk value;
        } else 0.0;
        const total_delta = if (version >= 2) blk: {
            const value = @as(f64, @bitCast(std.mem.readInt(u64, raw[offset..][0..8], .little)));
            offset += 8;
            break :blk value;
        } else 0.0;
        const rank_sum = if (version >= 2) blk: {
            const value = @as(f64, @bitCast(std.mem.readInt(u64, raw[offset..][0..8], .little)));
            offset += 8;
            break :blk value;
        } else 0.0;
        const converged = if (version >= 2) blk: {
            const value = std.mem.readInt(u64, raw[offset..][0..8], .little) != 0;
            offset += 8;
            break :blk value;
        } else false;
        const range_fields = if (version >= 3) blk: {
            const range_kind_raw = std.mem.readInt(u64, raw[offset..][0..8], .little);
            offset += 8;
            const decoded_range_kind: GraphMetricBuildPageRangeKind = switch (range_kind_raw) {
                @intFromEnum(GraphMetricBuildPageRangeKind.full) => .full,
                @intFromEnum(GraphMetricBuildPageRangeKind.reverse_edges) => .reverse_edges,
                @intFromEnum(GraphMetricBuildPageRangeKind.nodes) => .nodes,
                @intFromEnum(GraphMetricBuildPageRangeKind.scores) => .scores,
                @intFromEnum(GraphMetricBuildPageRangeKind.contributions) => .contributions,
                @intFromEnum(GraphMetricBuildPageRangeKind.job_control) => .job_control,
                else => return null,
            };
            const decoded_range_lower_len: usize = @intCast(std.mem.readInt(u64, raw[offset..][0..8], .little));
            offset += 8;
            const decoded_range_upper_len: usize = @intCast(std.mem.readInt(u64, raw[offset..][0..8], .little));
            offset += 8;
            const decoded_output_prefix_len: usize = @intCast(std.mem.readInt(u64, raw[offset..][0..8], .little));
            offset += 8;
            break :blk .{ decoded_range_kind, decoded_range_lower_len, decoded_range_upper_len, decoded_output_prefix_len };
        } else .{ GraphMetricBuildPageRangeKind.full, @as(usize, 0), @as(usize, 0), @as(usize, 0) };
        const range_kind = range_fields[0];
        const range_lower_len = range_fields[1];
        const range_upper_len = range_fields[2];
        const output_prefix_len = range_fields[3];
        if (offset + worker_id_len + cursor_len + last_error_len + range_lower_len + range_upper_len + output_prefix_len != raw.len) return null;
        const worker_id = raw[offset..][0..worker_id_len];
        offset += worker_id_len;
        const cursor = raw[offset..][0..cursor_len];
        offset += cursor_len;
        const last_error = raw[offset..][0..last_error_len];
        offset += last_error_len;
        const range_lower = raw[offset..][0..range_lower_len];
        offset += range_lower_len;
        const range_upper = raw[offset..][0..range_upper_len];
        offset += range_upper_len;
        const output_prefix = raw[offset..][0..output_prefix_len];
        return .{
            .job_id = job_id,
            .phase = phase,
            .iteration = @intCast(iteration_raw),
            .page_id = page_id,
            .state = state,
            .range_kind = range_kind,
            .range_lower = range_lower,
            .range_upper = range_upper,
            .output_prefix = output_prefix,
            .worker_id = worker_id,
            .lease_expires_at_ms = lease_expires_at_ms,
            .attempt = attempt,
            .cursor = cursor,
            .completed_units = completed_units,
            .total_units = total_units,
            .last_error = last_error,
            .output_fingerprint = output_fingerprint,
            .max_delta = max_delta,
            .total_delta = total_delta,
            .rank_sum = rank_sum,
            .converged = converged,
        };
