            event.at_ms,
            event.target_edge_generation,
            event.published_generation,
            event.score_count,
        }) |value| {
            std.mem.writeInt(u64, out[offset..][0..8], value, .little);
            offset += 8;
        }
    }

    fn decodeGraphMetricEvent(sequence: u64, raw: []const u8) ?GraphMetricEvent {
        if (raw.len != graph_metric_event_encoded_len) return null;
        var offset: usize = 0;
        const kind_raw = std.mem.readInt(u64, raw[offset..][0..8], .little);
        offset += 8;
        const kind: GraphMetricEventKind = switch (kind_raw) {
            @intFromEnum(GraphMetricEventKind.publish) => .publish,
            @intFromEnum(GraphMetricEventKind.delete) => .delete,
            @intFromEnum(GraphMetricEventKind.pause) => .pause,
            @intFromEnum(GraphMetricEventKind.@"resume") => .@"resume",
            @intFromEnum(GraphMetricEventKind.failed) => .failed,
            else => return null,
        };
        const at_ms = std.mem.readInt(u64, raw[offset..][0..8], .little);
        offset += 8;
        const target_edge_generation = std.mem.readInt(u64, raw[offset..][0..8], .little);
        offset += 8;
        const published_generation = std.mem.readInt(u64, raw[offset..][0..8], .little);
        offset += 8;
        return .{
            .sequence = sequence,
            .kind = kind,
            .at_ms = at_ms,
            .target_edge_generation = target_edge_generation,
            .published_generation = published_generation,
            .score_count = std.mem.readInt(u64, raw[offset..][0..8], .little),
        };
    }

    fn putF64(batch: anytype, key: []const u8, value: f64) !void {
        var buf: [8]u8 = undefined;
        std.mem.writeInt(u64, &buf, @bitCast(value), .little);
        try batch.put(key, &buf);
    }

    fn decodeF64(raw: []const u8) ?f64 {
        if (raw.len < 8) return null;
        const bits = std.mem.readInt(u64, raw[0..8], .little);
        return @bitCast(bits);
    }

    fn readF64OrZero(txn: anytype, key: []const u8) !f64 {
        const raw = txn.get(key) catch |err| switch (err) {
            error.NotFound => return 0.0,
            else => return err,
        };
        return decodeF64(raw) orelse 0.0;
    }

    fn metricConfig(self: *const GraphIndex, metric_name: []const u8) ?GraphMetricConfig {
        for (self.metric_configs) |cfg| {
            if (std.mem.eql(u8, cfg.name, metric_name)) return cfg;
        }
        return null;
    }

    fn graphMetricEdgeAllowed(filter: GraphMetricEdgeFilter, edge_type: []const u8) bool {
        return switch (filter.mode) {
            .all => true,
            .types => filter.includesType(edge_type),
        };
    }

    fn graphMetricEdgeFiltersEqual(a: GraphMetricEdgeFilter, b: GraphMetricEdgeFilter) bool {
        return a.equivalent(b);
    }

    fn graphMetricConfigFingerprintHashU64(hasher: *std.hash.Wyhash, value: u64) void {
        var raw = value;
        hasher.update(std.mem.asBytes(&raw));
    }

    fn graphMetricConfigFingerprint(cfg: GraphMetricConfig) u64 {
        var hasher = std.hash.Wyhash.init(0);
        graphMetricConfigFingerprintHashU64(&hasher, @intFromEnum(cfg.kind));
        graphMetricConfigFingerprintHashU64(&hasher, @as(u64, @bitCast(cfg.damping)));
        graphMetricConfigFingerprintHashU64(&hasher, @as(u64, @bitCast(cfg.tolerance)));
        graphMetricConfigFingerprintHashU64(&hasher, cfg.max_iterations);
        graphMetricConfigFingerprintHashU64(&hasher, @intFromEnum(cfg.edge_filter.mode));
        graphMetricConfigFingerprintHashU64(&hasher, cfg.edge_filter.types.len);
        var last: ?[]const u8 = null;
        var emitted: usize = 0;
        while (emitted < cfg.edge_filter.types.len) {
            const edge_type = nextGraphMetricEdgeFilterType(cfg.edge_filter.types, last) orelse break;
            graphMetricConfigFingerprintHashU64(&hasher, edge_type.len);
            hasher.update(edge_type);
            last = edge_type;
            emitted += 1;
        }
        return hasher.final();
    }

    fn nextGraphMetricEdgeFilterType(types: []const []const u8, last: ?[]const u8) ?[]const u8 {
        var next: ?[]const u8 = null;
        for (types) |edge_type| {
            if (last) |prior| {
                if (std.mem.order(u8, edge_type, prior) != .gt) continue;
            }
            if (next == null or std.mem.lessThan(u8, edge_type, next.?)) {
                next = edge_type;
            }
        }
        return next;
    }

    fn graphMetricScoresFingerprint(scores: []const GraphMetricScore) u64 {
        var hasher = std.hash.Wyhash.init(0);
        graphMetricConfigFingerprintHashU64(&hasher, scores.len);
        for (scores) |score| {
            graphMetricConfigFingerprintHashU64(&hasher, score.node.len);
            hasher.update(score.node);
            graphMetricConfigFingerprintHashU64(&hasher, @as(u64, @bitCast(score.score)));
        }
        return hasher.final();
    }

    fn graphMetricBuildPhaseFromRaw(phase_raw: u64) ?GraphMetricBuildPhase {
        return switch (phase_raw) {
            @intFromEnum(GraphMetricBuildPhase.idle) => .idle,
            @intFromEnum(GraphMetricBuildPhase.computing) => .computing,
            @intFromEnum(GraphMetricBuildPhase.publishing) => .publishing,
            @intFromEnum(GraphMetricBuildPhase.complete) => .complete,
            @intFromEnum(GraphMetricBuildPhase.prepare_generation) => .prepare_generation,
            @intFromEnum(GraphMetricBuildPhase.scan_edges_and_out_degree) => .scan_edges_and_out_degree,
            @intFromEnum(GraphMetricBuildPhase.initialize_ranks) => .initialize_ranks,
            @intFromEnum(GraphMetricBuildPhase.iterate_contributions) => .iterate_contributions,
            @intFromEnum(GraphMetricBuildPhase.reduce_ranks) => .reduce_ranks,
            @intFromEnum(GraphMetricBuildPhase.hits_hub_contributions) => .hits_hub_contributions,
            @intFromEnum(GraphMetricBuildPhase.hits_hub_reduce_ranks) => .hits_hub_reduce_ranks,
            @intFromEnum(GraphMetricBuildPhase.check_convergence) => .check_convergence,
            @intFromEnum(GraphMetricBuildPhase.publish_generation) => .publish_generation,
            @intFromEnum(GraphMetricBuildPhase.cleanup_old_generations) => .cleanup_old_generations,
            else => null,
        };
    }

    fn graphMetricBuildManifestPhases(kind: GraphMetricKind) []const GraphMetricBuildPhase {
        return switch (kind) {
            .degree => graph_metric_degree_build_phases[0..],
            .pagerank, .eigenvector => graph_metric_iterative_build_phases[0..],
            .hits_authority, .hits_hub => graph_metric_hits_build_phases[0..],
        };
    }

    fn graphMetricKindIsIterative(kind: GraphMetricKind) bool {
        return switch (kind) {
            .pagerank, .eigenvector, .hits_authority, .hits_hub => true,
            .degree => false,
        };
    }

    fn graphMetricBuildManifestNextPhase(kind: GraphMetricKind, phase: GraphMetricBuildPhase) ?GraphMetricBuildPhase {
        const phases = graphMetricBuildManifestPhases(kind);
        for (phases, 0..) |candidate, i| {
            if (candidate != phase) continue;
            if (i + 1 >= phases.len) return null;
            return phases[i + 1];
        }
        return null;
    }

    fn graphMetricBuildManifestPhaseUnits(phase: GraphMetricBuildPhase, edge_count: u64, node_count: u64) u64 {
        return switch (phase) {
            .scan_edges_and_out_degree, .iterate_contributions, .hits_hub_contributions => edge_count,
            .initialize_ranks, .reduce_ranks, .hits_hub_reduce_ranks, .check_convergence => node_count,
            .prepare_generation, .publish_generation, .cleanup_old_generations => 1,
            .idle, .computing, .publishing, .complete => 0,
        };
    }

    fn graphMetricBuildManifestPhaseRangeKind(phase: GraphMetricBuildPhase) GraphMetricBuildPageRangeKind {
        return switch (phase) {
            .scan_edges_and_out_degree, .iterate_contributions, .hits_hub_contributions => .reverse_edges,
            .initialize_ranks, .reduce_ranks, .hits_hub_reduce_ranks, .check_convergence => .nodes,
            .publish_generation, .cleanup_old_generations => .job_control,
            .prepare_generation, .idle, .computing, .publishing, .complete => .full,
        };
    }

    fn graphMetricBuildJobId(metric_name: []const u8, target_generation: u64, started_at_ms: u64) u64 {
        var hasher = std.hash.Wyhash.init(0xA17F_6D3B_2C91_5E44);
        hasher.update(metric_name);
        graphMetricConfigFingerprintHashU64(&hasher, target_generation);
        graphMetricConfigFingerprintHashU64(&hasher, started_at_ms);
        const id = hasher.final();
        return if (id == 0) 1 else id;
    }

    fn graphMetricActiveBuildProgress(cfg: GraphMetricConfig, phase: GraphMetricBuildPhase, iteration: u32) f64 {
        return switch (phase) {
            .idle => 0.0,
            .prepare_generation => 0.01,
            .scan_edges_and_out_degree => 0.05,
            .initialize_ranks => 0.1,
            .computing => blk: {
                if (iteration == 0 or cfg.max_iterations == 0) break :blk 0.01;
                const progress = @as(f64, @floatFromInt(iteration)) / @as(f64, @floatFromInt(cfg.max_iterations));
                break :blk @min(0.98, @max(0.01, progress));
            },
            .iterate_contributions => blk: {
                if (iteration == 0 or cfg.max_iterations == 0) break :blk 0.1;
                const progress = @as(f64, @floatFromInt(iteration)) / @as(f64, @floatFromInt(cfg.max_iterations));
                break :blk @min(0.9, @max(0.1, progress));
            },
            .reduce_ranks => 0.92,
            .hits_hub_contributions => 0.93,
            .hits_hub_reduce_ranks => 0.94,
            .check_convergence => 0.95,
            .publishing, .publish_generation => 0.99,
            .cleanup_old_generations => 0.995,
            .complete => 1.0,
        };
    }

    const PageRankNode = struct {
        key: []u8,
        rank: f64,
        next_rank: f64 = 0.0,
        out_degree: u64 = 0,
    };

    const PageRankEdge = struct {
        source: usize,
        target: usize,
    };

    const PageRankInitializeNode = struct {
        node: []const u8,
        out_degree: u64 = 0,
    };

    const DegreeNode = struct {
        key: []u8,
        degree: u64 = 0,
    };

    fn getOrPutPageRankNode(
        self: *GraphIndex,
        map: *std.StringHashMapUnmanaged(usize),
        nodes: *std.ArrayListUnmanaged(PageRankNode),
        key: []const u8,
    ) !usize {
        if (map.get(key)) |idx| return idx;
        const owned = try self.alloc.dupe(u8, key);
        errdefer self.alloc.free(owned);
        const idx = nodes.items.len;
        try nodes.append(self.alloc, .{ .key = owned, .rank = 0.0 });
        errdefer _ = nodes.pop();
        try map.put(self.alloc, owned, idx);
        return idx;
    }

    fn getOrPutDegreeNode(
        self: *GraphIndex,
        map: *std.StringHashMapUnmanaged(usize),
        nodes: *std.ArrayListUnmanaged(DegreeNode),
        key: []const u8,
    ) !usize {
        if (map.get(key)) |idx| return idx;
        const owned = try self.alloc.dupe(u8, key);
        errdefer self.alloc.free(owned);
        const idx = nodes.items.len;
        try nodes.append(self.alloc, .{ .key = owned });
        errdefer _ = nodes.pop();
        try map.put(self.alloc, owned, idx);
        return idx;
    }

    fn freePageRankNodes(self: *GraphIndex, nodes: []PageRankNode) void {
        for (nodes) |node| self.alloc.free(node.key);
    }

    fn freeDegreeNodes(self: *GraphIndex, nodes: []DegreeNode) void {
        for (nodes) |node| self.alloc.free(node.key);
    }

    fn collectPageRankGraph(
        self: *GraphIndex,
        filter: GraphMetricEdgeFilter,
        nodes: *std.ArrayListUnmanaged(PageRankNode),
        edges: *std.ArrayListUnmanaged(PageRankEdge),
    ) !void {
        var map = std.StringHashMapUnmanaged(usize).empty;
        defer map.deinit(self.alloc);

        var txn = try self.beginReadReverseTxn();
        defer txn.abort();
        var cur = try txn.openCursor();
        defer cur.close();
        var entry_opt = try cur.first();
        while (entry_opt) |entry| : (entry_opt = try cur.next()) {
            if (std.mem.startsWith(u8, entry.key, graph_meta_prefix)) continue;
            var parsed = (try parseReverseEdgeKeyAlloc(self.alloc, entry.key)) orelse continue;
            defer parsed.deinit(self.alloc);
            if (!std.mem.eql(u8, parsed.index_name, self.index_name)) continue;
            if (!graphMetricEdgeAllowed(filter, parsed.edge_type)) continue;
            const source_idx = try self.getOrPutPageRankNode(&map, nodes, parsed.source);
            const target_idx = try self.getOrPutPageRankNode(&map, nodes, parsed.target);
            nodes.items[source_idx].out_degree += 1;
            try edges.append(self.alloc, .{ .source = source_idx, .target = target_idx });
        }
    }

    fn collectDegreeGraph(
        self: *GraphIndex,
        filter: GraphMetricEdgeFilter,
        nodes: *std.ArrayListUnmanaged(DegreeNode),
    ) !void {
        var map = std.StringHashMapUnmanaged(usize).empty;
        defer map.deinit(self.alloc);

        var txn = try self.beginReadReverseTxn();
        defer txn.abort();
        var cur = try txn.openCursor();
        defer cur.close();
        var entry_opt = try cur.first();
        while (entry_opt) |entry| : (entry_opt = try cur.next()) {
            if (std.mem.startsWith(u8, entry.key, graph_meta_prefix)) continue;
            var parsed = (try parseReverseEdgeKeyAlloc(self.alloc, entry.key)) orelse continue;
            defer parsed.deinit(self.alloc);
            if (!std.mem.eql(u8, parsed.index_name, self.index_name)) continue;
            if (!graphMetricEdgeAllowed(filter, parsed.edge_type)) continue;
            const source_idx = try self.getOrPutDegreeNode(&map, nodes, parsed.source);
            const target_idx = try self.getOrPutDegreeNode(&map, nodes, parsed.target);
            nodes.items[source_idx].degree += 1;
            nodes.items[target_idx].degree += 1;
        }
    }

    fn putPageRankScanNode(
        self: *GraphIndex,
        nodes: *std.StringHashMapUnmanaged(void),
        node: []const u8,
    ) !void {
        const result = try nodes.getOrPut(self.alloc, node);
        if (result.found_existing) return;
        result.key_ptr.* = try self.alloc.dupe(u8, node);
        result.value_ptr.* = {};
    }

    fn freeStringHashMapKeys(self: *GraphIndex, comptime V: type, map: *std.StringHashMapUnmanaged(V)) void {
        var key_it = map.keyIterator();
        while (key_it.next()) |key_ptr| self.alloc.free(key_ptr.*);
        map.deinit(self.alloc);
    }

    fn graphMetricPageRankScanFingerprint(page: GraphMetricBuildPage, scanned_units: u64, node_count: usize, out_degree_total: u64) u64 {
        var hasher = std.hash.Wyhash.init(0xD392_8A6D_7C51_10EF);
        graphMetricConfigFingerprintHashU64(&hasher, page.page_id);
        graphMetricConfigFingerprintHashU64(&hasher, page.iteration);
        graphMetricConfigFingerprintHashU64(&hasher, scanned_units);
        graphMetricConfigFingerprintHashU64(&hasher, @intCast(node_count));
        graphMetricConfigFingerprintHashU64(&hasher, out_degree_total);
        return hasher.final();
    }

    fn graphMetricPageRankInitializeFingerprint(page: GraphMetricBuildPage, node_count: usize, out_degree_total: u64, rank_sum: f64) u64 {
        var hasher = std.hash.Wyhash.init(0x69D0_CAA5_410C_F81B);
        graphMetricConfigFingerprintHashU64(&hasher, page.page_id);
        graphMetricConfigFingerprintHashU64(&hasher, page.iteration);
        graphMetricConfigFingerprintHashU64(&hasher, @intCast(node_count));
        graphMetricConfigFingerprintHashU64(&hasher, out_degree_total);
        graphMetricConfigFingerprintHashU64(&hasher, @bitCast(rank_sum));
        return hasher.final();
    }

    fn graphMetricPageRankContributionFingerprint(page: GraphMetricBuildPage, scanned_units: u64, target_count: usize, contribution_sum: f64) u64 {
        var hasher = std.hash.Wyhash.init(0xA755_7F0A_3E41_C2BD);
        graphMetricConfigFingerprintHashU64(&hasher, page.page_id);
        graphMetricConfigFingerprintHashU64(&hasher, page.iteration);
        graphMetricConfigFingerprintHashU64(&hasher, scanned_units);
        graphMetricConfigFingerprintHashU64(&hasher, @intCast(target_count));
        graphMetricConfigFingerprintHashU64(&hasher, @bitCast(contribution_sum));
        return hasher.final();
    }

    fn graphMetricPageRankReduceFingerprint(page: GraphMetricBuildPage, node_count: usize, contribution_sum: f64, rank_sum: f64) u64 {
        var hasher = std.hash.Wyhash.init(0xE50F_0C79_924B_A365);
        graphMetricConfigFingerprintHashU64(&hasher, page.page_id);
        graphMetricConfigFingerprintHashU64(&hasher, page.iteration);
        graphMetricConfigFingerprintHashU64(&hasher, @intCast(node_count));
        graphMetricConfigFingerprintHashU64(&hasher, @bitCast(contribution_sum));
        graphMetricConfigFingerprintHashU64(&hasher, @bitCast(rank_sum));
        return hasher.final();
    }

    fn graphMetricPageRankConvergenceFingerprint(page: GraphMetricBuildPage, node_count: usize, max_delta: f64, total_delta: f64, rank_sum: f64) u64 {
        var hasher = std.hash.Wyhash.init(0xC7AE_4085_6E22_A91F);
        graphMetricConfigFingerprintHashU64(&hasher, page.page_id);
        graphMetricConfigFingerprintHashU64(&hasher, page.iteration);
        graphMetricConfigFingerprintHashU64(&hasher, @intCast(node_count));
        graphMetricConfigFingerprintHashU64(&hasher, @bitCast(max_delta));
        graphMetricConfigFingerprintHashU64(&hasher, @bitCast(total_delta));
        graphMetricConfigFingerprintHashU64(&hasher, @bitCast(rank_sum));
        return hasher.final();
    }

    fn graphMetricHitsHubRawEntryFingerprint(node: []const u8, raw_hub: f64) u64 {
        var hasher = std.hash.Wyhash.init(0x4E43_C711_D637_AE19);
        graphMetricConfigFingerprintHashU64(&hasher, node.len);
        hasher.update(node);
        graphMetricConfigFingerprintHashU64(&hasher, @bitCast(raw_hub));
        const fingerprint = hasher.final();
        return if (fingerprint == 0) 1 else fingerprint;
    }

    fn graphMetricHitsHubRawSummaryFingerprint(metric_name: []const u8, cfg: GraphMetricConfig, job_id: u64, iteration: u32, authority_norm: f64, count: usize, hub_norm: f64, raw_fingerprint: u64) u64 {
        var hasher = std.hash.Wyhash.init(0xB56A_0FA2_C4DD_7189);
        graphMetricConfigFingerprintHashU64(&hasher, metric_name.len);
        hasher.update(metric_name);
        graphMetricConfigFingerprintHashU64(&hasher, graphMetricConfigFingerprint(cfg));
        graphMetricConfigFingerprintHashU64(&hasher, job_id);
        graphMetricConfigFingerprintHashU64(&hasher, iteration);
        graphMetricConfigFingerprintHashU64(&hasher, @bitCast(authority_norm));
        graphMetricConfigFingerprintHashU64(&hasher, @intCast(count));
        graphMetricConfigFingerprintHashU64(&hasher, @bitCast(hub_norm));
        graphMetricConfigFingerprintHashU64(&hasher, raw_fingerprint);
        const fingerprint = hasher.final();
        return if (fingerprint == 0) 1 else fingerprint;
    }

    fn graphMetricHitsReduceFingerprint(page: GraphMetricBuildPage, node_count: usize, contribution_sum: f64, rank_sum: f64, hub_summary: HitsHubRawSummary) u64 {
        var hasher = std.hash.Wyhash.init(0x8ECA_74E5_5BB7_0D31);
        graphMetricConfigFingerprintHashU64(&hasher, page.page_id);
        graphMetricConfigFingerprintHashU64(&hasher, page.iteration);
        graphMetricConfigFingerprintHashU64(&hasher, @intCast(node_count));
        graphMetricConfigFingerprintHashU64(&hasher, @bitCast(contribution_sum));
        graphMetricConfigFingerprintHashU64(&hasher, @bitCast(rank_sum));
        graphMetricConfigFingerprintHashU64(&hasher, @intCast(hub_summary.count));
        graphMetricConfigFingerprintHashU64(&hasher, @bitCast(hub_summary.norm));
        graphMetricConfigFingerprintHashU64(&hasher, hub_summary.fingerprint);
        const fingerprint = hasher.final();
        return if (fingerprint == 0) 1 else fingerprint;
    }

    fn collectPageRankScannedNodes(
        self: *GraphIndex,
        txn: anytype,
        metric_name: []const u8,
        job_id: u64,
        out: *std.ArrayListUnmanaged([]u8),
    ) !void {
        const manifest = try self.metricBuildManifest(txn, metric_name, job_id) orelse return error.GraphMetricBuildManifestNotFound;
        var graph_nodes = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (graph_nodes.items) |node| self.alloc.free(node);
            graph_nodes.deinit(self.alloc);
        }
        try self.collectGraphNodeKeysInBatch(txn, &graph_nodes);
        for (graph_nodes.items) |node| {
            var page_id: u64 = 0;
            while (page_id <= manifest.page_count) : (page_id += 1) {
                const key = try self.graphMetricBuildPageRankNodePartialKeyAlloc(metric_name, job_id, node, page_id);
                defer self.alloc.free(key);
                if ((try readU64OrZero(txn, key)) == 0) continue;
                if (!pageRankNodeListContains(out.items, node)) {
                    try out.append(self.alloc, try self.alloc.dupe(u8, node));
                }
                break;
            }
        }
    }

    fn pageRankNodeListContains(nodes: []const []u8, needle: []const u8) bool {
        for (nodes) |node| {
            if (std.mem.eql(u8, node, needle)) return true;
        }
        return false;
    }

    fn aggregatePageRankOutDegreeForNode(
        self: *GraphIndex,
        txn: anytype,
        metric_name: []const u8,
        job_id: u64,
        node: []const u8,
    ) !u64 {
        const manifest = try self.metricBuildManifest(txn, metric_name, job_id) orelse return error.GraphMetricBuildManifestNotFound;
        var total: u64 = 0;
        var page_id: u64 = 0;
        while (page_id <= manifest.page_count) : (page_id += 1) {
            const partial_key = try self.graphMetricBuildPageRankOutDegreePartialKeyAlloc(metric_name, job_id, node, page_id);
            defer self.alloc.free(partial_key);
            total += try readU64OrZero(txn, partial_key);
        }
        return total;
    }

    fn aggregatePageRankContributionForNode(
        self: *GraphIndex,
        txn: anytype,
        metric_name: []const u8,
        job_id: u64,
        iteration: u32,
        node: []const u8,
    ) !f64 {
        const manifest = try self.metricBuildManifest(txn, metric_name, job_id) orelse return error.GraphMetricBuildManifestNotFound;
        var total: f64 = 0.0;
        var page_id: u64 = 0;
        while (page_id <= manifest.page_count) : (page_id += 1) {
            const contribution_key = try self.graphMetricBuildPageRankContributionKeyAlloc(metric_name, job_id, iteration, node, page_id);
            defer self.alloc.free(contribution_key);
            const value = try readF64OrZero(txn, contribution_key);
            if (!std.math.isFinite(value)) return error.InvalidGraphMetricScore;
            total += value;
        }
        return total;
    }

    fn executePageRankScanBuildPage(
        self: *GraphIndex,
        metric_name: []const u8,
        cfg: GraphMetricConfig,
        job: GraphMetricBuildJob,
        page: GraphMetricBuildPage,
    ) !usize {
        return try self.executePageRankScanBuildPageWithLimit(metric_name, cfg, job, page, null);
    }

    fn executePageRankScanBuildPageWithLimit(
        self: *GraphIndex,
        metric_name: []const u8,
        cfg: GraphMetricConfig,
        job: GraphMetricBuildJob,
        page: GraphMetricBuildPage,
        max_scan_units: ?u64,
    ) !usize {
        var out_degrees = std.StringHashMapUnmanaged(u64).empty;
        defer self.freeStringHashMapKeys(u64, &out_degrees);
        var nodes = std.StringHashMapUnmanaged(void).empty;
        defer self.freeStringHashMapKeys(void, &nodes);

        var scanned_units: u64 = 0;
        var prior_completed_units: u64 = 0;
        var page_attempt = page.attempt;
        var reached_page_end = true;
        var last_scanned_key: []u8 = "";
        defer if (last_scanned_key.len > 0) self.alloc.free(last_scanned_key);
        {
            var txn = try self.beginReadReverseTxn();
            defer txn.abort();
            const execution_page = try self.metricBuildPage(&txn, metric_name, job.job_id, .scan_edges_and_out_degree, page.iteration, page.page_id) orelse page;
            try self.validateGraphMetricBuildPageExecutionLease(page, execution_page);
            prior_completed_units = execution_page.completed_units;
            page_attempt = execution_page.attempt;
            var cur = try txn.openCursor();
            defer cur.close();
            const resume_cursor = execution_page.cursor;
            const seek_key = if (resume_cursor.len > 0) resume_cursor else execution_page.range_lower;
            var entry_opt = if (seek_key.len > 0) try cur.seekAtOrAfter(seek_key) else try cur.first();
            while (entry_opt) |entry| : (entry_opt = try cur.next()) {
                if (resume_cursor.len > 0 and std.mem.order(u8, entry.key, resume_cursor) != .gt) continue;
                if (execution_page.range_upper.len > 0 and std.mem.order(u8, entry.key, execution_page.range_upper) != .lt) break;
                if (std.mem.startsWith(u8, entry.key, graph_meta_prefix)) continue;
                var parsed = (try parseReverseEdgeKeyAlloc(self.alloc, entry.key)) orelse continue;
                defer parsed.deinit(self.alloc);
                if (!std.mem.eql(u8, parsed.index_name, self.index_name)) continue;
                if (max_scan_units) |limit| {
                    if (scanned_units >= limit) {
                        reached_page_end = false;
                        break;
                    }
                }
                scanned_units += 1;
                if (last_scanned_key.len > 0) self.alloc.free(last_scanned_key);
                last_scanned_key = try self.alloc.dupe(u8, entry.key);
                if (!graphMetricEdgeAllowed(cfg.edge_filter, parsed.edge_type)) continue;
                try self.putPageRankScanNode(&nodes, parsed.source);
                try self.putPageRankScanNode(&nodes, parsed.target);
                const out_degree = try out_degrees.getOrPut(self.alloc, parsed.source);
                if (out_degree.found_existing) {
                    out_degree.value_ptr.* += 1;
                } else {
                    out_degree.key_ptr.* = try self.alloc.dupe(u8, parsed.source);
                    out_degree.value_ptr.* = 1;
                }
            }
        }

        const completed_units_raw = prior_completed_units + scanned_units;
        const completed_units = if (page.total_units != 0) @min(completed_units_raw, page.total_units) else completed_units_raw;
        const worker_id = if (page.worker_id.len != 0) page.worker_id else graph_metric_local_build_worker_id;
        var write_page = page;
        write_page.attempt = page_attempt;
        const out_degree_total = try self.writePageRankScanPartialsForAttempt(metric_name, job, write_page, prior_completed_units, &out_degrees, &nodes, reached_page_end);
        const fingerprint = graphMetricPageRankScanFingerprint(page, completed_units, nodes.count(), out_degree_total);
        if (!reached_page_end) {
            _ = try self.updateGraphMetricBuildPageProgressForAttempt(metric_name, job.job_id, .scan_edges_and_out_degree, page.iteration, page.page_id, worker_id, page.attempt, last_scanned_key, completed_units, page.total_units);
            return nodes.count();
        }
        const complete_units = if (page.total_units != 0) page.total_units else completed_units;
        _ = try self.updateGraphMetricBuildPageProgressForAttempt(metric_name, job.job_id, .scan_edges_and_out_degree, page.iteration, page.page_id, worker_id, page.attempt, "", completed_units, page.total_units);
        _ = try self.completeGraphMetricBuildPageForAttempt(metric_name, job.job_id, .scan_edges_and_out_degree, page.iteration, page.page_id, worker_id, page.attempt, complete_units, fingerprint);
        return nodes.count();
    }

    fn writePageRankScanPartialsForAttempt(
        self: *GraphIndex,
        metric_name: []const u8,
        job: GraphMetricBuildJob,
        claimed_page: GraphMetricBuildPage,
        prior_completed_units: u64,
        out_degrees: *std.StringHashMapUnmanaged(u64),
        nodes: *std.StringHashMapUnmanaged(void),
        adopt_on_complete: bool,
    ) !u64 {
        var batch = try self.beginWriteReverseBatch();
        errdefer batch.abort();
        const current_page = try self.metricBuildPage(&batch, metric_name, job.job_id, .scan_edges_and_out_degree, claimed_page.iteration, claimed_page.page_id) orelse return error.GraphMetricBuildPageNotFound;
        try self.validateGraphMetricBuildPageExecutionLease(claimed_page, current_page);

        var out_degree_total: u64 = 0;
        var out_it = out_degrees.iterator();
        while (out_it.next()) |entry| {
            out_degree_total += entry.value_ptr.*;
            const key = try self.graphMetricBuildAttemptPageRankOutDegreePartialKeyAlloc(metric_name, job.job_id, .scan_edges_and_out_degree, claimed_page.iteration, claimed_page.page_id, claimed_page.attempt, entry.key_ptr.*);
            defer self.alloc.free(key);
            const prior = if (prior_completed_units != 0) try readU64OrZero(&batch, key) else 0;
            try putU64(&batch, key, prior + entry.value_ptr.*);
        }
        var node_it = nodes.keyIterator();
        while (node_it.next()) |node_ptr| {
            const key = try self.graphMetricBuildAttemptPageRankNodePartialKeyAlloc(metric_name, job.job_id, .scan_edges_and_out_degree, claimed_page.iteration, claimed_page.page_id, claimed_page.attempt, node_ptr.*);
            defer self.alloc.free(key);
            try putU64(&batch, key, 1);
        }
        if (adopt_on_complete) {
            _ = try self.adoptPageRankScanAttemptOutputInBatch(&batch, metric_name, job.job_id, claimed_page);
        }
        try batch.commit();
        return out_degree_total;
    }

    fn executePageRankInitializeBuildPage(
        self: *GraphIndex,
        metric_name: []const u8,
        job: GraphMetricBuildJob,
        page: GraphMetricBuildPage,
    ) !usize {
        var range_lower: []u8 = "";
        defer if (range_lower.len > 0) self.alloc.free(range_lower);
        var range_upper: []u8 = "";
        defer if (range_upper.len > 0) self.alloc.free(range_upper);
        var total_units = page.total_units;
        {
            var txn = try self.beginReadReverseTxn();
            defer txn.abort();
            const execution_page = try self.metricBuildPage(&txn, metric_name, job.job_id, .initialize_ranks, page.iteration, page.page_id) orelse page;
            try self.validateGraphMetricBuildPageExecutionLease(page, execution_page);
            if (execution_page.range_lower.len > 0) range_lower = try self.alloc.dupe(u8, execution_page.range_lower);
            if (execution_page.range_upper.len > 0) range_upper = try self.alloc.dupe(u8, execution_page.range_upper);
            total_units = execution_page.total_units;
        }

        var nodes = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (nodes.items) |node| self.alloc.free(node);
            nodes.deinit(self.alloc);
        }
        {
            var txn = try self.beginReadReverseTxn();
            defer txn.abort();
            try self.collectPageRankScannedNodes(&txn, metric_name, job.job_id, &nodes);
        }

        const total_nodes = nodes.items.len;
        const initial_rank = if (total_nodes == 0) 0.0 else 1.0 / @as(f64, @floatFromInt(total_nodes));
        var initialized_nodes: usize = 0;
        var out_degree_total: u64 = 0;
        var rank_sum: f64 = 0.0;
        var initialized = std.ArrayListUnmanaged(PageRankInitializeNode).empty;
        defer initialized.deinit(self.alloc);
        {
            var read_txn = try self.beginReadReverseTxn();
            defer read_txn.abort();
            for (nodes.items) |node| {
                if (range_lower.len > 0 and std.mem.order(u8, node, range_lower) == .lt) continue;
                if (range_upper.len > 0 and std.mem.order(u8, node, range_upper) != .lt) continue;
                const out_degree = try self.aggregatePageRankOutDegreeForNode(&read_txn, metric_name, job.job_id, node);
                out_degree_total += out_degree;
                initialized_nodes += 1;
                rank_sum += initial_rank;
                try initialized.append(self.alloc, .{ .node = node, .out_degree = out_degree });
            }
        }
        try self.writePageRankInitializeOutputForAttempt(metric_name, job, page, initialized.items, initial_rank);

        const worker_id = if (page.worker_id.len != 0) page.worker_id else graph_metric_local_build_worker_id;
        const completed_units = if (total_units != 0) total_units else @as(u64, @intCast(initialized_nodes));
        const cursor = try std.fmt.allocPrint(self.alloc, "pagerank-initialize:nodes={d};rank_sum={d}", .{ initialized_nodes, rank_sum });
        defer self.alloc.free(cursor);
        const fingerprint = graphMetricPageRankInitializeFingerprint(page, initialized_nodes, out_degree_total, rank_sum);
        _ = try self.updateGraphMetricBuildPageProgressForAttempt(metric_name, job.job_id, .initialize_ranks, page.iteration, page.page_id, worker_id, page.attempt, cursor, completed_units, total_units);
        _ = try self.completeGraphMetricBuildPageForAttempt(metric_name, job.job_id, .initialize_ranks, page.iteration, page.page_id, worker_id, page.attempt, completed_units, fingerprint);
        return initialized_nodes;
    }

    fn writePageRankInitializeOutputForAttempt(
        self: *GraphIndex,
        metric_name: []const u8,
        job: GraphMetricBuildJob,
        claimed_page: GraphMetricBuildPage,
        initialized: []const PageRankInitializeNode,
        initial_rank: f64,
    ) !void {
        var batch = try self.beginWriteReverseBatch();
        errdefer batch.abort();
        const current_page = try self.metricBuildPage(&batch, metric_name, job.job_id, .initialize_ranks, claimed_page.iteration, claimed_page.page_id) orelse return error.GraphMetricBuildPageNotFound;
        try self.validateGraphMetricBuildPageExecutionLease(claimed_page, current_page);
        if (!std.math.isFinite(initial_rank)) return error.InvalidGraphMetricScore;
        for (initialized) |entry| {
            const out_degree_key = try self.graphMetricBuildPageRankOutDegreeKeyAlloc(metric_name, job.job_id, entry.node);
            defer self.alloc.free(out_degree_key);
            try putU64(&batch, out_degree_key, entry.out_degree);
            const rank_key = try self.graphMetricBuildPageRankKeyAlloc(metric_name, job.job_id, 0, entry.node);
            defer self.alloc.free(rank_key);
            try putF64(&batch, rank_key, initial_rank);
        }
        try batch.commit();
    }

    fn executePageRankContributionBuildPage(
        self: *GraphIndex,
        metric_name: []const u8,
        cfg: GraphMetricConfig,
        job: GraphMetricBuildJob,
        page: GraphMetricBuildPage,
    ) !usize {
        return try self.executePageRankContributionBuildPageWithLimit(metric_name, cfg, job, page, null);
    }

    fn executePageRankContributionBuildPageWithLimit(
        self: *GraphIndex,
        metric_name: []const u8,
        cfg: GraphMetricConfig,
        job: GraphMetricBuildJob,
        page: GraphMetricBuildPage,
        max_scan_units: ?u64,
    ) !usize {
        var contributions = std.StringHashMapUnmanaged(f64).empty;
        defer self.freeStringHashMapKeys(f64, &contributions);
        var scanned_units: u64 = 0;
        var prior_completed_units: u64 = 0;
        var page_attempt = page.attempt;
        var total_units = page.total_units;
        var reached_page_end = true;
        var last_scanned_key: []u8 = "";
        defer if (last_scanned_key.len > 0) self.alloc.free(last_scanned_key);
        var contribution_sum: f64 = 0.0;
        {
            var txn = try self.beginReadReverseTxn();
            defer txn.abort();
            const execution_page = try self.metricBuildPage(&txn, metric_name, job.job_id, .iterate_contributions, page.iteration, page.page_id) orelse page;
            try self.validateGraphMetricBuildPageExecutionLease(page, execution_page);
            prior_completed_units = execution_page.completed_units;
            page_attempt = execution_page.attempt;
            total_units = execution_page.total_units;
            var cur = try txn.openCursor();
            defer cur.close();
            const resume_cursor = execution_page.cursor;
            const seek_key = if (resume_cursor.len > 0) resume_cursor else execution_page.range_lower;
            var entry_opt = if (seek_key.len > 0) try cur.seekAtOrAfter(seek_key) else try cur.first();
            while (entry_opt) |entry| : (entry_opt = try cur.next()) {
                if (resume_cursor.len > 0 and std.mem.order(u8, entry.key, resume_cursor) != .gt) continue;
                if (execution_page.range_upper.len > 0 and std.mem.order(u8, entry.key, execution_page.range_upper) != .lt) break;
                if (std.mem.startsWith(u8, entry.key, graph_meta_prefix)) continue;
                var parsed = (try parseReverseEdgeKeyAlloc(self.alloc, entry.key)) orelse continue;
                defer parsed.deinit(self.alloc);
                if (!std.mem.eql(u8, parsed.index_name, self.index_name)) continue;
                if (max_scan_units) |limit| {
                    if (scanned_units >= limit) {
                        reached_page_end = false;
                        break;
                    }
                }
                scanned_units += 1;
                if (last_scanned_key.len > 0) self.alloc.free(last_scanned_key);
                last_scanned_key = try self.alloc.dupe(u8, entry.key);
                if (!graphMetricEdgeAllowed(cfg.edge_filter, parsed.edge_type)) continue;

                const out_degree_key = try self.graphMetricBuildPageRankOutDegreeKeyAlloc(metric_name, job.job_id, parsed.source);
                defer self.alloc.free(out_degree_key);
                const out_degree = try readU64OrZero(&txn, out_degree_key);
                if (out_degree == 0) continue;

                const rank_key = try self.graphMetricBuildPageRankKeyAlloc(metric_name, job.job_id, page.iteration, parsed.source);
                defer self.alloc.free(rank_key);
                const source_rank = try readF64OrZero(&txn, rank_key);
                if (!std.math.isFinite(source_rank)) return error.InvalidGraphMetricScore;
                const contribution = cfg.damping * source_rank / @as(f64, @floatFromInt(out_degree));
                if (!std.math.isFinite(contribution)) return error.InvalidGraphMetricScore;

                const result = try contributions.getOrPut(self.alloc, parsed.target);
                if (result.found_existing) {
                    result.value_ptr.* += contribution;
                } else {
                    result.key_ptr.* = try self.alloc.dupe(u8, parsed.target);
                    result.value_ptr.* = contribution;
                }
                contribution_sum += contribution;
            }
        }

        var write_page = page;
        write_page.attempt = page_attempt;
        try self.writePageRankContributionAttemptPartialsForAttempt(metric_name, job, write_page, prior_completed_units, &contributions, reached_page_end);

        const worker_id = if (page.worker_id.len != 0) page.worker_id else graph_metric_local_build_worker_id;
        const completed_units_raw = prior_completed_units + scanned_units;
        const completed_units = if (total_units != 0) @min(completed_units_raw, total_units) else completed_units_raw;
        const cursor = try std.fmt.allocPrint(self.alloc, "pagerank-contribution:targets={d};sum={d}", .{ contributions.count(), contribution_sum });
        defer self.alloc.free(cursor);
        const fingerprint = graphMetricPageRankContributionFingerprint(page, scanned_units, contributions.count(), contribution_sum);
        if (!reached_page_end) {
            _ = try self.updateGraphMetricBuildPageProgressForAttempt(metric_name, job.job_id, .iterate_contributions, page.iteration, page.page_id, worker_id, page.attempt, last_scanned_key, completed_units, total_units);
            return contributions.count();
        }
        _ = try self.updateGraphMetricBuildPageProgressForAttempt(metric_name, job.job_id, .iterate_contributions, page.iteration, page.page_id, worker_id, page.attempt, cursor, completed_units, total_units);
        _ = try self.completeGraphMetricBuildPageForAttempt(metric_name, job.job_id, .iterate_contributions, page.iteration, page.page_id, worker_id, page.attempt, completed_units, fingerprint);
        return contributions.count();
    }

    fn writePageRankContributionAttemptPartialsForAttempt(
        self: *GraphIndex,
        metric_name: []const u8,
        job: GraphMetricBuildJob,
        claimed_page: GraphMetricBuildPage,
        prior_completed_units: u64,
        contributions: *std.StringHashMapUnmanaged(f64),
        adopt_on_complete: bool,
    ) !void {
        var batch = try self.beginWriteReverseBatch();
        errdefer batch.abort();
        const current_page = try self.metricBuildPage(&batch, metric_name, job.job_id, .iterate_contributions, claimed_page.iteration, claimed_page.page_id) orelse return error.GraphMetricBuildPageNotFound;
        try self.validateGraphMetricBuildPageExecutionLease(claimed_page, current_page);
        var it = contributions.iterator();
        while (it.next()) |entry| {
            if (!std.math.isFinite(entry.value_ptr.*)) return error.InvalidGraphMetricScore;
            const contribution_key = try self.graphMetricBuildAttemptPageRankContributionKeyAlloc(metric_name, job.job_id, .iterate_contributions, claimed_page.iteration, claimed_page.page_id, claimed_page.attempt, entry.key_ptr.*);
            defer self.alloc.free(contribution_key);
            const prior = if (prior_completed_units != 0) try readF64OrZero(&batch, contribution_key) else 0.0;
            try putF64(&batch, contribution_key, prior + entry.value_ptr.*);
        }
        if (adopt_on_complete) {
            _ = try self.adoptPageRankContributionAttemptOutputInBatch(&batch, metric_name, job.job_id, claimed_page);
        }
        try batch.commit();
    }

    fn executePageRankReduceBuildPage(
        self: *GraphIndex,
        metric_name: []const u8,
        cfg: GraphMetricConfig,
        job: GraphMetricBuildJob,
        page: GraphMetricBuildPage,
    ) !usize {
        return try self.executePageRankReduceBuildPageWithLimit(metric_name, cfg, job, page, null);
    }

    fn executePageRankReduceBuildPageWithLimit(
        self: *GraphIndex,
        metric_name: []const u8,
        cfg: GraphMetricConfig,
        job: GraphMetricBuildJob,
        page: GraphMetricBuildPage,
        max_reduce_units: ?u64,
    ) !usize {
        var range_lower: []u8 = "";
        defer if (range_lower.len > 0) self.alloc.free(range_lower);
        var range_upper: []u8 = "";
        defer if (range_upper.len > 0) self.alloc.free(range_upper);
        var resume_cursor: []u8 = "";
        defer if (resume_cursor.len > 0) self.alloc.free(resume_cursor);
        var prior_completed_units: u64 = 0;
        var total_units = page.total_units;
        {
            var txn = try self.beginReadReverseTxn();
            defer txn.abort();
            const execution_page = try self.metricBuildPage(&txn, metric_name, job.job_id, .reduce_ranks, page.iteration, page.page_id) orelse page;
            try self.validateGraphMetricBuildPageExecutionLease(page, execution_page);
            if (execution_page.range_lower.len > 0) range_lower = try self.alloc.dupe(u8, execution_page.range_lower);
            if (execution_page.range_upper.len > 0) range_upper = try self.alloc.dupe(u8, execution_page.range_upper);
            if (execution_page.cursor.len > 0) resume_cursor = try self.alloc.dupe(u8, execution_page.cursor);
            prior_completed_units = execution_page.completed_units;
            total_units = execution_page.total_units;
        }

        var nodes = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (nodes.items) |node| self.alloc.free(node);
            nodes.deinit(self.alloc);
        }
        {
            var txn = try self.beginReadReverseTxn();
            defer txn.abort();
            try self.collectPageRankScannedNodes(&txn, metric_name, job.job_id, &nodes);
        }

        const total_nodes = nodes.items.len;
        var reduced = std.ArrayListUnmanaged(GraphMetricScore).empty;
        defer reduced.deinit(self.alloc);
        var sink_mass: f64 = 0.0;
        var contribution_sum: f64 = 0.0;
        var rank_sum: f64 = 0.0;
        var reached_page_end = true;
        var last_reduced_node: []u8 = "";
        defer if (last_reduced_node.len > 0) self.alloc.free(last_reduced_node);
        if (total_nodes > 0) {
            const node_count_f = @as(f64, @floatFromInt(total_nodes));
            {
                var read_txn = try self.beginReadReverseTxn();
                defer read_txn.abort();
                for (nodes.items) |node| {
                    const out_degree_key = try self.graphMetricBuildPageRankOutDegreeKeyAlloc(metric_name, job.job_id, node);
                    defer self.alloc.free(out_degree_key);
                    const out_degree = try readU64OrZero(&read_txn, out_degree_key);
                    if (out_degree != 0) continue;
                    const rank_key = try self.graphMetricBuildPageRankKeyAlloc(metric_name, job.job_id, page.iteration, node);
                    defer self.alloc.free(rank_key);
                    const rank = try readF64OrZero(&read_txn, rank_key);
                    if (!std.math.isFinite(rank)) return error.InvalidGraphMetricScore;
                    sink_mass += rank;
                }
            }

            const base = (1.0 - cfg.damping) / node_count_f;
            const sink_contribution = cfg.damping * sink_mass / node_count_f;
            var read_txn = try self.beginReadReverseTxn();
            defer read_txn.abort();
            for (nodes.items) |node| {
                if (range_lower.len > 0 and std.mem.order(u8, node, range_lower) == .lt) continue;
                if (range_upper.len > 0 and std.mem.order(u8, node, range_upper) != .lt) continue;
                if (resume_cursor.len > 0 and std.mem.order(u8, node, resume_cursor) != .gt) continue;
                if (max_reduce_units) |limit| {
                    if (reduced.items.len >= limit) {
                        reached_page_end = false;
                        break;
                    }
                }
                const contribution = try self.aggregatePageRankContributionForNode(&read_txn, metric_name, job.job_id, page.iteration, node);
                contribution_sum += contribution;
                const next_rank = base + sink_contribution + contribution;
                if (!std.math.isFinite(next_rank)) return error.InvalidGraphMetricScore;
                rank_sum += next_rank;
                try reduced.append(self.alloc, .{ .node = node, .score = next_rank });
                if (last_reduced_node.len > 0) self.alloc.free(last_reduced_node);
                last_reduced_node = try self.alloc.dupe(u8, node);
            }
        }

        const worker_id = if (page.worker_id.len != 0) page.worker_id else graph_metric_local_build_worker_id;
        const completed_units_raw = prior_completed_units + @as(u64, @intCast(reduced.items.len));
        const completed_units = if (total_units != 0) @min(completed_units_raw, total_units) else completed_units_raw;
        const cursor = try std.fmt.allocPrint(self.alloc, "pagerank-reduce:nodes={d};rank_sum={d}", .{ reduced.items.len, rank_sum });
        defer self.alloc.free(cursor);
        const fingerprint = graphMetricPageRankReduceFingerprint(page, reduced.items.len, contribution_sum, rank_sum);
        if (!reached_page_end) {
            _ = try self.writeSingleVectorReduceRanksForAttempt(metric_name, job, page, worker_id, last_reduced_node, completed_units, total_units, reduced.items, 0, false);
            return reduced.items.len;
        }
        const complete_units = if (total_units != 0) total_units else completed_units;
        _ = try self.writeSingleVectorReduceRanksForAttempt(metric_name, job, page, worker_id, cursor, complete_units, total_units, reduced.items, fingerprint, true);
        return reduced.items.len;
    }

    fn writeSingleVectorReduceRanksForAttempt(
        self: *GraphIndex,
        metric_name: []const u8,
        job: GraphMetricBuildJob,
        claimed_page: GraphMetricBuildPage,
        worker_id: []const u8,
        cursor: []const u8,
        completed_units: u64,
        total_units: u64,
        ranks: []const GraphMetricScore,
        output_fingerprint: u64,
        complete_page: bool,
    ) !GraphMetricBuildPage {
        var batch = try self.beginWriteReverseBatch();
        errdefer batch.abort();
        var page = try self.metricBuildPage(&batch, metric_name, job.job_id, .reduce_ranks, claimed_page.iteration, claimed_page.page_id) orelse return error.GraphMetricBuildPageNotFound;
        if (page.state == .complete) {
            if (!complete_page or page.attempt != claimed_page.attempt) return error.GraphMetricBuildPageNotLeased;
            if (page.output_fingerprint != output_fingerprint) return error.GraphMetricBuildPageOutputMismatch;
            try batch.commit();
            return page;
        }
        var expected_page = claimed_page;
        expected_page.worker_id = worker_id;
        try self.validateGraphMetricBuildPageExecutionLease(expected_page, page);
        const effective_total_units = if (total_units != 0) total_units else page.total_units;
        if (effective_total_units != 0 and completed_units > effective_total_units) return error.InvalidGraphMetricBuildProgress;

        for (ranks) |score| {
            if (!std.math.isFinite(score.score)) return error.InvalidGraphMetricScore;
            const rank_key = try self.graphMetricBuildPageRankKeyAlloc(metric_name, job.job_id, claimed_page.iteration + 1, score.node);
            defer self.alloc.free(rank_key);
            try putF64(&batch, rank_key, score.score);
        }

        if (try self.metricBuildJob(&batch, metric_name)) |existing_job| {
            if (existing_job.job_id == job.job_id and existing_job.phase == .reduce_ranks and existing_job.iteration == claimed_page.iteration) {
                var progress_job = existing_job;
                progress_job.cursor = cursor;
                progress_job.completed_units = completed_units;
                progress_job.total_units = effective_total_units;
                progress_job.updated_at_ms = @divTrunc(platform_time.realtimeNs(), std.time.ns_per_ms);
                try self.putGraphMetricBuildJobInBatch(&batch, metric_name, progress_job);
            }
        }

        page.completed_units = completed_units;
        page.total_units = effective_total_units;
        page.cursor = cursor;
        page.last_error = "";
        if (complete_page) {
            page.state = .complete;
            page.worker_id = worker_id;
            page.lease_expires_at_ms = 0;
            page.completed_units = if (effective_total_units != 0) effective_total_units else completed_units;
            page.cursor = "";
            page.output_fingerprint = output_fingerprint;
        }
        try self.putGraphMetricBuildPageInBatch(&batch, metric_name, page);
        try batch.commit();
        return page;
    }

    fn executeEigenvectorInitializeBuildPage(
        self: *GraphIndex,
        metric_name: []const u8,
        job: GraphMetricBuildJob,
        page: GraphMetricBuildPage,
    ) !usize {
        var range_lower: []u8 = "";
        defer if (range_lower.len > 0) self.alloc.free(range_lower);
        var range_upper: []u8 = "";
        defer if (range_upper.len > 0) self.alloc.free(range_upper);
        var total_units = page.total_units;
        {
            var txn = try self.beginReadReverseTxn();
            defer txn.abort();
            const execution_page = try self.metricBuildPage(&txn, metric_name, job.job_id, .initialize_ranks, page.iteration, page.page_id) orelse page;
            try self.validateGraphMetricBuildPageExecutionLease(page, execution_page);
            if (execution_page.range_lower.len > 0) range_lower = try self.alloc.dupe(u8, execution_page.range_lower);
            if (execution_page.range_upper.len > 0) range_upper = try self.alloc.dupe(u8, execution_page.range_upper);
            total_units = execution_page.total_units;
        }

        var nodes = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (nodes.items) |node| self.alloc.free(node);
            nodes.deinit(self.alloc);
        }
        {
            var txn = try self.beginReadReverseTxn();
            defer txn.abort();
            try self.collectPageRankScannedNodes(&txn, metric_name, job.job_id, &nodes);
        }

        const total_nodes = nodes.items.len;
        const initial_rank = if (total_nodes == 0) 0.0 else 1.0 / @sqrt(@as(f64, @floatFromInt(total_nodes)));
        var initialized_nodes: usize = 0;
        var rank_sum: f64 = 0.0;
        var initialized = std.ArrayListUnmanaged([]const u8).empty;
        defer initialized.deinit(self.alloc);
        {
            for (nodes.items) |node| {
                if (range_lower.len > 0 and std.mem.order(u8, node, range_lower) == .lt) continue;
                if (range_upper.len > 0 and std.mem.order(u8, node, range_upper) != .lt) continue;
                initialized_nodes += 1;
                rank_sum += initial_rank;
                try initialized.append(self.alloc, node);
            }
        }
        try self.writeEigenvectorInitializeOutputForAttempt(metric_name, job, page, initialized.items, initial_rank);

        const worker_id = if (page.worker_id.len != 0) page.worker_id else graph_metric_local_build_worker_id;
        const completed_units = if (total_units != 0) total_units else @as(u64, @intCast(initialized_nodes));
        const cursor = try std.fmt.allocPrint(self.alloc, "eigenvector-initialize:nodes={d};rank_sum={d}", .{ initialized_nodes, rank_sum });
        defer self.alloc.free(cursor);
        const fingerprint = graphMetricPageRankInitializeFingerprint(page, initialized_nodes, 0, rank_sum);
        _ = try self.updateGraphMetricBuildPageProgressForAttempt(metric_name, job.job_id, .initialize_ranks, page.iteration, page.page_id, worker_id, page.attempt, cursor, completed_units, total_units);
        _ = try self.completeGraphMetricBuildPageForAttempt(metric_name, job.job_id, .initialize_ranks, page.iteration, page.page_id, worker_id, page.attempt, completed_units, fingerprint);
        return initialized_nodes;
    }

    fn writeEigenvectorInitializeOutputForAttempt(
        self: *GraphIndex,
        metric_name: []const u8,
        job: GraphMetricBuildJob,
        claimed_page: GraphMetricBuildPage,
        initialized_nodes: []const []const u8,
        initial_rank: f64,
    ) !void {
        var batch = try self.beginWriteReverseBatch();
        errdefer batch.abort();
        const current_page = try self.metricBuildPage(&batch, metric_name, job.job_id, .initialize_ranks, claimed_page.iteration, claimed_page.page_id) orelse return error.GraphMetricBuildPageNotFound;
        try self.validateGraphMetricBuildPageExecutionLease(claimed_page, current_page);
        if (!std.math.isFinite(initial_rank)) return error.InvalidGraphMetricScore;
        for (initialized_nodes) |node| {
            const rank_key = try self.graphMetricBuildPageRankKeyAlloc(metric_name, job.job_id, 0, node);
            defer self.alloc.free(rank_key);
            try putF64(&batch, rank_key, initial_rank);
        }
        try batch.commit();
    }

    fn executeEigenvectorContributionBuildPage(
        self: *GraphIndex,
        metric_name: []const u8,
        cfg: GraphMetricConfig,
        job: GraphMetricBuildJob,
        page: GraphMetricBuildPage,
    ) !usize {
        return try self.executeEigenvectorContributionBuildPageWithLimit(metric_name, cfg, job, page, null);
    }

    fn executeEigenvectorContributionBuildPageWithLimit(
        self: *GraphIndex,
        metric_name: []const u8,
        cfg: GraphMetricConfig,
        job: GraphMetricBuildJob,
        page: GraphMetricBuildPage,
        max_scan_units: ?u64,
    ) !usize {
        var contributions = std.StringHashMapUnmanaged(f64).empty;
        defer self.freeStringHashMapKeys(f64, &contributions);
        var scanned_units: u64 = 0;
        var prior_completed_units: u64 = 0;
        var page_attempt = page.attempt;
        var total_units = page.total_units;
        var contribution_sum: f64 = 0.0;
        var reached_page_end = true;
        var last_scanned_key: []u8 = "";
        defer if (last_scanned_key.len > 0) self.alloc.free(last_scanned_key);
        {
            var txn = try self.beginReadReverseTxn();
            defer txn.abort();
            const execution_page = try self.metricBuildPage(&txn, metric_name, job.job_id, .iterate_contributions, page.iteration, page.page_id) orelse page;
            try self.validateGraphMetricBuildPageExecutionLease(page, execution_page);
            prior_completed_units = execution_page.completed_units;
            page_attempt = execution_page.attempt;
            total_units = execution_page.total_units;
            var cur = try txn.openCursor();
            defer cur.close();
            const resume_cursor = execution_page.cursor;
            const seek_key = if (resume_cursor.len > 0) resume_cursor else execution_page.range_lower;
            var entry_opt = if (seek_key.len > 0) try cur.seekAtOrAfter(seek_key) else try cur.first();
            while (entry_opt) |entry| : (entry_opt = try cur.next()) {
                if (resume_cursor.len > 0 and std.mem.order(u8, entry.key, resume_cursor) != .gt) continue;
                if (execution_page.range_upper.len > 0 and std.mem.order(u8, entry.key, execution_page.range_upper) != .lt) break;
                if (std.mem.startsWith(u8, entry.key, graph_meta_prefix)) continue;
                var parsed = (try parseReverseEdgeKeyAlloc(self.alloc, entry.key)) orelse continue;
                defer parsed.deinit(self.alloc);
                if (!std.mem.eql(u8, parsed.index_name, self.index_name)) continue;
                if (max_scan_units) |limit| {
                    if (scanned_units >= limit) {
                        reached_page_end = false;
                        break;
                    }
                }
                scanned_units += 1;
                if (!graphMetricEdgeAllowed(cfg.edge_filter, parsed.edge_type)) continue;

                const rank_key = try self.graphMetricBuildPageRankKeyAlloc(metric_name, job.job_id, page.iteration, parsed.source);
                defer self.alloc.free(rank_key);
                const source_rank = try readF64OrZero(&txn, rank_key);
                if (!std.math.isFinite(source_rank)) return error.InvalidGraphMetricScore;

                const result = try contributions.getOrPut(self.alloc, parsed.target);
                if (result.found_existing) {
                    result.value_ptr.* += source_rank;
                } else {
                    result.key_ptr.* = try self.alloc.dupe(u8, parsed.target);
                    result.value_ptr.* = source_rank;
                }
                contribution_sum += source_rank;
                if (last_scanned_key.len > 0) self.alloc.free(last_scanned_key);
                last_scanned_key = try self.alloc.dupe(u8, entry.key);
            }
        }

        var write_page = page;
        write_page.attempt = page_attempt;
        try self.writePageRankContributionAttemptPartialsForAttempt(metric_name, job, write_page, prior_completed_units, &contributions, reached_page_end);

        const worker_id = if (page.worker_id.len != 0) page.worker_id else graph_metric_local_build_worker_id;
        const completed_units_raw = prior_completed_units + scanned_units;
        const completed_units = if (total_units != 0) @min(completed_units_raw, total_units) else completed_units_raw;
        const cursor = try std.fmt.allocPrint(self.alloc, "eigenvector-contribution:targets={d};sum={d}", .{ contributions.count(), contribution_sum });
        defer self.alloc.free(cursor);
        const fingerprint = graphMetricPageRankContributionFingerprint(page, scanned_units, contributions.count(), contribution_sum);
        if (!reached_page_end) {
            _ = try self.updateGraphMetricBuildPageProgressForAttempt(metric_name, job.job_id, .iterate_contributions, page.iteration, page.page_id, worker_id, page.attempt, last_scanned_key, completed_units, total_units);
            return contributions.count();
        }
        _ = try self.updateGraphMetricBuildPageProgressForAttempt(metric_name, job.job_id, .iterate_contributions, page.iteration, page.page_id, worker_id, page.attempt, cursor, completed_units, total_units);
        _ = try self.completeGraphMetricBuildPageForAttempt(metric_name, job.job_id, .iterate_contributions, page.iteration, page.page_id, worker_id, page.attempt, completed_units, fingerprint);
        return contributions.count();
    }

    fn executeEigenvectorReduceBuildPage(
        self: *GraphIndex,
        metric_name: []const u8,
        job: GraphMetricBuildJob,
        page: GraphMetricBuildPage,
    ) !usize {
        return try self.executeEigenvectorReduceBuildPageWithLimit(metric_name, job, page, null);
    }

    fn executeEigenvectorReduceBuildPageWithLimit(
        self: *GraphIndex,
        metric_name: []const u8,
        job: GraphMetricBuildJob,
        page: GraphMetricBuildPage,
        max_reduce_units: ?u64,
    ) !usize {
        var range_lower: []u8 = "";
        defer if (range_lower.len > 0) self.alloc.free(range_lower);
        var range_upper: []u8 = "";
        defer if (range_upper.len > 0) self.alloc.free(range_upper);
        var resume_cursor: []u8 = "";
        defer if (resume_cursor.len > 0) self.alloc.free(resume_cursor);
        var prior_completed_units: u64 = 0;
        var total_units = page.total_units;
        {
            var txn = try self.beginReadReverseTxn();
            defer txn.abort();
            const execution_page = try self.metricBuildPage(&txn, metric_name, job.job_id, .reduce_ranks, page.iteration, page.page_id) orelse page;
            try self.validateGraphMetricBuildPageExecutionLease(page, execution_page);
            if (execution_page.range_lower.len > 0) range_lower = try self.alloc.dupe(u8, execution_page.range_lower);
            if (execution_page.range_upper.len > 0) range_upper = try self.alloc.dupe(u8, execution_page.range_upper);
            if (execution_page.cursor.len > 0) resume_cursor = try self.alloc.dupe(u8, execution_page.cursor);
            prior_completed_units = execution_page.completed_units;
            total_units = execution_page.total_units;
        }

        var nodes = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (nodes.items) |node| self.alloc.free(node);
            nodes.deinit(self.alloc);
        }
        {
            var txn = try self.beginReadReverseTxn();
            defer txn.abort();
            try self.collectPageRankScannedNodes(&txn, metric_name, job.job_id, &nodes);
        }

        var norm_sq: f64 = 0.0;
        {
            var txn = try self.beginReadReverseTxn();
            defer txn.abort();
            for (nodes.items) |node| {
                const contribution = try self.aggregatePageRankContributionForNode(&txn, metric_name, job.job_id, page.iteration, node);
                if (!std.math.isFinite(contribution)) return error.InvalidGraphMetricScore;
                norm_sq += contribution * contribution;
            }
        }
        const norm = @sqrt(norm_sq);
        if (!std.math.isFinite(norm)) return error.InvalidGraphMetricScore;

        var reduced = std.ArrayListUnmanaged(GraphMetricScore).empty;
        defer reduced.deinit(self.alloc);
        var contribution_sum: f64 = 0.0;
        var rank_sum: f64 = 0.0;
        var reached_page_end = true;
        var last_reduced_node: []u8 = "";
        defer if (last_reduced_node.len > 0) self.alloc.free(last_reduced_node);
        {
            var txn = try self.beginReadReverseTxn();
            defer txn.abort();
            for (nodes.items) |node| {
                if (range_lower.len > 0 and std.mem.order(u8, node, range_lower) == .lt) continue;
                if (range_upper.len > 0 and std.mem.order(u8, node, range_upper) != .lt) continue;
                if (resume_cursor.len > 0 and std.mem.order(u8, node, resume_cursor) != .gt) continue;
                if (max_reduce_units) |limit| {
                    if (reduced.items.len >= limit) {
                        reached_page_end = false;
                        break;
                    }
                }
                const contribution = try self.aggregatePageRankContributionForNode(&txn, metric_name, job.job_id, page.iteration, node);
                if (!std.math.isFinite(contribution)) return error.InvalidGraphMetricScore;
                contribution_sum += contribution;
                const next_rank = if (norm > 0.0) contribution / norm else 0.0;
                if (!std.math.isFinite(next_rank)) return error.InvalidGraphMetricScore;
                rank_sum += next_rank;
                try reduced.append(self.alloc, .{ .node = node, .score = next_rank });
                if (last_reduced_node.len > 0) self.alloc.free(last_reduced_node);
                last_reduced_node = try self.alloc.dupe(u8, node);
            }
        }

        const worker_id = if (page.worker_id.len != 0) page.worker_id else graph_metric_local_build_worker_id;
        const completed_units_raw = prior_completed_units + @as(u64, @intCast(reduced.items.len));
        const completed_units = if (total_units != 0) @min(completed_units_raw, total_units) else completed_units_raw;
        const cursor = try std.fmt.allocPrint(self.alloc, "eigenvector-reduce:nodes={d};rank_sum={d}", .{ reduced.items.len, rank_sum });
        defer self.alloc.free(cursor);
        const fingerprint = graphMetricPageRankReduceFingerprint(page, reduced.items.len, contribution_sum, rank_sum);
        if (!reached_page_end) {
            _ = try self.writeSingleVectorReduceRanksForAttempt(metric_name, job, page, worker_id, last_reduced_node, completed_units, total_units, reduced.items, 0, false);
            return reduced.items.len;
        }
        const complete_units = if (total_units != 0) total_units else completed_units;
        _ = try self.writeSingleVectorReduceRanksForAttempt(metric_name, job, page, worker_id, cursor, complete_units, total_units, reduced.items, fingerprint, true);
        return reduced.items.len;
    }

    fn executeHitsInitializeBuildPage(
        self: *GraphIndex,
        metric_name: []const u8,
        job: GraphMetricBuildJob,
        page: GraphMetricBuildPage,
    ) !usize {
        var range_lower: []u8 = "";
        defer if (range_lower.len > 0) self.alloc.free(range_lower);
        var range_upper: []u8 = "";
        defer if (range_upper.len > 0) self.alloc.free(range_upper);
        var total_units = page.total_units;
        {
            var txn = try self.beginReadReverseTxn();
            defer txn.abort();
            const execution_page = try self.metricBuildPage(&txn, metric_name, job.job_id, .initialize_ranks, page.iteration, page.page_id) orelse page;
            try self.validateGraphMetricBuildPageExecutionLease(page, execution_page);
            if (execution_page.range_lower.len > 0) range_lower = try self.alloc.dupe(u8, execution_page.range_lower);
            if (execution_page.range_upper.len > 0) range_upper = try self.alloc.dupe(u8, execution_page.range_upper);
            total_units = execution_page.total_units;
        }

        var nodes = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (nodes.items) |node| self.alloc.free(node);
            nodes.deinit(self.alloc);
        }
        {
            var txn = try self.beginReadReverseTxn();
            defer txn.abort();
            try self.collectPageRankScannedNodes(&txn, metric_name, job.job_id, &nodes);
        }

        const total_nodes = nodes.items.len;
        const initial_rank = if (total_nodes == 0) 0.0 else 1.0 / @sqrt(@as(f64, @floatFromInt(total_nodes)));
        var initialized_nodes: usize = 0;
        var rank_sum: f64 = 0.0;
        var initialized = std.ArrayListUnmanaged([]const u8).empty;
        defer initialized.deinit(self.alloc);
        {
            for (nodes.items) |node| {
                if (range_lower.len > 0 and std.mem.order(u8, node, range_lower) == .lt) continue;
                if (range_upper.len > 0 and std.mem.order(u8, node, range_upper) != .lt) continue;
                initialized_nodes += 1;
                rank_sum += initial_rank * 2.0;
                try initialized.append(self.alloc, node);
            }
        }
        try self.writeHitsInitializeOutputForAttempt(metric_name, job, page, initialized.items, initial_rank);

        const worker_id = if (page.worker_id.len != 0) page.worker_id else graph_metric_local_build_worker_id;
        const completed_units = if (total_units != 0) total_units else @as(u64, @intCast(initialized_nodes));
        const cursor = try std.fmt.allocPrint(self.alloc, "hits-initialize:nodes={d};rank_sum={d}", .{ initialized_nodes, rank_sum });
        defer self.alloc.free(cursor);
        const fingerprint = graphMetricPageRankInitializeFingerprint(page, initialized_nodes, 0, rank_sum);
        _ = try self.updateGraphMetricBuildPageProgressForAttempt(metric_name, job.job_id, .initialize_ranks, page.iteration, page.page_id, worker_id, page.attempt, cursor, completed_units, total_units);
        _ = try self.completeGraphMetricBuildPageForAttempt(metric_name, job.job_id, .initialize_ranks, page.iteration, page.page_id, worker_id, page.attempt, completed_units, fingerprint);
        return initialized_nodes;
    }

    fn writeHitsInitializeOutputForAttempt(
        self: *GraphIndex,
        metric_name: []const u8,
        job: GraphMetricBuildJob,
        claimed_page: GraphMetricBuildPage,
        initialized_nodes: []const []const u8,
        initial_rank: f64,
    ) !void {
        var batch = try self.beginWriteReverseBatch();
        errdefer batch.abort();
        const current_page = try self.metricBuildPage(&batch, metric_name, job.job_id, .initialize_ranks, claimed_page.iteration, claimed_page.page_id) orelse return error.GraphMetricBuildPageNotFound;
        try self.validateGraphMetricBuildPageExecutionLease(claimed_page, current_page);
        if (!std.math.isFinite(initial_rank)) return error.InvalidGraphMetricScore;
        for (initialized_nodes) |node| {
            const authority_key = try self.graphMetricBuildHitsRankKeyAlloc(metric_name, job.job_id, "authority", 0, node);
            defer self.alloc.free(authority_key);
            try putF64(&batch, authority_key, initial_rank);
            const hub_key = try self.graphMetricBuildHitsRankKeyAlloc(metric_name, job.job_id, "hub", 0, node);
            defer self.alloc.free(hub_key);
            try putF64(&batch, hub_key, initial_rank);
        }
        try batch.commit();
    }

