    }

    fn hitsAuthorityRankForNode(self: *GraphIndex, txn: anytype, metric_name: []const u8, job_id: u64, iteration: u32, authority_norm: f64, node: []const u8) !f64 {
        const contribution = try self.aggregatePageRankContributionForNode(txn, metric_name, job_id, iteration, node);
        if (!std.math.isFinite(contribution)) return error.InvalidGraphMetricScore;
        return if (authority_norm > 0.0) contribution / authority_norm else 0.0;
    }

    fn readHitsHubRawForNode(self: *GraphIndex, txn: anytype, metric_name: []const u8, job_id: u64, iteration: u32, node: []const u8) !f64 {
        const key = try self.graphMetricBuildHitsHubRawKeyAlloc(metric_name, job_id, iteration, node);
        defer self.alloc.free(key);
        const raw = try readF64OrZero(txn, key);
        if (!std.math.isFinite(raw)) return error.InvalidGraphMetricScore;
        return raw;
    }

    const HitsHubRawSummary = struct {
        count: usize = 0,
        norm: f64 = 0.0,
        raw_fingerprint: u64 = 0,
        fingerprint: u64 = 0,
    };

    fn putHitsHubRawSummaryInBatch(
        self: *GraphIndex,
        batch: anytype,
        metric_name: []const u8,
        job_id: u64,
        iteration: u32,
        summary: HitsHubRawSummary,
    ) !void {
        const key = try self.graphMetricBuildHitsHubRawSummaryKeyAlloc(metric_name, job_id, iteration);
        defer self.alloc.free(key);
        var encoded: [32]u8 = undefined;
        std.mem.writeInt(u64, encoded[0..8], @intCast(summary.count), .little);
        std.mem.writeInt(u64, encoded[8..16], @bitCast(summary.norm), .little);
        std.mem.writeInt(u64, encoded[16..24], summary.raw_fingerprint, .little);
        std.mem.writeInt(u64, encoded[24..32], summary.fingerprint, .little);
        try batch.put(key, &encoded);
    }

    fn hitsHubRawSummary(
        self: *GraphIndex,
        txn: anytype,
        metric_name: []const u8,
        job_id: u64,
        iteration: u32,
    ) !?HitsHubRawSummary {
        const key = try self.graphMetricBuildHitsHubRawSummaryKeyAlloc(metric_name, job_id, iteration);
        defer self.alloc.free(key);
        const raw = txn.get(key) catch |err| switch (err) {
            error.NotFound => return null,
            else => return err,
        };
        if (raw.len != 16 and raw.len != 24 and raw.len != 32) return error.InvalidGraphMetricBuildManifest;
        const count = std.mem.readInt(u64, raw[0..8], .little);
        const norm = @as(f64, @bitCast(std.mem.readInt(u64, raw[8..16], .little)));
        const raw_fingerprint = if (raw.len >= 32) std.mem.readInt(u64, raw[16..24], .little) else 0;
        const fingerprint = if (raw.len >= 32) std.mem.readInt(u64, raw[24..32], .little) else if (raw.len >= 24) std.mem.readInt(u64, raw[16..24], .little) else 0;
        if (!std.math.isFinite(norm)) return error.InvalidGraphMetricScore;
        return .{ .count = @intCast(count), .norm = norm, .raw_fingerprint = raw_fingerprint, .fingerprint = fingerprint };
    }

    fn hitsHubRawNamespaceSummary(
        self: *GraphIndex,
        txn: anytype,
        metric_name: []const u8,
        job_id: u64,
        iteration: u32,
    ) !HitsHubRawSummary {
        const prefix = try self.graphMetricBuildHitsHubRawPrefixAlloc(metric_name, job_id, iteration);
        defer self.alloc.free(prefix);
        var count: usize = 0;
        var norm_sq: f64 = 0.0;
        var raw_fingerprint: u64 = 0;
        var cur = try txn.openCursor();
        defer cur.close();
        var entry_opt = try cur.seekAtOrAfter(prefix);
        while (entry_opt) |entry| : (entry_opt = try cur.next()) {
            if (!std.mem.startsWith(u8, entry.key, prefix)) break;
            const node = (try graphMetricFirstComponentAfterPrefixAlloc(self.alloc, entry.key, prefix)) orelse continue;
            defer self.alloc.free(node);
            const raw_hub = decodeF64(entry.value) orelse return error.InvalidGraphMetricScore;
            if (!std.math.isFinite(raw_hub)) return error.InvalidGraphMetricScore;
            count += 1;
            norm_sq += raw_hub * raw_hub;
            raw_fingerprint ^= graphMetricHitsHubRawEntryFingerprint(node, raw_hub);
        }
        const norm = @sqrt(norm_sq);
        if (!std.math.isFinite(norm)) return error.InvalidGraphMetricScore;
        return .{ .count = count, .norm = norm, .raw_fingerprint = raw_fingerprint };
    }

    fn materializeHitsHubRawContributions(
        self: *GraphIndex,
        metric_name: []const u8,
        cfg: GraphMetricConfig,
        job_id: u64,
        iteration: u32,
        authority_norm: f64,
    ) !HitsHubRawSummary {
        {
            var txn = try self.beginReadReverseTxn();
            defer txn.abort();
            if (try self.hitsHubRawSummary(&txn, metric_name, job_id, iteration)) |summary| {
                const raw_summary = try self.hitsHubRawNamespaceSummary(&txn, metric_name, job_id, iteration);
                const expected_fingerprint = graphMetricHitsHubRawSummaryFingerprint(metric_name, cfg, job_id, iteration, authority_norm, raw_summary.count, raw_summary.norm, raw_summary.raw_fingerprint);
                if (summary.count == raw_summary.count and
                    @as(u64, @bitCast(summary.norm)) == @as(u64, @bitCast(raw_summary.norm)) and
                    summary.raw_fingerprint == raw_summary.raw_fingerprint and
                    summary.fingerprint == expected_fingerprint)
                {
                    return summary;
                }
            }
        }

        var hub_raw = std.StringHashMapUnmanaged(f64).empty;
        defer self.freeStringHashMapKeys(f64, &hub_raw);
        {
            var txn = try self.beginReadReverseTxn();
            defer txn.abort();
            var cur = try txn.openCursor();
            defer cur.close();
            var entry_opt = try cur.first();
            while (entry_opt) |entry| : (entry_opt = try cur.next()) {
                if (std.mem.startsWith(u8, entry.key, graph_meta_prefix)) continue;
                var parsed = (try parseReverseEdgeKeyAlloc(self.alloc, entry.key)) orelse continue;
                defer parsed.deinit(self.alloc);
                if (!std.mem.eql(u8, parsed.index_name, self.index_name)) continue;
                if (!graphMetricEdgeAllowed(cfg.edge_filter, parsed.edge_type)) continue;
                const target_authority = try self.hitsAuthorityRankForNode(&txn, metric_name, job_id, iteration, authority_norm, parsed.target);
                const result = try hub_raw.getOrPut(self.alloc, parsed.source);
                if (result.found_existing) {
                    result.value_ptr.* += target_authority;
                } else {
                    result.key_ptr.* = try self.alloc.dupe(u8, parsed.source);
                    result.value_ptr.* = target_authority;
                }
            }
        }

        var hub_norm_sq: f64 = 0.0;
        var raw_fingerprint: u64 = 0;
        {
            var batch = try self.beginWriteReverseBatch();
            errdefer batch.abort();
            const raw_prefix = try self.graphMetricBuildHitsHubRawPrefixAlloc(metric_name, job_id, iteration);
            defer self.alloc.free(raw_prefix);
            _ = try self.deleteKeysWithPrefixInBatch(&batch, raw_prefix);
            var it = hub_raw.iterator();
            while (it.next()) |entry| {
                if (!std.math.isFinite(entry.value_ptr.*)) return error.InvalidGraphMetricScore;
                hub_norm_sq += entry.value_ptr.* * entry.value_ptr.*;
                raw_fingerprint ^= graphMetricHitsHubRawEntryFingerprint(entry.key_ptr.*, entry.value_ptr.*);
                const key = try self.graphMetricBuildHitsHubRawKeyAlloc(metric_name, job_id, iteration, entry.key_ptr.*);
                defer self.alloc.free(key);
                try putF64(&batch, key, entry.value_ptr.*);
            }
            try batch.commit();
        }
        const hub_norm = @sqrt(hub_norm_sq);
        if (!std.math.isFinite(hub_norm)) return error.InvalidGraphMetricScore;
        const summary: HitsHubRawSummary = .{
            .count = hub_raw.count(),
            .norm = hub_norm,
            .raw_fingerprint = raw_fingerprint,
            .fingerprint = graphMetricHitsHubRawSummaryFingerprint(metric_name, cfg, job_id, iteration, authority_norm, hub_raw.count(), hub_norm, raw_fingerprint),
        };
        {
            var batch = try self.beginWriteReverseBatch();
            errdefer batch.abort();
            try self.putHitsHubRawSummaryInBatch(&batch, metric_name, job_id, iteration, summary);
            try batch.commit();
        }
        return summary;
    }

    fn executeHitsReduceBuildPage(
        self: *GraphIndex,
        metric_name: []const u8,
        cfg: GraphMetricConfig,
        job: GraphMetricBuildJob,
        page: GraphMetricBuildPage,
    ) !usize {
        return try self.executeHitsReduceBuildPageWithLimit(metric_name, cfg, job, page, null);
    }

    fn executeHitsReduceBuildPageWithLimit(
        self: *GraphIndex,
        metric_name: []const u8,
        cfg: GraphMetricConfig,
        job: GraphMetricBuildJob,
        page: GraphMetricBuildPage,
        max_reduce_units: ?u64,
    ) !usize {
        _ = cfg;
        var range_lower: []u8 = "";
        defer if (range_lower.len > 0) self.alloc.free(range_lower);
        var range_upper: []u8 = "";
        defer if (range_upper.len > 0) self.alloc.free(range_upper);
        var resume_cursor: []u8 = "";
        defer if (resume_cursor.len > 0) self.alloc.free(resume_cursor);
        var prior_completed_units: u64 = 0;
        var total_units = page.total_units;
        {
            var txn = try self.beginReadReverseTxn();
            defer txn.abort();
            const execution_page = try self.metricBuildPage(&txn, metric_name, job.job_id, .reduce_ranks, page.iteration, page.page_id) orelse page;
            try self.validateGraphMetricBuildPageExecutionLease(page, execution_page);
            if (execution_page.range_lower.len > 0) range_lower = try self.alloc.dupe(u8, execution_page.range_lower);
            if (execution_page.range_upper.len > 0) range_upper = try self.alloc.dupe(u8, execution_page.range_upper);
            if (execution_page.cursor.len > 0) resume_cursor = try self.alloc.dupe(u8, execution_page.cursor);
            prior_completed_units = execution_page.completed_units;
            total_units = execution_page.total_units;
        }

        var nodes = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (nodes.items) |node| self.alloc.free(node);
            nodes.deinit(self.alloc);
        }
        {
            var txn = try self.beginReadReverseTxn();
            defer txn.abort();
            try self.collectPageRankScannedNodes(&txn, metric_name, job.job_id, &nodes);
        }

        var authority_norm_sq: f64 = 0.0;
        {
            var txn = try self.beginReadReverseTxn();
            defer txn.abort();
            for (nodes.items) |node| {
                const contribution = try self.aggregatePageRankContributionForNode(&txn, metric_name, job.job_id, page.iteration, node);
                if (!std.math.isFinite(contribution)) return error.InvalidGraphMetricScore;
                authority_norm_sq += contribution * contribution;
            }
        }
        const authority_norm = @sqrt(authority_norm_sq);
        if (!std.math.isFinite(authority_norm)) return error.InvalidGraphMetricScore;

        var reduced = std.ArrayListUnmanaged(GraphMetricScore).empty;
        defer reduced.deinit(self.alloc);
        var contribution_sum: f64 = 0.0;
        var rank_sum: f64 = 0.0;
        var reached_page_end = true;
        var last_reduced_node: []u8 = "";
        defer if (last_reduced_node.len > 0) self.alloc.free(last_reduced_node);
        {
            var txn = try self.beginReadReverseTxn();
            defer txn.abort();
            for (nodes.items) |node| {
                if (range_lower.len > 0 and std.mem.order(u8, node, range_lower) == .lt) continue;
                if (range_upper.len > 0 and std.mem.order(u8, node, range_upper) != .lt) continue;
                if (resume_cursor.len > 0 and std.mem.order(u8, node, resume_cursor) != .gt) continue;
                if (max_reduce_units) |limit| {
                    if (reduced.items.len >= limit) {
                        reached_page_end = false;
                        break;
                    }
                }
                const authority = try self.hitsAuthorityRankForNode(&txn, metric_name, job.job_id, page.iteration, authority_norm, node);
                if (!std.math.isFinite(authority)) return error.InvalidGraphMetricScore;
                contribution_sum += authority;
                rank_sum += authority;
                try reduced.append(self.alloc, .{ .node = node, .score = authority });
                if (last_reduced_node.len > 0) self.alloc.free(last_reduced_node);
                last_reduced_node = try self.alloc.dupe(u8, node);
            }
        }

        const worker_id = if (page.worker_id.len != 0) page.worker_id else graph_metric_local_build_worker_id;
        const completed_units_raw = prior_completed_units + @as(u64, @intCast(reduced.items.len));
        const completed_units = if (total_units != 0) @min(completed_units_raw, total_units) else completed_units_raw;
        const cursor = try std.fmt.allocPrint(self.alloc, "hits-authority-reduce:nodes={d};rank_sum={d}", .{ reduced.items.len, rank_sum });
        defer self.alloc.free(cursor);
        const fingerprint = graphMetricPageRankReduceFingerprint(page, reduced.items.len, contribution_sum, rank_sum);
        if (!reached_page_end) {
            _ = try self.writeHitsReduceRanksForAttempt(metric_name, job, page, .reduce_ranks, "authority", worker_id, last_reduced_node, completed_units, total_units, reduced.items, 0, false);
            return reduced.items.len;
        }
        const complete_units = if (total_units != 0) total_units else completed_units;
        _ = try self.writeHitsReduceRanksForAttempt(metric_name, job, page, .reduce_ranks, "authority", worker_id, cursor, complete_units, total_units, reduced.items, fingerprint, true);
        return reduced.items.len;
    }

    fn writeHitsReduceRanksForAttempt(
        self: *GraphIndex,
        metric_name: []const u8,
        job: GraphMetricBuildJob,
        claimed_page: GraphMetricBuildPage,
        phase: GraphMetricBuildPhase,
        vector_name: []const u8,
        worker_id: []const u8,
        cursor: []const u8,
        completed_units: u64,
        total_units: u64,
        ranks: []const GraphMetricScore,
        output_fingerprint: u64,
        complete_page: bool,
    ) !GraphMetricBuildPage {
        var batch = try self.beginWriteReverseBatch();
        errdefer batch.abort();
        var page = try self.metricBuildPage(&batch, metric_name, job.job_id, phase, claimed_page.iteration, claimed_page.page_id) orelse return error.GraphMetricBuildPageNotFound;
        if (page.state == .complete) {
            if (!complete_page or page.attempt != claimed_page.attempt) return error.GraphMetricBuildPageNotLeased;
            if (page.output_fingerprint != output_fingerprint) return error.GraphMetricBuildPageOutputMismatch;
            try batch.commit();
            return page;
        }
        var expected_page = claimed_page;
        expected_page.worker_id = worker_id;
        try self.validateGraphMetricBuildPageExecutionLease(expected_page, page);
        const effective_total_units = if (total_units != 0) total_units else page.total_units;
        if (effective_total_units != 0 and completed_units > effective_total_units) return error.InvalidGraphMetricBuildProgress;

        for (ranks) |score| {
            if (!std.math.isFinite(score.score)) return error.InvalidGraphMetricScore;
            const rank_key = try self.graphMetricBuildHitsRankKeyAlloc(metric_name, job.job_id, vector_name, claimed_page.iteration + 1, score.node);
            defer self.alloc.free(rank_key);
            try putF64(&batch, rank_key, score.score);
        }

        if (try self.metricBuildJob(&batch, metric_name)) |existing_job| {
            if (existing_job.job_id == job.job_id and existing_job.phase == phase and existing_job.iteration == claimed_page.iteration) {
                var progress_job = existing_job;
                progress_job.cursor = cursor;
                progress_job.completed_units = completed_units;
                progress_job.total_units = effective_total_units;
                progress_job.updated_at_ms = @divTrunc(platform_time.realtimeNs(), std.time.ns_per_ms);
                try self.putGraphMetricBuildJobInBatch(&batch, metric_name, progress_job);
            }
        }

        page.completed_units = completed_units;
        page.total_units = effective_total_units;
        page.cursor = cursor;
        page.last_error = "";
        if (complete_page) {
            page.state = .complete;
            page.worker_id = worker_id;
            page.lease_expires_at_ms = 0;
            page.completed_units = if (effective_total_units != 0) effective_total_units else completed_units;
            page.cursor = "";
            page.output_fingerprint = output_fingerprint;
        }
        try self.putGraphMetricBuildPageInBatch(&batch, metric_name, page);
        try batch.commit();
        return page;
    }

    fn executeHitsHubContributionBuildPage(
        self: *GraphIndex,
        metric_name: []const u8,
        cfg: GraphMetricConfig,
        job: GraphMetricBuildJob,
        page: GraphMetricBuildPage,
    ) !usize {
        return try self.executeHitsHubContributionBuildPageWithLimit(metric_name, cfg, job, page, null);
    }

    fn executeHitsHubContributionBuildPageWithLimit(
        self: *GraphIndex,
        metric_name: []const u8,
        cfg: GraphMetricConfig,
        job: GraphMetricBuildJob,
        page: GraphMetricBuildPage,
        max_scan_units: ?u64,
    ) !usize {
        var hub_raw = std.StringHashMapUnmanaged(f64).empty;
        defer self.freeStringHashMapKeys(f64, &hub_raw);
        var scanned_units: u64 = 0;
        var prior_completed_units: u64 = 0;
        var page_attempt = page.attempt;
        var total_units = page.total_units;
        var raw_sum: f64 = 0.0;
        var reached_page_end = true;
        var last_scanned_key: []u8 = "";
        defer if (last_scanned_key.len > 0) self.alloc.free(last_scanned_key);
        {
            var txn = try self.beginReadReverseTxn();
            defer txn.abort();
            const execution_page = try self.metricBuildPage(&txn, metric_name, job.job_id, .hits_hub_contributions, page.iteration, page.page_id) orelse page;
            try self.validateGraphMetricBuildPageExecutionLease(page, execution_page);
            prior_completed_units = execution_page.completed_units;
            page_attempt = execution_page.attempt;
            total_units = execution_page.total_units;
            var cur = try txn.openCursor();
            defer cur.close();
            const resume_cursor = execution_page.cursor;
            const seek_key = if (resume_cursor.len > 0) resume_cursor else execution_page.range_lower;
            var entry_opt = if (seek_key.len > 0) try cur.seekAtOrAfter(seek_key) else try cur.first();
            while (entry_opt) |entry| : (entry_opt = try cur.next()) {
                if (resume_cursor.len > 0 and std.mem.order(u8, entry.key, resume_cursor) != .gt) continue;
                if (execution_page.range_upper.len > 0 and std.mem.order(u8, entry.key, execution_page.range_upper) != .lt) break;
                if (std.mem.startsWith(u8, entry.key, graph_meta_prefix)) continue;
                var parsed = (try parseReverseEdgeKeyAlloc(self.alloc, entry.key)) orelse continue;
                defer parsed.deinit(self.alloc);
                if (!std.mem.eql(u8, parsed.index_name, self.index_name)) continue;
                if (max_scan_units) |limit| {
                    if (scanned_units >= limit) {
                        reached_page_end = false;
                        break;
                    }
                }
                scanned_units += 1;
                if (!graphMetricEdgeAllowed(cfg.edge_filter, parsed.edge_type)) continue;

                const authority_key = try self.graphMetricBuildHitsRankKeyAlloc(metric_name, job.job_id, "authority", page.iteration + 1, parsed.target);
                defer self.alloc.free(authority_key);
                const target_authority = try readF64OrZero(&txn, authority_key);
                if (!std.math.isFinite(target_authority)) return error.InvalidGraphMetricScore;

                const result = try hub_raw.getOrPut(self.alloc, parsed.source);
                if (result.found_existing) {
                    result.value_ptr.* += target_authority;
                } else {
                    result.key_ptr.* = try self.alloc.dupe(u8, parsed.source);
                    result.value_ptr.* = target_authority;
                }
                raw_sum += target_authority;
                if (last_scanned_key.len > 0) self.alloc.free(last_scanned_key);
                last_scanned_key = try self.alloc.dupe(u8, entry.key);
            }
        }

        var write_page = page;
        write_page.attempt = page_attempt;
        try self.writeHitsHubRawAttemptPartialsForAttempt(metric_name, job, write_page, prior_completed_units, &hub_raw, reached_page_end);

        const worker_id = if (page.worker_id.len != 0) page.worker_id else graph_metric_local_build_worker_id;
        const completed_units_raw = prior_completed_units + scanned_units;
        const completed_units = if (total_units != 0) @min(completed_units_raw, total_units) else completed_units_raw;
        const cursor = try std.fmt.allocPrint(self.alloc, "hits-hub-contribution:sources={d};sum={d}", .{ hub_raw.count(), raw_sum });
        defer self.alloc.free(cursor);
        const fingerprint = graphMetricPageRankContributionFingerprint(page, scanned_units, hub_raw.count(), raw_sum);
        if (!reached_page_end) {
            _ = try self.updateGraphMetricBuildPageProgressForAttempt(metric_name, job.job_id, .hits_hub_contributions, page.iteration, page.page_id, worker_id, page.attempt, last_scanned_key, completed_units, total_units);
            return hub_raw.count();
        }
        _ = try self.updateGraphMetricBuildPageProgressForAttempt(metric_name, job.job_id, .hits_hub_contributions, page.iteration, page.page_id, worker_id, page.attempt, cursor, completed_units, total_units);
        _ = try self.completeGraphMetricBuildPageForAttempt(metric_name, job.job_id, .hits_hub_contributions, page.iteration, page.page_id, worker_id, page.attempt, completed_units, fingerprint);
        return hub_raw.count();
    }

    fn writeHitsHubRawAttemptPartialsForAttempt(
        self: *GraphIndex,
        metric_name: []const u8,
        job: GraphMetricBuildJob,
        claimed_page: GraphMetricBuildPage,
        prior_completed_units: u64,
        hub_raw: *std.StringHashMapUnmanaged(f64),
        adopt_on_complete: bool,
    ) !void {
        var batch = try self.beginWriteReverseBatch();
        errdefer batch.abort();
        const current_page = try self.metricBuildPage(&batch, metric_name, job.job_id, .hits_hub_contributions, claimed_page.iteration, claimed_page.page_id) orelse return error.GraphMetricBuildPageNotFound;
        try self.validateGraphMetricBuildPageExecutionLease(claimed_page, current_page);
        var it = hub_raw.iterator();
        while (it.next()) |entry| {
            if (!std.math.isFinite(entry.value_ptr.*)) return error.InvalidGraphMetricScore;
            const raw_key = try self.graphMetricBuildAttemptHitsHubRawKeyAlloc(metric_name, job.job_id, .hits_hub_contributions, claimed_page.iteration, claimed_page.page_id, claimed_page.attempt, entry.key_ptr.*);
            defer self.alloc.free(raw_key);
            const prior = if (prior_completed_units != 0) try readF64OrZero(&batch, raw_key) else 0.0;
            try putF64(&batch, raw_key, prior + entry.value_ptr.*);
        }
        if (adopt_on_complete) {
            _ = try self.adoptHitsHubRawAttemptOutputInBatch(&batch, metric_name, job.job_id, claimed_page);
        }
        try batch.commit();
    }

    fn ensureHitsHubRawSummaryInBatch(
        self: *GraphIndex,
        batch: anytype,
        metric_name: []const u8,
        cfg: GraphMetricConfig,
        job_id: u64,
        iteration: u32,
    ) !HitsHubRawSummary {
        const raw_summary = try self.hitsHubRawNamespaceSummary(batch, metric_name, job_id, iteration);
        const expected_fingerprint = graphMetricHitsHubRawSummaryFingerprint(metric_name, cfg, job_id, iteration, 0.0, raw_summary.count, raw_summary.norm, raw_summary.raw_fingerprint);
        if (try self.hitsHubRawSummary(batch, metric_name, job_id, iteration)) |summary| {
            if (summary.count == raw_summary.count and
                @as(u64, @bitCast(summary.norm)) == @as(u64, @bitCast(raw_summary.norm)) and
                summary.raw_fingerprint == raw_summary.raw_fingerprint and
                summary.fingerprint == expected_fingerprint)
            {
                return summary;
            }
        }
        const summary: HitsHubRawSummary = .{
            .count = raw_summary.count,
            .norm = raw_summary.norm,
            .raw_fingerprint = raw_summary.raw_fingerprint,
            .fingerprint = expected_fingerprint,
        };
        try self.putHitsHubRawSummaryInBatch(batch, metric_name, job_id, iteration, summary);
        return summary;
    }

    fn ensureHitsHubRawSummaryForPageAttempt(
        self: *GraphIndex,
        metric_name: []const u8,
        cfg: GraphMetricConfig,
        job: GraphMetricBuildJob,
        claimed_page: GraphMetricBuildPage,
        worker_id: []const u8,
    ) !HitsHubRawSummary {
        var batch = try self.beginWriteReverseBatch();
        errdefer batch.abort();
        var expected_page = claimed_page;
        expected_page.worker_id = worker_id;
        const page = try self.metricBuildPage(&batch, metric_name, job.job_id, .hits_hub_reduce_ranks, claimed_page.iteration, claimed_page.page_id) orelse return error.GraphMetricBuildPageNotFound;
        try self.validateGraphMetricBuildPageExecutionLease(expected_page, page);
        const summary = try self.ensureHitsHubRawSummaryInBatch(&batch, metric_name, cfg, job.job_id, claimed_page.iteration);
        try batch.commit();
        return summary;
    }

    fn executeHitsHubReduceBuildPage(
        self: *GraphIndex,
        metric_name: []const u8,
        cfg: GraphMetricConfig,
        job: GraphMetricBuildJob,
        page: GraphMetricBuildPage,
    ) !usize {
        return try self.executeHitsHubReduceBuildPageWithLimit(metric_name, cfg, job, page, null);
    }

    fn executeHitsHubReduceBuildPageWithLimit(
        self: *GraphIndex,
        metric_name: []const u8,
        cfg: GraphMetricConfig,
        job: GraphMetricBuildJob,
        page: GraphMetricBuildPage,
        max_reduce_units: ?u64,
    ) !usize {
        var range_lower: []u8 = "";
        defer if (range_lower.len > 0) self.alloc.free(range_lower);
        var range_upper: []u8 = "";
        defer if (range_upper.len > 0) self.alloc.free(range_upper);
        var resume_cursor: []u8 = "";
        defer if (resume_cursor.len > 0) self.alloc.free(resume_cursor);
        var prior_completed_units: u64 = 0;
        var total_units = page.total_units;
        {
            var txn = try self.beginReadReverseTxn();
            defer txn.abort();
            const execution_page = try self.metricBuildPage(&txn, metric_name, job.job_id, .hits_hub_reduce_ranks, page.iteration, page.page_id) orelse page;
            try self.validateGraphMetricBuildPageExecutionLease(page, execution_page);
            if (execution_page.range_lower.len > 0) range_lower = try self.alloc.dupe(u8, execution_page.range_lower);
            if (execution_page.range_upper.len > 0) range_upper = try self.alloc.dupe(u8, execution_page.range_upper);
            if (execution_page.cursor.len > 0) resume_cursor = try self.alloc.dupe(u8, execution_page.cursor);
            prior_completed_units = execution_page.completed_units;
            total_units = execution_page.total_units;
        }

        var nodes = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (nodes.items) |node| self.alloc.free(node);
            nodes.deinit(self.alloc);
        }
        {
            var txn = try self.beginReadReverseTxn();
            defer txn.abort();
            try self.collectPageRankScannedNodes(&txn, metric_name, job.job_id, &nodes);
        }

        var hub_summary: HitsHubRawSummary = undefined;
        const worker_id = if (page.worker_id.len != 0) page.worker_id else graph_metric_local_build_worker_id;
        hub_summary = try self.ensureHitsHubRawSummaryForPageAttempt(metric_name, cfg, job, page, worker_id);

        var reduced = std.ArrayListUnmanaged(GraphMetricScore).empty;
        defer reduced.deinit(self.alloc);
        var raw_sum: f64 = 0.0;
        var rank_sum: f64 = 0.0;
        var reached_page_end = true;
        var last_reduced_node: []u8 = "";
        defer if (last_reduced_node.len > 0) self.alloc.free(last_reduced_node);
        {
            var txn = try self.beginReadReverseTxn();
            defer txn.abort();
            for (nodes.items) |node| {
                if (range_lower.len > 0 and std.mem.order(u8, node, range_lower) == .lt) continue;
                if (range_upper.len > 0 and std.mem.order(u8, node, range_upper) != .lt) continue;
                if (resume_cursor.len > 0 and std.mem.order(u8, node, resume_cursor) != .gt) continue;
                if (max_reduce_units) |limit| {
                    if (reduced.items.len >= limit) {
                        reached_page_end = false;
                        break;
                    }
                }
                const raw_hub = try self.readHitsHubRawForNode(&txn, metric_name, job.job_id, page.iteration, node);
                const hub = if (hub_summary.norm > 0.0) raw_hub / hub_summary.norm else 0.0;
                if (!std.math.isFinite(hub)) return error.InvalidGraphMetricScore;
                raw_sum += raw_hub;
                rank_sum += hub;
                try reduced.append(self.alloc, .{ .node = node, .score = hub });
                if (last_reduced_node.len > 0) self.alloc.free(last_reduced_node);
                last_reduced_node = try self.alloc.dupe(u8, node);
            }
        }

        const completed_units_raw = prior_completed_units + @as(u64, @intCast(reduced.items.len));
        const completed_units = if (total_units != 0) @min(completed_units_raw, total_units) else completed_units_raw;
        const cursor = try std.fmt.allocPrint(self.alloc, "hits-hub-reduce:nodes={d};rank_sum={d}", .{ reduced.items.len, rank_sum });
        defer self.alloc.free(cursor);
        const fingerprint = graphMetricHitsReduceFingerprint(page, reduced.items.len, raw_sum, rank_sum, hub_summary);
        if (!reached_page_end) {
            _ = try self.writeHitsReduceRanksForAttempt(metric_name, job, page, .hits_hub_reduce_ranks, "hub", worker_id, last_reduced_node, completed_units, total_units, reduced.items, 0, false);
            return reduced.items.len;
        }
        const complete_units = if (total_units != 0) total_units else completed_units;
        _ = try self.writeHitsReduceRanksForAttempt(metric_name, job, page, .hits_hub_reduce_ranks, "hub", worker_id, cursor, complete_units, total_units, reduced.items, fingerprint, true);
        return reduced.items.len;
    }

    fn executeHitsConvergenceBuildPage(
        self: *GraphIndex,
        metric_name: []const u8,
        cfg: GraphMetricConfig,
        job: GraphMetricBuildJob,
        page: GraphMetricBuildPage,
    ) !GraphMetricBuildPageExecutionResult {
        var range_lower: []u8 = "";
        defer if (range_lower.len > 0) self.alloc.free(range_lower);
        var range_upper: []u8 = "";
        defer if (range_upper.len > 0) self.alloc.free(range_upper);
        var resume_cursor: []u8 = "";
        defer if (resume_cursor.len > 0) self.alloc.free(resume_cursor);
        var prior_completed_units: u64 = 0;
        var prior_max_delta: f64 = 0.0;
        var prior_total_delta: f64 = 0.0;
        var prior_rank_sum: f64 = 0.0;
        var total_units = page.total_units;
        {
            var txn = try self.beginReadReverseTxn();
            defer txn.abort();
            const execution_page = try self.metricBuildPage(&txn, metric_name, job.job_id, .check_convergence, page.iteration, page.page_id) orelse page;
            try self.validateGraphMetricBuildPageExecutionLease(page, execution_page);
            if (execution_page.range_lower.len > 0) range_lower = try self.alloc.dupe(u8, execution_page.range_lower);
            if (execution_page.range_upper.len > 0) range_upper = try self.alloc.dupe(u8, execution_page.range_upper);
            if (execution_page.cursor.len > 0) resume_cursor = try self.alloc.dupe(u8, execution_page.cursor);
            prior_completed_units = execution_page.completed_units;
            prior_max_delta = execution_page.max_delta;
            prior_total_delta = execution_page.total_delta;
            prior_rank_sum = execution_page.rank_sum;
            total_units = execution_page.total_units;
        }

        var nodes = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (nodes.items) |node| self.alloc.free(node);
            nodes.deinit(self.alloc);
        }
        {
            var txn = try self.beginReadReverseTxn();
            defer txn.abort();
            try self.collectPageRankScannedNodes(&txn, metric_name, job.job_id, &nodes);
        }

        var checked_nodes: usize = 0;
        var max_delta: f64 = 0.0;
        var total_delta: f64 = 0.0;
        var rank_sum: f64 = 0.0;
        {
            var txn = try self.beginReadReverseTxn();
            defer txn.abort();
            for (nodes.items) |node| {
                if (range_lower.len > 0 and std.mem.order(u8, node, range_lower) == .lt) continue;
                if (range_upper.len > 0 and std.mem.order(u8, node, range_upper) != .lt) continue;
                if (resume_cursor.len > 0 and std.mem.order(u8, node, resume_cursor) != .gt) continue;
                const prior_authority_key = try self.graphMetricBuildHitsRankKeyAlloc(metric_name, job.job_id, "authority", page.iteration, node);
                defer self.alloc.free(prior_authority_key);
                const next_authority_key = try self.graphMetricBuildHitsRankKeyAlloc(metric_name, job.job_id, "authority", page.iteration + 1, node);
                defer self.alloc.free(next_authority_key);
                const prior_hub_key = try self.graphMetricBuildHitsRankKeyAlloc(metric_name, job.job_id, "hub", page.iteration, node);
                defer self.alloc.free(prior_hub_key);
                const next_hub_key = try self.graphMetricBuildHitsRankKeyAlloc(metric_name, job.job_id, "hub", page.iteration + 1, node);
                defer self.alloc.free(next_hub_key);
                const prior_authority = try readF64OrZero(&txn, prior_authority_key);
                const next_authority = try readF64OrZero(&txn, next_authority_key);
                const prior_hub = try readF64OrZero(&txn, prior_hub_key);
                const next_hub = try readF64OrZero(&txn, next_hub_key);
                if (!std.math.isFinite(prior_authority) or !std.math.isFinite(next_authority) or !std.math.isFinite(prior_hub) or !std.math.isFinite(next_hub)) return error.InvalidGraphMetricScore;
                const authority_delta = @abs(next_authority - prior_authority);
                const hub_delta = @abs(next_hub - prior_hub);
                max_delta = @max(max_delta, @max(authority_delta, hub_delta));
                total_delta += authority_delta + hub_delta;
                rank_sum += next_authority + next_hub;
                checked_nodes += 1;
            }
        }

        max_delta = @max(prior_max_delta, max_delta);
        total_delta += prior_total_delta;
        rank_sum += prior_rank_sum;
        if (!std.math.isFinite(max_delta) or !std.math.isFinite(total_delta) or !std.math.isFinite(rank_sum)) return error.InvalidGraphMetricScore;
        const worker_id = if (page.worker_id.len != 0) page.worker_id else graph_metric_local_build_worker_id;
        const completed_units_raw = prior_completed_units + @as(u64, @intCast(checked_nodes));
        const completed_units = if (total_units != 0) @min(completed_units_raw, total_units) else completed_units_raw;
        const cursor = try std.fmt.allocPrint(self.alloc, "hits-check:nodes={d};delta={d}", .{ checked_nodes, total_delta });
        defer self.alloc.free(cursor);
        const fingerprint = graphMetricPageRankConvergenceFingerprint(page, checked_nodes, max_delta, total_delta, rank_sum);
        const complete_units = if (total_units != 0) total_units else completed_units;
        _ = try self.updateGraphMetricBuildPageProgressForAttempt(metric_name, job.job_id, .check_convergence, page.iteration, page.page_id, worker_id, page.attempt, cursor, complete_units, total_units);
        const completed = try self.completeGraphMetricBuildConvergencePageForAttempt(metric_name, job.job_id, page.iteration, page.page_id, worker_id, page.attempt, complete_units, fingerprint, max_delta, total_delta, rank_sum, total_delta <= cfg.tolerance);
        return .{
            .phase = .check_convergence,
            .page_id = page.page_id,
            .completed_page = completed.state == .complete,
            .completed_units = completed.completed_units,
            .total_units = completed.total_units,
            .output_fingerprint = completed.output_fingerprint,
            .max_delta = max_delta,
            .total_delta = total_delta,
            .rank_sum = rank_sum,
            .score_count = checked_nodes,
        };
    }

    fn executePageRankConvergenceBuildPage(
        self: *GraphIndex,
        metric_name: []const u8,
        cfg: GraphMetricConfig,
        job: GraphMetricBuildJob,
        page: GraphMetricBuildPage,
    ) !GraphMetricBuildPageExecutionResult {
        return try self.executePageRankConvergenceBuildPageWithLimit(metric_name, cfg, job, page, null);
    }

    fn executePageRankConvergenceBuildPageWithLimit(
        self: *GraphIndex,
        metric_name: []const u8,
        cfg: GraphMetricConfig,
        job: GraphMetricBuildJob,
        page: GraphMetricBuildPage,
        max_check_units: ?u64,
    ) !GraphMetricBuildPageExecutionResult {
        var range_lower: []u8 = "";
        defer if (range_lower.len > 0) self.alloc.free(range_lower);
        var range_upper: []u8 = "";
        defer if (range_upper.len > 0) self.alloc.free(range_upper);
        var resume_cursor: []u8 = "";
        defer if (resume_cursor.len > 0) self.alloc.free(resume_cursor);
        var prior_completed_units: u64 = 0;
        var prior_max_delta: f64 = 0.0;
        var prior_total_delta: f64 = 0.0;
        var prior_rank_sum: f64 = 0.0;
        var total_units = page.total_units;
        {
            var txn = try self.beginReadReverseTxn();
            defer txn.abort();
            const execution_page = try self.metricBuildPage(&txn, metric_name, job.job_id, .check_convergence, page.iteration, page.page_id) orelse page;
            try self.validateGraphMetricBuildPageExecutionLease(page, execution_page);
            if (execution_page.range_lower.len > 0) range_lower = try self.alloc.dupe(u8, execution_page.range_lower);
            if (execution_page.range_upper.len > 0) range_upper = try self.alloc.dupe(u8, execution_page.range_upper);
            if (execution_page.cursor.len > 0) resume_cursor = try self.alloc.dupe(u8, execution_page.cursor);
            prior_completed_units = execution_page.completed_units;
            prior_max_delta = execution_page.max_delta;
            prior_total_delta = execution_page.total_delta;
            prior_rank_sum = execution_page.rank_sum;
            total_units = execution_page.total_units;
        }

        var nodes = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (nodes.items) |node| self.alloc.free(node);
            nodes.deinit(self.alloc);
        }
        {
            var txn = try self.beginReadReverseTxn();
            defer txn.abort();
            try self.collectPageRankScannedNodes(&txn, metric_name, job.job_id, &nodes);
        }

        var checked_nodes: usize = 0;
        var max_delta: f64 = 0.0;
        var total_delta: f64 = 0.0;
        var rank_sum: f64 = 0.0;
        var reached_page_end = true;
        var last_checked_node: []u8 = "";
        defer if (last_checked_node.len > 0) self.alloc.free(last_checked_node);
        {
            var txn = try self.beginReadReverseTxn();
            defer txn.abort();
            for (nodes.items) |node| {
                if (range_lower.len > 0 and std.mem.order(u8, node, range_lower) == .lt) continue;
                if (range_upper.len > 0 and std.mem.order(u8, node, range_upper) != .lt) continue;
                if (resume_cursor.len > 0 and std.mem.order(u8, node, resume_cursor) != .gt) continue;
                if (max_check_units) |limit| {
                    if (checked_nodes >= limit) {
                        reached_page_end = false;
                        break;
                    }
                }
                const prior_rank_key = try self.graphMetricBuildPageRankKeyAlloc(metric_name, job.job_id, page.iteration, node);
                defer self.alloc.free(prior_rank_key);
                const next_rank_key = try self.graphMetricBuildPageRankKeyAlloc(metric_name, job.job_id, page.iteration + 1, node);
                defer self.alloc.free(next_rank_key);
                const prior_rank = try readF64OrZero(&txn, prior_rank_key);
                const next_rank = try readF64OrZero(&txn, next_rank_key);
                if (!std.math.isFinite(prior_rank) or !std.math.isFinite(next_rank)) return error.InvalidGraphMetricScore;
                const delta = @abs(next_rank - prior_rank);
                max_delta = @max(max_delta, delta);
                total_delta += delta;
                rank_sum += next_rank;
                checked_nodes += 1;
                if (last_checked_node.len > 0) self.alloc.free(last_checked_node);
                last_checked_node = try self.alloc.dupe(u8, node);
            }
        }

        max_delta = @max(prior_max_delta, max_delta);
        total_delta += prior_total_delta;
        rank_sum += prior_rank_sum;
        if (!std.math.isFinite(max_delta) or !std.math.isFinite(total_delta) or !std.math.isFinite(rank_sum)) return error.InvalidGraphMetricScore;
        const worker_id = if (page.worker_id.len != 0) page.worker_id else graph_metric_local_build_worker_id;
        const completed_units_raw = prior_completed_units + @as(u64, @intCast(checked_nodes));
        const completed_units = if (total_units != 0) @min(completed_units_raw, total_units) else completed_units_raw;
        const cursor = try std.fmt.allocPrint(self.alloc, "pagerank-check:nodes={d};delta={d}", .{ checked_nodes, total_delta });
        defer self.alloc.free(cursor);
        const fingerprint = graphMetricPageRankConvergenceFingerprint(page, checked_nodes, max_delta, total_delta, rank_sum);
        if (!reached_page_end) {
            _ = try self.updateGraphMetricBuildConvergencePageProgressForAttempt(metric_name, job.job_id, page.iteration, page.page_id, worker_id, page.attempt, last_checked_node, completed_units, total_units, max_delta, total_delta, rank_sum);
            return .{
                .phase = .check_convergence,
                .page_id = page.page_id,
                .completed_page = false,
                .completed_units = completed_units,
                .total_units = total_units,
                .max_delta = max_delta,
                .total_delta = total_delta,
                .rank_sum = rank_sum,
                .score_count = checked_nodes,
            };
        }
        const complete_units = if (total_units != 0) total_units else completed_units;
        _ = try self.updateGraphMetricBuildPageProgressForAttempt(metric_name, job.job_id, .check_convergence, page.iteration, page.page_id, worker_id, page.attempt, cursor, complete_units, total_units);
        const completed = try self.completeGraphMetricBuildConvergencePageForAttempt(metric_name, job.job_id, page.iteration, page.page_id, worker_id, page.attempt, complete_units, fingerprint, max_delta, total_delta, rank_sum, total_delta <= cfg.tolerance);
        return .{
            .phase = .check_convergence,
            .page_id = page.page_id,
            .completed_page = completed.state == .complete,
            .completed_units = completed.completed_units,
            .total_units = completed.total_units,
            .output_fingerprint = completed.output_fingerprint,
            .max_delta = max_delta,
            .total_delta = total_delta,
            .rank_sum = rank_sum,
            .score_count = checked_nodes,
        };
    }

    fn executeDegreeScanBuildPage(
        self: *GraphIndex,
        metric_name: []const u8,
        cfg: GraphMetricConfig,
        job: GraphMetricBuildJob,
        page: GraphMetricBuildPage,
    ) !usize {
        return try self.executeDegreeScanBuildPageWithLimit(metric_name, cfg, job, page, null);
    }

    fn executeDegreeScanBuildPageWithLimit(
        self: *GraphIndex,
        metric_name: []const u8,
        cfg: GraphMetricConfig,
        job: GraphMetricBuildJob,
        page: GraphMetricBuildPage,
        max_scan_units: ?u64,
    ) !usize {
        var map = std.StringHashMapUnmanaged(usize).empty;
        defer map.deinit(self.alloc);
        var nodes = std.ArrayListUnmanaged(DegreeNode).empty;
        defer {
            self.freeDegreeNodes(nodes.items);
            nodes.deinit(self.alloc);
        }

        var scanned_units: u64 = 0;
        var prior_completed_units: u64 = 0;
        var page_attempt = page.attempt;
        var reached_page_end = true;
        var last_scanned_key: []u8 = "";
        defer if (last_scanned_key.len > 0) self.alloc.free(last_scanned_key);
        {
            var txn = try self.beginReadReverseTxn();
            defer txn.abort();
            const execution_page = try self.metricBuildPage(&txn, metric_name, job.job_id, .scan_edges_and_out_degree, page.iteration, page.page_id) orelse page;
            try self.validateGraphMetricBuildPageExecutionLease(page, execution_page);
            prior_completed_units = execution_page.completed_units;
            page_attempt = execution_page.attempt;
            var cur = try txn.openCursor();
            defer cur.close();
            const resume_cursor = execution_page.cursor;
            const seek_key = if (resume_cursor.len > 0) resume_cursor else execution_page.range_lower;
            var entry_opt = if (seek_key.len > 0) try cur.seekAtOrAfter(seek_key) else try cur.first();
            while (entry_opt) |entry| : (entry_opt = try cur.next()) {
                if (resume_cursor.len > 0 and std.mem.order(u8, entry.key, resume_cursor) != .gt) continue;
                if (execution_page.range_upper.len > 0 and std.mem.order(u8, entry.key, execution_page.range_upper) != .lt) break;
                if (std.mem.startsWith(u8, entry.key, graph_meta_prefix)) continue;
                var parsed = (try parseReverseEdgeKeyAlloc(self.alloc, entry.key)) orelse continue;
                defer parsed.deinit(self.alloc);
                if (!std.mem.eql(u8, parsed.index_name, self.index_name)) continue;
                if (max_scan_units) |limit| {
                    if (scanned_units >= limit) {
                        reached_page_end = false;
                        break;
                    }
                }
                scanned_units += 1;
                if (last_scanned_key.len > 0) self.alloc.free(last_scanned_key);
                last_scanned_key = try self.alloc.dupe(u8, entry.key);
                if (!graphMetricEdgeAllowed(cfg.edge_filter, parsed.edge_type)) continue;
                const source_idx = try self.getOrPutDegreeNode(&map, &nodes, parsed.source);
                const target_idx = try self.getOrPutDegreeNode(&map, &nodes, parsed.target);
                nodes.items[source_idx].degree += 1;
                nodes.items[target_idx].degree += 1;
            }
        }

        const scores = try self.alloc.alloc(GraphMetricScore, nodes.items.len);
        defer self.alloc.free(scores);
        for (nodes.items, 0..) |node, i| {
            scores[i] = .{
                .node = node.key,
                .score = @floatFromInt(node.degree),
            };
        }
        const score_fingerprint = graphMetricScoresFingerprint(scores);
        const completed_units_raw = prior_completed_units + scanned_units;
        const completed_units = if (page.total_units != 0) @min(completed_units_raw, page.total_units) else completed_units_raw;
        const worker_id = if (page.worker_id.len != 0) page.worker_id else graph_metric_local_build_worker_id;
        {
            var score_batch = try self.beginWriteReverseBatch();
            errdefer score_batch.abort();
            for (nodes.items) |node| {
                const partial_key = try self.graphMetricBuildAttemptDegreePartialKeyAlloc(metric_name, job.job_id, .scan_edges_and_out_degree, page.iteration, page.page_id, page_attempt, node.key);
                defer self.alloc.free(partial_key);
                const prior = if (prior_completed_units != 0) try readU64OrZero(&score_batch, partial_key) else 0;
                try putU64(&score_batch, partial_key, prior + node.degree);
            }
            if (reached_page_end) {
                var adopt_page = page;
                adopt_page.attempt = page_attempt;
                _ = try self.adoptDegreeScanAttemptOutputInBatch(&score_batch, metric_name, job.job_id, adopt_page);
            }
            try score_batch.commit();
        }
        if (!reached_page_end) {
            _ = try self.updateGraphMetricBuildPageProgressForAttempt(metric_name, job.job_id, .scan_edges_and_out_degree, page.iteration, page.page_id, worker_id, page.attempt, last_scanned_key, completed_units, page.total_units);
            return scores.len;
        }
        const complete_units = if (page.total_units != 0) page.total_units else completed_units;
        _ = try self.updateGraphMetricBuildPageProgressForAttempt(metric_name, job.job_id, .scan_edges_and_out_degree, page.iteration, page.page_id, worker_id, page.attempt, "", completed_units, page.total_units);
        _ = try self.completeGraphMetricBuildPageForAttempt(metric_name, job.job_id, .scan_edges_and_out_degree, page.iteration, page.page_id, worker_id, page.attempt, complete_units, score_fingerprint);
        return scores.len;
    }

    fn executeDegreeReduceBuildPage(
        self: *GraphIndex,
        metric_name: []const u8,
        job: GraphMetricBuildJob,
        page: GraphMetricBuildPage,
    ) !usize {
        var totals = std.StringHashMapUnmanaged(u64).empty;
        defer {
            var key_it = totals.keyIterator();
            while (key_it.next()) |key_ptr| self.alloc.free(key_ptr.*);
            totals.deinit(self.alloc);
        }

        var partial_count: u64 = 0;
        {
            var txn = try self.beginReadReverseTxn();
            defer txn.abort();
            const execution_page = try self.metricBuildPage(&txn, metric_name, job.job_id, .reduce_ranks, page.iteration, page.page_id) orelse page;
            try self.validateGraphMetricBuildPageExecutionLease(page, execution_page);
            const prefix = try self.graphMetricBuildDegreePartialPrefixAlloc(metric_name, job.job_id);
            defer self.alloc.free(prefix);
            var cur = try txn.openCursor();
            defer cur.close();
            var entry_opt = try cur.seekAtOrAfter(prefix);
            while (entry_opt) |entry| : (entry_opt = try cur.next()) {
                if (!std.mem.startsWith(u8, entry.key, prefix)) break;
                const value = if (entry.value.len >= 8) std.mem.readInt(u64, entry.value[0..8], .little) else continue;
                const node = (try graphMetricFirstComponentAfterPrefixAlloc(self.alloc, entry.key, prefix)) orelse continue;
                errdefer self.alloc.free(node);
                if (execution_page.range_lower.len > 0 and std.mem.order(u8, node, execution_page.range_lower) == .lt) {
                    self.alloc.free(node);
                    continue;
                }
                if (execution_page.range_upper.len > 0 and std.mem.order(u8, node, execution_page.range_upper) != .lt) {
                    self.alloc.free(node);
                    continue;
                }
                const result = try totals.getOrPut(self.alloc, node);
                if (result.found_existing) {
                    self.alloc.free(node);
                    result.value_ptr.* += value;
                } else {
                    result.key_ptr.* = node;
                    result.value_ptr.* = value;
                }
                partial_count += 1;
            }
        }

        const scores = try self.alloc.alloc(GraphMetricScore, totals.count());
        defer self.alloc.free(scores);
        var idx: usize = 0;
        var it = totals.iterator();
        while (it.next()) |entry| : (idx += 1) {
            scores[idx] = .{
                .node = entry.key_ptr.*,
                .score = @floatFromInt(entry.value_ptr.*),
            };
        }
        const score_fingerprint = graphMetricScoresFingerprint(scores);
        const worker_id = if (page.worker_id.len != 0) page.worker_id else graph_metric_local_build_worker_id;
        const reduce_cursor = try std.fmt.allocPrint(self.alloc, "degree-reduce:partials={d};scores={d}", .{ partial_count, scores.len });
        defer self.alloc.free(reduce_cursor);
        const completed_units = if (page.total_units != 0) @min(@as(u64, @intCast(scores.len)), page.total_units) else @as(u64, @intCast(scores.len));
        _ = try self.completeDegreeReduceBuildPageWithScoresForAttempt(metric_name, job, page, worker_id, reduce_cursor, completed_units, scores, score_fingerprint);
        return scores.len;
    }

    fn completeDegreeReduceBuildPageWithScoresForAttempt(
        self: *GraphIndex,
        metric_name: []const u8,
        job: GraphMetricBuildJob,
        claimed_page: GraphMetricBuildPage,
        worker_id: []const u8,
        cursor: []const u8,
        completed_units: u64,
        scores: []const GraphMetricScore,
        output_fingerprint: u64,
    ) !GraphMetricBuildPage {
        var batch = try self.beginWriteReverseBatch();
        errdefer batch.abort();
        var page = try self.metricBuildPage(&batch, metric_name, job.job_id, .reduce_ranks, claimed_page.iteration, claimed_page.page_id) orelse return error.GraphMetricBuildPageNotFound;
        if (page.state == .complete) {
            if (page.attempt != claimed_page.attempt) return error.GraphMetricBuildPageNotLeased;
            if (page.output_fingerprint != output_fingerprint) return error.GraphMetricBuildPageOutputMismatch;
            try batch.commit();
            return page;
        }
        var expected_page = claimed_page;
        expected_page.worker_id = worker_id;
        try self.validateGraphMetricBuildPageExecutionLease(expected_page, page);
        if (page.total_units != 0 and completed_units > page.total_units) return error.InvalidGraphMetricBuildProgress;

        try self.putGraphMetricScoresInBatch(&batch, metric_name, job.score_generation, scores);

        if (try self.metricBuildJob(&batch, metric_name)) |existing_job| {
            if (existing_job.job_id == job.job_id and existing_job.phase == .reduce_ranks and existing_job.iteration == claimed_page.iteration) {
                var progress_job = existing_job;
                progress_job.cursor = cursor;
                progress_job.completed_units = completed_units;
                progress_job.total_units = page.total_units;
                progress_job.updated_at_ms = @divTrunc(platform_time.realtimeNs(), std.time.ns_per_ms);
                try self.putGraphMetricBuildJobInBatch(&batch, metric_name, progress_job);
            }
        }

        page.state = .complete;
        page.worker_id = worker_id;
        page.lease_expires_at_ms = 0;
        page.completed_units = if (page.total_units != 0) page.total_units else completed_units;
        page.cursor = "";
        page.last_error = "";
        page.output_fingerprint = output_fingerprint;
        try self.putGraphMetricBuildPageInBatch(&batch, metric_name, page);
        try batch.commit();
        return page;
    }

    fn executeGraphMetricCleanupBuildPage(
        self: *GraphIndex,
        metric_name: []const u8,
        kind: GraphMetricKind,
        job: GraphMetricBuildJob,
        page: GraphMetricBuildPage,
    ) !GraphMetricBuildPageExecutionResult {
        var cleanup_page = page;
        var page_cursor: []u8 = "";
        defer if (page_cursor.len > 0) self.alloc.free(page_cursor);
        var page_output_prefix: []u8 = "";
        defer if (page_output_prefix.len > 0) self.alloc.free(page_output_prefix);
        var page_worker_id: []u8 = "";
        defer if (page_worker_id.len > 0) self.alloc.free(page_worker_id);
        {
            var txn = try self.beginReadReverseTxn();
            defer txn.abort();
            const execution_page = try self.metricBuildPage(&txn, metric_name, job.job_id, .cleanup_old_generations, page.iteration, page.page_id) orelse page;
            try self.validateGraphMetricBuildPageExecutionLease(page, execution_page);
            if (execution_page.cursor.len > 0) page_cursor = try self.alloc.dupe(u8, execution_page.cursor);
            if (execution_page.output_prefix.len > 0) page_output_prefix = try self.alloc.dupe(u8, execution_page.output_prefix);
            if (execution_page.worker_id.len > 0) page_worker_id = try self.alloc.dupe(u8, execution_page.worker_id);
            cleanup_page = execution_page;
        }
        cleanup_page.cursor = page_cursor;
        cleanup_page.output_prefix = page_output_prefix;
        cleanup_page.worker_id = page_worker_id;
        const worker_id = if (cleanup_page.worker_id.len != 0) cleanup_page.worker_id else graph_metric_local_build_worker_id;
        const cleanup_cursor = try std.fmt.allocPrint(self.alloc, "cleanup-job:{d}:page:{d}", .{ job.job_id, page.page_id });
        defer self.alloc.free(cleanup_cursor);
        const job_namespace_prefix = try self.graphMetricBuildJobNamespacePrefixAlloc(metric_name, job.job_id);
        defer self.alloc.free(job_namespace_prefix);
        const is_final_cleanup = graphMetricBuildCleanupPageIsFinal(kind, cleanup_page);
        const cleanup_prefix = try self.graphMetricBuildCleanupPagePrefixAlloc(metric_name, kind, job.job_id, cleanup_page);
        defer self.alloc.free(cleanup_prefix);

        var batch = try self.beginWriteReverseBatch();
        errdefer batch.abort();
        var delete_page = try self.deleteKeysWithPrefixPageInBatch(&batch, cleanup_prefix, cleanup_page.cursor, graph_metric_build_cleanup_delete_page_units);
        defer delete_page.deinit(self.alloc);
        const completed_units_raw = cleanup_page.completed_units + @as(u64, @intCast(delete_page.removed));
        if (!delete_page.reached_end) {
            var progress_page = cleanup_page;
            progress_page.state = .leased;
            progress_page.worker_id = worker_id;
            progress_page.cursor = delete_page.cursor;
            progress_page.completed_units = completed_units_raw;
            progress_page.last_error = "";
            progress_page.output_prefix = cleanup_prefix;
            try self.putGraphMetricBuildPageInBatch(&batch, metric_name, progress_page);

            if (try self.metricBuildJob(&batch, metric_name)) |existing_job| {
                if (existing_job.job_id == job.job_id and existing_job.phase == .cleanup_old_generations) {
                    var updated_job = existing_job;
                    updated_job.cursor = delete_page.cursor;
                    updated_job.completed_units = completed_units_raw;
                    updated_job.total_units = cleanup_page.total_units;
                    updated_job.updated_at_ms = @divTrunc(platform_time.realtimeNs(), std.time.ns_per_ms);
                    try self.putGraphMetricBuildJobInBatch(&batch, metric_name, updated_job);
                }
            }

            try batch.commit();
            return .{
                .phase = .cleanup_old_generations,
                .page_id = page.page_id,
                .completed_page = false,
                .completed_units = completed_units_raw,
                .total_units = cleanup_page.total_units,
                .score_count = delete_page.removed,
            };
        }

        if (is_final_cleanup) {
            _ = try self.deleteGraphMetricBuildJobNamespaceInBatch(&batch, metric_name, job.job_id);
            try self.putGraphMetricBuildJobInBatch(&batch, metric_name, .{
                .job_id = job.job_id,
                .target_generation = job.target_generation,
                .score_generation = job.score_generation,
                .started_at_ms = job.started_at_ms,
                .updated_at_ms = @divTrunc(platform_time.realtimeNs(), std.time.ns_per_ms),
                .lease_expires_at_ms = 0,
                .phase = .complete,
                .iteration = job.iteration,
                .worker_id = job.worker_id,
                .completed_units = cleanup_page.total_units,
                .total_units = cleanup_page.total_units,
            });
            const lease_key = try self.graphMetricBuildLeaseKeyAlloc(metric_name);
            defer self.alloc.free(lease_key);
            batch.delete(lease_key) catch |err| switch (err) {
                error.NotFound => {},
                else => return err,
            };
        } else {
            const completed_page = GraphMetricBuildPage{
                .job_id = job.job_id,
                .phase = .cleanup_old_generations,
                .iteration = page.iteration,
                .page_id = page.page_id,
                .state = .complete,
                .range_kind = .job_control,
                .output_prefix = cleanup_prefix,
                .worker_id = worker_id,
                .cursor = cleanup_cursor,
                .completed_units = cleanup_page.total_units,
                .total_units = cleanup_page.total_units,
                .output_fingerprint = graphMetricBuildJobId(metric_name, job.target_generation, job.started_at_ms) ^ page.page_id ^ completed_units_raw,
            };
            try self.putGraphMetricBuildPageInBatch(&batch, metric_name, completed_page);
        }
        try batch.commit();
        return .{
            .phase = .cleanup_old_generations,
            .page_id = page.page_id,
            .completed_page = true,
            .completed_units = cleanup_page.total_units,
            .total_units = cleanup_page.total_units,
            .score_count = delete_page.removed,
            .published = is_final_cleanup,
            .completed_build = is_final_cleanup,
        };
    }

    fn graphMetricBuildPhaseHasPageExecutor(kind: GraphMetricKind, phase: GraphMetricBuildPhase) bool {
        return switch (kind) {
            .degree => switch (phase) {
                .prepare_generation,
                .scan_edges_and_out_degree,
                .reduce_ranks,
                .cleanup_old_generations,
                => true,
                else => false,
            },
            .pagerank => switch (phase) {
                .prepare_generation,
                .scan_edges_and_out_degree,
                .initialize_ranks,
                .iterate_contributions,
                .reduce_ranks,
                .check_convergence,
                .cleanup_old_generations,
                => true,
                else => false,
            },
            .eigenvector => switch (phase) {
                .prepare_generation,
                .scan_edges_and_out_degree,
                .initialize_ranks,
                .iterate_contributions,
                .reduce_ranks,
                .hits_hub_contributions,
                .hits_hub_reduce_ranks,
                .check_convergence,
                .cleanup_old_generations,
                => true,
                else => false,
            },
            .hits_authority,
            .hits_hub,
            => switch (phase) {
                .prepare_generation,
                .scan_edges_and_out_degree,
                .initialize_ranks,
                .iterate_contributions,
                .reduce_ranks,
                .hits_hub_contributions,
                .hits_hub_reduce_ranks,
                .check_convergence,
                .cleanup_old_generations,
                => true,
                else => false,
            },
        };
    }

    fn executeGraphMetricBuildPage(
        self: *GraphIndex,
        metric_name: []const u8,
        cfg: GraphMetricConfig,
        job: GraphMetricBuildJob,
        page: GraphMetricBuildPage,
    ) !GraphMetricBuildPageExecutionResult {
        return switch (cfg.kind) {
            .degree => try self.executeDegreeMetricBuildPage(metric_name, cfg, job, page),
            .pagerank => try self.executePageRankMetricBuildPage(metric_name, cfg, job, page),
            .eigenvector => try self.executeEigenvectorMetricBuildPage(metric_name, cfg, job, page),
            .hits_authority,
            .hits_hub,
            => try self.executeHitsMetricBuildPage(metric_name, cfg, job, page),
        };
    }

    fn executeEigenvectorMetricBuildPage(
        self: *GraphIndex,
        metric_name: []const u8,
        cfg: GraphMetricConfig,
        job: GraphMetricBuildJob,
        page: GraphMetricBuildPage,
    ) !GraphMetricBuildPageExecutionResult {
        return switch (page.phase) {
            .prepare_generation => blk: {
                const worker_id = if (page.worker_id.len != 0) page.worker_id else graph_metric_local_build_worker_id;
                const fingerprint = graphMetricBuildJobId(metric_name, job.target_generation, job.started_at_ms);
                const completed = try self.completeGraphMetricBuildPageForAttempt(metric_name, job.job_id, .prepare_generation, page.iteration, page.page_id, worker_id, page.attempt, page.total_units, fingerprint);
                break :blk .{
                    .phase = .prepare_generation,
                    .page_id = page.page_id,
                    .completed_page = true,
                    .completed_units = completed.completed_units,
                    .total_units = completed.total_units,
                    .output_fingerprint = completed.output_fingerprint,
                };
            },
            .scan_edges_and_out_degree => blk: {
                const node_count = try self.executePageRankScanBuildPage(metric_name, cfg, job, page);
                const completed = try self.readGraphMetricBuildPageCompletionSnapshotOrInput(metric_name, job.job_id, page);
                break :blk .{
                    .phase = .scan_edges_and_out_degree,
                    .page_id = page.page_id,
                    .completed_page = completed.state == .complete,
                    .completed_units = completed.completed_units,
                    .total_units = completed.total_units,
                    .output_fingerprint = completed.output_fingerprint,
                    .score_count = node_count,
                };
            },
            .initialize_ranks => blk: {
                const node_count = try self.executeEigenvectorInitializeBuildPage(metric_name, job, page);
                const completed = try self.readGraphMetricBuildPageCompletionSnapshotOrInput(metric_name, job.job_id, page);
                break :blk .{
                    .phase = .initialize_ranks,
                    .page_id = page.page_id,
                    .completed_page = completed.state == .complete,
                    .completed_units = completed.completed_units,
                    .total_units = completed.total_units,
                    .output_fingerprint = completed.output_fingerprint,
                    .score_count = node_count,
                };
            },
            .iterate_contributions => blk: {
                const target_count = try self.executeEigenvectorContributionBuildPage(metric_name, cfg, job, page);
                const completed = try self.readGraphMetricBuildPageCompletionSnapshotOrInput(metric_name, job.job_id, page);
                break :blk .{
                    .phase = .iterate_contributions,
                    .page_id = page.page_id,
                    .completed_page = completed.state == .complete,
                    .completed_units = completed.completed_units,
                    .total_units = completed.total_units,
                    .output_fingerprint = completed.output_fingerprint,
                    .score_count = target_count,
                };
            },
            .reduce_ranks => blk: {
                const node_count = try self.executeEigenvectorReduceBuildPage(metric_name, job, page);
                const completed = try self.readGraphMetricBuildPageCompletionSnapshotOrInput(metric_name, job.job_id, page);
                break :blk .{
                    .phase = .reduce_ranks,
                    .page_id = page.page_id,
                    .completed_page = completed.state == .complete,
                    .completed_units = completed.completed_units,
                    .total_units = completed.total_units,
                    .output_fingerprint = completed.output_fingerprint,
                    .score_count = node_count,
                };
            },
            .check_convergence => try self.executePageRankConvergenceBuildPage(metric_name, cfg, job, page),
            .cleanup_old_generations => blk: {
                break :blk try self.executeGraphMetricCleanupBuildPage(metric_name, cfg.kind, job, page);
            },
            else => error.UnsupportedGraphMetricBuildPhase,
        };
    }

