        try std.testing.expectError(error.InvalidGraphMetricScore, graph.runGraphMetric("pagerank"));
        var job_txn = try graph.beginReadReverseTxn();
        defer job_txn.abort();
        const failed_job = try graph.metricBuildJob(&job_txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(@as(u64, 1), failed_job.retry_count);
        try std.testing.expectEqualStrings("InvalidGraphMetricScore", failed_job.last_error);
    }
    store.close();

    metrics[0].damping = 0.85;
    store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    var failed = try graph.graphMetricStatus("pagerank");
    defer failed.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.failed, failed.state);
    try std.testing.expectEqual(published_generation, failed.published_generation);
    try std.testing.expectEqual(@as(u64, 1), failed.retry_count);
    try std.testing.expectEqualStrings("InvalidGraphMetricScore", failed.last_error);
    try std.testing.expect(failed.build_queued);
    try std.testing.expectEqual(GraphIndex.GraphMetricEventKind.failed, failed.last_event.?.kind);
    {
        var job_txn = try graph.beginReadReverseTxn();
        defer job_txn.abort();
        const failed_job = try graph.metricBuildJob(&job_txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(@as(u64, 1), failed_job.retry_count);
        try std.testing.expectEqualStrings("InvalidGraphMetricScore", failed_job.last_error);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.check_convergence, failed_job.phase);
    }

    const after_reopen_top = try graph.graphMetricTopK("pagerank", 1);
    defer {
        for (after_reopen_top) |*score| score.deinit(alloc);
        alloc.free(after_reopen_top);
    }
    try std.testing.expectEqual(@as(usize, 1), after_reopen_top.len);
    try std.testing.expectEqualStrings(expected_top_node, after_reopen_top[0].node);
    try std.testing.expectApproxEqAbs(expected_top_score, after_reopen_top[0].score, 0.0000000001);

    var recovered = try graph.runGraphMetric("pagerank");
    defer recovered.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.fresh, recovered.state);
    try std.testing.expectEqual(@as(u64, 0), recovered.retry_count);
    try std.testing.expectEqualStrings("", recovered.last_error);
    {
        var job_txn = try graph.beginReadReverseTxn();
        defer job_txn.abort();
        const recovered_job = try graph.metricBuildJob(&job_txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.complete, recovered_job.phase);
        try std.testing.expectEqual(@as(u64, 0), recovered_job.retry_count);
        try std.testing.expectEqualStrings("", recovered_job.last_error);
    }
}

test "graph metric status exposes queued and active local build lease" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-metric-lease");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-metric-lease");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{.{
        .name = "degree",
        .kind = .degree,
        .refresh = .manual,
    }};
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    try graph.addEdge("doc-a", "doc-b", "cites", 1.0, 0, 0, "");

    var queued = try graph.graphMetricStatus("degree");
    defer queued.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.not_ready, queued.state);
    try std.testing.expect(queued.build_queued);
    try std.testing.expectEqual(graph.edge_generation, queued.queued_generation);
    try std.testing.expectEqual(@as(u64, 0), queued.building_generation);

    try graph.acquireGraphMetricBuildLease("degree", graph.edge_generation);
    defer graph.releaseGraphMetricBuildLease("degree") catch {};

    var building = try graph.graphMetricStatus("degree");
    defer building.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.building, building.state);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.prepare_generation, building.phase);
    try std.testing.expectEqual(graph.edge_generation, building.building_generation);
    try std.testing.expect(building.build_job_id != 0);
    try std.testing.expect(building.build_started_at_ms != 0);
    try std.testing.expectEqual(@as(u32, 0), building.build_iteration);
    try std.testing.expectEqual(@as(u64, 0), building.queued_generation);
    try std.testing.expectEqualStrings(graph_metric_local_build_worker_id, building.build_worker_id);
    try std.testing.expect(building.build_lease_expires_at_ms > 0);
    try std.testing.expectApproxEqAbs(@as(f64, 0.01), building.progress, 0.0001);
    {
        var job_txn = try graph.beginReadReverseTxn();
        defer job_txn.abort();
        const active_job = try graph.metricBuildJob(&job_txn, "degree") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(building.build_job_id, active_job.job_id);
        try std.testing.expectEqual(graph.edge_generation, active_job.target_generation);
        try std.testing.expectEqual(graph.edge_generation, active_job.score_generation);
        try std.testing.expectEqual(building.build_started_at_ms, active_job.started_at_ms);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.prepare_generation, active_job.phase);
        try std.testing.expectEqual(@as(u32, 0), active_job.iteration);
        try std.testing.expectEqualStrings(graph_metric_local_build_worker_id, active_job.worker_id);
    }

    try graph.updateGraphMetricBuildLeaseProgressWithCursor("degree", .computing, 5, "edge-page:0007", 7, 20);
    var iterating = try graph.graphMetricStatus("degree");
    defer iterating.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.building, iterating.state);
    try std.testing.expectEqual(building.build_job_id, iterating.build_job_id);
    try std.testing.expectEqual(building.build_started_at_ms, iterating.build_started_at_ms);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.computing, iterating.phase);
    try std.testing.expectEqual(@as(u32, 5), iterating.build_iteration);
    try std.testing.expectEqualStrings("edge-page:0007", iterating.build_cursor);
    try std.testing.expectEqual(@as(u64, 7), iterating.build_completed_units);
    try std.testing.expectEqual(@as(u64, 20), iterating.build_total_units);
    try std.testing.expectApproxEqAbs(@as(f64, 0.1), iterating.progress, 0.0001);
    {
        var job_txn = try graph.beginReadReverseTxn();
        defer job_txn.abort();
        const active_job = try graph.metricBuildJob(&job_txn, "degree") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(iterating.build_job_id, active_job.job_id);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.computing, active_job.phase);
        try std.testing.expectEqual(@as(u32, 5), active_job.iteration);
        try std.testing.expectEqualStrings("edge-page:0007", active_job.cursor);
        try std.testing.expectEqual(@as(u64, 7), active_job.completed_units);
        try std.testing.expectEqual(@as(u64, 20), active_job.total_units);
        try std.testing.expect(active_job.updated_at_ms >= active_job.started_at_ms);
    }

    try std.testing.expectError(error.GraphMetricBuildAlreadyRunning, graph.runGraphMetric("degree"));

    try graph.releaseGraphMetricBuildLease("degree");

    const custom_started_at_ms = @divTrunc(platform_time.realtimeNs(), std.time.ns_per_ms);
    const custom_lease = GraphIndex.GraphMetricBuildLease{
        .job_id = 99,
        .target_generation = graph.edge_generation,
        .started_at_ms = custom_started_at_ms,
        .lease_expires_at_ms = @divTrunc(platform_time.realtimeNs(), std.time.ns_per_ms) + graph_metric_local_build_lease_ms,
        .phase = .publishing,
        .iteration = 17,
        .worker_id = "worker-a",
    };
    const custom_lease_key = try graph.graphMetricBuildLeaseKeyAlloc("degree");
    defer alloc.free(custom_lease_key);
    const custom_lease_encoded = try alloc.alloc(u8, GraphIndex.graphMetricBuildLeaseEncodedLen(custom_lease));
    defer alloc.free(custom_lease_encoded);
    GraphIndex.encodeGraphMetricBuildLease(custom_lease, custom_lease_encoded);
    var custom_lease_batch = try graph.beginWriteReverseBatch();
    errdefer custom_lease_batch.abort();
    try custom_lease_batch.put(custom_lease_key, custom_lease_encoded);
    try custom_lease_batch.commit();

    var custom_building = try graph.graphMetricStatus("degree");
    defer custom_building.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.building, custom_building.state);
    try std.testing.expectEqual(@as(u64, 99), custom_building.build_job_id);
    try std.testing.expectEqual(custom_started_at_ms, custom_building.build_started_at_ms);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.publishing, custom_building.phase);
    try std.testing.expectEqual(@as(u32, 17), custom_building.build_iteration);
    try std.testing.expectEqualStrings("worker-a", custom_building.build_worker_id);
    try std.testing.expectApproxEqAbs(@as(f64, 0.99), custom_building.progress, 0.0001);

    try graph.releaseGraphMetricBuildLease("degree");
    var published = try graph.runGraphMetric("degree");
    defer published.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.fresh, published.state);
    try std.testing.expect(!published.build_queued);
    try std.testing.expectEqual(@as(u64, 0), published.building_generation);
    try std.testing.expectEqual(@as(u64, 0), published.build_job_id);
    try std.testing.expectEqual(@as(u64, 0), published.build_started_at_ms);
    {
        var job_txn = try graph.beginReadReverseTxn();
        defer job_txn.abort();
        const completed_job = try graph.metricBuildJob(&job_txn, "degree") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.complete, completed_job.phase);
        try std.testing.expectEqual(graph.edge_generation, completed_job.target_generation);
        try std.testing.expectEqual(graph.edge_generation, completed_job.score_generation);
        try std.testing.expectEqual(@as(u64, 0), completed_job.lease_expires_at_ms);
        try std.testing.expect(completed_job.updated_at_ms >= completed_job.started_at_ms);
    }
}

test "graph metric build lease survives reopen and expired lease can be reclaimed" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-metric-lease-reopen");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-metric-lease-reopen");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{.{
        .name = "degree",
        .kind = .degree,
        .refresh = .manual,
    }};
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });

    try graph.addEdge("doc-a", "doc-b", "cites", 1.0, 0, 0, "");
    const target_generation = graph.edge_generation;
    try graph.acquireGraphMetricBuildLease("degree", target_generation);
    try graph.updateGraphMetricBuildLeaseProgressWithCursor("degree", .computing, 5, "edge-page:0013", 13, 20);
    graph.close();

    graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    var active = try graph.graphMetricStatus("degree");
    try std.testing.expectEqual(GraphIndex.GraphMetricState.building, active.state);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.computing, active.phase);
    try std.testing.expect(active.build_job_id != 0);
    const active_job_id = active.build_job_id;
    try std.testing.expect(active.build_started_at_ms != 0);
    const active_started_at_ms = active.build_started_at_ms;
    try std.testing.expectEqual(target_generation, active.building_generation);
    try std.testing.expectEqual(@as(u32, 5), active.build_iteration);
    try std.testing.expectEqualStrings("edge-page:0013", active.build_cursor);
    try std.testing.expectEqual(@as(u64, 13), active.build_completed_units);
    try std.testing.expectEqual(@as(u64, 20), active.build_total_units);
    try std.testing.expectEqualStrings(graph_metric_local_build_worker_id, active.build_worker_id);
    try std.testing.expectApproxEqAbs(@as(f64, 0.1), active.progress, 0.0001);
    {
        var job_txn = try graph.beginReadReverseTxn();
        defer job_txn.abort();
        const active_job = try graph.metricBuildJob(&job_txn, "degree") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(active.build_job_id, active_job.job_id);
        try std.testing.expectEqual(active.build_started_at_ms, active_job.started_at_ms);
        try std.testing.expectEqual(target_generation, active_job.target_generation);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.computing, active_job.phase);
        try std.testing.expectEqual(@as(u32, 5), active_job.iteration);
        try std.testing.expectEqualStrings("edge-page:0013", active_job.cursor);
        try std.testing.expectEqual(@as(u64, 13), active_job.completed_units);
        try std.testing.expectEqual(@as(u64, 20), active_job.total_units);
        try std.testing.expectEqualStrings(graph_metric_local_build_worker_id, active_job.worker_id);
    }
    active.deinit(alloc);

    const now_ms = @divTrunc(platform_time.realtimeNs(), std.time.ns_per_ms);
    const expired_lease = GraphIndex.GraphMetricBuildLease{
        .target_generation = target_generation,
        .started_at_ms = now_ms - 1,
        .lease_expires_at_ms = now_ms - 1,
        .phase = .computing,
        .iteration = 9,
        .worker_id = "expired-worker",
    };
    const expired_lease_key = try graph.graphMetricBuildLeaseKeyAlloc("degree");
    defer alloc.free(expired_lease_key);
    const expired_lease_encoded = try alloc.alloc(u8, GraphIndex.graphMetricBuildLeaseEncodedLen(expired_lease));
    defer alloc.free(expired_lease_encoded);
    GraphIndex.encodeGraphMetricBuildLease(expired_lease, expired_lease_encoded);
    var expired_batch = try graph.beginWriteReverseBatch();
    errdefer expired_batch.abort();
    try expired_batch.put(expired_lease_key, expired_lease_encoded);
    try expired_batch.commit();
    graph.close();

    graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();
    var expired = try graph.graphMetricStatus("degree");
    try std.testing.expectEqual(GraphIndex.GraphMetricState.not_ready, expired.state);
    try std.testing.expect(expired.build_queued);
    try std.testing.expectEqual(@as(u64, 0), expired.building_generation);
    try std.testing.expectEqual(@as(u64, 0), expired.build_job_id);
    try std.testing.expectEqual(@as(u64, 0), expired.build_started_at_ms);
    try std.testing.expectEqual(@as(u32, 0), expired.build_iteration);
    try std.testing.expectEqualStrings("", expired.build_worker_id);
    expired.deinit(alloc);

    var rebuilt = try graph.runGraphMetric("degree");
    defer rebuilt.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.fresh, rebuilt.state);
    try std.testing.expect(!rebuilt.build_queued);
    try std.testing.expectEqual(@as(u64, 0), rebuilt.building_generation);
    try std.testing.expectEqual(@as(u64, 0), rebuilt.build_job_id);
    try std.testing.expectEqual(@as(u64, 0), rebuilt.build_started_at_ms);
    try std.testing.expect(active_job_id != 0);
    try std.testing.expect(active_started_at_ms != 0);
    {
        var job_txn = try graph.beginReadReverseTxn();
        defer job_txn.abort();
        const completed_job = try graph.metricBuildJob(&job_txn, "degree") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.complete, completed_job.phase);
        try std.testing.expectEqual(target_generation, completed_job.target_generation);
        try std.testing.expectEqual(@as(u64, 0), completed_job.lease_expires_at_ms);
    }
}

test "graph metric edge filter equality and fingerprint treat types as set" {
    const left_types = [_][]const u8{ "cites", "mentions" };
    const right_types = [_][]const u8{ "mentions", "cites" };
    const left_filter = GraphMetricEdgeFilter{ .mode = .types, .types = &left_types };
    const right_filter = GraphMetricEdgeFilter{ .mode = .types, .types = &right_types };

    try std.testing.expect(left_filter.equivalent(right_filter));
    try std.testing.expect(right_filter.equivalent(left_filter));

    const left = GraphMetricConfig{
        .name = "pagerank",
        .kind = .pagerank,
        .edge_filter = left_filter,
    };
    const right = GraphMetricConfig{
        .name = "pagerank",
        .kind = .pagerank,
        .edge_filter = right_filter,
    };
    try std.testing.expectEqual(GraphIndex.graphMetricConfigFingerprint(left), GraphIndex.graphMetricConfigFingerprint(right));
}

test "graph metric build manifest is durable and idempotent across reopen" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-metric-manifest");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-metric-manifest");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{.{
        .name = "pagerank",
        .kind = .pagerank,
        .refresh = .manual,
    }};
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });

    try graph.addEdge("doc-a", "doc-b", "cites", 1.0, 0, 0, "");
    try graph.addEdge("doc-b", "doc-c", "cites", 1.0, 0, 0, "");
    const target_generation = graph.edge_generation;
    try graph.acquireGraphMetricBuildLease("pagerank", target_generation);

    var active_job = GraphIndex.GraphMetricBuildJob{};
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        active_job = try graph.metricBuildJob(&txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
        const manifest = try graph.metricBuildManifest(&txn, "pagerank", active_job.job_id) orelse return error.TestExpectedGraphMetricBuildManifest;
        try std.testing.expectEqual(active_job.job_id, manifest.job_id);
        try std.testing.expectEqual(target_generation, manifest.target_generation);
        try std.testing.expectEqual(target_generation, manifest.score_generation);
        try std.testing.expectEqual(GraphIndex.graphMetricConfigFingerprint(metrics[0]), manifest.config_fingerprint);
        try std.testing.expectEqual(@as(u64, 2), manifest.edge_count);
        try std.testing.expectEqual(@as(u64, 3), manifest.node_count);
        try std.testing.expectEqual(GraphIndex.graph_metric_iterative_build_phases.len, manifest.phase_count);
        try std.testing.expectEqual(GraphIndex.graph_metric_iterative_build_phases.len + 2, manifest.page_count);

        const scan_page = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .scan_edges_and_out_degree, 0, 1) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.pending, scan_page.state);
        try std.testing.expectEqual(@as(u64, 2), scan_page.total_units);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageRangeKind.reverse_edges, scan_page.range_kind);
        try std.testing.expect(scan_page.range_lower.len > 0);
        try std.testing.expectEqualStrings("", scan_page.range_upper);
        const initialize_page = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .initialize_ranks, 0, 2) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(@as(u64, 3), initialize_page.total_units);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageRangeKind.nodes, initialize_page.range_kind);
    }
    graph.close();

    graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const manifest = try graph.metricBuildManifest(&txn, "pagerank", active_job.job_id) orelse return error.TestExpectedGraphMetricBuildManifest;
        try std.testing.expectEqual(target_generation, manifest.target_generation);
        const scan_page = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .scan_edges_and_out_degree, 0, 1) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.pending, scan_page.state);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageRangeKind.reverse_edges, scan_page.range_kind);
        try std.testing.expect(scan_page.range_lower.len > 0);
    }

    {
        var batch = try graph.beginWriteReverseBatch();
        errdefer batch.abort();
        try graph.putGraphMetricBuildPageInBatch(&batch, "pagerank", .{
            .job_id = active_job.job_id,
            .phase = .scan_edges_and_out_degree,
            .iteration = 0,
            .page_id = 1,
            .state = .complete,
            .completed_units = 2,
            .total_units = 2,
            .output_fingerprint = 1234,
        });
        try batch.commit();
    }

    try graph.ensureGraphMetricBuildManifestForJob("pagerank", active_job);
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const manifest = try graph.metricBuildManifest(&txn, "pagerank", active_job.job_id) orelse return error.TestExpectedGraphMetricBuildManifest;
        try std.testing.expectEqual(GraphIndex.graph_metric_iterative_build_phases.len + 2, manifest.page_count);
        const scan_page = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .scan_edges_and_out_degree, 0, 1) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.complete, scan_page.state);
        try std.testing.expectEqual(@as(u64, 2), scan_page.completed_units);
        try std.testing.expectEqual(@as(u64, 1234), scan_page.output_fingerprint);
    }
}

test "graph metric build pagerank manifest partitions iterative phase pages" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-pagerank-manifest-partitions");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-pagerank-manifest-partitions");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{.{
        .name = "pagerank",
        .kind = .pagerank,
        .refresh = .manual,
    }};
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    for (0..graph_metric_build_target_scan_page_units + 1) |i| {
        var target_buf: [64]u8 = undefined;
        const target = try std.fmt.bufPrint(&target_buf, "doc-{d:0>3}", .{i});
        try graph.addEdge("hub", target, "cites", 1.0, 0, 0, "");
    }
    try graph.acquireGraphMetricBuildLease("pagerank", graph.edge_generation);
    defer graph.releaseGraphMetricBuildLease("pagerank") catch {};

    var job_txn = try graph.beginReadReverseTxn();
    const active_job = try graph.metricBuildJob(&job_txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
    job_txn.abort();

    var txn = try graph.beginReadReverseTxn();
    defer txn.abort();
    const manifest = try graph.metricBuildManifest(&txn, "pagerank", active_job.job_id) orelse return error.TestExpectedGraphMetricBuildManifest;
    try std.testing.expectEqual(GraphIndex.graph_metric_iterative_build_phases.len + 7, manifest.page_count);

    const first_scan = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .scan_edges_and_out_degree, 0, 1) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageRangeKind.reverse_edges, first_scan.range_kind);
    try std.testing.expect(first_scan.range_lower.len > 0);
    try std.testing.expect(first_scan.range_upper.len > 0);
    try std.testing.expectEqual(@as(u64, graph_metric_build_target_scan_page_units), first_scan.total_units);
    const second_scan = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .scan_edges_and_out_degree, 0, 2) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqualStrings(first_scan.range_upper, second_scan.range_lower);
    try std.testing.expectEqualStrings("", second_scan.range_upper);
    try std.testing.expectEqual(@as(u64, 1), second_scan.total_units);

    const first_init = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .initialize_ranks, 0, 2) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageRangeKind.nodes, first_init.range_kind);
    try std.testing.expect(first_init.range_lower.len > 0);
    try std.testing.expect(first_init.range_upper.len > 0);
    try std.testing.expectEqual(@as(u64, graph_metric_build_target_reduce_page_units), first_init.total_units);
    const second_init = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .initialize_ranks, 0, 3) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqualStrings(first_init.range_upper, second_init.range_lower);
    try std.testing.expectEqualStrings("", second_init.range_upper);
    try std.testing.expectEqual(graph.node_count - graph_metric_build_target_reduce_page_units, second_init.total_units);

    const contribution = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .iterate_contributions, 0, 3) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageRangeKind.reverse_edges, contribution.range_kind);
    const reduce = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .reduce_ranks, 0, 4) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageRangeKind.nodes, reduce.range_kind);
    const convergence = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .check_convergence, 0, 5) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageRangeKind.nodes, convergence.range_kind);

    const out_degree_cleanup = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .cleanup_old_generations, 0, 0) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageRangeKind.job_control, out_degree_cleanup.range_kind);
    try std.testing.expect(out_degree_cleanup.output_prefix.len > 0);
    const node_cleanup = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .cleanup_old_generations, 0, 1) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageRangeKind.job_control, node_cleanup.range_kind);
    try std.testing.expect(node_cleanup.output_prefix.len > 0);
    const final_cleanup = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .cleanup_old_generations, 0, 2) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageRangeKind.job_control, final_cleanup.range_kind);
    try std.testing.expect(final_cleanup.output_prefix.len > 0);
    try std.testing.expect(!std.mem.eql(u8, out_degree_cleanup.output_prefix, node_cleanup.output_prefix));
    try std.testing.expect(!std.mem.eql(u8, node_cleanup.output_prefix, final_cleanup.output_prefix));
    try std.testing.expect((try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .cleanup_old_generations, 0, 3)) == null);
}

test "graph pagerank planned scan page writes durable out-degree intermediates" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-pagerank-scan-executor");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-pagerank-scan-executor");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const edge_types = [_][]const u8{"cites"};
    const metrics = [_]GraphMetricConfig{.{
        .name = "pagerank",
        .kind = .pagerank,
        .refresh = .manual,
        .edge_filter = .{ .mode = .types, .types = &edge_types },
    }};
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    try graph.addEdge("doc-a", "doc-b", "cites", 1.0, 0, 0, "");
    try graph.addEdge("doc-a", "doc-c", "cites", 1.0, 0, 0, "");
    try graph.addEdge("doc-b", "doc-c", "cites", 1.0, 0, 0, "");
    try graph.addEdge("doc-c", "doc-d", "related", 1.0, 0, 0, "");
    try graph.acquireGraphMetricBuildLease("pagerank", graph.edge_generation);
    defer graph.releaseGraphMetricBuildLease("pagerank") catch {};

    var job_txn = try graph.beginReadReverseTxn();
    const active_job = try graph.metricBuildJob(&job_txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
    job_txn.abort();

    _ = try graph.claimGraphMetricBuildPageAt("pagerank", active_job.job_id, .prepare_generation, 0, 0, "worker-a", 1000);
    _ = try graph.completeGraphMetricBuildPage("pagerank", active_job.job_id, .prepare_generation, 0, 0, "worker-a", 1, GraphIndex.graphMetricBuildJobId("pagerank", active_job.target_generation, active_job.started_at_ms));
    try std.testing.expect(try graph.advanceGraphMetricBuildPhaseIfReady("pagerank", active_job.job_id, .prepare_generation, 0));

    const scan = try graph.runGraphMetricPlannedWorkerStep("pagerank", metrics[0], "worker-a");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.scan_edges_and_out_degree, scan.phase);
    try std.testing.expect(scan.claimed_page);
    try std.testing.expect(scan.completed_page);
    try std.testing.expect(scan.advanced_phase);

    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .scan_edges_and_out_degree, 0, 1) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.complete, page.state);
        try std.testing.expectEqual(@as(u64, 4), page.completed_units);
        try std.testing.expect(page.output_fingerprint != 0);
        const job = try graph.metricBuildJob(&txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.initialize_ranks, job.phase);

        const doc_a_out_key = try graph.graphMetricBuildPageRankOutDegreePartialKeyAlloc("pagerank", active_job.job_id, "doc-a", 1);
        defer alloc.free(doc_a_out_key);
        try std.testing.expectEqual(@as(u64, 2), try GraphIndex.readU64OrZero(&txn, doc_a_out_key));
        const doc_b_out_key = try graph.graphMetricBuildPageRankOutDegreePartialKeyAlloc("pagerank", active_job.job_id, "doc-b", 1);
        defer alloc.free(doc_b_out_key);
        try std.testing.expectEqual(@as(u64, 1), try GraphIndex.readU64OrZero(&txn, doc_b_out_key));
        const doc_c_out_key = try graph.graphMetricBuildPageRankOutDegreePartialKeyAlloc("pagerank", active_job.job_id, "doc-c", 1);
        defer alloc.free(doc_c_out_key);
        try std.testing.expectEqual(@as(u64, 0), try GraphIndex.readU64OrZero(&txn, doc_c_out_key));

        inline for (.{ "doc-a", "doc-b", "doc-c" }) |node| {
            const node_key = try graph.graphMetricBuildPageRankNodePartialKeyAlloc("pagerank", active_job.job_id, node, 1);
            defer alloc.free(node_key);
            try std.testing.expectEqual(@as(u64, 1), try GraphIndex.readU64OrZero(&txn, node_key));
        }
        const filtered_node_key = try graph.graphMetricBuildPageRankNodePartialKeyAlloc("pagerank", active_job.job_id, "doc-d", 1);
        defer alloc.free(filtered_node_key);
        try std.testing.expectEqual(@as(u64, 0), try GraphIndex.readU64OrZero(&txn, filtered_node_key));
    }

    const initialize = try graph.runGraphMetricPlannedWorkerStep("pagerank", metrics[0], "worker-a");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.initialize_ranks, initialize.phase);
    try std.testing.expect(initialize.claimed_page);
    try std.testing.expect(initialize.completed_page);
    try std.testing.expect(initialize.advanced_phase);
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .initialize_ranks, 0, 2) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.complete, page.state);
        try std.testing.expectEqual(@as(u64, 4), page.completed_units);
        try std.testing.expect(page.output_fingerprint != 0);
        const job = try graph.metricBuildJob(&txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.iterate_contributions, job.phase);

        inline for (.{ "doc-a", "doc-b", "doc-c" }) |node| {
            const rank_key = try graph.graphMetricBuildPageRankKeyAlloc("pagerank", active_job.job_id, 0, node);
            defer alloc.free(rank_key);
            try std.testing.expectApproxEqAbs(@as(f64, 1.0 / 3.0), try GraphIndex.readF64OrZero(&txn, rank_key), 0.0000001);
        }
        const filtered_rank_key = try graph.graphMetricBuildPageRankKeyAlloc("pagerank", active_job.job_id, 0, "doc-d");
        defer alloc.free(filtered_rank_key);
        try std.testing.expectEqual(@as(f64, 0.0), try GraphIndex.readF64OrZero(&txn, filtered_rank_key));

        const doc_a_out_total_key = try graph.graphMetricBuildPageRankOutDegreeKeyAlloc("pagerank", active_job.job_id, "doc-a");
        defer alloc.free(doc_a_out_total_key);
        try std.testing.expectEqual(@as(u64, 2), try GraphIndex.readU64OrZero(&txn, doc_a_out_total_key));
        const doc_b_out_total_key = try graph.graphMetricBuildPageRankOutDegreeKeyAlloc("pagerank", active_job.job_id, "doc-b");
        defer alloc.free(doc_b_out_total_key);
        try std.testing.expectEqual(@as(u64, 1), try GraphIndex.readU64OrZero(&txn, doc_b_out_total_key));
        const doc_c_out_total_key = try graph.graphMetricBuildPageRankOutDegreeKeyAlloc("pagerank", active_job.job_id, "doc-c");
        defer alloc.free(doc_c_out_total_key);
        try std.testing.expectEqual(@as(u64, 0), try GraphIndex.readU64OrZero(&txn, doc_c_out_total_key));
    }

    const contributions = try graph.runGraphMetricPlannedWorkerStep("pagerank", metrics[0], "worker-a");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.iterate_contributions, contributions.phase);
    try std.testing.expect(contributions.claimed_page);
    try std.testing.expect(contributions.completed_page);
    try std.testing.expect(contributions.advanced_phase);
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .iterate_contributions, 0, 3) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.complete, page.state);
        try std.testing.expectEqual(@as(u64, 4), page.completed_units);
        try std.testing.expect(page.output_fingerprint != 0);
        const job = try graph.metricBuildJob(&txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.reduce_ranks, job.phase);

        const doc_b_contribution_key = try graph.graphMetricBuildPageRankContributionKeyAlloc("pagerank", active_job.job_id, 0, "doc-b", 3);
        defer alloc.free(doc_b_contribution_key);
        try std.testing.expectApproxEqAbs(@as(f64, 0.85 * (1.0 / 3.0) / 2.0), try GraphIndex.readF64OrZero(&txn, doc_b_contribution_key), 0.0000001);
        const doc_c_contribution_key = try graph.graphMetricBuildPageRankContributionKeyAlloc("pagerank", active_job.job_id, 0, "doc-c", 3);
        defer alloc.free(doc_c_contribution_key);
        try std.testing.expectApproxEqAbs(@as(f64, 0.85 * (1.0 / 3.0) / 2.0 + 0.85 * (1.0 / 3.0)), try GraphIndex.readF64OrZero(&txn, doc_c_contribution_key), 0.0000001);
        const doc_d_contribution_key = try graph.graphMetricBuildPageRankContributionKeyAlloc("pagerank", active_job.job_id, 0, "doc-d", 3);
        defer alloc.free(doc_d_contribution_key);
        try std.testing.expectEqual(@as(f64, 0.0), try GraphIndex.readF64OrZero(&txn, doc_d_contribution_key));
    }

    const reduce = try graph.runGraphMetricPlannedWorkerStep("pagerank", metrics[0], "worker-a");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.reduce_ranks, reduce.phase);
    try std.testing.expect(reduce.claimed_page);
    try std.testing.expect(reduce.completed_page);
    try std.testing.expect(reduce.advanced_phase);
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .reduce_ranks, 0, 4) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.complete, page.state);
        try std.testing.expectEqual(@as(u64, 4), page.completed_units);
        try std.testing.expect(page.output_fingerprint != 0);
        const job = try graph.metricBuildJob(&txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.check_convergence, job.phase);

        const doc_a_rank_key = try graph.graphMetricBuildPageRankKeyAlloc("pagerank", active_job.job_id, 1, "doc-a");
        defer alloc.free(doc_a_rank_key);
        try std.testing.expectApproxEqAbs(@as(f64, 0.14444444444444446), try GraphIndex.readF64OrZero(&txn, doc_a_rank_key), 0.0000001);
        const doc_b_rank_key = try graph.graphMetricBuildPageRankKeyAlloc("pagerank", active_job.job_id, 1, "doc-b");
        defer alloc.free(doc_b_rank_key);
        try std.testing.expectApproxEqAbs(@as(f64, 0.2861111111111111), try GraphIndex.readF64OrZero(&txn, doc_b_rank_key), 0.0000001);
        const doc_c_rank_key = try graph.graphMetricBuildPageRankKeyAlloc("pagerank", active_job.job_id, 1, "doc-c");
        defer alloc.free(doc_c_rank_key);
        try std.testing.expectApproxEqAbs(@as(f64, 0.5694444444444444), try GraphIndex.readF64OrZero(&txn, doc_c_rank_key), 0.0000001);
        const doc_d_rank_key = try graph.graphMetricBuildPageRankKeyAlloc("pagerank", active_job.job_id, 1, "doc-d");
        defer alloc.free(doc_d_rank_key);
        try std.testing.expectEqual(@as(f64, 0.0), try GraphIndex.readF64OrZero(&txn, doc_d_rank_key));
    }

    const convergence = try graph.runGraphMetricPlannedWorkerStep("pagerank", metrics[0], "worker-a");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.check_convergence, convergence.phase);
    try std.testing.expect(convergence.claimed_page);
    try std.testing.expect(convergence.completed_page);
    try std.testing.expect(convergence.advanced_phase);
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .check_convergence, 0, 5) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.complete, page.state);
        try std.testing.expectEqual(@as(u64, 4), page.completed_units);
        try std.testing.expect(page.output_fingerprint != 0);
        try std.testing.expectApproxEqAbs(@as(f64, 0.2361111111111111), page.max_delta, 0.0000001);
        try std.testing.expectApproxEqAbs(@as(f64, 0.4722222222222222), page.total_delta, 0.0000001);
        try std.testing.expectApproxEqAbs(@as(f64, 1.0), page.rank_sum, 0.0000001);
        try std.testing.expect(!page.converged);
        const job = try graph.metricBuildJob(&txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.iterate_contributions, job.phase);
        try std.testing.expectEqual(@as(u32, 1), job.iteration);
        const next_contribution = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .iterate_contributions, 1, 3) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.pending, next_contribution.state);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageRangeKind.reverse_edges, next_contribution.range_kind);
        const next_reduce = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .reduce_ranks, 1, 4) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.pending, next_reduce.state);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageRangeKind.nodes, next_reduce.range_kind);
        const next_check = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .check_convergence, 1, 5) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.pending, next_check.state);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageRangeKind.nodes, next_check.range_kind);

        const phase_summary = try graph.metricBuildPhaseSummary(&txn, "pagerank", active_job.job_id, .check_convergence, 0) orelse return error.TestExpectedGraphMetricBuildPhaseSummary;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhaseState.complete, phase_summary.state);
        try std.testing.expectApproxEqAbs(@as(f64, 0.2361111111111111), phase_summary.max_delta, 0.0000001);
        try std.testing.expectApproxEqAbs(@as(f64, 0.4722222222222222), phase_summary.total_delta, 0.0000001);
        try std.testing.expectApproxEqAbs(@as(f64, 1.0), phase_summary.rank_sum, 0.0000001);
        try std.testing.expect(!phase_summary.converged);
        const iteration_summary = try graph.metricBuildIterationSummary(&txn, "pagerank", active_job.job_id, 0) orelse return error.TestExpectedGraphMetricBuildIterationSummary;
        try std.testing.expect(!iteration_summary.converged);
        try std.testing.expect(!iteration_summary.fixed_iteration_limit);
    }
}

test "graph pagerank reclaimed scan page overwrites stale partial output" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-pagerank-scan-reclaim");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-pagerank-scan-reclaim");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{.{
        .name = "pagerank",
        .kind = .pagerank,
        .refresh = .manual,
        .max_iterations = 1,
    }};
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    try graph.addEdge("doc-a", "doc-b", "cites", 1.0, 0, 0, "");
    try graph.addEdge("doc-a", "doc-c", "cites", 1.0, 0, 0, "");
    try graph.acquireGraphMetricBuildLease("pagerank", graph.edge_generation);
    defer graph.releaseGraphMetricBuildLease("pagerank") catch {};

    var job_txn = try graph.beginReadReverseTxn();
    const active_job = try graph.metricBuildJob(&job_txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
    job_txn.abort();

    const prepare = try graph.runGraphMetricPlannedWorkerStep("pagerank", metrics[0], "worker-setup");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.prepare_generation, prepare.phase);
    try std.testing.expect(prepare.completed_page);
    try std.testing.expect(prepare.advanced_phase);

    const partial_scan_claim = try graph.claimGraphMetricBuildPageAt("pagerank", active_job.job_id, .scan_edges_and_out_degree, 0, 1, "worker-a", 2000) orelse return error.TestExpectedGraphMetricBuildPage;
    _ = try graph.executePageRankScanBuildPageWithLimit("pagerank", metrics[0], active_job, partial_scan_claim, 1);
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .scan_edges_and_out_degree, 0, 1) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, page.state);
        try std.testing.expectEqual(@as(u64, 1), page.completed_units);
        try std.testing.expect(page.cursor.len > 0);

        const partial_out_degree = try graph.aggregatePageRankOutDegreeForNode(&txn, "pagerank", active_job.job_id, "doc-a");
        try std.testing.expectEqual(@as(u64, 0), partial_out_degree);
        const attempt_out_degree_key = try graph.graphMetricBuildAttemptPageRankOutDegreePartialKeyAlloc("pagerank", active_job.job_id, .scan_edges_and_out_degree, 0, partial_scan_claim.page_id, partial_scan_claim.attempt, "doc-a");
        defer alloc.free(attempt_out_degree_key);
        try std.testing.expectEqual(@as(u64, 1), try GraphIndex.readU64OrZero(&txn, attempt_out_degree_key));
        const node_b_key = try graph.graphMetricBuildPageRankNodePartialKeyAlloc("pagerank", active_job.job_id, "doc-b", 1);
        defer alloc.free(node_b_key);
        try std.testing.expectError(error.NotFound, txn.get(node_b_key));
        const attempt_node_b_key = try graph.graphMetricBuildAttemptPageRankNodePartialKeyAlloc("pagerank", active_job.job_id, .scan_edges_and_out_degree, 0, partial_scan_claim.page_id, partial_scan_claim.attempt, "doc-b");
        defer alloc.free(attempt_node_b_key);
        try std.testing.expectEqual(@as(u64, 1), try GraphIndex.readU64OrZero(&txn, attempt_node_b_key));
    }

    const scan_expires_at = blk: {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .scan_edges_and_out_degree, 0, 1) orelse return error.TestExpectedGraphMetricBuildPage;
        break :blk page.lease_expires_at_ms;
    };
    const reclaimed_scan = try graph.claimGraphMetricBuildPageAt("pagerank", active_job.job_id, .scan_edges_and_out_degree, 0, 1, "worker-b", scan_expires_at + 1) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, reclaimed_scan.state);
    try std.testing.expectEqual(@as(u64, 2), reclaimed_scan.attempt);
    try std.testing.expectEqual(@as(u64, 0), reclaimed_scan.completed_units);
    try std.testing.expectEqualStrings("", reclaimed_scan.cursor);
    {
        var stale_out_degrees = std.StringHashMapUnmanaged(u64).empty;
        defer {
            var key_it = stale_out_degrees.keyIterator();
            while (key_it.next()) |key_ptr| alloc.free(key_ptr.*);
            stale_out_degrees.deinit(alloc);
        }
        var stale_nodes = std.StringHashMapUnmanaged(void).empty;
        defer {
            var key_it = stale_nodes.keyIterator();
            while (key_it.next()) |key_ptr| alloc.free(key_ptr.*);
            stale_nodes.deinit(alloc);
        }
        try stale_out_degrees.put(alloc, try alloc.dupe(u8, "doc-a"), 99);
        try stale_nodes.put(alloc, try alloc.dupe(u8, "doc-stale"), {});
        try std.testing.expectError(error.GraphMetricBuildPageNotLeased, graph.writePageRankScanPartialsForAttempt("pagerank", active_job, partial_scan_claim, 0, &stale_out_degrees, &stale_nodes, false));
    }
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const stale_node_key = try graph.graphMetricBuildPageRankNodePartialKeyAlloc("pagerank", active_job.job_id, "doc-stale", 1);
        defer alloc.free(stale_node_key);
        try std.testing.expectError(error.NotFound, txn.get(stale_node_key));
        const partial_out_degree = try graph.aggregatePageRankOutDegreeForNode(&txn, "pagerank", active_job.job_id, "doc-a");
        try std.testing.expectEqual(@as(u64, 0), partial_out_degree);
    }

    _ = try graph.executePageRankScanBuildPageWithLimit("pagerank", metrics[0], active_job, reclaimed_scan, null);
    try std.testing.expect(try graph.advanceGraphMetricBuildPhaseIfReady("pagerank", active_job.job_id, .scan_edges_and_out_degree, 0));
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .scan_edges_and_out_degree, 0, 1) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.complete, page.state);
        try std.testing.expectEqual(page.total_units, page.completed_units);

        const out_degree = try graph.aggregatePageRankOutDegreeForNode(&txn, "pagerank", active_job.job_id, "doc-a");
        try std.testing.expectEqual(@as(u64, 2), out_degree);
        inline for (.{ "doc-a", "doc-b", "doc-c" }) |node| {
            const node_key = try graph.graphMetricBuildPageRankNodePartialKeyAlloc("pagerank", active_job.job_id, node, 1);
            defer alloc.free(node_key);
            try std.testing.expectEqual(@as(u64, 1), try GraphIndex.readU64OrZero(&txn, node_key));
        }
        const job = try graph.metricBuildJob(&txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.initialize_ranks, job.phase);
    }
}

test "graph pagerank reclaimed initialize page overwrites stale rank output" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-pagerank-initialize-reclaim");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-pagerank-initialize-reclaim");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{.{
        .name = "pagerank",
        .kind = .pagerank,
        .refresh = .manual,
        .max_iterations = 1,
        .tolerance = 0.000001,
    }};
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    try graph.addEdge("doc-a", "doc-b", "cites", 1.0, 0, 0, "");
    try graph.addEdge("doc-c", "doc-b", "cites", 1.0, 0, 0, "");
    try graph.acquireGraphMetricBuildLease("pagerank", graph.edge_generation);
    defer graph.releaseGraphMetricBuildLease("pagerank") catch {};

    var job_txn = try graph.beginReadReverseTxn();
    const active_job = try graph.metricBuildJob(&job_txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
    job_txn.abort();

    inline for (.{ .prepare_generation, .scan_edges_and_out_degree }) |expected_phase| {
        const step = try graph.runGraphMetricPlannedWorkerStep("pagerank", metrics[0], "worker-setup");
        try std.testing.expectEqual(expected_phase, step.phase);
        try std.testing.expect(step.claimed_page);
        try std.testing.expect(step.completed_page);
        try std.testing.expect(step.advanced_phase);
    }

    const initial_claim = try graph.claimNextGraphMetricBuildPageAt("pagerank", active_job.job_id, .initialize_ranks, 0, "worker-a", 2000) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, initial_claim.state);
    try std.testing.expectEqual(@as(u64, 1), initial_claim.attempt);

    {
        var batch = try graph.beginWriteReverseBatch();
        errdefer batch.abort();
        inline for (.{ "doc-a", "doc-b", "doc-c" }) |node| {
            const out_degree_key = try graph.graphMetricBuildPageRankOutDegreeKeyAlloc("pagerank", active_job.job_id, node);
            defer alloc.free(out_degree_key);
            try GraphIndex.putU64(&batch, out_degree_key, 99);
            const rank_key = try graph.graphMetricBuildPageRankKeyAlloc("pagerank", active_job.job_id, 0, node);
            defer alloc.free(rank_key);
            try GraphIndex.putF64(&batch, rank_key, 42.0);
        }
        try batch.commit();
    }

    const reclaimed = try graph.claimGraphMetricBuildPageAt(
        "pagerank",
        active_job.job_id,
        .initialize_ranks,
        0,
        initial_claim.page_id,
        "worker-b",
        initial_claim.lease_expires_at_ms + 1,
    ) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, reclaimed.state);
    try std.testing.expectEqual(@as(u64, 2), reclaimed.attempt);
    try std.testing.expectEqual(@as(u64, 0), reclaimed.completed_units);
    try std.testing.expectEqualStrings("", reclaimed.cursor);
    try std.testing.expectEqual(@as(u64, 0), reclaimed.output_fingerprint);
    const stale_initialized = [_]GraphIndex.PageRankInitializeNode{.{
        .node = "doc-a",
        .out_degree = 123,
    }};
    try std.testing.expectError(error.GraphMetricBuildPageNotLeased, graph.writePageRankInitializeOutputForAttempt("pagerank", active_job, initial_claim, &stale_initialized, 99.0));
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const out_degree_key = try graph.graphMetricBuildPageRankOutDegreeKeyAlloc("pagerank", active_job.job_id, "doc-a");
        defer alloc.free(out_degree_key);
        try std.testing.expectEqual(@as(u64, 99), try GraphIndex.readU64OrZero(&txn, out_degree_key));
        const rank_key = try graph.graphMetricBuildPageRankKeyAlloc("pagerank", active_job.job_id, 0, "doc-a");
        defer alloc.free(rank_key);
        try std.testing.expectApproxEqAbs(@as(f64, 42.0), try GraphIndex.readF64OrZero(&txn, rank_key), 0.0000001);
    }

    _ = try graph.executePageRankInitializeBuildPage("pagerank", active_job, reclaimed);
    try std.testing.expect(try graph.advanceGraphMetricBuildPhaseIfReady("pagerank", active_job.job_id, .initialize_ranks, 0));

    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .initialize_ranks, 0, initial_claim.page_id) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.complete, page.state);
        try std.testing.expectEqual(page.total_units, page.completed_units);

        const expected_rank = 1.0 / 3.0;
        inline for (.{ "doc-a", "doc-b", "doc-c" }) |node| {
            const out_degree_key = try graph.graphMetricBuildPageRankOutDegreeKeyAlloc("pagerank", active_job.job_id, node);
            defer alloc.free(out_degree_key);
            const out_degree = try GraphIndex.readU64OrZero(&txn, out_degree_key);
            if (std.mem.eql(u8, node, "doc-b")) {
                try std.testing.expectEqual(@as(u64, 0), out_degree);
            } else {
                try std.testing.expectEqual(@as(u64, 1), out_degree);
            }
            const rank_key = try graph.graphMetricBuildPageRankKeyAlloc("pagerank", active_job.job_id, 0, node);
            defer alloc.free(rank_key);
            try std.testing.expectApproxEqAbs(expected_rank, try GraphIndex.readF64OrZero(&txn, rank_key), 0.0000001);
        }

        const job = try graph.metricBuildJob(&txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.iterate_contributions, job.phase);
    }
}

test "graph pagerank contribution and reduce pages resume from durable cursor after reopen" {
    const alloc = std.testing.allocator;
