        try std.testing.expect(step.advanced_phase);
    }

    const first_claim = try graph.claimGraphMetricBuildPageAt("pagerank", active_job.job_id, .iterate_contributions, 0, 3, "worker-a", 2000) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, first_claim.state);
    _ = try graph.executePageRankContributionBuildPageWithLimit("pagerank", metrics[0], active_job, first_claim, 1);
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .iterate_contributions, 0, 3) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, page.state);
        try std.testing.expectEqual(@as(u64, 1), page.completed_units);
        try std.testing.expect(page.cursor.len > 0);
        const job = try graph.metricBuildJob(&txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.iterate_contributions, job.phase);
        try std.testing.expectEqualStrings(page.cursor, job.cursor);

        const adopted_contribution = try graph.aggregatePageRankContributionForNode(&txn, "pagerank", active_job.job_id, 0, "doc-b");
        try std.testing.expectApproxEqAbs(@as(f64, 0.0), adopted_contribution, 0.0);
        const attempt_contribution_key = try graph.graphMetricBuildAttemptPageRankContributionKeyAlloc("pagerank", active_job.job_id, .iterate_contributions, 0, 3, first_claim.attempt, "doc-b");
        defer alloc.free(attempt_contribution_key);
        try std.testing.expectApproxEqAbs(@as(f64, 0.85 * (1.0 / 3.0)), try GraphIndex.readF64OrZero(&txn, attempt_contribution_key), 0.0000001);
    }
    graph.close();

    graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();
    const renewed = try graph.claimGraphMetricBuildPageAt("pagerank", active_job.job_id, .iterate_contributions, 0, 3, "worker-a", 2001) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, renewed.state);
    try std.testing.expectEqual(@as(u64, 1), renewed.completed_units);
    try std.testing.expect(renewed.cursor.len > 0);

    _ = try graph.executePageRankContributionBuildPageWithLimit("pagerank", metrics[0], active_job, renewed, null);
    try std.testing.expect(try graph.advanceGraphMetricBuildPhaseIfReady("pagerank", active_job.job_id, .iterate_contributions, 0));
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .iterate_contributions, 0, 3) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.complete, page.state);
        try std.testing.expectEqual(@as(u64, 2), page.completed_units);
        try std.testing.expect(page.output_fingerprint != 0);
        const job = try graph.metricBuildJob(&txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.reduce_ranks, job.phase);

        const doc_b_contribution_key = try graph.graphMetricBuildPageRankContributionKeyAlloc("pagerank", active_job.job_id, 0, "doc-b", 3);
        defer alloc.free(doc_b_contribution_key);
        try std.testing.expectApproxEqAbs(@as(f64, 2.0 * 0.85 * (1.0 / 3.0)), try GraphIndex.readF64OrZero(&txn, doc_b_contribution_key), 0.0000001);
        const attempt_contribution_key = try graph.graphMetricBuildAttemptPageRankContributionKeyAlloc("pagerank", active_job.job_id, .iterate_contributions, 0, 3, first_claim.attempt, "doc-b");
        defer alloc.free(attempt_contribution_key);
        try std.testing.expectApproxEqAbs(@as(f64, 2.0 * 0.85 * (1.0 / 3.0)), try GraphIndex.readF64OrZero(&txn, attempt_contribution_key), 0.0000001);
    }

    const reduce_claim = try graph.claimGraphMetricBuildPageAt("pagerank", active_job.job_id, .reduce_ranks, 0, 4, "worker-r", 3000) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, reduce_claim.state);
    _ = try graph.executePageRankReduceBuildPageWithLimit("pagerank", metrics[0], active_job, reduce_claim, 1);
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .reduce_ranks, 0, 4) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, page.state);
        try std.testing.expectEqual(@as(u64, 1), page.completed_units);
        try std.testing.expect(page.cursor.len > 0);
        const job = try graph.metricBuildJob(&txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.reduce_ranks, job.phase);
        try std.testing.expectEqualStrings(page.cursor, job.cursor);
    }
    graph.close();

    graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    const renewed_reduce = try graph.claimGraphMetricBuildPageAt("pagerank", active_job.job_id, .reduce_ranks, 0, 4, "worker-r", 3001) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, renewed_reduce.state);
    try std.testing.expectEqual(@as(u64, 1), renewed_reduce.completed_units);
    try std.testing.expect(renewed_reduce.cursor.len > 0);

    _ = try graph.executePageRankReduceBuildPageWithLimit("pagerank", metrics[0], active_job, renewed_reduce, null);
    try std.testing.expect(try graph.advanceGraphMetricBuildPhaseIfReady("pagerank", active_job.job_id, .reduce_ranks, 0));
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .reduce_ranks, 0, 4) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.complete, page.state);
        try std.testing.expectEqual(@as(u64, 3), page.completed_units);
        try std.testing.expect(page.output_fingerprint != 0);
        const job = try graph.metricBuildJob(&txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.check_convergence, job.phase);

        const doc_a_rank_key = try graph.graphMetricBuildPageRankKeyAlloc("pagerank", active_job.job_id, 1, "doc-a");
        defer alloc.free(doc_a_rank_key);
        try std.testing.expectApproxEqAbs(@as(f64, 0.14444444444444446), try GraphIndex.readF64OrZero(&txn, doc_a_rank_key), 0.0000001);
        const doc_b_rank_key = try graph.graphMetricBuildPageRankKeyAlloc("pagerank", active_job.job_id, 1, "doc-b");
        defer alloc.free(doc_b_rank_key);
        try std.testing.expectApproxEqAbs(@as(f64, 0.7111111111111111), try GraphIndex.readF64OrZero(&txn, doc_b_rank_key), 0.0000001);
        const doc_c_rank_key = try graph.graphMetricBuildPageRankKeyAlloc("pagerank", active_job.job_id, 1, "doc-c");
        defer alloc.free(doc_c_rank_key);
        try std.testing.expectApproxEqAbs(@as(f64, 0.14444444444444446), try GraphIndex.readF64OrZero(&txn, doc_c_rank_key), 0.0000001);
    }

    const check_claim = try graph.claimGraphMetricBuildPageAt("pagerank", active_job.job_id, .check_convergence, 0, 5, "worker-c", 4000) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, check_claim.state);
    const partial_check = try graph.executePageRankConvergenceBuildPageWithLimit("pagerank", metrics[0], active_job, check_claim, 1);
    try std.testing.expect(!partial_check.completed_page);
    try std.testing.expectEqual(@as(u64, 1), partial_check.completed_units);
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .check_convergence, 0, 5) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, page.state);
        try std.testing.expectEqual(@as(u64, 1), page.completed_units);
        try std.testing.expect(page.cursor.len > 0);
        try std.testing.expect(page.max_delta > 0.0);
        try std.testing.expect(page.total_delta > 0.0);
        try std.testing.expect(page.rank_sum > 0.0);
        const job = try graph.metricBuildJob(&txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.check_convergence, job.phase);
        try std.testing.expectEqualStrings(page.cursor, job.cursor);
    }
    graph.close();

    graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .check_convergence, 0, 5) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, page.state);
        try std.testing.expectEqualStrings("worker-c", page.worker_id);
    }
    const renewed_check = try graph.claimGraphMetricBuildPageAt("pagerank", active_job.job_id, .check_convergence, 0, 5, "worker-c", 4001) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, renewed_check.state);
    try std.testing.expectEqual(@as(u64, 1), renewed_check.completed_units);
    try std.testing.expect(renewed_check.cursor.len > 0);

    const completed_check = try graph.executePageRankConvergenceBuildPageWithLimit("pagerank", metrics[0], active_job, renewed_check, null);
    try std.testing.expect(completed_check.completed_page);
    try std.testing.expectApproxEqAbs(@as(f64, 0.37777777777777777), completed_check.max_delta, 0.0000001);
    try std.testing.expectApproxEqAbs(@as(f64, 0.7555555555555555), completed_check.total_delta, 0.0000001);
    try std.testing.expectApproxEqAbs(@as(f64, 1.0), completed_check.rank_sum, 0.0000001);
    try std.testing.expect(try graph.advanceGraphMetricBuildPhaseIfReady("pagerank", active_job.job_id, .check_convergence, 0));
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .check_convergence, 0, 5) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.complete, page.state);
        try std.testing.expectEqual(@as(u64, 3), page.completed_units);
        try std.testing.expect(page.output_fingerprint != 0);
        try std.testing.expectApproxEqAbs(@as(f64, 0.37777777777777777), page.max_delta, 0.0000001);
        try std.testing.expectApproxEqAbs(@as(f64, 0.7555555555555555), page.total_delta, 0.0000001);
        try std.testing.expectApproxEqAbs(@as(f64, 1.0), page.rank_sum, 0.0000001);
        try std.testing.expect(!page.converged);
        const job = try graph.metricBuildJob(&txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.publish_generation, job.phase);
        const iteration_summary = try graph.metricBuildIterationSummary(&txn, "pagerank", active_job.job_id, 0) orelse return error.TestExpectedGraphMetricBuildIterationSummary;
        try std.testing.expect(!iteration_summary.converged);
        try std.testing.expect(iteration_summary.fixed_iteration_limit);
    }
}

