test "graph pagerank later iteration exhausted page fails build and preserves prior generation" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-pagerank-later-iteration-exhausted-preserves-published");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-pagerank-later-iteration-exhausted-preserves-published");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{.{
        .name = "pagerank",
        .kind = .pagerank,
        .refresh = .manual,
        .max_iterations = 2,
        .tolerance = 0.000001,
    }};
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    try graph.addEdge("doc-a", "doc-b", "cites", 1.0, 0, 0, "");
    try graph.addEdge("doc-c", "doc-b", "cites", 1.0, 0, 0, "");
    var published = try graph.runPageRankMetricPlanned("pagerank");
    defer published.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.fresh, published.state);
    const published_generation = published.published_generation;

    const before_failure_top = try graph.graphMetricTopK("pagerank", 10);
    defer {
        for (before_failure_top) |*score| score.deinit(alloc);
        alloc.free(before_failure_top);
    }
    try std.testing.expectEqual(@as(usize, 3), before_failure_top.len);

    try graph.addEdge("doc-d", "doc-b", "cites", 1.0, 0, 0, "");
    const rebuilding_generation = graph.edge_generation;
    try std.testing.expect(rebuilding_generation > published_generation);
    var building = try graph.ensureGraphMetricPlannedBuild("pagerank", rebuilding_generation);
    defer building.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.building, building.state);
    try std.testing.expectEqual(rebuilding_generation, building.building_generation);

    const active_job = blk: {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const job = try graph.metricBuildJob(&txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(building.build_job_id, job.job_id);
        try std.testing.expectEqual(rebuilding_generation, job.target_generation);
        break :blk job;
    };

    inline for (.{ .prepare_generation, .scan_edges_and_out_degree, .initialize_ranks, .iterate_contributions, .reduce_ranks, .check_convergence }) |expected_phase| {
        const step = try graph.runGraphMetricPlannedWorkerStep("pagerank", metrics[0], "worker-a");
        try std.testing.expectEqual(expected_phase, step.phase);
        try std.testing.expect(step.claimed_page);
        try std.testing.expect(step.completed_page);
        try std.testing.expect(step.advanced_phase);
    }
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const job = try graph.metricBuildJob(&txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(active_job.job_id, job.job_id);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.iterate_contributions, job.phase);
        try std.testing.expectEqual(@as(u32, 1), job.iteration);
        _ = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .iterate_contributions, 1, 3) orelse return error.TestExpectedGraphMetricBuildPage;
    }

    var attempt: u64 = 0;
    while (attempt < graph_metric_build_max_page_attempts) : (attempt += 1) {
        const worker_id = switch (attempt) {
            0 => "worker-a",
            1 => "worker-b",
            else => "worker-c",
        };
        const page = try graph.claimGraphMetricBuildPageAt("pagerank", active_job.job_id, .iterate_contributions, 1, 3, worker_id, 2000 + attempt) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(attempt + 1, page.attempt);
        _ = try graph.failGraphMetricBuildPage("pagerank", active_job.job_id, .iterate_contributions, 1, 3, worker_id, "retryable later contribution failure");
    }

    graph.close();
    graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .iterate_contributions, 1, 3) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.failed, page.state);
        try std.testing.expectEqual(@as(u64, graph_metric_build_max_page_attempts), page.attempt);
        try std.testing.expectEqualStrings("retryable later contribution failure", page.last_error);
        const job = try graph.metricBuildJob(&txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(active_job.job_id, job.job_id);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.iterate_contributions, job.phase);
        try std.testing.expectEqual(@as(u32, 1), job.iteration);
    }

    const failed_step = try graph.runGraphMetricPlannedCoordinatorStepForMetric("pagerank");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.iterate_contributions, failed_step.phase);
    try std.testing.expect(failed_step.failed_build);
    try std.testing.expect(!failed_step.advanced_phase);
    try std.testing.expect(!failed_step.published);

    var failed_status = try graph.graphMetricStatus("pagerank");
    defer failed_status.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.failed, failed_status.state);
    try std.testing.expectEqual(published_generation, failed_status.published_generation);
    try std.testing.expectEqual(@as(u64, 0), failed_status.build_job_id);
    try std.testing.expectEqualStrings("GraphMetricBuildPageAttemptsExhausted", failed_status.last_error);
    try std.testing.expectEqual(@as(usize, 1), failed_status.recent_failures.len);
    try std.testing.expectEqual(active_job.job_id, failed_status.recent_failures[0].job_id);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.iterate_contributions, failed_status.recent_failures[0].phase);
    try std.testing.expectEqual(@as(u32, 1), failed_status.recent_failures[0].iteration);

    const after_failure_top = try graph.graphMetricTopK("pagerank", 10);
    defer {
        for (after_failure_top) |*score| score.deinit(alloc);
        alloc.free(after_failure_top);
    }
    try std.testing.expectEqual(before_failure_top.len, after_failure_top.len);
    for (before_failure_top, after_failure_top) |before, after| {
        try std.testing.expectEqualStrings(before.node, after.node);
        try std.testing.expectApproxEqAbs(before.score, after.score, 0.0000001);
        try std.testing.expect(!std.mem.eql(u8, after.node, "doc-d"));
    }

    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const failed_job = try graph.metricBuildJob(&txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(active_job.job_id, failed_job.job_id);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.iterate_contributions, failed_job.phase);
        try std.testing.expectEqual(@as(u32, 1), failed_job.iteration);
        try std.testing.expectEqualStrings("GraphMetricBuildPageAttemptsExhausted", failed_job.last_error);
        try std.testing.expect((try graph.metricBuildManifest(&txn, "pagerank", active_job.job_id)) == null);
        try std.testing.expectEqual(@as(usize, 0), try graph.countGraphMetricScoreGeneration("pagerank", rebuilding_generation));
    }
}

test "graph pagerank convergence page reclaim recomputes without stale partial summary" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-pagerank-convergence-reclaim");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-pagerank-convergence-reclaim");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{.{
        .name = "pagerank",
        .kind = .pagerank,
        .refresh = .manual,
        .max_iterations = 1,
        .tolerance = 0.000001,
    }};
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    try graph.addEdge("doc-a", "doc-b", "cites", 1.0, 0, 0, "");
    try graph.addEdge("doc-c", "doc-b", "cites", 1.0, 0, 0, "");
    try graph.acquireGraphMetricBuildLease("pagerank", graph.edge_generation);

    var job_txn = try graph.beginReadReverseTxn();
    const active_job = try graph.metricBuildJob(&job_txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
    job_txn.abort();

    inline for (.{ .prepare_generation, .scan_edges_and_out_degree, .initialize_ranks, .iterate_contributions, .reduce_ranks }) |expected_phase| {
        const step = try graph.runGraphMetricPlannedWorkerStep("pagerank", metrics[0], "worker-a");
        try std.testing.expectEqual(expected_phase, step.phase);
        try std.testing.expect(step.claimed_page);
        try std.testing.expect(step.completed_page);
        try std.testing.expect(step.advanced_phase);
    }

    const check_claim = try graph.claimGraphMetricBuildPageAt("pagerank", active_job.job_id, .check_convergence, 0, 5, "worker-a", 4000) orelse return error.TestExpectedGraphMetricBuildPage;
    const partial_check = try graph.executePageRankConvergenceBuildPageWithLimit("pagerank", metrics[0], active_job, check_claim, 1);
    try std.testing.expect(!partial_check.completed_page);
    try std.testing.expect(partial_check.max_delta > 0.0);
    try std.testing.expect(partial_check.total_delta > 0.0);
    try std.testing.expect(partial_check.rank_sum > 0.0);

    var expires_at: u64 = 0;
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .check_convergence, 0, 5) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, page.state);
        try std.testing.expectEqual(@as(u64, 1), page.completed_units);
        try std.testing.expect(page.max_delta > 0.0);
        try std.testing.expect(page.total_delta > 0.0);
        try std.testing.expect(page.rank_sum > 0.0);
        expires_at = page.lease_expires_at_ms;
    }

    const reclaimed = try graph.claimGraphMetricBuildPageAt("pagerank", active_job.job_id, .check_convergence, 0, 5, "worker-b", expires_at + 1) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, reclaimed.state);
    try std.testing.expectEqual(@as(u64, 2), reclaimed.attempt);
    try std.testing.expectEqual(@as(u64, 0), reclaimed.completed_units);
    try std.testing.expectEqualStrings("", reclaimed.cursor);
    try std.testing.expectEqual(@as(u64, 0), reclaimed.output_fingerprint);
    try std.testing.expectApproxEqAbs(@as(f64, 0.0), reclaimed.max_delta, 0.0);
    try std.testing.expectApproxEqAbs(@as(f64, 0.0), reclaimed.total_delta, 0.0);
    try std.testing.expectApproxEqAbs(@as(f64, 0.0), reclaimed.rank_sum, 0.0);
    try std.testing.expect(!reclaimed.converged);

    try std.testing.expectError(error.GraphMetricBuildPageNotLeased, graph.updateGraphMetricBuildConvergencePageProgressForAttempt("pagerank", active_job.job_id, 0, 5, check_claim.worker_id, check_claim.attempt, "stale-check", 1, check_claim.total_units, 99.0, 99.0, 99.0));
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .check_convergence, 0, 5) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectApproxEqAbs(@as(f64, 0.0), page.max_delta, 0.0);
        try std.testing.expectApproxEqAbs(@as(f64, 0.0), page.total_delta, 0.0);
        try std.testing.expectApproxEqAbs(@as(f64, 0.0), page.rank_sum, 0.0);
    }

    const completed_check = try graph.executePageRankConvergenceBuildPageWithLimit("pagerank", metrics[0], active_job, reclaimed, null);
    try std.testing.expect(completed_check.completed_page);
    try std.testing.expectApproxEqAbs(@as(f64, 0.37777777777777777), completed_check.max_delta, 0.0000001);
    try std.testing.expectApproxEqAbs(@as(f64, 0.7555555555555555), completed_check.total_delta, 0.0000001);
    try std.testing.expectApproxEqAbs(@as(f64, 1.0), completed_check.rank_sum, 0.0000001);
    try std.testing.expect(try graph.advanceGraphMetricBuildPhaseIfReady("pagerank", active_job.job_id, .check_convergence, 0));
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .check_convergence, 0, 5) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.complete, page.state);
        try std.testing.expectApproxEqAbs(@as(f64, 0.37777777777777777), page.max_delta, 0.0000001);
        try std.testing.expectApproxEqAbs(@as(f64, 0.7555555555555555), page.total_delta, 0.0000001);
        try std.testing.expectApproxEqAbs(@as(f64, 1.0), page.rank_sum, 0.0000001);
        const job = try graph.metricBuildJob(&txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.publish_generation, job.phase);
    }
}

test "graph pagerank reclaimed contribution and reduce pages overwrite partial output" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-pagerank-partial-reclaim");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-pagerank-partial-reclaim");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{.{
        .name = "pagerank",
        .kind = .pagerank,
        .refresh = .manual,
        .max_iterations = 1,
        .tolerance = 0.000001,
    }};
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    try graph.addEdge("doc-a", "doc-b", "cites", 1.0, 0, 0, "");
    try graph.addEdge("doc-c", "doc-b", "cites", 1.0, 0, 0, "");
    try graph.acquireGraphMetricBuildLease("pagerank", graph.edge_generation);
    defer graph.releaseGraphMetricBuildLease("pagerank") catch {};

    var job_txn = try graph.beginReadReverseTxn();
    const active_job = try graph.metricBuildJob(&job_txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
    job_txn.abort();

    inline for (.{ .prepare_generation, .scan_edges_and_out_degree, .initialize_ranks }) |expected_phase| {
        const step = try graph.runGraphMetricPlannedWorkerStep("pagerank", metrics[0], "worker-setup");
        try std.testing.expectEqual(expected_phase, step.phase);
        try std.testing.expect(step.claimed_page);
        try std.testing.expect(step.completed_page);
        try std.testing.expect(step.advanced_phase);
    }

    const partial_contribution_claim = try graph.claimNextGraphMetricBuildPageAt("pagerank", active_job.job_id, .iterate_contributions, 0, "worker-a", 2000) orelse return error.TestExpectedGraphMetricBuildPage;
    _ = try graph.executePageRankContributionBuildPageWithLimit("pagerank", metrics[0], active_job, partial_contribution_claim, 1);
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const partial_page = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .iterate_contributions, 0, partial_contribution_claim.page_id) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, partial_page.state);
        try std.testing.expectEqual(@as(u64, 1), partial_page.completed_units);
        const partial_contribution = try graph.aggregatePageRankContributionForNode(&txn, "pagerank", active_job.job_id, 0, "doc-b");
        try std.testing.expectApproxEqAbs(@as(f64, 0.0), partial_contribution, 0.0);
        const attempt_contribution_key = try graph.graphMetricBuildAttemptPageRankContributionKeyAlloc("pagerank", active_job.job_id, .iterate_contributions, 0, partial_contribution_claim.page_id, partial_contribution_claim.attempt, "doc-b");
        defer alloc.free(attempt_contribution_key);
        try std.testing.expectApproxEqAbs(@as(f64, 0.2833333333333333), try GraphIndex.readF64OrZero(&txn, attempt_contribution_key), 0.0000001);
    }

    const contribution_expires_at = blk: {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .iterate_contributions, 0, partial_contribution_claim.page_id) orelse return error.TestExpectedGraphMetricBuildPage;
        break :blk page.lease_expires_at_ms;
    };
    const reclaimed_contribution = try graph.claimGraphMetricBuildPageAt("pagerank", active_job.job_id, .iterate_contributions, 0, partial_contribution_claim.page_id, "worker-b", contribution_expires_at + 1) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, reclaimed_contribution.state);
    try std.testing.expectEqual(@as(u64, 2), reclaimed_contribution.attempt);
    try std.testing.expectEqual(@as(u64, 0), reclaimed_contribution.completed_units);
    try std.testing.expectEqualStrings("", reclaimed_contribution.cursor);
    var stale_contributions = std.StringHashMapUnmanaged(f64).empty;
    defer graph.freeStringHashMapKeys(f64, &stale_contributions);
    {
        const entry = try stale_contributions.getOrPut(alloc, "doc-b");
        try std.testing.expect(!entry.found_existing);
        entry.key_ptr.* = try alloc.dupe(u8, "doc-b");
        entry.value_ptr.* = 99.0;
    }
    try std.testing.expectError(error.GraphMetricBuildPageNotLeased, graph.writePageRankContributionAttemptPartialsForAttempt("pagerank", active_job, partial_contribution_claim, 0, &stale_contributions, false));
    {
        var batch = try graph.beginWriteReverseBatch();
        defer batch.abort();
        try std.testing.expectError(error.GraphMetricBuildPageNotLeased, graph.adoptPageRankContributionAttemptOutputInBatch(&batch, "pagerank", active_job.job_id, partial_contribution_claim));
    }
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const contribution = try graph.aggregatePageRankContributionForNode(&txn, "pagerank", active_job.job_id, 0, "doc-b");
        try std.testing.expectApproxEqAbs(@as(f64, 0.0), contribution, 0.0);
    }
    try std.testing.expectError(error.GraphMetricBuildPageNotLeased, graph.executePageRankContributionBuildPageWithLimit("pagerank", metrics[0], active_job, partial_contribution_claim, null));
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const replacement_attempt_key = try graph.graphMetricBuildAttemptPageRankContributionKeyAlloc("pagerank", active_job.job_id, .iterate_contributions, 0, partial_contribution_claim.page_id, reclaimed_contribution.attempt, "doc-b");
        defer alloc.free(replacement_attempt_key);
        try std.testing.expectApproxEqAbs(@as(f64, 0.0), try GraphIndex.readF64OrZero(&txn, replacement_attempt_key), 0.0);
    }
    _ = try graph.executePageRankContributionBuildPageWithLimit("pagerank", metrics[0], active_job, reclaimed_contribution, null);
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const contribution = try graph.aggregatePageRankContributionForNode(&txn, "pagerank", active_job.job_id, 0, "doc-b");
        try std.testing.expectApproxEqAbs(@as(f64, 0.5666666666666667), contribution, 0.0000001);
        const abandoned_attempt_key = try graph.graphMetricBuildAttemptPageRankContributionKeyAlloc("pagerank", active_job.job_id, .iterate_contributions, 0, partial_contribution_claim.page_id, partial_contribution_claim.attempt, "doc-b");
        defer alloc.free(abandoned_attempt_key);
        try std.testing.expectApproxEqAbs(@as(f64, 0.2833333333333333), try GraphIndex.readF64OrZero(&txn, abandoned_attempt_key), 0.0000001);
        const adopted_attempt_key = try graph.graphMetricBuildAttemptPageRankContributionKeyAlloc("pagerank", active_job.job_id, .iterate_contributions, 0, partial_contribution_claim.page_id, reclaimed_contribution.attempt, "doc-b");
        defer alloc.free(adopted_attempt_key);
        try std.testing.expectApproxEqAbs(@as(f64, 0.5666666666666667), try GraphIndex.readF64OrZero(&txn, adopted_attempt_key), 0.0000001);
        const page = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .iterate_contributions, 0, partial_contribution_claim.page_id) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.complete, page.state);
        try std.testing.expectEqual(page.total_units, page.completed_units);
    }
    try std.testing.expect(try graph.advanceGraphMetricBuildPhaseIfReady("pagerank", active_job.job_id, .iterate_contributions, 0));

    const partial_reduce_claim = try graph.claimNextGraphMetricBuildPageAt("pagerank", active_job.job_id, .reduce_ranks, 0, "worker-a", 3000) orelse return error.TestExpectedGraphMetricBuildPage;
    _ = try graph.executePageRankReduceBuildPageWithLimit("pagerank", metrics[0], active_job, partial_reduce_claim, 1);
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const partial_page = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .reduce_ranks, 0, partial_reduce_claim.page_id) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, partial_page.state);
        try std.testing.expectEqual(@as(u64, 1), partial_page.completed_units);
    }

    const reduce_expires_at = blk: {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .reduce_ranks, 0, partial_reduce_claim.page_id) orelse return error.TestExpectedGraphMetricBuildPage;
        break :blk page.lease_expires_at_ms;
    };
    const reclaimed_reduce = try graph.claimGraphMetricBuildPageAt("pagerank", active_job.job_id, .reduce_ranks, 0, partial_reduce_claim.page_id, "worker-b", reduce_expires_at + 1) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, reclaimed_reduce.state);
    try std.testing.expectEqual(@as(u64, 2), reclaimed_reduce.attempt);
    try std.testing.expectEqual(@as(u64, 0), reclaimed_reduce.completed_units);
    try std.testing.expectEqualStrings("", reclaimed_reduce.cursor);
    try std.testing.expectError(error.GraphMetricBuildPageNotLeased, graph.executePageRankReduceBuildPageWithLimit("pagerank", metrics[0], active_job, partial_reduce_claim, null));
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const rank_b_key = try graph.graphMetricBuildPageRankKeyAlloc("pagerank", active_job.job_id, 1, "doc-b");
        defer alloc.free(rank_b_key);
        try std.testing.expectApproxEqAbs(@as(f64, 0.0), try GraphIndex.readF64OrZero(&txn, rank_b_key), 0.0);
    }
    _ = try graph.executePageRankReduceBuildPageWithLimit("pagerank", metrics[0], active_job, reclaimed_reduce, null);
    try std.testing.expect(try graph.advanceGraphMetricBuildPhaseIfReady("pagerank", active_job.job_id, .reduce_ranks, 0));

    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const rank_a_key = try graph.graphMetricBuildPageRankKeyAlloc("pagerank", active_job.job_id, 1, "doc-a");
        defer alloc.free(rank_a_key);
        const rank_b_key = try graph.graphMetricBuildPageRankKeyAlloc("pagerank", active_job.job_id, 1, "doc-b");
        defer alloc.free(rank_b_key);
        const rank_c_key = try graph.graphMetricBuildPageRankKeyAlloc("pagerank", active_job.job_id, 1, "doc-c");
        defer alloc.free(rank_c_key);
        const rank_a = try GraphIndex.readF64OrZero(&txn, rank_a_key);
        const rank_b = try GraphIndex.readF64OrZero(&txn, rank_b_key);
        const rank_c = try GraphIndex.readF64OrZero(&txn, rank_c_key);
        try std.testing.expectApproxEqAbs(@as(f64, 0.14444444444444443), rank_a, 0.0000001);
        try std.testing.expectApproxEqAbs(@as(f64, 0.7111111111111111), rank_b, 0.0000001);
        try std.testing.expectApproxEqAbs(@as(f64, 0.14444444444444443), rank_c, 0.0000001);
        try std.testing.expectApproxEqAbs(@as(f64, 1.0), rank_a + rank_b + rank_c, 0.0000001);

        const summary = try graph.metricBuildPhaseSummary(&txn, "pagerank", active_job.job_id, .reduce_ranks, 0) orelse return error.TestExpectedGraphMetricBuildPhaseSummary;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhaseState.complete, summary.state);
        try std.testing.expectEqual(@as(u64, 0), summary.failed_pages);
    }
}

