test "graph pagerank planned cleanup resumes after non-final cleanup page reopen" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-pagerank-cleanup-reopen");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-pagerank-cleanup-reopen");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{.{
        .name = "pagerank",
        .kind = .pagerank,
        .refresh = .manual,
        .max_iterations = 1,
        .tolerance = 0.000001,
    }};
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });

    try graph.addEdge("doc-a", "doc-b", "cites", 1.0, 0, 0, "");
    try graph.acquireGraphMetricBuildLease("pagerank", graph.edge_generation);

    var job_txn = try graph.beginReadReverseTxn();
    const active_job = try graph.metricBuildJob(&job_txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
    job_txn.abort();

    inline for (.{ .prepare_generation, .scan_edges_and_out_degree, .initialize_ranks, .iterate_contributions, .reduce_ranks, .check_convergence }) |expected_phase| {
        const step = try graph.runGraphMetricPlannedWorkerStep("pagerank", metrics[0], "worker-a");
        try std.testing.expectEqual(expected_phase, step.phase);
        try std.testing.expect(step.claimed_page);
        try std.testing.expect(step.completed_page);
        try std.testing.expect(step.advanced_phase);
    }
    const publish = try graph.runGraphMetricPlannedWorkerStep("pagerank", metrics[0], "worker-a");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.publish_generation, publish.phase);
    try std.testing.expect(publish.advanced_phase);

    const visible_before_cleanup = try graph.graphMetricTopK("pagerank", 2);
    defer {
        for (visible_before_cleanup) |*score| score.deinit(alloc);
        alloc.free(visible_before_cleanup);
    }
    try std.testing.expectEqual(@as(usize, 2), visible_before_cleanup.len);
    try std.testing.expectEqualStrings("doc-b", visible_before_cleanup[0].node);

    const abandoned_attempt_key = try graph.graphMetricBuildAttemptPageRankContributionKeyAlloc("pagerank", active_job.job_id, .iterate_contributions, 0, 999, 1, "doc-abandoned");
    defer alloc.free(abandoned_attempt_key);
    {
        var batch = try graph.beginWriteReverseBatch();
        errdefer batch.abort();
        try GraphIndex.putF64(&batch, abandoned_attempt_key, 123.0);
        try batch.commit();
    }

    const first_cleanup = try graph.runGraphMetricPlannedWorkerStep("pagerank", metrics[0], "worker-a");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.cleanup_old_generations, first_cleanup.phase);
    try std.testing.expect(first_cleanup.claimed_page);
    try std.testing.expect(first_cleanup.completed_page);
    try std.testing.expect(!first_cleanup.published);
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const job = try graph.metricBuildJob(&txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.cleanup_old_generations, job.phase);
        const cleanup_page = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .cleanup_old_generations, 0, first_cleanup.page_id) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.complete, cleanup_page.state);
        try std.testing.expect((try graph.metricBuildManifest(&txn, "pagerank", active_job.job_id)) != null);
        _ = try txn.get(abandoned_attempt_key);
    }
    graph.close();

    graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();
    const visible_after_reopen = try graph.graphMetricTopK("pagerank", 2);
    defer {
        for (visible_after_reopen) |*score| score.deinit(alloc);
        alloc.free(visible_after_reopen);
    }
    try std.testing.expectEqual(@as(usize, 2), visible_after_reopen.len);
    try std.testing.expectEqualStrings("doc-b", visible_after_reopen[0].node);
    {
        var status = try graph.graphMetricStatus("pagerank");
        defer status.deinit(alloc);
        try std.testing.expectEqual(GraphIndex.GraphMetricState.building, status.state);
        try std.testing.expectEqual(active_job.job_id, status.build_job_id);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.cleanup_old_generations, status.phase);
    }

    const second_cleanup = try graph.runGraphMetricPlannedWorkerStep("pagerank", metrics[0], "worker-b");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.cleanup_old_generations, second_cleanup.phase);
    try std.testing.expect(second_cleanup.claimed_page);
    try std.testing.expect(second_cleanup.completed_page);
    try std.testing.expect(!second_cleanup.published);
    const final_cleanup = try graph.runGraphMetricPlannedWorkerStep("pagerank", metrics[0], "worker-c");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.cleanup_old_generations, final_cleanup.phase);
    try std.testing.expect(final_cleanup.claimed_page);
    try std.testing.expect(final_cleanup.completed_page);
    try std.testing.expect(final_cleanup.published);

    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const completed_job = try graph.metricBuildJob(&txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.complete, completed_job.phase);
        try std.testing.expect((try graph.metricBuildLease(&txn, "pagerank")) == null);
        try std.testing.expect((try graph.metricBuildManifest(&txn, "pagerank", active_job.job_id)) == null);
        try std.testing.expectError(error.NotFound, txn.get(abandoned_attempt_key));
    }
}

