        .max_iterations = 1,
        .tolerance = 0.000001,
    }};
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });

    try graph.addEdge("doc-a", "doc-b", "cites", 1.0, 0, 0, "");
    try graph.acquireGraphMetricBuildLease("pagerank", graph.edge_generation);

    var job_txn = try graph.beginReadReverseTxn();
    const active_job = try graph.metricBuildJob(&job_txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
    job_txn.abort();

    inline for (.{ .prepare_generation, .scan_edges_and_out_degree, .initialize_ranks, .iterate_contributions, .reduce_ranks, .check_convergence }) |expected_phase| {
        const step = try graph.runGraphMetricPlannedWorkerStep("pagerank", metrics[0], "worker-a");
        try std.testing.expectEqual(expected_phase, step.phase);
        try std.testing.expect(step.claimed_page);
        try std.testing.expect(step.completed_page);
        try std.testing.expect(step.advanced_phase);
    }
    const publish = try graph.runGraphMetricPlannedWorkerStep("pagerank", metrics[0], "worker-a");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.publish_generation, publish.phase);
    try std.testing.expect(publish.advanced_phase);

    {
        var batch = try graph.beginWriteReverseBatch();
        errdefer batch.abort();
        for (0..graph_metric_build_cleanup_delete_page_units + 6) |i| {
            var node_buf: [64]u8 = undefined;
            const node = try std.fmt.bufPrint(&node_buf, "cleanup-extra-{d:0>3}", .{i});
            const key = try graph.graphMetricBuildPageRankOutDegreePartialKeyAlloc("pagerank", active_job.job_id, node, 999);
            defer alloc.free(key);
            try GraphIndex.putU64(&batch, key, 1);
        }
        try batch.commit();
    }

    const first_cleanup = try graph.runGraphMetricPlannedWorkerStep("pagerank", metrics[0], "worker-clean");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.cleanup_old_generations, first_cleanup.phase);
    try std.testing.expect(first_cleanup.claimed_page);
    try std.testing.expect(!first_cleanup.completed_page);
    try std.testing.expect(!first_cleanup.published);
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const cleanup_page = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .cleanup_old_generations, 0, first_cleanup.page_id) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, cleanup_page.state);
        try std.testing.expect(cleanup_page.cursor.len > 0);
        try std.testing.expect(cleanup_page.completed_units >= graph_metric_build_cleanup_delete_page_units);
        const job = try graph.metricBuildJob(&txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.cleanup_old_generations, job.phase);
        try std.testing.expectEqualStrings(cleanup_page.cursor, job.cursor);
    }

    const visible_after_partial_cleanup = try graph.graphMetricTopK("pagerank", 2);
    defer {
        for (visible_after_partial_cleanup) |*score| score.deinit(alloc);
        alloc.free(visible_after_partial_cleanup);
    }
    try std.testing.expectEqual(@as(usize, 2), visible_after_partial_cleanup.len);
    try std.testing.expectEqualStrings("doc-b", visible_after_partial_cleanup[0].node);
    graph.close();

    graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();
    const renewed_cleanup = try graph.runGraphMetricPlannedWorkerStep("pagerank", metrics[0], "worker-clean");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.cleanup_old_generations, renewed_cleanup.phase);
    try std.testing.expect(renewed_cleanup.claimed_page);
    try std.testing.expect(renewed_cleanup.completed_page);
    try std.testing.expect(!renewed_cleanup.published);
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const cleanup_page = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .cleanup_old_generations, 0, renewed_cleanup.page_id) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.complete, cleanup_page.state);
        try std.testing.expectEqualStrings("cleanup-job:", cleanup_page.cursor[0.."cleanup-job:".len]);
    }

    const second_cleanup = try graph.runGraphMetricPlannedWorkerStep("pagerank", metrics[0], "worker-clean-2");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.cleanup_old_generations, second_cleanup.phase);
    try std.testing.expect(second_cleanup.claimed_page);
    try std.testing.expect(second_cleanup.completed_page);
    try std.testing.expect(!second_cleanup.published);
    const final_cleanup = try graph.runGraphMetricPlannedWorkerStep("pagerank", metrics[0], "worker-clean-3");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.cleanup_old_generations, final_cleanup.phase);
    try std.testing.expect(final_cleanup.claimed_page);
    try std.testing.expect(final_cleanup.completed_page);
    try std.testing.expect(final_cleanup.published);
}

test "graph pagerank planned build publishes scores matching local runner" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-pagerank-planned-parity");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-pagerank-planned-parity");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{
        .{
            .name = "pagerank_local",
            .kind = .pagerank,
            .refresh = .manual,
            .max_iterations = 2,
            .tolerance = 0.000001,
        },
        .{
            .name = "pagerank_planned",
            .kind = .pagerank,
            .refresh = .manual,
            .max_iterations = 2,
            .tolerance = 0.000001,
        },
    };
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    try graph.addEdge("doc-a", "doc-b", "cites", 1.0, 0, 0, "");
    try graph.addEdge("doc-b", "doc-c", "cites", 1.0, 0, 0, "");
    try graph.addEdge("doc-c", "doc-a", "cites", 1.0, 0, 0, "");
    try graph.addEdge("doc-a", "doc-c", "cites", 1.0, 0, 0, "");

    var local_status = try graph.runGraphMetric("pagerank_local");
    defer local_status.deinit(alloc);
    var planned_status = try graph.runPageRankMetricPlanned("pagerank_planned");
    defer planned_status.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.fresh, planned_status.state);
    try std.testing.expectEqual(local_status.published_generation, planned_status.published_generation);
    try std.testing.expectEqual(local_status.iterations_completed, planned_status.iterations_completed);
    try std.testing.expectEqual(local_status.converged, planned_status.converged);
    try std.testing.expectApproxEqAbs(local_status.delta, planned_status.delta, 0.0000001);

    const local_top = try graph.graphMetricTopK("pagerank_local", 3);
    defer {
        for (local_top) |*score| score.deinit(alloc);
        alloc.free(local_top);
    }
    const planned_top = try graph.graphMetricTopK("pagerank_planned", 3);
    defer {
        for (planned_top) |*score| score.deinit(alloc);
        alloc.free(planned_top);
    }
    try std.testing.expectEqual(local_top.len, planned_top.len);
    for (local_top, planned_top) |local, planned| {
        try std.testing.expectEqualStrings(local.node, planned.node);
        try std.testing.expectApproxEqAbs(local.score, planned.score, 0.0000001);
    }
}

test "graph pagerank failed planned build preserves prior published generation" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-pagerank-planned-failure-preserves-published");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-pagerank-planned-failure-preserves-published");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{.{
        .name = "pagerank",
        .kind = .pagerank,
        .refresh = .manual,
        .max_iterations = 1,
        .tolerance = 0.000001,
    }};
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    try graph.addEdge("doc-a", "doc-b", "cites", 1.0, 0, 0, "");
    var published = try graph.runPageRankMetricPlanned("pagerank");
    defer published.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.fresh, published.state);
    const published_generation = published.published_generation;

    const before_failure_top = try graph.graphMetricTopK("pagerank", 10);
    defer {
        for (before_failure_top) |*score| score.deinit(alloc);
        alloc.free(before_failure_top);
    }
    try std.testing.expectEqual(@as(usize, 2), before_failure_top.len);

    try graph.addEdge("doc-c", "doc-b", "cites", 1.0, 0, 0, "");
    const rebuilding_generation = graph.edge_generation;
    try std.testing.expect(rebuilding_generation > published_generation);
    var building = try graph.ensureGraphMetricPlannedBuild("pagerank", rebuilding_generation);
    defer building.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.building, building.state);
    try std.testing.expectEqual(rebuilding_generation, building.building_generation);

    const prepare = try graph.runGraphMetricPlannedWorkerPageStepForMetric("pagerank", "worker-a");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.prepare_generation, prepare.phase);
    try std.testing.expect(prepare.claimed_page);
    try std.testing.expect(prepare.completed_page);
    try std.testing.expect(!prepare.advanced_phase);

    var job_id: u64 = 0;
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const job = try graph.metricBuildJob(&txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
        job_id = job.job_id;
        try std.testing.expectEqual(building.build_job_id, job.job_id);
        try std.testing.expectEqual(rebuilding_generation, job.target_generation);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.prepare_generation, job.phase);
        _ = try graph.metricBuildManifest(&txn, "pagerank", job_id) orelse return error.TestExpectedGraphMetricBuildManifest;
    }

    var failed = try graph.failGraphMetricPlannedBuild("pagerank", error.InvalidGraphMetricScore);
    defer failed.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.failed, failed.state);
    try std.testing.expectEqual(published_generation, failed.published_generation);
    try std.testing.expectEqual(@as(u64, 0), failed.build_job_id);
    try std.testing.expectEqual(@as(u64, 1), failed.retry_count);
    try std.testing.expectEqualStrings("InvalidGraphMetricScore", failed.last_error);
    try std.testing.expectEqual(@as(usize, 1), failed.recent_failures.len);
    try std.testing.expectEqual(job_id, failed.recent_failures[0].job_id);

    const after_failure_top = try graph.graphMetricTopK("pagerank", 10);
    defer {
        for (after_failure_top) |*score| score.deinit(alloc);
        alloc.free(after_failure_top);
    }
    try std.testing.expectEqual(before_failure_top.len, after_failure_top.len);
    for (before_failure_top, after_failure_top) |before, after| {
        try std.testing.expectEqualStrings(before.node, after.node);
        try std.testing.expectApproxEqAbs(before.score, after.score, 0.0000001);
        try std.testing.expect(!std.mem.eql(u8, after.node, "doc-c"));
    }

    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const failed_job = try graph.metricBuildJob(&txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(job_id, failed_job.job_id);
        try std.testing.expectEqual(@as(u64, 1), failed_job.retry_count);
        try std.testing.expectEqualStrings("InvalidGraphMetricScore", failed_job.last_error);
        try std.testing.expect((try graph.metricBuildManifest(&txn, "pagerank", job_id)) == null);
        try std.testing.expectEqual(@as(usize, 0), try graph.countGraphMetricScoreGeneration("pagerank", rebuilding_generation));
    }

    try std.testing.expectError(error.GraphMetricBuildNotActive, graph.failGraphMetricPlannedBuild("pagerank", error.InvalidGraphMetricScore));
}

test "graph pagerank coordinator publish failure preserves prior published generation after reopen" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-pagerank-publish-failure-preserves-published");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-pagerank-publish-failure-preserves-published");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{.{
        .name = "pagerank",
        .kind = .pagerank,
        .refresh = .manual,
        .max_iterations = 1,
        .tolerance = 0.000001,
    }};
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });

    try graph.addEdge("doc-a", "doc-b", "cites", 1.0, 0, 0, "");
    var published = try graph.runPageRankMetricPlanned("pagerank");
    defer published.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.fresh, published.state);
    const published_generation = published.published_generation;

    const before_failure_top = try graph.graphMetricTopK("pagerank", 10);
    defer {
        for (before_failure_top) |*score| score.deinit(alloc);
        alloc.free(before_failure_top);
    }
    try std.testing.expectEqual(@as(usize, 2), before_failure_top.len);

    try graph.addEdge("doc-c", "doc-b", "cites", 1.0, 0, 0, "");
    const rebuilding_generation = graph.edge_generation;
    try std.testing.expect(rebuilding_generation > published_generation);
    var building = try graph.ensureGraphMetricPlannedBuild("pagerank", rebuilding_generation);
    defer building.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.building, building.state);

    const active_job = blk: {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const job = try graph.metricBuildJob(&txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(building.build_job_id, job.job_id);
        try std.testing.expectEqual(rebuilding_generation, job.target_generation);
        break :blk job;
    };

    inline for (.{ .prepare_generation, .scan_edges_and_out_degree, .initialize_ranks, .iterate_contributions, .reduce_ranks, .check_convergence }) |expected_phase| {
        const step = try graph.runGraphMetricPlannedWorkerStep("pagerank", metrics[0], "worker-a");
        try std.testing.expectEqual(expected_phase, step.phase);
        try std.testing.expect(step.claimed_page);
        try std.testing.expect(step.completed_page);
        try std.testing.expect(step.advanced_phase);
    }
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const job = try graph.metricBuildJob(&txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(active_job.job_id, job.job_id);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.publish_generation, job.phase);
        _ = try graph.verifyGraphMetricBuildPublishReady("pagerank", active_job.job_id);
    }

    {
        var batch = try graph.beginWriteReverseBatch();
        errdefer batch.abort();
        var manifest = try graph.metricBuildManifest(&batch, "pagerank", active_job.job_id) orelse return error.TestExpectedGraphMetricBuildManifest;
        manifest.config_fingerprint += 1;
        try graph.putGraphMetricBuildManifestInBatch(&batch, "pagerank", manifest);
        try batch.commit();
    }
    graph.close();

    graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const job = try graph.metricBuildJob(&txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(active_job.job_id, job.job_id);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.publish_generation, job.phase);
        try std.testing.expectError(error.InvalidGraphMetricBuildManifest, graph.verifyGraphMetricBuildPublishReady("pagerank", active_job.job_id));
    }

    const failed_step = try graph.runGraphMetricPlannedCoordinatorStepForMetric("pagerank");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.publish_generation, failed_step.phase);
    try std.testing.expect(failed_step.failed_build);
    try std.testing.expect(!failed_step.advanced_phase);
    try std.testing.expect(!failed_step.published);

    var failed_status = try graph.graphMetricStatus("pagerank");
    defer failed_status.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.failed, failed_status.state);
    try std.testing.expectEqual(published_generation, failed_status.published_generation);
    try std.testing.expectEqual(@as(u64, 0), failed_status.build_job_id);
    try std.testing.expectEqualStrings("InvalidGraphMetricBuildManifest", failed_status.last_error);
    try std.testing.expectEqual(@as(usize, 1), failed_status.recent_failures.len);
    try std.testing.expectEqual(active_job.job_id, failed_status.recent_failures[0].job_id);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.publish_generation, failed_status.recent_failures[0].phase);

    const after_failure_top = try graph.graphMetricTopK("pagerank", 10);
    defer {
        for (after_failure_top) |*score| score.deinit(alloc);
        alloc.free(after_failure_top);
    }
    try std.testing.expectEqual(before_failure_top.len, after_failure_top.len);
    for (before_failure_top, after_failure_top) |before, after| {
        try std.testing.expectEqualStrings(before.node, after.node);
        try std.testing.expectApproxEqAbs(before.score, after.score, 0.0000001);
        try std.testing.expect(!std.mem.eql(u8, after.node, "doc-c"));
    }

    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const failed_job = try graph.metricBuildJob(&txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(active_job.job_id, failed_job.job_id);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.publish_generation, failed_job.phase);
        try std.testing.expectEqualStrings("InvalidGraphMetricBuildManifest", failed_job.last_error);
        try std.testing.expect((try graph.metricBuildManifest(&txn, "pagerank", active_job.job_id)) == null);
        try std.testing.expectEqual(@as(usize, 0), try graph.countGraphMetricScoreGeneration("pagerank", active_job.score_generation));
    }
}

test "graph pagerank planned build drains partitioned pages across workers" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-pagerank-planned-multi-worker");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-pagerank-planned-multi-worker");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{
        .{
            .name = "pagerank_local",
            .kind = .pagerank,
            .refresh = .manual,
            .max_iterations = 1,
            .tolerance = 0.000001,
        },
        .{
            .name = "pagerank_planned",
            .kind = .pagerank,
            .refresh = .manual,
            .max_iterations = 1,
            .tolerance = 0.000001,
        },
    };
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    for (0..graph_metric_build_target_scan_page_units + 1) |i| {
        var source_buf: [64]u8 = undefined;
        const source = try std.fmt.bufPrint(&source_buf, "doc-{d:0>3}", .{i});
        try graph.addEdge(source, "hub", "cites", 1.0, 0, 0, "");
    }

    var local_status = try graph.runGraphMetric("pagerank_local");
    defer local_status.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.fresh, local_status.state);

    try graph.acquireGraphMetricBuildLease("pagerank_planned", graph.edge_generation);
    defer graph.releaseGraphMetricBuildLease("pagerank_planned") catch {};

    var job_txn = try graph.beginReadReverseTxn();
    const active_job = try graph.metricBuildJob(&job_txn, "pagerank_planned") orelse return error.TestExpectedGraphMetricBuildJob;
    job_txn.abort();

    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const manifest = try graph.metricBuildManifest(&txn, "pagerank_planned", active_job.job_id) orelse return error.TestExpectedGraphMetricBuildManifest;
        try std.testing.expect(manifest.page_count > GraphIndex.graph_metric_iterative_build_phases.len);
        _ = try graph.metricBuildPage(&txn, "pagerank_planned", active_job.job_id, .scan_edges_and_out_degree, 0, 1) orelse return error.TestExpectedGraphMetricBuildPage;
        _ = try graph.metricBuildPage(&txn, "pagerank_planned", active_job.job_id, .scan_edges_and_out_degree, 0, 2) orelse return error.TestExpectedGraphMetricBuildPage;
        _ = try graph.metricBuildPage(&txn, "pagerank_planned", active_job.job_id, .reduce_ranks, 0, 4) orelse return error.TestExpectedGraphMetricBuildPage;
        _ = try graph.metricBuildPage(&txn, "pagerank_planned", active_job.job_id, .reduce_ranks, 0, 5) orelse return error.TestExpectedGraphMetricBuildPage;
    }

    var worker_a_completed: usize = 0;
    var worker_b_completed: usize = 0;
    var completed = false;
    var steps: usize = 0;
    while (steps < 200) : (steps += 1) {
        const worker_id = if (steps % 2 == 0) "worker-a" else "worker-b";
        const step = try graph.runGraphMetricPlannedWorkerStep("pagerank_planned", metrics[1], worker_id);
        if (step.completed_page) {
            if (std.mem.eql(u8, worker_id, "worker-a")) {
                worker_a_completed += 1;
            } else {
                worker_b_completed += 1;
            }
        }
        if (step.completed_build and step.phase == .cleanup_old_generations) {
            completed = true;
            break;
        }
        if (!step.claimed_page and !step.advanced_phase and step.phase != .cleanup_old_generations) {
            return error.TestExpectedGraphMetricBuildProgress;
        }
    }
    try std.testing.expect(completed);
    try std.testing.expect(worker_a_completed > 0);
    try std.testing.expect(worker_b_completed > 0);

    var planned_status = try graph.graphMetricStatus("pagerank_planned");
    defer planned_status.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.fresh, planned_status.state);
    try std.testing.expectEqual(local_status.published_generation, planned_status.published_generation);
    try std.testing.expectEqual(local_status.iterations_completed, planned_status.iterations_completed);
    try std.testing.expectEqual(local_status.converged, planned_status.converged);
    try std.testing.expectApproxEqAbs(local_status.delta, planned_status.delta, 0.0000001);

    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const completed_job = try graph.metricBuildJob(&txn, "pagerank_planned") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(active_job.job_id, completed_job.job_id);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.complete, completed_job.phase);
        try std.testing.expect((try graph.metricBuildLease(&txn, "pagerank_planned")) == null);
        try std.testing.expect((try graph.metricBuildManifest(&txn, "pagerank_planned", active_job.job_id)) == null);
    }

    const top_limit: usize = @intCast(graph.node_count);
    const local_top = try graph.graphMetricTopK("pagerank_local", top_limit);
    defer {
        for (local_top) |*score| score.deinit(alloc);
        alloc.free(local_top);
    }
    const planned_top = try graph.graphMetricTopK("pagerank_planned", top_limit);
    defer {
        for (planned_top) |*score| score.deinit(alloc);
        alloc.free(planned_top);
    }
    try std.testing.expectEqual(local_top.len, planned_top.len);
    try std.testing.expectEqualStrings("hub", planned_top[0].node);
    for (local_top, planned_top) |local, planned| {
        try std.testing.expectEqualStrings(local.node, planned.node);
        try std.testing.expectApproxEqAbs(local.score, planned.score, 0.0000001);
    }
}

test "graph pagerank planned worker page step leaves phase and publish to coordinator" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-pagerank-worker-coordinator-split");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-pagerank-worker-coordinator-split");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{.{
        .name = "pagerank",
        .kind = .pagerank,
        .refresh = .manual,
        .max_iterations = 1,
        .tolerance = 0.000001,
    }};
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    try graph.addEdge("doc-a", "doc-b", "cites", 1.0, 0, 0, "");
    try graph.addEdge("doc-b", "doc-c", "cites", 1.0, 0, 0, "");
    var started = try graph.ensureGraphMetricPlannedBuild("pagerank", graph.edge_generation);
    defer started.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.building, started.state);

    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const job = try graph.metricBuildJob(&txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.prepare_generation, job.phase);
    }

    {
        const worker_step = try graph.runGraphMetricPlannedWorkerPageStepForMetric("pagerank", "worker-a");
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.prepare_generation, worker_step.phase);
        try std.testing.expect(worker_step.claimed_page);
        try std.testing.expect(worker_step.completed_page);
        try std.testing.expect(!worker_step.advanced_phase);
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const job = try graph.metricBuildJob(&txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.prepare_generation, job.phase);
    }
    {
        const coordinator_step = try graph.runGraphMetricPlannedCoordinatorStepForMetric("pagerank");
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.prepare_generation, coordinator_step.phase);
        try std.testing.expect(coordinator_step.advanced_phase);
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const job = try graph.metricBuildJob(&txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.scan_edges_and_out_degree, job.phase);
    }

    var guard: usize = 0;
    while (guard < 100) : (guard += 1) {
        var txn = try graph.beginReadReverseTxn();
        const job = try graph.metricBuildJob(&txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
        const phase = job.phase;
        txn.abort();
        if (phase == .publish_generation) break;
        if (phase == .complete or phase == .cleanup_old_generations) return error.TestExpectedGraphMetricBuildPublishPhase;

        const worker_id = if (guard % 2 == 0) "worker-a" else "worker-b";
        const worker_step = try graph.runGraphMetricPlannedWorkerPageStepForMetric("pagerank", worker_id);
        try std.testing.expect(!worker_step.advanced_phase);
        if (!worker_step.claimed_page) {
            const coordinator_step = try graph.runGraphMetricPlannedCoordinatorStepForMetric("pagerank");
            try std.testing.expectEqual(phase, coordinator_step.phase);
        } else if (worker_step.completed_page) {
            _ = try graph.runGraphMetricPlannedCoordinatorStepForMetric("pagerank");
        }
    }
    try std.testing.expect(guard < 100);

    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const job = try graph.metricBuildJob(&txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.publish_generation, job.phase);
    }

    const worker_publish_step = try graph.runGraphMetricPlannedWorkerPageStepForMetric("pagerank", "worker-publish");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.publish_generation, worker_publish_step.phase);
    try std.testing.expect(!worker_publish_step.claimed_page);
    try std.testing.expect(!worker_publish_step.advanced_phase);
    try std.testing.expect(!worker_publish_step.published);
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const job = try graph.metricBuildJob(&txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.publish_generation, job.phase);
        try std.testing.expectEqual(@as(u64, 0), try graph.metricPublishedGeneration(&txn, "pagerank"));
    }

    const coordinator_publish_step = try graph.runGraphMetricPlannedCoordinatorStepForMetric("pagerank");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.publish_generation, coordinator_publish_step.phase);
    try std.testing.expect(coordinator_publish_step.advanced_phase);
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const job = try graph.metricBuildJob(&txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.cleanup_old_generations, job.phase);
        try std.testing.expect((try graph.metricPublishedGeneration(&txn, "pagerank")) != 0);
    }
}

fn expectPlannedWorkerCoordinatorSplitUntilPublish(
    graph: *GraphIndex,
    metric_name: []const u8,
) !void {
    var started = try graph.ensureGraphMetricPlannedBuild(metric_name, graph.edge_generation);
    defer started.deinit(graph.alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.building, started.state);
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const job = try graph.metricBuildJob(&txn, metric_name) orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.prepare_generation, job.phase);
    }
    {
        const worker_step = try graph.runGraphMetricPlannedWorkerPageStepForMetric(metric_name, "worker-a");
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.prepare_generation, worker_step.phase);
        try std.testing.expect(worker_step.claimed_page);
        try std.testing.expect(worker_step.completed_page);
        try std.testing.expect(!worker_step.advanced_phase);
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const job = try graph.metricBuildJob(&txn, metric_name) orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.prepare_generation, job.phase);
    }
    {
        const coordinator_step = try graph.runGraphMetricPlannedCoordinatorStepForMetric(metric_name);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.prepare_generation, coordinator_step.phase);
        try std.testing.expect(coordinator_step.advanced_phase);
    }

    var guard: usize = 0;
    while (guard < 200) : (guard += 1) {
        var txn = try graph.beginReadReverseTxn();
        const job = try graph.metricBuildJob(&txn, metric_name) orelse return error.TestExpectedGraphMetricBuildJob;
        const phase = job.phase;
        txn.abort();
        if (phase == .publish_generation) break;
        if (phase == .complete or phase == .cleanup_old_generations) return error.TestExpectedGraphMetricBuildPublishPhase;

        const worker_id = switch (guard % 3) {
            0 => "worker-a",
            1 => "worker-b",
            else => "worker-c",
        };
        const worker_step = try graph.runGraphMetricPlannedWorkerPageStepForMetric(metric_name, worker_id);
        try std.testing.expect(!worker_step.advanced_phase);
        if (worker_step.completed_page or !worker_step.claimed_page) {
            _ = try graph.runGraphMetricPlannedCoordinatorStepForMetric(metric_name);
        }
    }
    try std.testing.expect(guard < 200);

    const worker_publish_step = try graph.runGraphMetricPlannedWorkerPageStepForMetric(metric_name, "worker-publish");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.publish_generation, worker_publish_step.phase);
    try std.testing.expect(!worker_publish_step.claimed_page);
    try std.testing.expect(!worker_publish_step.advanced_phase);
    try std.testing.expect(!worker_publish_step.published);
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const job = try graph.metricBuildJob(&txn, metric_name) orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.publish_generation, job.phase);
        try std.testing.expectEqual(@as(u64, 0), try graph.metricPublishedGeneration(&txn, metric_name));
    }

    const coordinator_publish_step = try graph.runGraphMetricPlannedCoordinatorStepForMetric(metric_name);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.publish_generation, coordinator_publish_step.phase);
    try std.testing.expect(coordinator_publish_step.advanced_phase);
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const job = try graph.metricBuildJob(&txn, metric_name) orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.cleanup_old_generations, job.phase);
        try std.testing.expect((try graph.metricPublishedGeneration(&txn, metric_name)) != 0);
    }
}

