test "graph pagerank planned build resumes after dynamic iteration planning reopen" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-pagerank-planned-reopen");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-pagerank-planned-reopen");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{.{
        .name = "pagerank",
        .kind = .pagerank,
        .refresh = .manual,
        .max_iterations = 2,
        .tolerance = 0.000001,
    }};
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });

    try graph.addEdge("doc-a", "doc-b", "cites", 1.0, 0, 0, "");
    try graph.acquireGraphMetricBuildLease("pagerank", graph.edge_generation);

    var job_txn = try graph.beginReadReverseTxn();
    const active_job = try graph.metricBuildJob(&job_txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
    job_txn.abort();

    inline for (.{ .prepare_generation, .scan_edges_and_out_degree, .initialize_ranks, .iterate_contributions, .reduce_ranks, .check_convergence }) |expected_phase| {
        const step = try graph.runGraphMetricPlannedWorkerStep("pagerank", metrics[0], "worker-a");
        try std.testing.expectEqual(expected_phase, step.phase);
        try std.testing.expect(step.claimed_page);
        try std.testing.expect(step.completed_page);
        try std.testing.expect(step.advanced_phase);
    }
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const job = try graph.metricBuildJob(&txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(active_job.job_id, job.job_id);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.iterate_contributions, job.phase);
        try std.testing.expectEqual(@as(u32, 1), job.iteration);
        _ = try graph.metricBuildPage(&txn, "pagerank", active_job.job_id, .iterate_contributions, 1, 3) orelse return error.TestExpectedGraphMetricBuildPage;
        _ = try graph.metricBuildIterationSummary(&txn, "pagerank", active_job.job_id, 0) orelse return error.TestExpectedGraphMetricBuildIterationSummary;
    }
    graph.close();

    graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();
    {
        var status = try graph.graphMetricStatus("pagerank");
        defer status.deinit(alloc);
        try std.testing.expectEqual(GraphIndex.GraphMetricState.building, status.state);
        try std.testing.expectEqual(active_job.job_id, status.build_job_id);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.iterate_contributions, status.phase);
        try std.testing.expectEqual(@as(u32, 1), status.build_iteration);
    }

    var resumed = try graph.runGraphMetricPlannedActive("pagerank", metrics[0]);
    defer resumed.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.fresh, resumed.state);
    try std.testing.expectEqual(@as(u32, 2), resumed.iterations_completed);
    try std.testing.expect(!resumed.converged);

    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const completed_job = try graph.metricBuildJob(&txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(active_job.job_id, completed_job.job_id);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.complete, completed_job.phase);
        try std.testing.expect((try graph.metricBuildLease(&txn, "pagerank")) == null);
        try std.testing.expect((try graph.metricBuildManifest(&txn, "pagerank", active_job.job_id)) == null);
    }
}

test "graph metric build degree manifest partitions reverse-edge scan pages" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-degree-manifest-partitions");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-degree-manifest-partitions");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{.{
        .name = "degree",
        .kind = .degree,
        .refresh = .manual,
    }};
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    for (0..graph_metric_build_target_scan_page_units + 1) |i| {
        var source_buf: [64]u8 = undefined;
        const source = try std.fmt.bufPrint(&source_buf, "doc-{d:0>3}", .{i});
        try graph.addEdge(source, "hub", "cites", 1.0, 0, 0, "");
    }
    try graph.acquireGraphMetricBuildLease("degree", graph.edge_generation);
    defer graph.releaseGraphMetricBuildLease("degree") catch {};

    var job_txn = try graph.beginReadReverseTxn();
    const active_job = try graph.metricBuildJob(&job_txn, "degree") orelse return error.TestExpectedGraphMetricBuildJob;
    job_txn.abort();

    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const manifest = try graph.metricBuildManifest(&txn, "degree", active_job.job_id) orelse return error.TestExpectedGraphMetricBuildManifest;
        try std.testing.expectEqual(GraphIndex.graph_metric_degree_build_phases.len, manifest.phase_count);
        try std.testing.expectEqual(GraphIndex.graph_metric_degree_build_phases.len + 3, manifest.page_count);

        const first_scan = try graph.metricBuildPage(&txn, "degree", active_job.job_id, .scan_edges_and_out_degree, 0, 1) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.pending, first_scan.state);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageRangeKind.reverse_edges, first_scan.range_kind);
        try std.testing.expect(first_scan.range_lower.len > 0);
        try std.testing.expect(first_scan.range_upper.len > 0);
        try std.testing.expectEqual(@as(u64, graph_metric_build_target_scan_page_units), first_scan.total_units);
        try std.testing.expect(first_scan.output_prefix.len > 0);

        const second_scan = try graph.metricBuildPage(&txn, "degree", active_job.job_id, .scan_edges_and_out_degree, 0, 2) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.pending, second_scan.state);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageRangeKind.reverse_edges, second_scan.range_kind);
        try std.testing.expectEqualStrings(first_scan.range_upper, second_scan.range_lower);
        try std.testing.expectEqualStrings("", second_scan.range_upper);
        try std.testing.expectEqual(@as(u64, 1), second_scan.total_units);

        try std.testing.expect((try graph.metricBuildPage(&txn, "degree", active_job.job_id, .scan_edges_and_out_degree, 0, 3)) == null);

        const reduce = try graph.metricBuildPage(&txn, "degree", active_job.job_id, .reduce_ranks, 0, 2) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageRangeKind.nodes, reduce.range_kind);
        try std.testing.expect(reduce.range_lower.len > 0);
        try std.testing.expect(reduce.range_upper.len > 0);
        try std.testing.expectEqual(@as(u64, graph_metric_build_target_reduce_page_units), reduce.total_units);
        try std.testing.expect(reduce.output_prefix.len > 0);

        const second_reduce = try graph.metricBuildPage(&txn, "degree", active_job.job_id, .reduce_ranks, 0, 3) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageRangeKind.nodes, second_reduce.range_kind);
        try std.testing.expectEqualStrings(reduce.range_upper, second_reduce.range_lower);
        try std.testing.expectEqualStrings("", second_reduce.range_upper);
        try std.testing.expectEqual(graph.node_count - graph_metric_build_target_reduce_page_units, second_reduce.total_units);

        try std.testing.expect((try graph.metricBuildPage(&txn, "degree", active_job.job_id, .reduce_ranks, 0, 4)) == null);

        const partial_cleanup = try graph.metricBuildPage(&txn, "degree", active_job.job_id, .cleanup_old_generations, 0, 0) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageRangeKind.job_control, partial_cleanup.range_kind);
        try std.testing.expect(partial_cleanup.output_prefix.len > 0);
        const final_cleanup = try graph.metricBuildPage(&txn, "degree", active_job.job_id, .cleanup_old_generations, 0, 1) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageRangeKind.job_control, final_cleanup.range_kind);
        try std.testing.expect(final_cleanup.output_prefix.len > 0);
        try std.testing.expect(!std.mem.eql(u8, partial_cleanup.output_prefix, final_cleanup.output_prefix));
        try std.testing.expect((try graph.metricBuildPage(&txn, "degree", active_job.job_id, .cleanup_old_generations, 0, 2)) == null);
    }

    try graph.ensureGraphMetricBuildManifestForJob("degree", active_job);
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const manifest = try graph.metricBuildManifest(&txn, "degree", active_job.job_id) orelse return error.TestExpectedGraphMetricBuildManifest;
        try std.testing.expectEqual(GraphIndex.graph_metric_degree_build_phases.len + 3, manifest.page_count);
        const first_scan = try graph.metricBuildPage(&txn, "degree", active_job.job_id, .scan_edges_and_out_degree, 0, 1) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.pending, first_scan.state);
        const second_scan = try graph.metricBuildPage(&txn, "degree", active_job.job_id, .scan_edges_and_out_degree, 0, 2) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(@as(u64, 1), second_scan.total_units);
    }
}

test "graph degree scan build page honors reverse-edge key range" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-degree-scan-range");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-degree-scan-range");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{.{
        .name = "degree",
        .kind = .degree,
        .refresh = .manual,
    }};
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    try graph.addEdge("doc-a", "doc-b", "cites", 1.0, 0, 0, "");
    try graph.addEdge("doc-c", "doc-d", "cites", 1.0, 0, 0, "");
    try graph.acquireGraphMetricBuildLease("degree", graph.edge_generation);

    var job_txn = try graph.beginReadReverseTxn();
    const active_job = try graph.metricBuildJob(&job_txn, "degree") orelse return error.TestExpectedGraphMetricBuildJob;
    job_txn.abort();

    var edge_keys = std.ArrayListUnmanaged([]u8).empty;
    defer {
        for (edge_keys.items) |key| alloc.free(key);
        edge_keys.deinit(alloc);
    }
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        var cur = try txn.openCursor();
        defer cur.close();
        var entry_opt = try cur.first();
        while (entry_opt) |entry| : (entry_opt = try cur.next()) {
            if (std.mem.startsWith(u8, entry.key, graph_meta_prefix)) continue;
            var parsed = (try parseReverseEdgeKeyAlloc(alloc, entry.key)) orelse continue;
            defer parsed.deinit(alloc);
            if (!std.mem.eql(u8, parsed.index_name, "links")) continue;
            try edge_keys.append(alloc, try alloc.dupe(u8, entry.key));
        }
    }
    try std.testing.expectEqual(@as(usize, 2), edge_keys.items.len);
    var first_edge = (try parseReverseEdgeKeyAlloc(alloc, edge_keys.items[0])) orelse return error.TestExpectedGraphEdge;
    defer first_edge.deinit(alloc);
    const expected_source = try alloc.dupe(u8, first_edge.source);
    defer alloc.free(expected_source);
    const expected_target = try alloc.dupe(u8, first_edge.target);
    defer alloc.free(expected_target);
    var second_edge = (try parseReverseEdgeKeyAlloc(alloc, edge_keys.items[1])) orelse return error.TestExpectedGraphEdge;
    defer second_edge.deinit(alloc);
    const excluded_source = try alloc.dupe(u8, second_edge.source);
    defer alloc.free(excluded_source);
    const excluded_target = try alloc.dupe(u8, second_edge.target);
    defer alloc.free(excluded_target);

    {
        var batch = try graph.beginWriteReverseBatch();
        errdefer batch.abort();
        var page = try graph.metricBuildPage(&batch, "degree", active_job.job_id, .scan_edges_and_out_degree, 0, 1) orelse return error.TestExpectedGraphMetricBuildPage;
        page.range_kind = .reverse_edges;
        page.range_lower = edge_keys.items[0];
        page.range_upper = edge_keys.items[1];
        try graph.putGraphMetricBuildPageInBatch(&batch, "degree", page);
        try batch.commit();
    }

    const claimed = try graph.claimGraphMetricBuildPage("degree", active_job.job_id, .scan_edges_and_out_degree, 0, 1, graph_metric_local_build_worker_id) orelse return error.TestExpectedGraphMetricBuildPage;
    const score_count = try graph.executeDegreeScanBuildPage("degree", metrics[0], active_job, claimed);
    try std.testing.expectEqual(@as(usize, 2), score_count);

    var score_txn = try graph.beginReadReverseTxn();
    defer score_txn.abort();
    const expected_nodes = [_][]const u8{ expected_source, expected_target };
    for (expected_nodes) |node| {
        const partial_key = try graph.graphMetricBuildDegreePartialKeyAlloc("degree", active_job.job_id, node, claimed.page_id);
        defer alloc.free(partial_key);
        const raw = try score_txn.get(partial_key);
        try std.testing.expectEqual(@as(u64, 1), std.mem.readInt(u64, raw[0..8], .little));
    }
    const excluded_nodes = [_][]const u8{ excluded_source, excluded_target };
    for (excluded_nodes) |node| {
        const partial_key = try graph.graphMetricBuildDegreePartialKeyAlloc("degree", active_job.job_id, node, claimed.page_id);
        defer alloc.free(partial_key);
        try std.testing.expectError(error.NotFound, score_txn.get(partial_key));
    }
}

test "graph degree reduce aggregates partials from multiple scan pages" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
