        edge_keys.deinit(alloc);
    }
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        var cur = try txn.openCursor();
        defer cur.close();
        var entry_opt = try cur.first();
        while (entry_opt) |entry| : (entry_opt = try cur.next()) {
            if (std.mem.startsWith(u8, entry.key, graph_meta_prefix)) continue;
            var parsed = (try parseReverseEdgeKeyAlloc(alloc, entry.key)) orelse continue;
            defer parsed.deinit(alloc);
            if (!std.mem.eql(u8, parsed.index_name, "links")) continue;
            try edge_keys.append(alloc, try alloc.dupe(u8, entry.key));
        }
    }
    try std.testing.expectEqual(@as(usize, 2), edge_keys.items.len);

    {
        var batch = try graph.beginWriteReverseBatch();
        errdefer batch.abort();
        var first_scan = try graph.metricBuildPage(&batch, "degree", active_job.job_id, .scan_edges_and_out_degree, 0, 1) orelse return error.TestExpectedGraphMetricBuildPage;
        first_scan.range_kind = .reverse_edges;
        first_scan.range_lower = edge_keys.items[0];
        first_scan.range_upper = edge_keys.items[1];
        first_scan.total_units = 1;
        try graph.putGraphMetricBuildPageInBatch(&batch, "degree", first_scan);
        try graph.putGraphMetricBuildPageInBatch(&batch, "degree", .{
            .job_id = active_job.job_id,
            .phase = .scan_edges_and_out_degree,
            .iteration = 0,
            .page_id = 99,
            .state = .pending,
            .range_kind = .reverse_edges,
            .range_lower = edge_keys.items[1],
            .range_upper = "",
            .total_units = 1,
        });
        try batch.commit();
    }

    _ = try graph.claimGraphMetricBuildPageAt("degree", active_job.job_id, .prepare_generation, 0, 0, "worker-a", 1000);
    _ = try graph.completeGraphMetricBuildPage("degree", active_job.job_id, .prepare_generation, 0, 0, "worker-a", 1, 10);
    try std.testing.expect(try graph.advanceGraphMetricBuildPhaseIfReady("degree", active_job.job_id, .prepare_generation, 0));

    const first_page = try graph.claimGraphMetricBuildPage("degree", active_job.job_id, .scan_edges_and_out_degree, 0, 1, "worker-a") orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(@as(usize, 2), try graph.executeDegreeScanBuildPage("degree", metrics[0], active_job, first_page));
    try std.testing.expect(!(try graph.advanceGraphMetricBuildPhaseIfReady("degree", active_job.job_id, .scan_edges_and_out_degree, 0)));

    const second_page = try graph.claimGraphMetricBuildPage("degree", active_job.job_id, .scan_edges_and_out_degree, 0, 99, "worker-b") orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(@as(usize, 2), try graph.executeDegreeScanBuildPage("degree", metrics[0], active_job, second_page));
    try std.testing.expect(try graph.advanceGraphMetricBuildPhaseIfReady("degree", active_job.job_id, .scan_edges_and_out_degree, 0));

    const reduce_page = try graph.claimGraphMetricBuildPage("degree", active_job.job_id, .reduce_ranks, 0, 2, "worker-r") orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(@as(usize, 3), try graph.executeDegreeReduceBuildPage("degree", active_job, reduce_page));
    try std.testing.expect(try graph.advanceGraphMetricBuildPhaseIfReady("degree", active_job.job_id, .reduce_ranks, 0));

    var score_txn = try graph.beginReadReverseTxn();
    defer score_txn.abort();
    const expected_scores = [_]struct {
        node: []const u8,
        score: f64,
    }{
        .{ .node = "doc-a", .score = 1.0 },
        .{ .node = "doc-b", .score = 2.0 },
        .{ .node = "doc-c", .score = 1.0 },
    };
    for (expected_scores) |expected| {
        const score_key = try graph.graphMetricScoreKeyAlloc("degree", active_job.score_generation, expected.node);
        defer alloc.free(score_key);
        const raw = try score_txn.get(score_key);
        try std.testing.expectApproxEqAbs(expected.score, GraphIndex.decodeF64(raw) orelse return error.TestExpectedGraphMetricScore, 0.0000001);
    }
    {
        const job = try graph.metricBuildJob(&score_txn, "degree") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.publish_generation, job.phase);
    }
}

