}

test "graph degree scan attempt output adopts only on page completion" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-degree-scan-attempt-adopt");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-degree-scan-attempt-adopt");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{.{
        .name = "degree",
        .kind = .degree,
        .refresh = .manual,
    }};
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    try graph.addEdge("doc-a", "hub", "cites", 1.0, 0, 0, "");
    try graph.addEdge("doc-c", "hub", "cites", 1.0, 0, 0, "");
    try graph.acquireGraphMetricBuildLease("degree", graph.edge_generation);
    defer graph.releaseGraphMetricBuildLease("degree") catch {};

    var job_txn = try graph.beginReadReverseTxn();
    const active_job = try graph.metricBuildJob(&job_txn, "degree") orelse return error.TestExpectedGraphMetricBuildJob;
    job_txn.abort();

    _ = try graph.claimGraphMetricBuildPageAt("degree", active_job.job_id, .prepare_generation, 0, 0, "worker-a", 1000);
    _ = try graph.completeGraphMetricBuildPage("degree", active_job.job_id, .prepare_generation, 0, 0, "worker-a", 1, 10);
    try std.testing.expect(try graph.advanceGraphMetricBuildPhaseIfReady("degree", active_job.job_id, .prepare_generation, 0));

    const first_claim = try graph.claimGraphMetricBuildPageAt("degree", active_job.job_id, .scan_edges_and_out_degree, 0, 1, "worker-a", 2000) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(@as(u64, 1), first_claim.attempt);
    try std.testing.expectEqual(@as(usize, 2), try graph.executeDegreeScanBuildPageWithLimit("degree", metrics[0], active_job, first_claim, 1));

    const attempt_hub_key = try graph.graphMetricBuildAttemptDegreePartialKeyAlloc("degree", active_job.job_id, .scan_edges_and_out_degree, 0, first_claim.page_id, first_claim.attempt, "hub");
    defer alloc.free(attempt_hub_key);
    const adopted_hub_key = try graph.graphMetricBuildDegreePartialKeyAlloc("degree", active_job.job_id, "hub", first_claim.page_id);
    defer alloc.free(adopted_hub_key);
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        try std.testing.expectEqual(@as(u64, 1), try GraphIndex.readU64OrZero(&txn, attempt_hub_key));
        try std.testing.expectError(error.NotFound, txn.get(adopted_hub_key));
        const page = try graph.metricBuildPage(&txn, "degree", active_job.job_id, .scan_edges_and_out_degree, 0, first_claim.page_id) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, page.state);
        try std.testing.expectEqual(@as(u64, 1), page.completed_units);
    }

    const renewed = try graph.claimGraphMetricBuildPageAt("degree", active_job.job_id, .scan_edges_and_out_degree, 0, first_claim.page_id, "worker-a", 2001) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(@as(u64, 1), renewed.attempt);
    try std.testing.expectEqual(@as(usize, 2), try graph.executeDegreeScanBuildPage("degree", metrics[0], active_job, renewed));
    try std.testing.expect(try graph.advanceGraphMetricBuildPhaseIfReady("degree", active_job.job_id, .scan_edges_and_out_degree, 0));
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        try std.testing.expectEqual(@as(u64, 2), try GraphIndex.readU64OrZero(&txn, attempt_hub_key));
        try std.testing.expectEqual(@as(u64, 2), try GraphIndex.readU64OrZero(&txn, adopted_hub_key));
        const page = try graph.metricBuildPage(&txn, "degree", active_job.job_id, .scan_edges_and_out_degree, 0, first_claim.page_id) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.complete, page.state);
    }

    const reduce_page = try graph.claimGraphMetricBuildPage("degree", active_job.job_id, .reduce_ranks, 0, 2, "worker-r") orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(@as(usize, 3), try graph.executeDegreeReduceBuildPage("degree", active_job, reduce_page));
    try std.testing.expect(try graph.advanceGraphMetricBuildPhaseIfReady("degree", active_job.job_id, .reduce_ranks, 0));

    const publish = try graph.runGraphMetricPlannedWorkerStep("degree", metrics[0], "worker-publish");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.publish_generation, publish.phase);
    try std.testing.expect(publish.advanced_phase);

    const first_cleanup = try graph.runGraphMetricPlannedWorkerStep("degree", metrics[0], "worker-clean-1");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.cleanup_old_generations, first_cleanup.phase);
    try std.testing.expect(first_cleanup.completed_page);
    try std.testing.expect(!first_cleanup.published);
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        try std.testing.expect((try txn.get(attempt_hub_key)).len >= 8);
        try std.testing.expectError(error.NotFound, txn.get(adopted_hub_key));
    }

    const final_cleanup = try graph.runGraphMetricPlannedWorkerStep("degree", metrics[0], "worker-clean-2");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.cleanup_old_generations, final_cleanup.phase);
    try std.testing.expect(final_cleanup.completed_page);
    try std.testing.expect(final_cleanup.published);
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        try std.testing.expectError(error.NotFound, txn.get(attempt_hub_key));
        try std.testing.expectError(error.NotFound, txn.get(adopted_hub_key));
        const completed_job = try graph.metricBuildJob(&txn, "degree") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.complete, completed_job.phase);
    }
}

test "graph degree scan page reclaim recomputes without double counting partials" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-degree-scan-reclaim");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-degree-scan-reclaim");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{.{
        .name = "degree",
        .kind = .degree,
        .refresh = .manual,
    }};
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    try graph.addEdge("doc-a", "hub", "cites", 1.0, 0, 0, "");
    try graph.addEdge("doc-c", "hub", "cites", 1.0, 0, 0, "");
    try graph.acquireGraphMetricBuildLease("degree", graph.edge_generation);
    defer graph.releaseGraphMetricBuildLease("degree") catch {};

    var job_txn = try graph.beginReadReverseTxn();
    const active_job = try graph.metricBuildJob(&job_txn, "degree") orelse return error.TestExpectedGraphMetricBuildJob;
    job_txn.abort();

    _ = try graph.claimGraphMetricBuildPageAt("degree", active_job.job_id, .prepare_generation, 0, 0, "worker-a", 1000);
    _ = try graph.completeGraphMetricBuildPage("degree", active_job.job_id, .prepare_generation, 0, 0, "worker-a", 1, 10);
    try std.testing.expect(try graph.advanceGraphMetricBuildPhaseIfReady("degree", active_job.job_id, .prepare_generation, 0));

    const first_claim = try graph.claimGraphMetricBuildPageAt("degree", active_job.job_id, .scan_edges_and_out_degree, 0, 1, "worker-a", 2000) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(@as(usize, 2), try graph.executeDegreeScanBuildPageWithLimit("degree", metrics[0], active_job, first_claim, 1));

    var persisted_cursor: []u8 = "";
    defer if (persisted_cursor.len > 0) alloc.free(persisted_cursor);
    var expires_at: u64 = 0;
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "degree", active_job.job_id, .scan_edges_and_out_degree, 0, 1) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expect(page.cursor.len > 0);
        persisted_cursor = try alloc.dupe(u8, page.cursor);
        expires_at = page.lease_expires_at_ms;
    }

    const reclaimed = try graph.claimGraphMetricBuildPageAt("degree", active_job.job_id, .scan_edges_and_out_degree, 0, 1, "worker-b", expires_at + 1) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(@as(u64, 2), reclaimed.attempt);
    try std.testing.expectEqualStrings("worker-b", reclaimed.worker_id);
    try std.testing.expectEqualStrings("", reclaimed.cursor);
    try std.testing.expectEqual(@as(u64, 0), reclaimed.completed_units);
    try std.testing.expect(!std.mem.eql(u8, persisted_cursor, reclaimed.cursor));

    try std.testing.expectEqual(@as(usize, 3), try graph.executeDegreeScanBuildPage("degree", metrics[0], active_job, reclaimed));
    try std.testing.expect(try graph.advanceGraphMetricBuildPhaseIfReady("degree", active_job.job_id, .scan_edges_and_out_degree, 0));

    const reduce_page = try graph.claimGraphMetricBuildPage("degree", active_job.job_id, .reduce_ranks, 0, 2, "worker-r") orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(@as(usize, 3), try graph.executeDegreeReduceBuildPage("degree", active_job, reduce_page));

    var score_txn = try graph.beginReadReverseTxn();
    defer score_txn.abort();
    const hub_key = try graph.graphMetricScoreKeyAlloc("degree", active_job.score_generation, "hub");
    defer alloc.free(hub_key);
    const raw = try score_txn.get(hub_key);
    try std.testing.expectApproxEqAbs(@as(f64, 2.0), GraphIndex.decodeF64(raw) orelse return error.TestExpectedGraphMetricScore, 0.0000001);
}

