    _ = try graph.completeGraphMetricBuildPage("degree", active_job.job_id, .prepare_generation, 0, 0, "worker-a", 1, 10);
    try std.testing.expect(try graph.advanceGraphMetricBuildPhaseIfReady("degree", active_job.job_id, .prepare_generation, 0));

    const scan_page = try graph.claimGraphMetricBuildPageAt("degree", active_job.job_id, .scan_edges_and_out_degree, 0, 1, "worker-s", 2000) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(@as(usize, 3), try graph.executeDegreeScanBuildPage("degree", metrics[0], active_job, scan_page));
    try std.testing.expect(try graph.advanceGraphMetricBuildPhaseIfReady("degree", active_job.job_id, .scan_edges_and_out_degree, 0));

    const stale_reduce = try graph.claimGraphMetricBuildPageAt("degree", active_job.job_id, .reduce_ranks, 0, 2, "worker-a", 3000) orelse return error.TestExpectedGraphMetricBuildPage;
    const reclaimed_reduce = try graph.claimGraphMetricBuildPageAt("degree", active_job.job_id, .reduce_ranks, 0, 2, "worker-b", stale_reduce.lease_expires_at_ms + 1) orelse return error.TestExpectedGraphMetricBuildPage;
