    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        try std.testing.expectError(error.NotFound, txn.get(hub_key));
    }

    const scores = [_]GraphIndex.GraphMetricScore{.{
        .node = "hub",
        .score = 2.0,
    }};
    const completed = try graph.completeDegreeReduceBuildPageWithScoresForAttempt("degree", active_job, reclaimed_reduce, reclaimed_reduce.worker_id, "degree-reduce:partials=2;scores=1", 1, &scores, GraphIndex.graphMetricScoresFingerprint(&scores));
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.complete, completed.state);
    try std.testing.expectEqual(reclaimed_reduce.attempt, completed.attempt);
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const raw = try txn.get(hub_key);
        try std.testing.expectApproxEqAbs(@as(f64, 2.0), GraphIndex.decodeF64(raw) orelse return error.TestExpectedGraphMetricScore, 0.0000001);
    }
}

test "graph metric build page lease lifecycle supports reclaim and idempotent completion" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-metric-page-lease");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-metric-page-lease");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{.{
        .name = "pagerank",
        .kind = .pagerank,
        .refresh = .manual,
    }};
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    try graph.addEdge("doc-a", "doc-b", "cites", 1.0, 0, 0, "");
    try graph.acquireGraphMetricBuildLease("pagerank", graph.edge_generation);

    var job_txn = try graph.beginReadReverseTxn();
    const active_job = try graph.metricBuildJob(&job_txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
    job_txn.abort();

    const start_ms: u64 = 1000;
    const first_claim = try graph.claimGraphMetricBuildPageAt("pagerank", active_job.job_id, .scan_edges_and_out_degree, 0, 1, "worker-a", start_ms) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, first_claim.state);
    try std.testing.expectEqual(@as(u64, 1), first_claim.attempt);
    try std.testing.expectEqualStrings("worker-a", first_claim.worker_id);
    try std.testing.expect(first_claim.lease_expires_at_ms > start_ms);

    try std.testing.expect((try graph.claimGraphMetricBuildPageAt("pagerank", active_job.job_id, .scan_edges_and_out_degree, 0, 1, "worker-b", start_ms + 1)) == null);
    const same_worker_claim = try graph.claimGraphMetricBuildPageAt("pagerank", active_job.job_id, .scan_edges_and_out_degree, 0, 1, "worker-a", start_ms + 2) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(@as(u64, 1), same_worker_claim.attempt);
    try std.testing.expectEqualStrings("worker-a", same_worker_claim.worker_id);

    const reclaimed = try graph.claimGraphMetricBuildPageAt("pagerank", active_job.job_id, .scan_edges_and_out_degree, 0, 1, "worker-b", same_worker_claim.lease_expires_at_ms + 1) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, reclaimed.state);
    try std.testing.expectEqual(@as(u64, 2), reclaimed.attempt);
    try std.testing.expectEqualStrings("worker-b", reclaimed.worker_id);
    try std.testing.expectError(error.GraphMetricBuildPageNotLeased, graph.completeGraphMetricBuildPage("pagerank", active_job.job_id, .scan_edges_and_out_degree, 0, 1, "worker-a", 1, 55));

    const completed = try graph.completeGraphMetricBuildPage("pagerank", active_job.job_id, .scan_edges_and_out_degree, 0, 1, "worker-b", 1, 55);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.complete, completed.state);
    try std.testing.expectEqual(@as(u64, 0), completed.lease_expires_at_ms);
    try std.testing.expectEqual(@as(u64, 1), completed.completed_units);
    try std.testing.expectEqual(@as(u64, 55), completed.output_fingerprint);
    try std.testing.expect((try graph.claimGraphMetricBuildPageAt("pagerank", active_job.job_id, .scan_edges_and_out_degree, 0, 1, "worker-c", completed.lease_expires_at_ms + 1)) == null);
    const completed_again = try graph.completeGraphMetricBuildPage("pagerank", active_job.job_id, .scan_edges_and_out_degree, 0, 1, "worker-c", 1, 55);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.complete, completed_again.state);
    try std.testing.expectError(error.GraphMetricBuildPageOutputMismatch, graph.completeGraphMetricBuildPage("pagerank", active_job.job_id, .scan_edges_and_out_degree, 0, 1, "worker-c", 1, 56));

    _ = try graph.claimGraphMetricBuildPageAt("pagerank", active_job.job_id, .initialize_ranks, 0, 2, "worker-a", start_ms);
    const failed = try graph.failGraphMetricBuildPage("pagerank", active_job.job_id, .initialize_ranks, 0, 2, "worker-a", "transient");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.failed, failed.state);
    try std.testing.expectEqual(@as(u64, 1), failed.attempt);
    try std.testing.expectEqualStrings("transient", failed.last_error);
    const retried = try graph.claimGraphMetricBuildPageAt("pagerank", active_job.job_id, .initialize_ranks, 0, 2, "worker-b", start_ms + 1) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, retried.state);
    try std.testing.expectEqual(@as(u64, 2), retried.attempt);
    try std.testing.expectEqualStrings("", retried.last_error);
    try std.testing.expectEqualStrings("worker-b", retried.worker_id);

    const same_worker_replacement = try graph.claimGraphMetricBuildPageAt("pagerank", active_job.job_id, .initialize_ranks, 0, 2, "worker-b", retried.lease_expires_at_ms + 1) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, same_worker_replacement.state);
    try std.testing.expectEqual(@as(u64, 3), same_worker_replacement.attempt);
    try std.testing.expectEqualStrings("worker-b", same_worker_replacement.worker_id);
    try std.testing.expectError(error.GraphMetricBuildPageNotLeased, graph.updateGraphMetricBuildPageProgressForAttempt("pagerank", active_job.job_id, .initialize_ranks, 0, 2, "worker-b", retried.attempt, "stale-cursor", 1, retried.total_units));
    try std.testing.expectError(error.GraphMetricBuildPageNotLeased, graph.completeGraphMetricBuildPageForAttempt("pagerank", active_job.job_id, .initialize_ranks, 0, 2, "worker-b", retried.attempt, 1, 66));
    try std.testing.expectError(error.GraphMetricBuildPageNotLeased, graph.failGraphMetricBuildPageForAttempt("pagerank", active_job.job_id, .initialize_ranks, 0, 2, "worker-b", retried.attempt, "stale failure"));
    const replacement_complete = try graph.completeGraphMetricBuildPageForAttempt("pagerank", active_job.job_id, .initialize_ranks, 0, 2, "worker-b", same_worker_replacement.attempt, 1, 66);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.complete, replacement_complete.state);
    try std.testing.expectEqual(@as(u64, 3), replacement_complete.attempt);
    try std.testing.expectError(error.GraphMetricBuildPageNotLeased, graph.completeGraphMetricBuildPageForAttempt("pagerank", active_job.job_id, .initialize_ranks, 0, 2, "worker-b", retried.attempt, 1, 66));
    const legacy_idempotent_complete = try graph.completeGraphMetricBuildPage("pagerank", active_job.job_id, .initialize_ranks, 0, 2, "worker-c", 1, 66);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.complete, legacy_idempotent_complete.state);
    try std.testing.expectEqual(@as(u64, 3), legacy_idempotent_complete.attempt);
}

