    }

    try std.testing.expect((try graph.claimGraphMetricBuildPageAt("degree", active_job.job_id, .scan_edges_and_out_degree, 0, 1, "worker-d", 2000)) == null);
    try std.testing.expect((try graph.claimNextGraphMetricBuildPageAt("degree", active_job.job_id, .scan_edges_and_out_degree, 0, "worker-d", 2000)) == null);
    const summary = try graph.summarizeGraphMetricBuildPhase("degree", active_job.job_id, .scan_edges_and_out_degree, 0);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhaseState.failed, summary.state);
    try std.testing.expectEqual(@as(u64, 1), summary.failed_pages);
}

test "graph metric coordinator fails build after page attempts exhaust" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-metric-page-exhausted-fail");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-metric-page-exhausted-fail");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{.{
        .name = "degree",
        .kind = .degree,
        .refresh = .manual,
    }};
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    try graph.addEdge("doc-a", "doc-b", "cites", 1.0, 0, 0, "");
    try graph.acquireGraphMetricBuildLease("degree", graph.edge_generation);

    const prepare_worker = try graph.runGraphMetricPlannedWorkerPageStepForMetric("degree", "worker-prepare");
    try std.testing.expect(prepare_worker.completed_page);
    try std.testing.expect(!prepare_worker.advanced_phase);
    const prepare_coordinator = try graph.runGraphMetricPlannedCoordinatorStepForMetric("degree");
    try std.testing.expect(prepare_coordinator.advanced_phase);

    const active_job = blk: {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const job = try graph.metricBuildJob(&txn, "degree") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.scan_edges_and_out_degree, job.phase);
        break :blk job;
    };

    var attempt: u64 = 0;
    while (attempt < graph_metric_build_max_page_attempts) : (attempt += 1) {
        const worker_id = switch (attempt) {
            0 => "worker-a",
            1 => "worker-b",
            else => "worker-c",
        };
        const page = try graph.claimGraphMetricBuildPageAt("degree", active_job.job_id, .scan_edges_and_out_degree, 0, 1, worker_id, 1000 + attempt) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(attempt + 1, page.attempt);
        _ = try graph.failGraphMetricBuildPage("degree", active_job.job_id, .scan_edges_and_out_degree, 0, 1, worker_id, "retryable");
    }

    const failed_step = try graph.runGraphMetricPlannedCoordinatorStepForMetric("degree");
    try std.testing.expect(failed_step.failed_build);
    try std.testing.expect(!failed_step.advanced_phase);
    try std.testing.expect(!failed_step.published);

    var status = try graph.graphMetricStatus("degree");
    defer status.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.failed, status.state);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.idle, status.phase);
    try std.testing.expectEqualStrings("GraphMetricBuildPageAttemptsExhausted", status.last_error);
    try std.testing.expectEqual(@as(u64, 0), status.published_generation);
}

test "graph metric build scheduler claims next eligible page" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-metric-page-scheduler");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-metric-page-scheduler");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{.{
        .name = "degree",
        .kind = .degree,
        .refresh = .manual,
    }};
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    try graph.addEdge("doc-a", "doc-b", "cites", 1.0, 0, 0, "");
    try graph.acquireGraphMetricBuildLease("degree", graph.edge_generation);

    var job_txn = try graph.beginReadReverseTxn();
    const active_job = try graph.metricBuildJob(&job_txn, "degree") orelse return error.TestExpectedGraphMetricBuildJob;
    job_txn.abort();

    {
        var batch = try graph.beginWriteReverseBatch();
        errdefer batch.abort();
        try graph.putGraphMetricBuildPageInBatch(&batch, "degree", .{
            .job_id = active_job.job_id,
            .phase = .scan_edges_and_out_degree,
            .iteration = 0,
            .page_id = 99,
            .state = .pending,
            .range_kind = .reverse_edges,
            .worker_id = "",
            .total_units = 2,
        });
        try batch.commit();
    }

    const first = try graph.claimNextGraphMetricBuildPageAt("degree", active_job.job_id, .scan_edges_and_out_degree, 0, "worker-a", 1000) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(@as(u64, 1), first.page_id);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, first.state);
    try std.testing.expectEqualStrings("worker-a", first.worker_id);

    const second = try graph.claimNextGraphMetricBuildPageAt("degree", active_job.job_id, .scan_edges_and_out_degree, 0, "worker-b", 1001) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(@as(u64, 99), second.page_id);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, second.state);
    try std.testing.expectEqualStrings("worker-b", second.worker_id);

    try std.testing.expect((try graph.claimNextGraphMetricBuildPageAt("degree", active_job.job_id, .scan_edges_and_out_degree, 0, "worker-c", 1002)) == null);

    const reclaimed = try graph.claimNextGraphMetricBuildPageAt("degree", active_job.job_id, .scan_edges_and_out_degree, 0, "worker-c", first.lease_expires_at_ms + 1) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(@as(u64, 1), reclaimed.page_id);
    try std.testing.expectEqual(@as(u64, 2), reclaimed.attempt);
    try std.testing.expectEqualStrings("worker-c", reclaimed.worker_id);

    _ = try graph.completeGraphMetricBuildPage("degree", active_job.job_id, .scan_edges_and_out_degree, 0, 1, "worker-c", 1, 10);
    const retried = try graph.claimNextGraphMetricBuildPageAt("degree", active_job.job_id, .scan_edges_and_out_degree, 0, "worker-d", second.lease_expires_at_ms + 1) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(@as(u64, 99), retried.page_id);
    try std.testing.expectEqual(@as(u64, 2), retried.attempt);
    try std.testing.expectEqualStrings("worker-d", retried.worker_id);
}

test "graph metric status summarizes multiple active build pages with cap" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-metric-page-status-cap");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-metric-page-status-cap");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{.{
        .name = "degree",
        .kind = .degree,
        .refresh = .manual,
    }};
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    try graph.addEdge("doc-a", "doc-b", "cites", 1.0, 0, 0, "");
    try graph.acquireGraphMetricBuildLease("degree", graph.edge_generation);

    var job_txn = try graph.beginReadReverseTxn();
    const active_job = try graph.metricBuildJob(&job_txn, "degree") orelse return error.TestExpectedGraphMetricBuildJob;
    job_txn.abort();

    _ = try graph.claimGraphMetricBuildPageAt("degree", active_job.job_id, .prepare_generation, 0, 0, "worker-prepare", 1000) orelse return error.TestExpectedGraphMetricBuildPage;
    _ = try graph.completeGraphMetricBuildPage("degree", active_job.job_id, .prepare_generation, 0, 0, "worker-prepare", 1, 10);
    try std.testing.expect(try graph.advanceGraphMetricBuildPhaseIfReady("degree", active_job.job_id, .prepare_generation, 0));

    {
        var batch = try graph.beginWriteReverseBatch();
        errdefer batch.abort();
        for (0..graph_metric_status_page_limit) |i| {
            try graph.putGraphMetricBuildPageInBatch(&batch, "degree", .{
                .job_id = active_job.job_id,
                .phase = .scan_edges_and_out_degree,
                .iteration = 0,
                .page_id = 100 + @as(u64, @intCast(i)),
                .state = .pending,
                .range_kind = .reverse_edges,
                .total_units = 4,
            });
        }
        try batch.commit();
    }

    for (0..graph_metric_status_page_limit + 1) |i| {
        var worker_buf: [64]u8 = undefined;
        const worker_id = try std.fmt.bufPrint(&worker_buf, "worker-{d}", .{i});
        const page_id: u64 = if (i == 0) 1 else 99 + @as(u64, @intCast(i));
        const claimed = try graph.claimGraphMetricBuildPageAt("degree", active_job.job_id, .scan_edges_and_out_degree, 0, page_id, worker_id, 2000 + @as(u64, @intCast(i))) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, claimed.state);
        try std.testing.expectEqualStrings(worker_id, claimed.worker_id);
        _ = try graph.updateGraphMetricBuildPageProgress("degree", active_job.job_id, .scan_edges_and_out_degree, 0, page_id, worker_id, worker_id, if (claimed.total_units > 0) 1 else 0, claimed.total_units);
    }

    var status = try graph.graphMetricStatus("degree");
    defer status.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.building, status.state);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.scan_edges_and_out_degree, status.phase);
    try std.testing.expect(status.build_job_id != 0);
    try std.testing.expect(status.build_started_at_ms != 0);
    try std.testing.expect(status.build_lease_expires_at_ms > 0);
    try std.testing.expect(std.math.isFinite(status.progress));
    try std.testing.expect(status.progress >= 0.0);
    try std.testing.expect(status.progress <= 1.0);
    try std.testing.expect(status.build_pages_truncated);
    try std.testing.expectEqual(@as(usize, graph_metric_status_page_limit), status.build_pages.len);
    for (status.build_pages) |page_status| {
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.scan_edges_and_out_degree, page_status.phase);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, page_status.state);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageRangeKind.reverse_edges, page_status.range_kind);
        try std.testing.expect(page_status.worker_id.len > 0);
        try std.testing.expect(page_status.lease_expires_at_ms > 0);
        try std.testing.expectEqual(@as(u64, 1), page_status.attempt);
        try std.testing.expect(page_status.cursor.len > 0);
        try std.testing.expectEqualStrings("", page_status.last_error);
        try std.testing.expect(page_status.completed_units > 0);
        try std.testing.expect(page_status.total_units > 0);
        try std.testing.expect(page_status.completed_units <= page_status.total_units);
    }
}

test "graph metric build page progress cursor survives renew and reopen" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-metric-page-progress");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-metric-page-progress");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{.{
        .name = "degree",
        .kind = .degree,
        .refresh = .manual,
    }};
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });

    try graph.addEdge("doc-a", "doc-b", "cites", 1.0, 0, 0, "");
    try graph.addEdge("doc-b", "doc-c", "cites", 1.0, 0, 0, "");
    try graph.acquireGraphMetricBuildLease("degree", graph.edge_generation);

    var job_txn = try graph.beginReadReverseTxn();
    const active_job = try graph.metricBuildJob(&job_txn, "degree") orelse return error.TestExpectedGraphMetricBuildJob;
    job_txn.abort();

    _ = try graph.claimGraphMetricBuildPageAt("degree", active_job.job_id, .prepare_generation, 0, 0, "worker-a", 1000);
    _ = try graph.completeGraphMetricBuildPage("degree", active_job.job_id, .prepare_generation, 0, 0, "worker-a", 1, 10);
    try std.testing.expect(try graph.advanceGraphMetricBuildPhaseIfReady("degree", active_job.job_id, .prepare_generation, 0));

    const claim = try graph.claimGraphMetricBuildPageAt("degree", active_job.job_id, .scan_edges_and_out_degree, 0, 1, "worker-a", 2000) orelse return error.TestExpectedGraphMetricBuildPage;
    const progress = try graph.updateGraphMetricBuildPageProgress("degree", active_job.job_id, .scan_edges_and_out_degree, 0, 1, "worker-a", "edge-page:0001", 1, claim.total_units);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, progress.state);
    try std.testing.expectEqualStrings("edge-page:0001", progress.cursor);
    try std.testing.expectEqual(@as(u64, 1), progress.completed_units);

    var status = try graph.graphMetricStatus("degree");
    defer status.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.building, status.state);
    try std.testing.expectEqualStrings("edge-page:0001", status.build_cursor);
    try std.testing.expectEqual(@as(u64, 1), status.build_completed_units);
    try std.testing.expectEqual(claim.total_units, status.build_total_units);
    try std.testing.expect(!status.build_pages_truncated);
    try std.testing.expectEqual(@as(usize, 1), status.build_pages.len);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.scan_edges_and_out_degree, status.build_pages[0].phase);
    try std.testing.expectEqual(@as(u32, 0), status.build_pages[0].iteration);
    try std.testing.expectEqual(@as(u64, 1), status.build_pages[0].page_id);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, status.build_pages[0].state);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageRangeKind.reverse_edges, status.build_pages[0].range_kind);
    try std.testing.expectEqualStrings("worker-a", status.build_pages[0].worker_id);
    try std.testing.expect(status.build_pages[0].lease_expires_at_ms > 0);
    try std.testing.expectEqual(@as(u64, 1), status.build_pages[0].attempt);
    try std.testing.expectEqualStrings("edge-page:0001", status.build_pages[0].cursor);
    try std.testing.expectEqual(@as(u64, 1), status.build_pages[0].completed_units);
    try std.testing.expectEqual(claim.total_units, status.build_pages[0].total_units);
    try std.testing.expectEqualStrings("", status.build_pages[0].last_error);

    _ = try graph.claimGraphMetricBuildPageAt("degree", active_job.job_id, .scan_edges_and_out_degree, 0, 1, "worker-a", 2001) orelse return error.TestExpectedGraphMetricBuildPage;
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const renewed = try graph.metricBuildPage(&txn, "degree", active_job.job_id, .scan_edges_and_out_degree, 0, 1) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqualStrings("edge-page:0001", renewed.cursor);
        try std.testing.expectEqual(@as(u64, 1), renewed.completed_units);
    }

    try std.testing.expectError(error.GraphMetricBuildPageNotLeased, graph.updateGraphMetricBuildPageProgress("degree", active_job.job_id, .scan_edges_and_out_degree, 0, 1, "worker-b", "edge-page:bad", 2, claim.total_units));
    graph.close();

    graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "degree", active_job.job_id, .scan_edges_and_out_degree, 0, 1) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqualStrings("edge-page:0001", page.cursor);
        try std.testing.expectEqual(@as(u64, 1), page.completed_units);
        const job = try graph.metricBuildJob(&txn, "degree") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqualStrings("edge-page:0001", job.cursor);
        try std.testing.expectEqual(@as(u64, 1), job.completed_units);
    }
    var reopened_status = try graph.graphMetricStatus("degree");
    defer reopened_status.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.building, reopened_status.state);
    try std.testing.expectEqual(@as(usize, 1), reopened_status.build_pages.len);
    try std.testing.expectEqual(@as(u64, 1), reopened_status.build_pages[0].page_id);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, reopened_status.build_pages[0].state);
    try std.testing.expectEqualStrings("worker-a", reopened_status.build_pages[0].worker_id);
    try std.testing.expectEqualStrings("edge-page:0001", reopened_status.build_pages[0].cursor);

    _ = try graph.failGraphMetricBuildPage("degree", active_job.job_id, .scan_edges_and_out_degree, 0, 1, "worker-a", "simulated page failure");
    var failed_status = try graph.graphMetricStatus("degree");
    defer failed_status.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.building, failed_status.state);
    try std.testing.expectEqual(@as(usize, 1), failed_status.build_pages.len);
    try std.testing.expectEqual(@as(u64, 1), failed_status.build_pages[0].page_id);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.failed, failed_status.build_pages[0].state);
    try std.testing.expectEqualStrings("worker-a", failed_status.build_pages[0].worker_id);
    try std.testing.expectEqual(@as(u64, 1), failed_status.build_pages[0].attempt);
    try std.testing.expectEqualStrings("edge-page:0001", failed_status.build_pages[0].cursor);
    try std.testing.expectEqual(@as(u64, 1), failed_status.build_pages[0].completed_units);
    try std.testing.expectEqual(claim.total_units, failed_status.build_pages[0].total_units);
    try std.testing.expectEqualStrings("simulated page failure", failed_status.build_pages[0].last_error);
}

test "graph metric build phase barrier persists summary and advances only when complete" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-metric-phase-barrier");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-metric-phase-barrier");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{.{
        .name = "degree",
        .kind = .degree,
        .refresh = .manual,
    }};
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    try graph.addEdge("doc-a", "doc-b", "cites", 1.0, 0, 0, "");
    try graph.acquireGraphMetricBuildLease("degree", graph.edge_generation);

    var job_txn = try graph.beginReadReverseTxn();
    const active_job = try graph.metricBuildJob(&job_txn, "degree") orelse return error.TestExpectedGraphMetricBuildJob;
    job_txn.abort();

    const pending = try graph.summarizeGraphMetricBuildPhase("degree", active_job.job_id, .prepare_generation, 0);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhaseState.pending, pending.state);
    try std.testing.expectEqual(@as(u64, 1), pending.expected_pages);
    try std.testing.expectEqual(@as(u64, 0), pending.completed_pages);
    try std.testing.expectEqual(@as(u64, 0), pending.failed_pages);
    try std.testing.expectEqual(@as(u64, 1), pending.total_units);
    try std.testing.expect(!(try graph.advanceGraphMetricBuildPhaseIfReady("degree", active_job.job_id, .prepare_generation, 0)));
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const job = try graph.metricBuildJob(&txn, "degree") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.prepare_generation, job.phase);
        const summary = try graph.metricBuildPhaseSummary(&txn, "degree", active_job.job_id, .prepare_generation, 0) orelse return error.TestExpectedGraphMetricBuildPhaseSummary;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhaseState.pending, summary.state);
    }

    _ = try graph.claimGraphMetricBuildPageAt("degree", active_job.job_id, .prepare_generation, 0, 0, "worker-a", 1000);
    _ = try graph.completeGraphMetricBuildPage("degree", active_job.job_id, .prepare_generation, 0, 0, "worker-a", 1, 100);
    try std.testing.expect(try graph.advanceGraphMetricBuildPhaseIfReady("degree", active_job.job_id, .prepare_generation, 0));
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const summary = try graph.metricBuildPhaseSummary(&txn, "degree", active_job.job_id, .prepare_generation, 0) orelse return error.TestExpectedGraphMetricBuildPhaseSummary;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhaseState.complete, summary.state);
        try std.testing.expectEqual(@as(u64, 1), summary.completed_pages);
        try std.testing.expectEqual(@as(u64, 1), summary.completed_units);
        try std.testing.expectEqual(@as(u64, 100), summary.output_fingerprint);
        const job = try graph.metricBuildJob(&txn, "degree") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.scan_edges_and_out_degree, job.phase);
        const lease = try graph.metricBuildLease(&txn, "degree") orelse return error.TestExpectedGraphMetricBuildLease;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.scan_edges_and_out_degree, lease.phase);
    }

    _ = try graph.claimGraphMetricBuildPageAt("degree", active_job.job_id, .scan_edges_and_out_degree, 0, 1, "worker-a", 2000);
    _ = try graph.failGraphMetricBuildPage("degree", active_job.job_id, .scan_edges_and_out_degree, 0, 1, "worker-a", "scan failed");
    const failed = try graph.summarizeGraphMetricBuildPhase("degree", active_job.job_id, .scan_edges_and_out_degree, 0);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhaseState.failed, failed.state);
    try std.testing.expectEqual(@as(u64, 1), failed.failed_pages);
    try std.testing.expect(!(try graph.advanceGraphMetricBuildPhaseIfReady("degree", active_job.job_id, .scan_edges_and_out_degree, 0)));
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const job = try graph.metricBuildJob(&txn, "degree") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.scan_edges_and_out_degree, job.phase);
    }
