    const pending = try graph.summarizeGraphMetricBuildPhase("degree", active_job.job_id, .scan_edges_and_out_degree, 0);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhaseState.pending, pending.state);
    try std.testing.expectEqual(@as(u64, 2), pending.expected_pages);
    try std.testing.expectEqual(@as(u64, 1), pending.completed_pages);
    try std.testing.expectEqual(@as(u64, 3), pending.total_units);
    try std.testing.expectEqual(@as(u64, 1), pending.completed_units);
    try std.testing.expectEqual(@as(u64, 20), pending.output_fingerprint);
    try std.testing.expect(!(try graph.advanceGraphMetricBuildPhaseIfReady("degree", active_job.job_id, .scan_edges_and_out_degree, 0)));

    _ = try graph.claimGraphMetricBuildPageAt("degree", active_job.job_id, .scan_edges_and_out_degree, 0, 99, "worker-b", 3000);
    _ = try graph.completeGraphMetricBuildPage("degree", active_job.job_id, .scan_edges_and_out_degree, 0, 99, "worker-b", 2, 30);
    try std.testing.expect(try graph.advanceGraphMetricBuildPhaseIfReady("degree", active_job.job_id, .scan_edges_and_out_degree, 0));
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const summary = try graph.metricBuildPhaseSummary(&txn, "degree", active_job.job_id, .scan_edges_and_out_degree, 0) orelse return error.TestExpectedGraphMetricBuildPhaseSummary;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhaseState.complete, summary.state);
        try std.testing.expectEqual(@as(u64, 2), summary.expected_pages);
        try std.testing.expectEqual(@as(u64, 2), summary.completed_pages);
        try std.testing.expectEqual(@as(u64, 3), summary.completed_units);
        try std.testing.expectEqual(@as(u64, 20 ^ 30), summary.output_fingerprint);
        const job = try graph.metricBuildJob(&txn, "degree") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.reduce_ranks, job.phase);
    }
}

test "graph metric build iteration summary records convergence from check phase" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-metric-iteration-summary");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-metric-iteration-summary");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{.{
        .name = "pagerank",
        .kind = .pagerank,
        .refresh = .manual,
        .max_iterations = 1,
        .tolerance = 0.00001,
    }};
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    try graph.addEdge("doc-a", "doc-b", "cites", 1.0, 0, 0, "");
    try graph.acquireGraphMetricBuildLease("pagerank", graph.edge_generation);

    var job_txn = try graph.beginReadReverseTxn();
    const active_job = try graph.metricBuildJob(&job_txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
    job_txn.abort();

    try std.testing.expectError(error.GraphMetricBuildIterationNotComplete, graph.recordGraphMetricBuildIterationSummaryFromCheckPhase("pagerank", active_job.job_id, 0));

    _ = try graph.claimGraphMetricBuildPageAt("pagerank", active_job.job_id, .check_convergence, 0, 5, "worker-a", 1000);
    const page = try graph.completeGraphMetricBuildConvergencePage("pagerank", active_job.job_id, 0, 5, "worker-a", 2, 77, 0.25, 0.30, 1.0, false);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.complete, page.state);
    try std.testing.expectApproxEqAbs(@as(f64, 0.25), page.max_delta, 0.0000001);
    try std.testing.expectApproxEqAbs(@as(f64, 0.30), page.total_delta, 0.0000001);
    try std.testing.expectApproxEqAbs(@as(f64, 1.0), page.rank_sum, 0.0000001);
    try std.testing.expect(!page.converged);

    const iteration_summary = try graph.recordGraphMetricBuildIterationSummaryFromCheckPhase("pagerank", active_job.job_id, 0);
    try std.testing.expectEqual(@as(u32, 0), iteration_summary.iteration);
    try std.testing.expectEqual(@as(u64, 1), iteration_summary.expected_pages);
    try std.testing.expectEqual(@as(u64, 1), iteration_summary.completed_pages);
    try std.testing.expectApproxEqAbs(@as(f64, 0.25), iteration_summary.max_delta, 0.0000001);
    try std.testing.expectApproxEqAbs(@as(f64, 0.30), iteration_summary.total_delta, 0.0000001);
    try std.testing.expectApproxEqAbs(@as(f64, 1.0), iteration_summary.rank_sum, 0.0000001);
    try std.testing.expect(!iteration_summary.converged);
    try std.testing.expect(iteration_summary.fixed_iteration_limit);
    try std.testing.expectEqual(@as(u64, 77), iteration_summary.output_fingerprint);

    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const phase_summary = try graph.metricBuildPhaseSummary(&txn, "pagerank", active_job.job_id, .check_convergence, 0) orelse return error.TestExpectedGraphMetricBuildPhaseSummary;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhaseState.complete, phase_summary.state);
        try std.testing.expectApproxEqAbs(@as(f64, 0.25), phase_summary.max_delta, 0.0000001);
        try std.testing.expectApproxEqAbs(@as(f64, 0.30), phase_summary.total_delta, 0.0000001);
        try std.testing.expectApproxEqAbs(@as(f64, 1.0), phase_summary.rank_sum, 0.0000001);
        try std.testing.expect(!phase_summary.converged);
        const stored_iteration = try graph.metricBuildIterationSummary(&txn, "pagerank", active_job.job_id, 0) orelse return error.TestExpectedGraphMetricBuildIterationSummary;
        try std.testing.expectEqual(@as(u64, 77), stored_iteration.output_fingerprint);
        try std.testing.expect(stored_iteration.fixed_iteration_limit);
    }
}

