    job_txn.abort();

    try std.testing.expectError(error.GraphMetricBuildPublishNotReady, graph.verifyGraphMetricBuildPublishReady("degree", active_job.job_id));

    _ = try graph.claimGraphMetricBuildPageAt("degree", active_job.job_id, .prepare_generation, 0, 0, "worker-a", 1000);
    _ = try graph.completeGraphMetricBuildPage("degree", active_job.job_id, .prepare_generation, 0, 0, "worker-a", 1, 100);
    try std.testing.expect(try graph.advanceGraphMetricBuildPhaseIfReady("degree", active_job.job_id, .prepare_generation, 0));
    try std.testing.expectError(error.GraphMetricBuildPublishNotReady, graph.verifyGraphMetricBuildPublishReady("degree", active_job.job_id));

    _ = try graph.claimGraphMetricBuildPageAt("degree", active_job.job_id, .scan_edges_and_out_degree, 0, 1, "worker-a", 2000);
    _ = try graph.completeGraphMetricBuildPage("degree", active_job.job_id, .scan_edges_and_out_degree, 0, 1, "worker-a", 1, 200);
    try std.testing.expect(try graph.advanceGraphMetricBuildPhaseIfReady("degree", active_job.job_id, .scan_edges_and_out_degree, 0));
    try std.testing.expectError(error.GraphMetricBuildPublishNotReady, graph.verifyGraphMetricBuildPublishReady("degree", active_job.job_id));

    _ = try graph.claimGraphMetricBuildPageAt("degree", active_job.job_id, .reduce_ranks, 0, 2, "worker-a", 3000);
    _ = try graph.completeGraphMetricBuildPage("degree", active_job.job_id, .reduce_ranks, 0, 2, "worker-a", 1, 300);
    try std.testing.expect(try graph.advanceGraphMetricBuildPhaseIfReady("degree", active_job.job_id, .reduce_ranks, 0));

    const verification = try graph.verifyGraphMetricBuildPublishReady("degree", active_job.job_id);
    try std.testing.expectEqual(active_job.job_id, verification.job_id);
    try std.testing.expectEqual(graph.edge_generation, verification.target_generation);
    try std.testing.expectEqual(graph.edge_generation, verification.score_generation);
    try std.testing.expectEqual(GraphIndex.graphMetricConfigFingerprint(metrics[0]), verification.config_fingerprint);
    try std.testing.expectEqual(@as(u64, 3), verification.expected_phases);
    try std.testing.expectEqual(@as(u64, 3), verification.completed_phases);
    try std.testing.expectEqual(@as(u64, 3), verification.expected_pages);
    try std.testing.expectEqual(@as(u64, 3), verification.completed_pages);
    try std.testing.expectEqual(@as(u64, 100 ^ 200 ^ 300), verification.output_fingerprint);
    try std.testing.expect(!verification.converged);
    try std.testing.expect(!verification.fixed_iteration_limit);

    {
        var batch = try graph.beginWriteReverseBatch();
        errdefer batch.abort();
        var manifest = try graph.metricBuildManifest(&batch, "degree", active_job.job_id) orelse return error.TestExpectedGraphMetricBuildManifest;
        manifest.config_fingerprint += 1;
        try graph.putGraphMetricBuildManifestInBatch(&batch, "degree", manifest);
        try batch.commit();
    }
    try std.testing.expectError(error.InvalidGraphMetricBuildManifest, graph.verifyGraphMetricBuildPublishReady("degree", active_job.job_id));
}

