            .kind = .degree,
            .refresh = .manual,
        },
    };
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    for (0..graph_metric_build_target_scan_page_units + 1) |i| {
        var source_buf: [64]u8 = undefined;
        const source = try std.fmt.bufPrint(&source_buf, "doc-{d:0>3}", .{i});
        try graph.addEdge(source, "hub", "cites", 1.0, 0, 0, "");
    }

    var local_status = try graph.runGraphMetric("degree_local");
    defer local_status.deinit(alloc);
    var planned_status = try graph.runDegreeMetricPlanned("degree_planned");
    defer planned_status.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.fresh, planned_status.state);
    try std.testing.expectEqual(graph.edge_generation, planned_status.published_generation);

    const local_top = try graph.graphMetricTopK("degree_local", 10);
    defer {
        for (local_top) |*score| score.deinit(alloc);
        alloc.free(local_top);
    }
    const planned_top = try graph.graphMetricTopK("degree_planned", 10);
    defer {
        for (planned_top) |*score| score.deinit(alloc);
        alloc.free(planned_top);
    }
    try std.testing.expectEqual(local_top.len, planned_top.len);
    try std.testing.expectEqualStrings("hub", planned_top[0].node);
    try std.testing.expectApproxEqAbs(@as(f64, @floatFromInt(graph_metric_build_target_scan_page_units + 1)), planned_top[0].score, 0.0000001);
    for (local_top, planned_top) |local, planned| {
        try std.testing.expectEqualStrings(local.node, planned.node);
        try std.testing.expectApproxEqAbs(local.score, planned.score, 0.0000001);
    }
}

test "graph degree planned worker step drives scheduled phases" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-degree-worker-step");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-degree-worker-step");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{.{
        .name = "degree",
        .kind = .degree,
        .refresh = .manual,
    }};
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    try graph.addEdge("doc-a", "doc-b", "cites", 1.0, 0, 0, "");
    try graph.acquireGraphMetricBuildLease("degree", graph.edge_generation);
    defer graph.releaseGraphMetricBuildLease("degree") catch {};

    const prepare = try graph.runDegreeMetricPlannedWorkerStep("degree", metrics[0], "worker-a");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.prepare_generation, prepare.phase);
    try std.testing.expect(prepare.claimed_page);
    try std.testing.expect(prepare.completed_page);
    try std.testing.expect(prepare.advanced_phase);
    try std.testing.expect(!prepare.published);
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const job = try graph.metricBuildJob(&txn, "degree") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.scan_edges_and_out_degree, job.phase);
    }

    const scan = try graph.runDegreeMetricPlannedWorkerStep("degree", metrics[0], "worker-a");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.scan_edges_and_out_degree, scan.phase);
    try std.testing.expect(scan.claimed_page);
    try std.testing.expect(scan.completed_page);
    try std.testing.expect(scan.advanced_phase);
    try std.testing.expect(!scan.published);
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const job = try graph.metricBuildJob(&txn, "degree") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.reduce_ranks, job.phase);
    }

    const reduce = try graph.runDegreeMetricPlannedWorkerStep("degree", metrics[0], "worker-a");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.reduce_ranks, reduce.phase);
    try std.testing.expect(reduce.claimed_page);
    try std.testing.expect(reduce.completed_page);
    try std.testing.expect(reduce.advanced_phase);
    try std.testing.expect(!reduce.published);
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const job = try graph.metricBuildJob(&txn, "degree") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.publish_generation, job.phase);
    }

    const publish = try graph.runDegreeMetricPlannedWorkerStep("degree", metrics[0], "worker-a");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.publish_generation, publish.phase);
    try std.testing.expect(!publish.published);
    try std.testing.expect(publish.advanced_phase);
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const job = try graph.metricBuildJob(&txn, "degree") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.cleanup_old_generations, job.phase);
        _ = try graph.metricBuildManifest(&txn, "degree", job.job_id) orelse return error.TestExpectedGraphMetricBuildManifest;
    }
    const published_before_cleanup = try graph.graphMetricTopK("degree", 10);
    defer {
        for (published_before_cleanup) |*score| score.deinit(alloc);
        alloc.free(published_before_cleanup);
    }
    try std.testing.expectEqual(@as(usize, 2), published_before_cleanup.len);

    const partial_cleanup = try graph.runDegreeMetricPlannedWorkerStep("degree", metrics[0], "worker-a");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.cleanup_old_generations, partial_cleanup.phase);
    try std.testing.expect(partial_cleanup.claimed_page);
    try std.testing.expect(partial_cleanup.completed_page);
    try std.testing.expect(!partial_cleanup.published);
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const job = try graph.metricBuildJob(&txn, "degree") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.cleanup_old_generations, job.phase);
        const cleanup_page = try graph.metricBuildPage(&txn, "degree", job.job_id, .cleanup_old_generations, 0, partial_cleanup.page_id) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.complete, cleanup_page.state);
        _ = try graph.metricBuildManifest(&txn, "degree", job.job_id) orelse return error.TestExpectedGraphMetricBuildManifest;
    }

    const cleanup = try graph.runDegreeMetricPlannedWorkerStep("degree", metrics[0], "worker-a");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.cleanup_old_generations, cleanup.phase);
    try std.testing.expect(cleanup.claimed_page);
    try std.testing.expect(cleanup.completed_page);
    try std.testing.expect(cleanup.published);
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const job = try graph.metricBuildJob(&txn, "degree") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.complete, job.phase);
        try std.testing.expect((try graph.metricBuildManifest(&txn, "degree", job.job_id)) == null);
    }

    var fresh = try graph.graphMetricStatus("degree");
    defer fresh.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.fresh, fresh.state);
    try std.testing.expectEqual(graph.edge_generation, fresh.published_generation);
}

