    const scan_not_ready = try graph.runGraphMetricPlannedCoordinatorStepForMetric("degree");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.scan_edges_and_out_degree, scan_not_ready.phase);
    try std.testing.expect(!scan_not_ready.advanced_phase);
    try std.testing.expect(!scan_not_ready.published);

    const scan_b = try graph.runGraphMetricPlannedWorkerPageStepForMetric("degree", "worker-scan-b");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.scan_edges_and_out_degree, scan_b.phase);
    try std.testing.expect(scan_b.claimed_page);
    try std.testing.expect(scan_b.completed_page);
    try std.testing.expect(scan_b.page_id != scan_a.page_id);
    try std.testing.expect(!scan_b.advanced_phase);

    const scan_ready = try graph.runGraphMetricPlannedCoordinatorStepForMetric("degree");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.scan_edges_and_out_degree, scan_ready.phase);
    try std.testing.expect(scan_ready.advanced_phase);

    const reduce_a = try graph.runGraphMetricPlannedWorkerPageStepForMetric("degree", "worker-reduce-a");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.reduce_ranks, reduce_a.phase);
    try std.testing.expect(reduce_a.claimed_page);
    try std.testing.expect(reduce_a.completed_page);
    try std.testing.expect(!reduce_a.advanced_phase);

    const reduce_not_ready = try graph.runGraphMetricPlannedCoordinatorStepForMetric("degree");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.reduce_ranks, reduce_not_ready.phase);
    try std.testing.expect(!reduce_not_ready.advanced_phase);
    try std.testing.expect(!reduce_not_ready.published);

    const reduce_b = try graph.runGraphMetricPlannedWorkerPageStepForMetric("degree", "worker-reduce-b");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.reduce_ranks, reduce_b.phase);
    try std.testing.expect(reduce_b.claimed_page);
    try std.testing.expect(reduce_b.completed_page);
    try std.testing.expect(reduce_b.page_id != reduce_a.page_id);
    try std.testing.expect(!reduce_b.advanced_phase);

    const reduce_ready = try graph.runGraphMetricPlannedCoordinatorStepForMetric("degree");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.reduce_ranks, reduce_ready.phase);
    try std.testing.expect(reduce_ready.advanced_phase);

    const worker_publish = try graph.runGraphMetricPlannedWorkerPageStepForMetric("degree", "worker-publish");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.publish_generation, worker_publish.phase);
    try std.testing.expect(!worker_publish.claimed_page);
    try std.testing.expect(!worker_publish.advanced_phase);
    try std.testing.expect(!worker_publish.published);

    const coordinator_publish = try graph.runGraphMetricPlannedCoordinatorStepForMetric("degree");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.publish_generation, coordinator_publish.phase);
    try std.testing.expect(coordinator_publish.advanced_phase);

    var published_during_cleanup = try graph.graphMetricStatus("degree");
    defer published_during_cleanup.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.building, published_during_cleanup.state);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.cleanup_old_generations, published_during_cleanup.phase);
    try std.testing.expectEqual(target_generation, published_during_cleanup.published_generation);

    var cleanup_finished = false;
    for (0..8) |_| {
        const cleanup = try graph.runGraphMetricPlannedWorkerPageStepForMetric("degree", "worker-clean");
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.cleanup_old_generations, cleanup.phase);
        try std.testing.expect(cleanup.claimed_page);
        try std.testing.expect(!cleanup.advanced_phase);
        if (cleanup.published) {
            cleanup_finished = true;
            break;
        }
    }
    try std.testing.expect(cleanup_finished);

    var fresh = try graph.graphMetricStatus("degree");
    defer fresh.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.fresh, fresh.state);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.complete, fresh.phase);
    try std.testing.expectEqual(target_generation, fresh.published_generation);

    const top = try graph.graphMetricTopK("degree", 2);
    defer {
        for (top) |*score| score.deinit(alloc);
        alloc.free(top);
    }
    try std.testing.expectEqual(@as(usize, 2), top.len);
    try std.testing.expectEqualStrings("hub", top[0].node);
    try std.testing.expectApproxEqAbs(@as(f64, @floatFromInt(graph_metric_build_target_scan_page_units + 1)), top[0].score, 0.0000001);
}

const GraphDegreePublicWorkerThreadCtx = struct {
    store_path: [*:0]const u8,
    rev_path: [*:0]const u8,
    worker_id: []const u8,
    err: ?anyerror = null,
    phase: GraphIndex.GraphMetricBuildPhase = .idle,
    page_id: u64 = 0,
    claimed_page: bool = false,
    completed_page: bool = false,
    advanced_phase: bool = false,
    published: bool = false,
};

fn runGraphDegreePublicWorkerThread(ctx: *GraphDegreePublicWorkerThreadCtx) void {
    const alloc = std.heap.page_allocator;
    const metrics = [_]GraphMetricConfig{.{
        .name = "degree",
        .kind = .degree,
        .refresh = .manual,
    }};
    var store = docstore.DocStore.open(alloc, ctx.store_path, .{}) catch |err| {
        ctx.err = err;
        return;
    };
    defer store.close();
    var graph = GraphIndex.open(alloc, &store, ctx.rev_path, "links", .{ .metric_configs = &metrics }) catch |err| {
        ctx.err = err;
        return;
    };
    defer graph.close();

    const step = graph.runGraphMetricPlannedWorkerPageStepForMetric("degree", ctx.worker_id) catch |err| {
        ctx.err = err;
        return;
    };
    ctx.phase = step.phase;
    ctx.page_id = step.page_id;
    ctx.claimed_page = step.claimed_page;
    ctx.completed_page = step.completed_page;
    ctx.advanced_phase = step.advanced_phase;
    ctx.published = step.published;
}

fn recordGraphDegreePublicWorkerThreadResult(
    pages: *[8]u64,
    page_count: *usize,
    ctx: GraphDegreePublicWorkerThreadCtx,
    expected_phase: GraphIndex.GraphMetricBuildPhase,
) !void {
    if (ctx.err) |err| return err;
    try std.testing.expectEqual(expected_phase, ctx.phase);
    try std.testing.expect(!ctx.advanced_phase);
    if (!ctx.completed_page) return;
    try std.testing.expect(ctx.claimed_page);
    for (pages[0..page_count.*]) |page_id| {
        if (page_id == ctx.page_id) return;
    }
    pages[page_count.*] = ctx.page_id;
    page_count.* += 1;
}

const GraphDegreeClaimWorkerThreadCtx = struct {
    store_path: [*:0]const u8,
    rev_path: [*:0]const u8,
    job_id: u64,
    worker_id: []const u8,
    now_ms: u64,
    requested_page_id: u64,
    err: ?anyerror = null,
    page_id: u64 = 0,
    attempt: u64 = 0,
    lease_expires_at_ms: u64 = 0,
};

fn runGraphDegreeClaimWorkerThread(ctx: *GraphDegreeClaimWorkerThreadCtx) void {
    const alloc = std.heap.page_allocator;
    var store = docstore.DocStore.open(alloc, ctx.store_path, .{}) catch |err| {
        ctx.err = err;
        return;
    };
    defer store.close();
    const metrics = [_]GraphMetricConfig{.{
        .name = "degree",
        .kind = .degree,
        .refresh = .manual,
    }};
    var graph = GraphIndex.open(alloc, &store, ctx.rev_path, "links", .{ .metric_configs = &metrics }) catch |err| {
        ctx.err = err;
        return;
    };
    defer graph.close();

    const page = graph.claimGraphMetricBuildPageAt("degree", ctx.job_id, .scan_edges_and_out_degree, 0, ctx.requested_page_id, ctx.worker_id, ctx.now_ms) catch |err| {
        ctx.err = err;
        return;
    } orelse {
        ctx.err = error.TestExpectedGraphMetricBuildPage;
        return;
    };
    ctx.page_id = page.page_id;
    ctx.attempt = page.attempt;
    ctx.lease_expires_at_ms = page.lease_expires_at_ms;
}

const GraphMetricPublicWorkerThreadCtx = struct {
    store_path: [*:0]const u8,
    rev_path: [*:0]const u8,
    metric_name: []const u8,
    kind: GraphMetricKind,
    worker_id: []const u8,
    err: ?anyerror = null,
    phase: GraphIndex.GraphMetricBuildPhase = .idle,
    page_id: u64 = 0,
    claimed_page: bool = false,
    completed_page: bool = false,
    advanced_phase: bool = false,
    published: bool = false,
};

fn runGraphMetricPublicWorkerThread(ctx: *GraphMetricPublicWorkerThreadCtx) void {
    const alloc = std.heap.page_allocator;
    var store = docstore.DocStore.open(alloc, ctx.store_path, .{}) catch |err| {
        ctx.err = err;
        return;
    };
    defer store.close();
    if (ctx.kind == .hits_authority or ctx.kind == .hits_hub) {
        const pair_name = if (ctx.kind == .hits_authority) "hits_hub" else "hits_authority";
        const pair_kind: GraphMetricKind = if (ctx.kind == .hits_authority) .hits_hub else .hits_authority;
        const metrics = [_]GraphMetricConfig{
            .{
                .name = ctx.metric_name,
                .kind = ctx.kind,
                .refresh = .manual,
                .max_iterations = 1,
                .tolerance = 0.000001,
            },
            .{
                .name = pair_name,
                .kind = pair_kind,
                .refresh = .manual,
                .max_iterations = 1,
                .tolerance = 0.000001,
            },
        };
        var graph = GraphIndex.open(alloc, &store, ctx.rev_path, "links", .{ .metric_configs = &metrics }) catch |err| {
            ctx.err = err;
            return;
        };
        defer graph.close();

        const step = graph.runGraphMetricPlannedWorkerPageStepForMetric(ctx.metric_name, ctx.worker_id) catch |err| {
            ctx.err = err;
            return;
        };
        ctx.phase = step.phase;
        ctx.page_id = step.page_id;
        ctx.claimed_page = step.claimed_page;
        ctx.completed_page = step.completed_page;
        ctx.advanced_phase = step.advanced_phase;
        ctx.published = step.published;
    } else {
        const metrics = [_]GraphMetricConfig{.{
            .name = ctx.metric_name,
            .kind = ctx.kind,
            .refresh = .manual,
            .max_iterations = 1,
            .tolerance = 0.000001,
        }};
        var graph = GraphIndex.open(alloc, &store, ctx.rev_path, "links", .{ .metric_configs = &metrics }) catch |err| {
            ctx.err = err;
            return;
        };
        defer graph.close();

        const step = graph.runGraphMetricPlannedWorkerPageStepForMetric(ctx.metric_name, ctx.worker_id) catch |err| {
            ctx.err = err;
            return;
        };
        ctx.phase = step.phase;
        ctx.page_id = step.page_id;
        ctx.claimed_page = step.claimed_page;
        ctx.completed_page = step.completed_page;
        ctx.advanced_phase = step.advanced_phase;
        ctx.published = step.published;
    }
}

fn recordGraphMetricPublicWorkerThreadResult(
    pages: *[8]u64,
    page_count: *usize,
    ctx: GraphMetricPublicWorkerThreadCtx,
    expected_phase: GraphIndex.GraphMetricBuildPhase,
) !void {
    if (ctx.err) |err| return err;
    try std.testing.expectEqual(expected_phase, ctx.phase);
    try std.testing.expect(!ctx.advanced_phase);
    try std.testing.expect(!ctx.published);
    if (!ctx.completed_page) return;
    try std.testing.expect(ctx.claimed_page);
    for (pages[0..page_count.*]) |page_id| {
        if (page_id == ctx.page_id) return;
    }
    pages[page_count.*] = ctx.page_id;
    page_count.* += 1;
}

fn expectGraphMetricConcurrentPublicPhase(
    alloc: Allocator,
    store_path: [*:0]const u8,
    rev_path: [*:0]const u8,
    metric_name: []const u8,
    kind: GraphMetricKind,
    expected_phase: GraphIndex.GraphMetricBuildPhase,
    expected_pages: usize,
) !void {
    var pages: [8]u64 = undefined;
    var page_count: usize = 0;
    for (0..12) |round| {
        if (page_count >= expected_pages) break;
        const worker_a = try std.fmt.allocPrint(alloc, "worker-{s}-a-{d}", .{ @tagName(expected_phase), round });
        defer alloc.free(worker_a);
        const worker_b = try std.fmt.allocPrint(alloc, "worker-{s}-b-{d}", .{ @tagName(expected_phase), round });
        defer alloc.free(worker_b);
        var worker_ctx_a = GraphMetricPublicWorkerThreadCtx{ .store_path = store_path, .rev_path = rev_path, .metric_name = metric_name, .kind = kind, .worker_id = worker_a };
        var worker_ctx_b = GraphMetricPublicWorkerThreadCtx{ .store_path = store_path, .rev_path = rev_path, .metric_name = metric_name, .kind = kind, .worker_id = worker_b };
        var thread_a = try std.Thread.spawn(.{}, runGraphMetricPublicWorkerThread, .{&worker_ctx_a});
        var thread_b = try std.Thread.spawn(.{}, runGraphMetricPublicWorkerThread, .{&worker_ctx_b});
        thread_a.join();
        thread_b.join();
        try recordGraphMetricPublicWorkerThreadResult(&pages, &page_count, worker_ctx_a, expected_phase);
        try recordGraphMetricPublicWorkerThreadResult(&pages, &page_count, worker_ctx_b, expected_phase);
    }
    try std.testing.expectEqual(expected_pages, page_count);
}

test "graph degree planned public workers claim phase pages from concurrent handles" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-degree-concurrent-public-workers");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-degree-concurrent-public-workers");
    defer cleanupTmp(rev_path);

    const metrics = [_]GraphMetricConfig{.{
        .name = "degree",
        .kind = .degree,
        .refresh = .manual,
    }};
    var target_generation: u64 = 0;
    {
        var store = try docstore.DocStore.open(alloc, store_path, .{});
        defer store.close();
        var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
        defer graph.close();

        for (0..graph_metric_build_target_scan_page_units + 1) |i| {
            var source_buf: [64]u8 = undefined;
            const source = try std.fmt.bufPrint(&source_buf, "doc-{d:0>3}", .{i});
            try graph.addEdge(source, "hub", "cites", 1.0, 0, 0, "");
        }
        target_generation = graph.edge_generation;

        var started = try graph.ensureGraphMetricPlannedBuild("degree", target_generation);
        defer started.deinit(alloc);
        try std.testing.expectEqual(GraphIndex.GraphMetricState.building, started.state);

        const prepare = try graph.runGraphMetricPlannedWorkerPageStepForMetric("degree", "worker-prepare");
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.prepare_generation, prepare.phase);
        try std.testing.expect(prepare.claimed_page);
        try std.testing.expect(prepare.completed_page);
        try std.testing.expect(!prepare.advanced_phase);

        const advance_prepare = try graph.runGraphMetricPlannedCoordinatorStepForMetric("degree");
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.prepare_generation, advance_prepare.phase);
        try std.testing.expect(advance_prepare.advanced_phase);
    }

    var scan_pages: [8]u64 = undefined;
    var scan_page_count: usize = 0;
    for (0..8) |round| {
        if (scan_page_count >= 2) break;
        const worker_a = try std.fmt.allocPrint(alloc, "worker-scan-a-{d}", .{round});
        defer alloc.free(worker_a);
        const worker_b = try std.fmt.allocPrint(alloc, "worker-scan-b-{d}", .{round});
        defer alloc.free(worker_b);
        var scan_a = GraphDegreePublicWorkerThreadCtx{ .store_path = store_path, .rev_path = rev_path, .worker_id = worker_a };
        var scan_b = GraphDegreePublicWorkerThreadCtx{ .store_path = store_path, .rev_path = rev_path, .worker_id = worker_b };
        var scan_thread_a = try std.Thread.spawn(.{}, runGraphDegreePublicWorkerThread, .{&scan_a});
        var scan_thread_b = try std.Thread.spawn(.{}, runGraphDegreePublicWorkerThread, .{&scan_b});
        scan_thread_a.join();
        scan_thread_b.join();
        try recordGraphDegreePublicWorkerThreadResult(&scan_pages, &scan_page_count, scan_a, .scan_edges_and_out_degree);
        try recordGraphDegreePublicWorkerThreadResult(&scan_pages, &scan_page_count, scan_b, .scan_edges_and_out_degree);
    }
    try std.testing.expectEqual(@as(usize, 2), scan_page_count);

    {
        var store = try docstore.DocStore.open(alloc, store_path, .{});
        defer store.close();
        var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
        defer graph.close();
        const scan_ready = try graph.runGraphMetricPlannedCoordinatorStepForMetric("degree");
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.scan_edges_and_out_degree, scan_ready.phase);
        try std.testing.expect(scan_ready.advanced_phase);
    }

    var reduce_pages: [8]u64 = undefined;
    var reduce_page_count: usize = 0;
    for (0..8) |round| {
        if (reduce_page_count >= 2) break;
        const worker_a = try std.fmt.allocPrint(alloc, "worker-reduce-a-{d}", .{round});
        defer alloc.free(worker_a);
        const worker_b = try std.fmt.allocPrint(alloc, "worker-reduce-b-{d}", .{round});
        defer alloc.free(worker_b);
        var reduce_a = GraphDegreePublicWorkerThreadCtx{ .store_path = store_path, .rev_path = rev_path, .worker_id = worker_a };
        var reduce_b = GraphDegreePublicWorkerThreadCtx{ .store_path = store_path, .rev_path = rev_path, .worker_id = worker_b };
        var reduce_thread_a = try std.Thread.spawn(.{}, runGraphDegreePublicWorkerThread, .{&reduce_a});
        var reduce_thread_b = try std.Thread.spawn(.{}, runGraphDegreePublicWorkerThread, .{&reduce_b});
        reduce_thread_a.join();
        reduce_thread_b.join();
        try recordGraphDegreePublicWorkerThreadResult(&reduce_pages, &reduce_page_count, reduce_a, .reduce_ranks);
        try recordGraphDegreePublicWorkerThreadResult(&reduce_pages, &reduce_page_count, reduce_b, .reduce_ranks);
    }
    try std.testing.expectEqual(@as(usize, 2), reduce_page_count);

    {
        var store = try docstore.DocStore.open(alloc, store_path, .{});
        defer store.close();
        var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
        defer graph.close();

        const reduce_ready = try graph.runGraphMetricPlannedCoordinatorStepForMetric("degree");
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.reduce_ranks, reduce_ready.phase);
        try std.testing.expect(reduce_ready.advanced_phase);

        const worker_publish = try graph.runGraphMetricPlannedWorkerPageStepForMetric("degree", "worker-publish");
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.publish_generation, worker_publish.phase);
        try std.testing.expect(!worker_publish.claimed_page);
        try std.testing.expect(!worker_publish.advanced_phase);
        try std.testing.expect(!worker_publish.published);

        const coordinator_publish = try graph.runGraphMetricPlannedCoordinatorStepForMetric("degree");
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.publish_generation, coordinator_publish.phase);
        try std.testing.expect(coordinator_publish.advanced_phase);

        var cleanup_finished = false;
        for (0..8) |_| {
            const cleanup = try graph.runGraphMetricPlannedWorkerPageStepForMetric("degree", "worker-clean");
            try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.cleanup_old_generations, cleanup.phase);
            try std.testing.expect(!cleanup.advanced_phase);
            if (cleanup.published) {
                cleanup_finished = true;
                break;
            }
        }
        try std.testing.expect(cleanup_finished);

        var fresh = try graph.graphMetricStatus("degree");
        defer fresh.deinit(alloc);
        try std.testing.expectEqual(GraphIndex.GraphMetricState.fresh, fresh.state);
        try std.testing.expectEqual(target_generation, fresh.published_generation);
        try std.testing.expectEqual(@as(usize, 0), fresh.build_pages.len);
    }
}

test "graph degree planned status reports concurrent worker page leases from reopened handles" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-degree-concurrent-status-workers");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-degree-concurrent-status-workers");
    defer cleanupTmp(rev_path);

    const metrics = [_]GraphMetricConfig{.{
        .name = "degree",
        .kind = .degree,
        .refresh = .manual,
    }};
    var job_id: u64 = 0;
    {
        var store = try docstore.DocStore.open(alloc, store_path, .{});
        defer store.close();
        var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
        defer graph.close();

        for (0..graph_metric_build_target_scan_page_units + 1) |i| {
            var source_buf: [64]u8 = undefined;
            const source = try std.fmt.bufPrint(&source_buf, "doc-{d:0>3}", .{i});
            try graph.addEdge(source, "hub", "cites", 1.0, 0, 0, "");
        }
        var started = try graph.ensureGraphMetricPlannedBuild("degree", graph.edge_generation);
        defer started.deinit(alloc);
        try std.testing.expectEqual(GraphIndex.GraphMetricState.building, started.state);
        job_id = started.build_job_id;

        const prepare = try graph.runGraphMetricPlannedWorkerPageStepForMetric("degree", "worker-prepare");
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.prepare_generation, prepare.phase);
        try std.testing.expect(prepare.claimed_page);
        try std.testing.expect(prepare.completed_page);
        try std.testing.expect(!prepare.advanced_phase);

        const advance_prepare = try graph.runGraphMetricPlannedCoordinatorStepForMetric("degree");
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.prepare_generation, advance_prepare.phase);
        try std.testing.expect(advance_prepare.advanced_phase);
    }

    var worker_a = GraphDegreeClaimWorkerThreadCtx{
        .store_path = store_path,
        .rev_path = rev_path,
        .job_id = job_id,
        .worker_id = "worker-status-a",
        .now_ms = 10_000,
        .requested_page_id = 1,
    };
    var worker_b = GraphDegreeClaimWorkerThreadCtx{
        .store_path = store_path,
        .rev_path = rev_path,
        .job_id = job_id,
        .worker_id = "worker-status-b",
        .now_ms = 10_001,
        .requested_page_id = 2,
    };
    runGraphDegreeClaimWorkerThread(&worker_a);
    if (worker_a.err) |err| return err;
    runGraphDegreeClaimWorkerThread(&worker_b);
    if (worker_b.err) |err| return err;
    try std.testing.expect(worker_a.page_id != worker_b.page_id);
    try std.testing.expectEqual(@as(u64, 1), worker_a.attempt);
    try std.testing.expectEqual(@as(u64, 1), worker_b.attempt);
    try std.testing.expect(worker_a.lease_expires_at_ms > worker_a.now_ms);
    try std.testing.expect(worker_b.lease_expires_at_ms > worker_b.now_ms);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    var status = try graph.graphMetricStatus("degree");
    defer status.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.building, status.state);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.scan_edges_and_out_degree, status.phase);
    try std.testing.expectEqual(job_id, status.build_job_id);
    try std.testing.expect(!status.build_pages_truncated);
    try std.testing.expectEqual(@as(usize, 2), status.build_pages.len);

    var saw_worker_a = false;
    var saw_worker_b = false;
    for (status.build_pages) |page| {
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.scan_edges_and_out_degree, page.phase);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, page.state);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageRangeKind.reverse_edges, page.range_kind);
        try std.testing.expectEqual(@as(u32, 0), page.iteration);
        try std.testing.expectEqual(@as(u64, 1), page.attempt);
        try std.testing.expect(page.lease_expires_at_ms > 0);
        try std.testing.expectEqualStrings("", page.last_error);
        if (std.mem.eql(u8, page.worker_id, "worker-status-a")) {
            saw_worker_a = true;
            try std.testing.expectEqual(worker_a.page_id, page.page_id);
            try std.testing.expectEqual(worker_a.lease_expires_at_ms, page.lease_expires_at_ms);
        } else if (std.mem.eql(u8, page.worker_id, "worker-status-b")) {
            saw_worker_b = true;
            try std.testing.expectEqual(worker_b.page_id, page.page_id);
            try std.testing.expectEqual(worker_b.lease_expires_at_ms, page.lease_expires_at_ms);
        } else {
            return error.TestUnexpectedGraphMetricBuildWorker;
        }
    }
    try std.testing.expect(saw_worker_a);
    try std.testing.expect(saw_worker_b);

    const blocked = try graph.runGraphMetricPlannedCoordinatorStepForMetric("degree");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.scan_edges_and_out_degree, blocked.phase);
    try std.testing.expect(!blocked.advanced_phase);
    try std.testing.expect(!blocked.published);
}

test "graph pagerank planned public workers claim partitioned phases from concurrent handles" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-pagerank-concurrent-public-workers");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-pagerank-concurrent-public-workers");
    defer cleanupTmp(rev_path);

    const metrics = [_]GraphMetricConfig{.{
        .name = "pagerank",
        .kind = .pagerank,
        .refresh = .manual,
        .max_iterations = 1,
        .tolerance = 0.000001,
    }};
    var target_generation: u64 = 0;
    {
        var store = try docstore.DocStore.open(alloc, store_path, .{});
        defer store.close();
        var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
        defer graph.close();

        for (0..graph_metric_build_target_scan_page_units + 1) |i| {
            var source_buf: [64]u8 = undefined;
            const source = try std.fmt.bufPrint(&source_buf, "doc-{d:0>3}", .{i});
            try graph.addEdge(source, "hub", "cites", 1.0, 0, 0, "");
        }
        target_generation = graph.edge_generation;

        var started = try graph.ensureGraphMetricPlannedBuild("pagerank", target_generation);
        defer started.deinit(alloc);
        try std.testing.expectEqual(GraphIndex.GraphMetricState.building, started.state);

        {
            var txn = try graph.beginReadReverseTxn();
            defer txn.abort();
            const job = try graph.metricBuildJob(&txn, "pagerank") orelse return error.TestExpectedGraphMetricBuildJob;
            _ = try graph.metricBuildPage(&txn, "pagerank", job.job_id, .scan_edges_and_out_degree, 0, 1) orelse return error.TestExpectedGraphMetricBuildPage;
            _ = try graph.metricBuildPage(&txn, "pagerank", job.job_id, .scan_edges_and_out_degree, 0, 2) orelse return error.TestExpectedGraphMetricBuildPage;
            _ = try graph.metricBuildPage(&txn, "pagerank", job.job_id, .initialize_ranks, 0, 2) orelse return error.TestExpectedGraphMetricBuildPage;
            _ = try graph.metricBuildPage(&txn, "pagerank", job.job_id, .initialize_ranks, 0, 3) orelse return error.TestExpectedGraphMetricBuildPage;
        }

        const prepare = try graph.runGraphMetricPlannedWorkerPageStepForMetric("pagerank", "worker-prepare");
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.prepare_generation, prepare.phase);
        try std.testing.expect(prepare.claimed_page);
        try std.testing.expect(prepare.completed_page);
        try std.testing.expect(!prepare.advanced_phase);

        const advance_prepare = try graph.runGraphMetricPlannedCoordinatorStepForMetric("pagerank");
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.prepare_generation, advance_prepare.phase);
        try std.testing.expect(advance_prepare.advanced_phase);
    }

    const partitioned_phases = [_]GraphIndex.GraphMetricBuildPhase{
        .scan_edges_and_out_degree,
        .initialize_ranks,
        .iterate_contributions,
        .reduce_ranks,
        .check_convergence,
    };
    for (partitioned_phases) |phase| {
        try expectGraphMetricConcurrentPublicPhase(alloc, store_path, rev_path, "pagerank", .pagerank, phase, 2);
        var store = try docstore.DocStore.open(alloc, store_path, .{});
        defer store.close();
        var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
        defer graph.close();
        const phase_ready = try graph.runGraphMetricPlannedCoordinatorStepForMetric("pagerank");
        try std.testing.expectEqual(phase, phase_ready.phase);
        try std.testing.expect(phase_ready.advanced_phase);
    }

    {
        var store = try docstore.DocStore.open(alloc, store_path, .{});
        defer store.close();
        var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
        defer graph.close();

        const worker_publish = try graph.runGraphMetricPlannedWorkerPageStepForMetric("pagerank", "worker-publish");
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.publish_generation, worker_publish.phase);
        try std.testing.expect(!worker_publish.claimed_page);
        try std.testing.expect(!worker_publish.advanced_phase);
        try std.testing.expect(!worker_publish.published);

        const coordinator_publish = try graph.runGraphMetricPlannedCoordinatorStepForMetric("pagerank");
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.publish_generation, coordinator_publish.phase);
        try std.testing.expect(coordinator_publish.advanced_phase);

        const duplicate_publish = try graph.runGraphMetricPlannedCoordinatorStepForMetric("pagerank");
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.cleanup_old_generations, duplicate_publish.phase);
        try std.testing.expect(!duplicate_publish.advanced_phase);
        try std.testing.expect(!duplicate_publish.published);

        var cleanup_finished = false;
        for (0..12) |_| {
            const cleanup = try graph.runGraphMetricPlannedWorkerPageStepForMetric("pagerank", "worker-clean");
            try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.cleanup_old_generations, cleanup.phase);
            try std.testing.expect(!cleanup.advanced_phase);
            if (cleanup.published) {
                cleanup_finished = true;
                break;
            }
        }
        try std.testing.expect(cleanup_finished);

        var fresh = try graph.graphMetricStatus("pagerank");
        defer fresh.deinit(alloc);
        try std.testing.expectEqual(GraphIndex.GraphMetricState.fresh, fresh.state);
        try std.testing.expectEqual(target_generation, fresh.published_generation);
        try std.testing.expectEqual(@as(u32, 1), fresh.iterations_completed);
        try std.testing.expectEqual(@as(usize, 0), fresh.build_pages.len);
        try std.testing.expectEqual(@as(usize, 1), fresh.recent_events.len);
        try std.testing.expectEqual(GraphIndex.GraphMetricEventKind.publish, fresh.recent_events[0].kind);

        const after_complete = try graph.runGraphMetricPlannedCoordinatorStepForMetric("pagerank");
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.complete, after_complete.phase);
        try std.testing.expect(after_complete.published);
        try std.testing.expect(!after_complete.advanced_phase);

        const top = try graph.graphMetricTopK("pagerank", 2);
        defer {
            for (top) |*score| score.deinit(alloc);
            alloc.free(top);
        }
        try std.testing.expectEqual(@as(usize, 2), top.len);
        try std.testing.expectEqualStrings("hub", top[0].node);
    }
}

