        try std.testing.expectEqual(@as(usize, 1), hub.recent_events.len);
        try std.testing.expectEqual(GraphIndex.GraphMetricEventKind.publish, authority.recent_events[0].kind);
        try std.testing.expectEqual(GraphIndex.GraphMetricEventKind.publish, hub.recent_events[0].kind);

