        try graph.addEdge(source, "hub", "cites", 1.0, 0, 0, "");
    }

    const target_generation = graph.edge_generation;
    const worker_ids = [_][]const u8{ "worker-a", "worker-b", "worker-c" };
    const metric_names = [_][]const u8{ "degree", "pagerank", "eigenvector" };
    for (metric_names) |metric_name| {
