}

test "graph degree planned public failure preserves prior published generation" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-degree-public-fail-build");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-degree-public-fail-build");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{.{
        .name = "degree",
        .kind = .degree,
        .refresh = .manual,
    }};
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    try std.testing.expectError(error.GraphMetricBuildJobNotFound, graph.failGraphMetricPlannedBuild("degree", error.InvalidGraphMetricScore));

    try graph.addEdge("doc-a", "hub", "cites", 1.0, 0, 0, "");
    var published = try graph.runDegreeMetricPlanned("degree");
    defer published.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.fresh, published.state);
    const prior_generation = published.published_generation;

    const before_failure = try graph.graphMetricTopK("degree", 10);
    defer {
        for (before_failure) |*score| score.deinit(alloc);
        alloc.free(before_failure);
    }
    try std.testing.expectEqual(@as(usize, 2), before_failure.len);

    try graph.addEdge("doc-b", "hub", "cites", 1.0, 0, 0, "");
    const rebuilding_generation = graph.edge_generation;
    try std.testing.expect(rebuilding_generation > prior_generation);

    var building = try graph.ensureGraphMetricPlannedBuild("degree", rebuilding_generation);
    defer building.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.building, building.state);
    try std.testing.expectEqual(rebuilding_generation, building.building_generation);

    const prepare = try graph.runGraphMetricPlannedWorkerPageStepForMetric("degree", "worker-prepare");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.prepare_generation, prepare.phase);
    try std.testing.expect(prepare.claimed_page);
    try std.testing.expect(prepare.completed_page);

    var failed = try graph.failGraphMetricPlannedBuild("degree", error.InvalidGraphMetricScore);
    defer failed.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.failed, failed.state);
    try std.testing.expectEqual(prior_generation, failed.published_generation);
    try std.testing.expectEqual(@as(u64, 0), failed.build_job_id);
    try std.testing.expectEqual(@as(u64, 1), failed.retry_count);
    try std.testing.expectEqualStrings("InvalidGraphMetricScore", failed.last_error);
    try std.testing.expectEqual(@as(usize, 1), failed.recent_failures.len);
    try std.testing.expectEqual(building.build_job_id, failed.recent_failures[0].job_id);

    const after_failure = try graph.graphMetricTopK("degree", 10);
    defer {
        for (after_failure) |*score| score.deinit(alloc);
        alloc.free(after_failure);
    }
    try std.testing.expectEqual(before_failure.len, after_failure.len);
    for (before_failure, after_failure) |before, after| {
        try std.testing.expectEqualStrings(before.node, after.node);
        try std.testing.expectApproxEqAbs(before.score, after.score, 0.0000001);
        try std.testing.expect(!std.mem.eql(u8, after.node, "doc-b"));
    }

    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        try std.testing.expect((try graph.metricBuildLease(&txn, "degree")) == null);
        const failed_job = try graph.metricBuildJob(&txn, "degree") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(building.build_job_id, failed_job.job_id);
        try std.testing.expectEqual(@as(u64, 1), failed_job.retry_count);
        try std.testing.expectEqualStrings("InvalidGraphMetricScore", failed_job.last_error);
        try std.testing.expect((try graph.metricBuildManifest(&txn, "degree", failed_job.job_id)) == null);
    }

    try std.testing.expectError(error.GraphMetricBuildNotActive, graph.failGraphMetricPlannedBuild("degree", error.InvalidGraphMetricScore));
}

