        for (0..graph_metric_build_target_scan_page_units + 1) |i| {
            var source_buf: [64]u8 = undefined;
            const source = try std.fmt.bufPrint(&source_buf, "doc-{d:0>3}", .{i});
            try graph.addEdge(source, "hub", "cites", 1.0, 0, 0, "");
        }
        target_generation = graph.edge_generation;
        try graph.acquireGraphMetricBuildLease("degree", target_generation);

        const prepare = try graph.runGraphMetricPlannedWorkerPageStep("degree", metrics[0], "worker-prepare");
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.prepare_generation, prepare.phase);
        try std.testing.expect(prepare.completed_page);
        try std.testing.expect(!prepare.advanced_phase);
        const advanced = try graph.runGraphMetricPlannedCoordinatorStep("degree", metrics[0]);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.prepare_generation, advanced.phase);
        try std.testing.expect(advanced.advanced_phase);

        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const job = try graph.metricBuildJob(&txn, "degree") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.scan_edges_and_out_degree, job.phase);
        job_id = job.job_id;
        score_generation = job.score_generation;
    }

    {
        var store = try docstore.DocStore.open(alloc, store_path, .{});
        defer store.close();
        var worker = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
        defer worker.close();

        const claim = try worker.claimGraphMetricBuildPageAt("degree", job_id, .scan_edges_and_out_degree, 0, 1, "worker-dead", 1000) orelse return error.TestExpectedGraphMetricBuildPage;
        dead_worker_lease_expires_at_ms = claim.lease_expires_at_ms;
        try std.testing.expectEqual(@as(u64, 1), claim.attempt);
        _ = try worker.updateGraphMetricBuildPageProgress("degree", job_id, .scan_edges_and_out_degree, 0, 1, "worker-dead", "dead-cursor", 1, claim.total_units);
    }

    {
        var store = try docstore.DocStore.open(alloc, store_path, .{});
        defer store.close();
        var observer = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
        defer observer.close();

        var status = try observer.graphMetricStatus("degree");
        defer status.deinit(alloc);
        try std.testing.expectEqual(GraphIndex.GraphMetricState.building, status.state);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.scan_edges_and_out_degree, status.phase);
        try std.testing.expectEqual(job_id, status.build_job_id);
        try std.testing.expectEqual(target_generation, status.building_generation);
        try std.testing.expectEqual(@as(usize, 1), status.build_pages.len);
        try std.testing.expectEqual(@as(u64, 1), status.build_pages[0].page_id);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, status.build_pages[0].state);
        try std.testing.expectEqualStrings("worker-dead", status.build_pages[0].worker_id);
        try std.testing.expectEqual(dead_worker_lease_expires_at_ms, status.build_pages[0].lease_expires_at_ms);
        try std.testing.expectEqual(@as(u64, 1), status.build_pages[0].attempt);
        try std.testing.expectEqualStrings("dead-cursor", status.build_pages[0].cursor);
        try std.testing.expectEqual(@as(u64, 1), status.build_pages[0].completed_units);
    }

    {
        var store = try docstore.DocStore.open(alloc, store_path, .{});
        defer store.close();
        var early_worker = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
        defer early_worker.close();

        try std.testing.expect((try early_worker.claimGraphMetricBuildPageAt("degree", job_id, .scan_edges_and_out_degree, 0, 1, "worker-early", dead_worker_lease_expires_at_ms - 1)) == null);
        var txn = try early_worker.beginReadReverseTxn();
        defer txn.abort();
        const still_leased = try early_worker.metricBuildPage(&txn, "degree", job_id, .scan_edges_and_out_degree, 0, 1) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, still_leased.state);
        try std.testing.expectEqualStrings("worker-dead", still_leased.worker_id);
        try std.testing.expectEqual(@as(u64, 1), still_leased.attempt);
        try std.testing.expectEqualStrings("dead-cursor", still_leased.cursor);
    }

    {
        var store = try docstore.DocStore.open(alloc, store_path, .{});
        defer store.close();
        var reclaim_worker = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
        defer reclaim_worker.close();

        const reclaimed = try reclaim_worker.claimGraphMetricBuildPageAt("degree", job_id, .scan_edges_and_out_degree, 0, 1, "worker-reclaim", dead_worker_lease_expires_at_ms + 1) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, reclaimed.state);
        try std.testing.expectEqualStrings("worker-reclaim", reclaimed.worker_id);
        try std.testing.expectEqual(@as(u64, 2), reclaimed.attempt);
        try std.testing.expectEqualStrings("", reclaimed.cursor);
        try std.testing.expectEqual(@as(u64, 0), reclaimed.completed_units);

        var txn = try reclaim_worker.beginReadReverseTxn();
        const job = try reclaim_worker.metricBuildJob(&txn, "degree") orelse return error.TestExpectedGraphMetricBuildJob;
        txn.abort();
        try std.testing.expect((try reclaim_worker.executeDegreeScanBuildPage("degree", metrics[0], job, reclaimed)) > 0);
    }

    var finished = false;
    for (0..80) |step_i| {
        {
            var store = try docstore.DocStore.open(alloc, store_path, .{});
            defer store.close();
            var worker = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
            defer worker.close();
            const worker_id = if (step_i % 2 == 0) "worker-a" else "worker-b";
            const worker_step = try worker.runGraphMetricPlannedWorkerPageStep("degree", metrics[0], worker_id);
            if (worker_step.completed_build) {
                finished = true;
                break;
            }
        }
        {
            var store = try docstore.DocStore.open(alloc, store_path, .{});
            defer store.close();
            var coordinator = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
            defer coordinator.close();
            const coordinator_step = try coordinator.runGraphMetricPlannedCoordinatorStep("degree", metrics[0]);
            if (coordinator_step.completed_build) {
                finished = true;
                break;
            }
        }
    }
    try std.testing.expect(finished);

    {
        var store = try docstore.DocStore.open(alloc, store_path, .{});
        defer store.close();
        var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
        defer graph.close();

        var status = try graph.graphMetricStatus("degree");
        defer status.deinit(alloc);
        try std.testing.expectEqual(GraphIndex.GraphMetricState.fresh, status.state);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.complete, status.phase);
        try std.testing.expectEqual(target_generation, status.published_generation);
        try std.testing.expectEqual(@as(usize, 0), status.build_pages.len);

        const top = try graph.graphMetricTopK("degree", 2);
        defer {
            for (top) |*score| score.deinit(alloc);
            alloc.free(top);
        }
        try std.testing.expectEqual(@as(usize, 2), top.len);
        try std.testing.expectEqualStrings("hub", top[0].node);
        try std.testing.expectApproxEqAbs(@as(f64, @floatFromInt(graph_metric_build_target_scan_page_units + 1)), top[0].score, 0.0000001);
    }
}

test "graph degree planned worker step uses injected time for lease reclaim" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-degree-worker-step-clock");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-degree-worker-step-clock");
    defer cleanupTmp(rev_path);

    const metrics = [_]GraphMetricConfig{.{
        .name = "degree",
        .kind = .degree,
        .refresh = .manual,
    }};

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    for (0..graph_metric_build_target_scan_page_units + 1) |i| {
        var source_buf: [64]u8 = undefined;
        const source = try std.fmt.bufPrint(&source_buf, "doc-{d:0>3}", .{i});
        try graph.addEdge(source, "hub", "cites", 1.0, 0, 0, "");
    }
    try graph.acquireGraphMetricBuildLease("degree", graph.edge_generation);
    defer graph.releaseGraphMetricBuildLease("degree") catch {};

    const prepare = try graph.runGraphMetricPlannedWorkerPageStepForMetricAt("degree", "worker-prepare", 1000);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.prepare_generation, prepare.phase);
    try std.testing.expect(prepare.claimed_page);
    try std.testing.expect(prepare.completed_page);

    const advanced = try graph.runGraphMetricPlannedCoordinatorStepForMetricAt("degree", 1001);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.prepare_generation, advanced.phase);
    try std.testing.expect(advanced.advanced_phase);

    const active_job = blk: {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        break :blk try graph.cloneGraphMetricBuildJobAlloc(try graph.metricBuildJob(&txn, "degree") orelse return error.TestExpectedGraphMetricBuildJob);
    };
    defer graph.deinitClonedGraphMetricBuildJob(active_job);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.scan_edges_and_out_degree, active_job.phase);

    const dead_claim = try graph.claimNextGraphMetricBuildPageAt("degree", active_job.job_id, .scan_edges_and_out_degree, 0, "worker-dead", 2000) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(@as(u64, 1), dead_claim.attempt);
    try std.testing.expect(dead_claim.lease_expires_at_ms > 2000);
    _ = try graph.updateGraphMetricBuildPageProgress("degree", active_job.job_id, .scan_edges_and_out_degree, 0, dead_claim.page_id, "worker-dead", "dead-cursor", 1, dead_claim.total_units);

    for (0..16) |_| {
        const live = try graph.runGraphMetricPlannedWorkerPageStepForMetricAt("degree", "worker-live", 1500);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.scan_edges_and_out_degree, live.phase);
        if (!live.claimed_page) break;
        try std.testing.expect(live.completed_page);
        try std.testing.expect(live.page_id != dead_claim.page_id);
    }

    const early = try graph.runGraphMetricPlannedWorkerPageStepForMetricAt("degree", "worker-early", dead_claim.lease_expires_at_ms - 1);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.scan_edges_and_out_degree, early.phase);
    try std.testing.expect(!early.claimed_page);
    try std.testing.expect(!early.completed_page);

    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "degree", active_job.job_id, .scan_edges_and_out_degree, 0, dead_claim.page_id) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, page.state);
        try std.testing.expectEqualStrings("worker-dead", page.worker_id);
        try std.testing.expectEqual(@as(u64, 1), page.attempt);
        try std.testing.expectEqualStrings("dead-cursor", page.cursor);
        try std.testing.expectEqual(@as(u64, 1), page.completed_units);
    }

    const reclaimed = try graph.runGraphMetricPlannedWorkerPageStepForMetricAt("degree", "worker-reclaim", dead_claim.lease_expires_at_ms + 1);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.scan_edges_and_out_degree, reclaimed.phase);
    try std.testing.expect(reclaimed.claimed_page);
    try std.testing.expect(reclaimed.completed_page);
    try std.testing.expectEqual(dead_claim.page_id, reclaimed.page_id);

    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "degree", active_job.job_id, .scan_edges_and_out_degree, 0, dead_claim.page_id) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.complete, page.state);
        try std.testing.expectEqualStrings("worker-reclaim", page.worker_id);
        try std.testing.expectEqual(@as(u64, 2), page.attempt);
        try std.testing.expectEqual(@as(u64, 0), page.lease_expires_at_ms);
        try std.testing.expectEqualStrings("", page.cursor);
    }
}

test "graph degree planned coordinator ticks are idempotent across barriers and publish" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-degree-coordinator-idempotent");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-degree-coordinator-idempotent");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{.{
        .name = "degree",
        .kind = .degree,
        .refresh = .manual,
    }};
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    for (0..graph_metric_build_target_scan_page_units + 1) |i| {
        var source_buf: [64]u8 = undefined;
        const source = try std.fmt.bufPrint(&source_buf, "doc-{d:0>3}", .{i});
        try graph.addEdge(source, "hub", "cites", 1.0, 0, 0, "");
    }
    try graph.acquireGraphMetricBuildLease("degree", graph.edge_generation);
    defer graph.releaseGraphMetricBuildLease("degree") catch {};

    const prepare = try graph.runGraphMetricPlannedWorkerPageStep("degree", metrics[0], "worker-prepare");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.prepare_generation, prepare.phase);
    try std.testing.expect(prepare.completed_page);

    const advance_prepare = try graph.runGraphMetricPlannedCoordinatorStep("degree", metrics[0]);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.prepare_generation, advance_prepare.phase);
    try std.testing.expect(advance_prepare.advanced_phase);
    const duplicate_prepare = try graph.runGraphMetricPlannedCoordinatorStep("degree", metrics[0]);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.scan_edges_and_out_degree, duplicate_prepare.phase);
    try std.testing.expect(!duplicate_prepare.advanced_phase);
    try std.testing.expect(!duplicate_prepare.published);

    while (true) {
        const step = try graph.runGraphMetricPlannedWorkerPageStep("degree", metrics[0], "worker-scan");
        if (!step.claimed_page) break;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.scan_edges_and_out_degree, step.phase);
        try std.testing.expect(step.completed_page);
    }
    const advance_scan = try graph.runGraphMetricPlannedCoordinatorStep("degree", metrics[0]);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.scan_edges_and_out_degree, advance_scan.phase);
    try std.testing.expect(advance_scan.advanced_phase);
    const duplicate_scan = try graph.runGraphMetricPlannedCoordinatorStep("degree", metrics[0]);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.reduce_ranks, duplicate_scan.phase);
    try std.testing.expect(!duplicate_scan.advanced_phase);
    try std.testing.expect(!duplicate_scan.published);

    while (true) {
        const step = try graph.runGraphMetricPlannedWorkerPageStep("degree", metrics[0], "worker-reduce");
        if (!step.claimed_page) break;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.reduce_ranks, step.phase);
        try std.testing.expect(step.completed_page);
    }
    const advance_reduce = try graph.runGraphMetricPlannedCoordinatorStep("degree", metrics[0]);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.reduce_ranks, advance_reduce.phase);
    try std.testing.expect(advance_reduce.advanced_phase);

    var stale_publish_job: GraphIndex.GraphMetricBuildJob = undefined;
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        stale_publish_job = try graph.cloneGraphMetricBuildJobAlloc(try graph.metricBuildJob(&txn, "degree") orelse return error.TestExpectedGraphMetricBuildJob);
    }
    defer graph.deinitClonedGraphMetricBuildJob(stale_publish_job);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.publish_generation, stale_publish_job.phase);
    const publish_step = try graph.runGraphMetricPlannedCoordinatorStep("degree", metrics[0]);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.publish_generation, publish_step.phase);
    try std.testing.expect(publish_step.advanced_phase);
    try std.testing.expectError(error.GraphMetricBuildPublishNotReady, graph.publishGraphMetricBuildFromCoordinator("degree", metrics[0], stale_publish_job));

    var published = try graph.graphMetricStatus("degree");
    defer published.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.building, published.state);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.cleanup_old_generations, published.phase);
    try std.testing.expectEqual(@as(usize, 1), published.recent_events.len);
    try std.testing.expectEqual(GraphIndex.GraphMetricEventKind.publish, published.recent_events[0].kind);
    const published_generation = published.published_generation;

    const cleanup_coordinator = try graph.runGraphMetricPlannedCoordinatorStep("degree", metrics[0]);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.cleanup_old_generations, cleanup_coordinator.phase);
    try std.testing.expect(!cleanup_coordinator.advanced_phase);
    try std.testing.expect(!cleanup_coordinator.published);

    var cleanup_done = false;
    for (0..8) |_| {
        const cleanup = try graph.runGraphMetricPlannedWorkerPageStep("degree", metrics[0], "worker-clean");
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.cleanup_old_generations, cleanup.phase);
        try std.testing.expect(!cleanup.advanced_phase);
        if (cleanup.published) {
            try std.testing.expect(cleanup.completed_page);
            cleanup_done = true;
            break;
        }
    }
    try std.testing.expect(cleanup_done);

    const after_complete = try graph.runGraphMetricPlannedCoordinatorStep("degree", metrics[0]);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.complete, after_complete.phase);
    try std.testing.expect(after_complete.published);
    try std.testing.expect(!after_complete.advanced_phase);

    var fresh = try graph.graphMetricStatus("degree");
    defer fresh.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.fresh, fresh.state);
    try std.testing.expectEqual(published_generation, fresh.published_generation);
    try std.testing.expectEqual(@as(usize, 1), fresh.recent_events.len);
    try std.testing.expectEqual(GraphIndex.GraphMetricEventKind.publish, fresh.recent_events[0].kind);
}

test "graph degree planned build serves prior generation while active" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-degree-planned-active");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-degree-planned-active");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{.{
        .name = "degree",
        .kind = .degree,
        .refresh = .manual,
    }};
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    try graph.addEdge("doc-a", "doc-b", "cites", 1.0, 0, 0, "");
    var published = try graph.runDegreeMetricPlanned("degree");
    defer published.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.fresh, published.state);
    const first_generation = published.published_generation;

    try graph.addEdge("doc-c", "doc-b", "cites", 1.0, 0, 0, "");
    const second_generation = graph.edge_generation;
    try std.testing.expect(second_generation > first_generation);
    try graph.acquireGraphMetricBuildLease("degree", second_generation);
    defer graph.releaseGraphMetricBuildLease("degree") catch {};

    var building = try graph.graphMetricStatus("degree");
    defer building.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.building, building.state);
    try std.testing.expectEqual(first_generation, building.published_generation);
    try std.testing.expectEqual(second_generation, building.building_generation);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.prepare_generation, building.phase);

    const stale_top = try graph.graphMetricTopK("degree", 10);
    defer {
        for (stale_top) |*score| score.deinit(alloc);
        alloc.free(stale_top);
    }
    try std.testing.expectEqual(@as(usize, 2), stale_top.len);
    for (stale_top) |score| {
        try std.testing.expect(!std.mem.eql(u8, score.node, "doc-c"));
        try std.testing.expectApproxEqAbs(@as(f64, 1.0), score.score, 0.001);
    }
    try std.testing.expectError(error.GraphMetricBuildPublishNotReady, graph.verifyGraphMetricBuildPublishReady("degree", building.build_job_id));

    try graph.releaseGraphMetricBuildLease("degree");
    var rebuilt = try graph.runDegreeMetricPlanned("degree");
    defer rebuilt.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.fresh, rebuilt.state);
    try std.testing.expectEqual(second_generation, rebuilt.published_generation);

    const fresh_top = try graph.graphMetricTopK("degree", 10);
    defer {
        for (fresh_top) |*score| score.deinit(alloc);
        alloc.free(fresh_top);
    }
    try std.testing.expectEqual(@as(usize, 3), fresh_top.len);
    try std.testing.expectEqualStrings("doc-b", fresh_top[0].node);
    try std.testing.expectApproxEqAbs(@as(f64, 2.0), fresh_top[0].score, 0.001);
}

