    var fresh = try graph.graphMetricStatus("degree");
    defer fresh.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.fresh, fresh.state);
    try std.testing.expectEqual(status.published_generation, fresh.published_generation);
}

test "graph metric failed planned build cleans abandoned scores and job namespace" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-metric-failed-job-cleanup");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-metric-failed-job-cleanup");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{.{
        .name = "degree",
        .kind = .degree,
        .refresh = .manual,
    }};
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    try graph.addEdge("doc-a", "doc-b", "cites", 1.0, 0, 0, "");
    try graph.acquireGraphMetricBuildLease("degree", graph.edge_generation);
    defer graph.releaseGraphMetricBuildLease("degree") catch {};

    inline for (.{ .prepare_generation, .scan_edges_and_out_degree, .reduce_ranks }) |expected_phase| {
        const step = try graph.runDegreeMetricPlannedWorkerStep("degree", metrics[0], "worker-a");
        try std.testing.expectEqual(expected_phase, step.phase);
        try std.testing.expect(step.claimed_page);
        try std.testing.expect(step.completed_page);
        try std.testing.expect(step.advanced_phase);
    }

    var job_id: u64 = 0;
    var score_generation: u64 = 0;
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const job = try graph.metricBuildJob(&txn, "degree") orelse return error.TestExpectedGraphMetricBuildJob;
        job_id = job.job_id;
        score_generation = job.score_generation;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.publish_generation, job.phase);
        try std.testing.expectEqual(@as(usize, 2), try graph.countGraphMetricScoreGeneration("degree", score_generation));
        _ = try graph.metricBuildManifest(&txn, "degree", job_id) orelse return error.TestExpectedGraphMetricBuildManifest;
        _ = try graph.metricBuildPage(&txn, "degree", job_id, .scan_edges_and_out_degree, 0, 1) orelse return error.TestExpectedGraphMetricBuildPage;
        _ = try graph.metricBuildPhaseSummary(&txn, "degree", job_id, .scan_edges_and_out_degree, 0) orelse return error.TestExpectedGraphMetricBuildPhaseSummary;
    }

    try graph.recordGraphMetricFailure("degree", error.InvalidGraphMetricScore);

    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const failed_job = try graph.metricBuildJob(&txn, "degree") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(job_id, failed_job.job_id);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.publish_generation, failed_job.phase);
        try std.testing.expectEqual(@as(u64, 1), failed_job.retry_count);
        try std.testing.expectEqualStrings("InvalidGraphMetricScore", failed_job.last_error);
        try std.testing.expectEqual(@as(usize, 0), try graph.countGraphMetricScoreGeneration("degree", score_generation));
        try std.testing.expect((try graph.metricBuildManifest(&txn, "degree", job_id)) == null);
        try std.testing.expect((try graph.metricBuildPage(&txn, "degree", job_id, .scan_edges_and_out_degree, 0, 1)) == null);
        try std.testing.expect((try graph.metricBuildPhaseSummary(&txn, "degree", job_id, .scan_edges_and_out_degree, 0)) == null);
    }

    var failed = try graph.graphMetricStatus("degree");
    defer failed.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.failed, failed.state);
    try std.testing.expectEqual(@as(u64, 0), failed.published_generation);
    try std.testing.expectEqual(@as(u64, 1), failed.retry_count);
    try std.testing.expectEqualStrings("InvalidGraphMetricScore", failed.last_error);
    try std.testing.expectEqual(@as(usize, 1), failed.recent_failures.len);
    try std.testing.expectEqual(job_id, failed.recent_failures[0].job_id);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.publish_generation, failed.recent_failures[0].phase);
    try std.testing.expectEqual(@as(u64, 1), failed.recent_failures[0].retry_count);
    try std.testing.expectEqualStrings("InvalidGraphMetricScore", failed.recent_failures[0].last_error);
}

test "graph metric failed planned build retains bounded diagnostics" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-metric-failed-job-retention");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-metric-failed-job-retention");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{.{
        .name = "degree",
        .kind = .degree,
        .refresh = .manual,
    }};
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    try graph.addEdge("doc-a", "doc-b", "cites", 1.0, 0, 0, "");
    try graph.acquireGraphMetricBuildLease("degree", graph.edge_generation);
    defer graph.releaseGraphMetricBuildLease("degree") catch {};

    const prepare = try graph.runDegreeMetricPlannedWorkerStep("degree", metrics[0], "worker-a");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.prepare_generation, prepare.phase);
    try std.testing.expect(prepare.completed_page);

    var job_id: u64 = 0;
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const job = try graph.metricBuildJob(&txn, "degree") orelse return error.TestExpectedGraphMetricBuildJob;
        job_id = job.job_id;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.scan_edges_and_out_degree, job.phase);
    }

    for (0..graph_metric_recent_event_limit + 2) |_| {
        try graph.recordGraphMetricFailure("degree", error.InvalidGraphMetricScore);
    }

    var failed = try graph.graphMetricStatus("degree");
    defer failed.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.failed, failed.state);
    try std.testing.expectEqual(@as(u64, graph_metric_recent_event_limit + 2), failed.retry_count);
    try std.testing.expectEqual(@as(usize, graph_metric_recent_event_limit), failed.recent_failures.len);
    try std.testing.expectEqual(@as(u64, graph_metric_recent_event_limit + 2), failed.recent_failures[0].sequence);
    try std.testing.expectEqual(@as(u64, graph_metric_recent_event_limit + 2), failed.recent_failures[0].retry_count);
    try std.testing.expectEqual(job_id, failed.recent_failures[0].job_id);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.scan_edges_and_out_degree, failed.recent_failures[0].phase);
    try std.testing.expectEqualStrings("InvalidGraphMetricScore", failed.recent_failures[0].last_error);
    try std.testing.expectEqual(@as(u64, 3), failed.recent_failures[failed.recent_failures.len - 1].sequence);
    try std.testing.expectEqual(GraphIndex.GraphMetricEventKind.failed, failed.last_event.?.kind);
    try std.testing.expectEqual(@as(usize, graph_metric_recent_event_limit), failed.recent_events.len);
    try std.testing.expectEqual(@as(u64, graph_metric_recent_event_limit + 2), failed.recent_events[0].sequence);
    try std.testing.expectEqual(GraphIndex.GraphMetricEventKind.failed, failed.recent_events[0].kind);
    try std.testing.expectEqual(@as(u64, 3), failed.recent_events[failed.recent_events.len - 1].sequence);

    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const pruned_key = try graph.graphMetricFailureRecordKeyAlloc("degree", 1);
        defer alloc.free(pruned_key);
        try std.testing.expectError(error.NotFound, txn.get(pruned_key));
        const retained_key = try graph.graphMetricFailureRecordKeyAlloc("degree", 3);
        defer alloc.free(retained_key);
        _ = try txn.get(retained_key);
        const pruned_event_key = try graph.graphMetricEventKeyAlloc("degree", 1);
        defer alloc.free(pruned_event_key);
        try std.testing.expectError(error.NotFound, txn.get(pruned_event_key));
        const retained_event_key = try graph.graphMetricEventKeyAlloc("degree", 3);
        defer alloc.free(retained_event_key);
        _ = try txn.get(retained_event_key);
    }
}

test "graph metric repeated failed planned builds bound diagnostics and cleanup abandoned namespaces" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-metric-repeated-failed-job-cleanup");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-metric-repeated-failed-job-cleanup");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{.{
        .name = "degree",
        .kind = .degree,
        .refresh = .manual,
    }};
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    const failed_build_count = graph_metric_recent_event_limit + 2;
    var failed_job_ids: [failed_build_count]u64 = undefined;
    var failed_score_generations: [failed_build_count]u64 = undefined;
    for (0..failed_build_count) |i| {
        var source_buf: [64]u8 = undefined;
        const source = try std.fmt.bufPrint(&source_buf, "doc-failed-{d}", .{i});
        try graph.addEdge(source, "hub", "cites", 1.0, 0, 0, "");
        const target_generation = graph.edge_generation;

        var building = try graph.ensureGraphMetricPlannedBuild("degree", target_generation);
        defer building.deinit(alloc);
        try std.testing.expectEqual(GraphIndex.GraphMetricState.building, building.state);

        inline for (.{ .prepare_generation, .scan_edges_and_out_degree, .reduce_ranks }) |expected_phase| {
            const step = try graph.runDegreeMetricPlannedWorkerStep("degree", metrics[0], "worker-a");
            try std.testing.expectEqual(expected_phase, step.phase);
            try std.testing.expect(step.claimed_page);
            try std.testing.expect(step.completed_page);
            try std.testing.expect(step.advanced_phase);
        }

        {
            var txn = try graph.beginReadReverseTxn();
            defer txn.abort();
            const job = try graph.metricBuildJob(&txn, "degree") orelse return error.TestExpectedGraphMetricBuildJob;
            failed_job_ids[i] = job.job_id;
            failed_score_generations[i] = job.score_generation;
            try std.testing.expectEqual(target_generation, job.target_generation);
            try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.publish_generation, job.phase);
            try std.testing.expect((try graph.countGraphMetricScoreGeneration("degree", job.score_generation)) > 0);
            _ = try graph.metricBuildManifest(&txn, "degree", job.job_id) orelse return error.TestExpectedGraphMetricBuildManifest;
        }

        var failed = try graph.failGraphMetricPlannedBuild("degree", error.InvalidGraphMetricScore);
        defer failed.deinit(alloc);
        try std.testing.expectEqual(GraphIndex.GraphMetricState.failed, failed.state);
        try std.testing.expectEqual(@as(u64, i + 1), failed.retry_count);
        try std.testing.expectEqual(@as(usize, @min(i + 1, graph_metric_recent_event_limit)), failed.recent_failures.len);

        {
            var txn = try graph.beginReadReverseTxn();
            defer txn.abort();
            try std.testing.expect((try graph.metricBuildLease(&txn, "degree")) == null);
            try std.testing.expect((try graph.metricBuildManifest(&txn, "degree", failed_job_ids[i])) == null);
            try std.testing.expect((try graph.metricBuildPage(&txn, "degree", failed_job_ids[i], .scan_edges_and_out_degree, 0, 1)) == null);
            try std.testing.expect((try graph.metricBuildPhaseSummary(&txn, "degree", failed_job_ids[i], .scan_edges_and_out_degree, 0)) == null);
            try std.testing.expectEqual(@as(usize, 0), try graph.countGraphMetricScoreGeneration("degree", failed_score_generations[i]));
            const job_namespace_prefix = try graph.graphMetricBuildJobNamespacePrefixAlloc("degree", failed_job_ids[i]);
            defer alloc.free(job_namespace_prefix);
            var cur = try txn.openCursor();
            defer cur.close();
            const maybe_job_namespace = try cur.seekAtOrAfter(job_namespace_prefix);
            if (maybe_job_namespace) |entry| try std.testing.expect(!std.mem.startsWith(u8, entry.key, job_namespace_prefix));
        }
    }

    var retained = try graph.graphMetricStatus("degree");
    defer retained.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.failed, retained.state);
    try std.testing.expectEqual(@as(u64, failed_build_count), retained.retry_count);
    try std.testing.expectEqual(@as(usize, graph_metric_recent_event_limit), retained.recent_failures.len);
    try std.testing.expectEqual(@as(u64, failed_build_count), retained.recent_failures[0].sequence);
    try std.testing.expectEqual(@as(u64, failed_build_count), retained.recent_events[0].sequence);
    try std.testing.expectEqual(GraphIndex.GraphMetricEventKind.failed, retained.last_event.?.kind);

    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const pruned_failure_key = try graph.graphMetricFailureRecordKeyAlloc("degree", 1);
        defer alloc.free(pruned_failure_key);
        try std.testing.expectError(error.NotFound, txn.get(pruned_failure_key));
        const retained_failure_key = try graph.graphMetricFailureRecordKeyAlloc("degree", failed_build_count - graph_metric_recent_event_limit + 1);
        defer alloc.free(retained_failure_key);
        _ = try txn.get(retained_failure_key);
        const pruned_event_key = try graph.graphMetricEventKeyAlloc("degree", 1);
        defer alloc.free(pruned_event_key);
        try std.testing.expectError(error.NotFound, txn.get(pruned_event_key));
        const retained_event_key = try graph.graphMetricEventKeyAlloc("degree", failed_build_count - graph_metric_recent_event_limit + 1);
        defer alloc.free(retained_event_key);
        _ = try txn.get(retained_event_key);
    }
}

fn drainGraphMetricBuildToPublishForTest(
    graph: *GraphIndex,
    metric_name: []const u8,
    cfg: GraphMetricConfig,
    worker_id: []const u8,
    phases: []const GraphIndex.GraphMetricBuildPhase,
) !void {
    for (phases) |expected_phase| {
        const step = try graph.runGraphMetricPlannedWorkerStep(metric_name, cfg, worker_id);
        try std.testing.expectEqual(expected_phase, step.phase);
        try std.testing.expect(step.claimed_page);
        try std.testing.expect(step.completed_page);
        try std.testing.expect(step.advanced_phase);
    }
}

fn expectGraphMetricBuildNamespaceRemovedForTest(
    graph: *GraphIndex,
    metric_name: []const u8,
    job_id: u64,
) !void {
    var txn = try graph.beginReadReverseTxn();
    defer txn.abort();

    const job_namespace_prefix = try graph.graphMetricBuildJobNamespacePrefixAlloc(metric_name, job_id);
    defer graph.alloc.free(job_namespace_prefix);
    var cur = try txn.openCursor();
    defer cur.close();
    const maybe_job_namespace = try cur.seekAtOrAfter(job_namespace_prefix);
    if (maybe_job_namespace) |entry| try std.testing.expect(!std.mem.startsWith(u8, entry.key, job_namespace_prefix));
}

fn seedUnpublishedGraphMetricScoreForTest(
    graph: *GraphIndex,
    metric_name: []const u8,
    score_generation: u64,
    node: []const u8,
) !void {
    const scores = [_]GraphIndex.GraphMetricScore{.{
        .node = node,
        .score = 1.0,
    }};
    var batch = try graph.beginWriteReverseBatch();
    errdefer batch.abort();
    try graph.putGraphMetricScoresInBatch(&batch, metric_name, score_generation, scores[0..]);
    try batch.commit();
}

fn verifyRepeatedFailedIterativeMetricBuildCleanup(
    alloc: Allocator,
    metric_name: []const u8,
    kind: GraphMetricKind,
) !void {
    var store_label_buf: [128]u8 = undefined;
    const store_label = try std.fmt.bufPrint(&store_label_buf, "store-{s}-repeated-failed-job-cleanup", .{metric_name});
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, store_label);
    defer cleanupTmp(store_path);
    var rev_label_buf: [128]u8 = undefined;
    const rev_label = try std.fmt.bufPrint(&rev_label_buf, "rev-{s}-repeated-failed-job-cleanup", .{metric_name});
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, rev_label);
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{.{
        .name = metric_name,
        .kind = kind,
        .refresh = .manual,
        .max_iterations = 1,
        .tolerance = 0.000001,
    }};
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    const phases = [_]GraphIndex.GraphMetricBuildPhase{
        .prepare_generation,
        .scan_edges_and_out_degree,
        .initialize_ranks,
        .iterate_contributions,
        .reduce_ranks,
        .check_convergence,
    };
    const failed_build_count = graph_metric_recent_event_limit + 2;
    var failed_job_ids: [failed_build_count]u64 = undefined;
    var failed_score_generations: [failed_build_count]u64 = undefined;
    for (0..failed_build_count) |i| {
        var source_buf: [64]u8 = undefined;
        const source = try std.fmt.bufPrint(&source_buf, "{s}-failed-{d}", .{ metric_name, i });
        try graph.addEdge(source, "hub", "cites", 1.0, 0, 0, "");
        const target_generation = graph.edge_generation;

        var building = try graph.ensureGraphMetricPlannedBuild(metric_name, target_generation);
        defer building.deinit(alloc);
        try std.testing.expectEqual(GraphIndex.GraphMetricState.building, building.state);

        try drainGraphMetricBuildToPublishForTest(&graph, metric_name, metrics[0], "worker-a", phases[0..]);

        {
            var txn = try graph.beginReadReverseTxn();
            defer txn.abort();
            const job = try graph.metricBuildJob(&txn, metric_name) orelse return error.TestExpectedGraphMetricBuildJob;
            failed_job_ids[i] = job.job_id;
            failed_score_generations[i] = job.score_generation;
            try std.testing.expectEqual(target_generation, job.target_generation);
            try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.publish_generation, job.phase);
            _ = try graph.metricBuildManifest(&txn, metric_name, job.job_id) orelse return error.TestExpectedGraphMetricBuildManifest;
        }
        try seedUnpublishedGraphMetricScoreForTest(&graph, metric_name, failed_score_generations[i], "abandoned-score");
        try std.testing.expect((try graph.countGraphMetricScoreGeneration(metric_name, failed_score_generations[i])) > 0);

        var failed = try graph.failGraphMetricPlannedBuild(metric_name, error.InvalidGraphMetricScore);
        defer failed.deinit(alloc);
        try std.testing.expectEqual(GraphIndex.GraphMetricState.failed, failed.state);
        try std.testing.expectEqual(@as(u64, i + 1), failed.retry_count);
        try std.testing.expectEqual(@as(usize, @min(i + 1, graph_metric_recent_event_limit)), failed.recent_failures.len);

        {
            var txn = try graph.beginReadReverseTxn();
            defer txn.abort();
            try std.testing.expect((try graph.metricBuildLease(&txn, metric_name)) == null);
            try std.testing.expect((try graph.metricBuildManifest(&txn, metric_name, failed_job_ids[i])) == null);
            try std.testing.expectEqual(@as(usize, 0), try graph.countGraphMetricScoreGeneration(metric_name, failed_score_generations[i]));
        }
        try expectGraphMetricBuildNamespaceRemovedForTest(&graph, metric_name, failed_job_ids[i]);
    }

    var retained = try graph.graphMetricStatus(metric_name);
    defer retained.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.failed, retained.state);
    try std.testing.expectEqual(@as(u64, failed_build_count), retained.retry_count);
    try std.testing.expectEqual(@as(usize, graph_metric_recent_event_limit), retained.recent_failures.len);
    try std.testing.expectEqual(@as(u64, failed_build_count), retained.recent_failures[0].sequence);
    try std.testing.expectEqual(@as(u64, failed_build_count), retained.recent_events[0].sequence);
    try std.testing.expectEqual(GraphIndex.GraphMetricEventKind.failed, retained.last_event.?.kind);

    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const pruned_failure_key = try graph.graphMetricFailureRecordKeyAlloc(metric_name, 1);
        defer alloc.free(pruned_failure_key);
        try std.testing.expectError(error.NotFound, txn.get(pruned_failure_key));
        const retained_failure_key = try graph.graphMetricFailureRecordKeyAlloc(metric_name, failed_build_count - graph_metric_recent_event_limit + 1);
        defer alloc.free(retained_failure_key);
        _ = try txn.get(retained_failure_key);
        const pruned_event_key = try graph.graphMetricEventKeyAlloc(metric_name, 1);
        defer alloc.free(pruned_event_key);
        try std.testing.expectError(error.NotFound, txn.get(pruned_event_key));
        const retained_event_key = try graph.graphMetricEventKeyAlloc(metric_name, failed_build_count - graph_metric_recent_event_limit + 1);
        defer alloc.free(retained_event_key);
        _ = try txn.get(retained_event_key);
    }
}

test "graph metric repeated failed iterative builds bound diagnostics and cleanup abandoned namespaces" {
    const alloc = std.testing.allocator;
    try verifyRepeatedFailedIterativeMetricBuildCleanup(alloc, "pagerank", .pagerank);
    try verifyRepeatedFailedIterativeMetricBuildCleanup(alloc, "eigenvector", .eigenvector);
}

