            try std.testing.expectEqual(target_generation, job.target_generation);
            try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.publish_generation, job.phase);
            _ = try graph.metricBuildManifest(&txn, "hits_authority", job.job_id) orelse return error.TestExpectedGraphMetricBuildManifest;
        }
        try seedUnpublishedGraphMetricScoreForTest(&graph, "hits_authority", failed_score_generations[i], "abandoned-authority");
        try seedUnpublishedGraphMetricScoreForTest(&graph, "hits_hub", failed_score_generations[i], "abandoned-hub");
        try std.testing.expect((try graph.countGraphMetricScoreGeneration("hits_authority", failed_score_generations[i])) > 0);
        try std.testing.expect((try graph.countGraphMetricScoreGeneration("hits_hub", failed_score_generations[i])) > 0);

        var failed_authority = try graph.failGraphMetricPlannedBuild("hits_authority", error.InvalidGraphMetricScore);
        defer failed_authority.deinit(alloc);
        var failed_hub = try graph.graphMetricStatus("hits_hub");
        defer failed_hub.deinit(alloc);
        try std.testing.expectEqual(GraphIndex.GraphMetricState.failed, failed_authority.state);
        try std.testing.expectEqual(GraphIndex.GraphMetricState.failed, failed_hub.state);
        try std.testing.expectEqual(@as(u64, i + 1), failed_authority.retry_count);
        try std.testing.expectEqual(@as(u64, i + 1), failed_hub.retry_count);
        try std.testing.expectEqual(@as(usize, @min(i + 1, graph_metric_recent_event_limit)), failed_authority.recent_failures.len);
        try std.testing.expectEqual(failed_authority.recent_failures.len, failed_hub.recent_failures.len);

        {
            var txn = try graph.beginReadReverseTxn();
            defer txn.abort();
            try std.testing.expect((try graph.metricBuildLease(&txn, "hits_authority")) == null);
            try std.testing.expect((try graph.metricBuildManifest(&txn, "hits_authority", failed_job_ids[i])) == null);
            try std.testing.expectEqual(@as(usize, 0), try graph.countGraphMetricScoreGeneration("hits_authority", failed_score_generations[i]));
            try std.testing.expectEqual(@as(usize, 0), try graph.countGraphMetricScoreGeneration("hits_hub", failed_score_generations[i]));
        }
        try expectGraphMetricBuildNamespaceRemovedForTest(&graph, "hits_authority", failed_job_ids[i]);
    }

    var retained_authority = try graph.graphMetricStatus("hits_authority");
    defer retained_authority.deinit(alloc);
    var retained_hub = try graph.graphMetricStatus("hits_hub");
    defer retained_hub.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.failed, retained_authority.state);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.failed, retained_hub.state);
    try std.testing.expectEqual(@as(u64, failed_build_count), retained_authority.retry_count);
    try std.testing.expectEqual(retained_authority.retry_count, retained_hub.retry_count);
    try std.testing.expectEqual(@as(usize, graph_metric_recent_event_limit), retained_authority.recent_failures.len);
    try std.testing.expectEqual(retained_authority.recent_failures.len, retained_hub.recent_failures.len);
    try std.testing.expectEqual(@as(u64, failed_build_count), retained_authority.recent_failures[0].sequence);
    try std.testing.expectEqual(retained_authority.recent_failures[0].sequence, retained_hub.recent_failures[0].sequence);
    try std.testing.expectEqual(@as(u64, failed_build_count), retained_authority.recent_events[0].sequence);
    try std.testing.expectEqual(retained_authority.recent_events[0].sequence, retained_hub.recent_events[0].sequence);
    try std.testing.expectEqual(GraphIndex.GraphMetricEventKind.failed, retained_authority.last_event.?.kind);
    try std.testing.expectEqual(GraphIndex.GraphMetricEventKind.failed, retained_hub.last_event.?.kind);

    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        inline for (.{ "hits_authority", "hits_hub" }) |metric_name| {
            const pruned_failure_key = try graph.graphMetricFailureRecordKeyAlloc(metric_name, 1);
            defer alloc.free(pruned_failure_key);
            try std.testing.expectError(error.NotFound, txn.get(pruned_failure_key));
            const retained_failure_key = try graph.graphMetricFailureRecordKeyAlloc(metric_name, failed_build_count - graph_metric_recent_event_limit + 1);
            defer alloc.free(retained_failure_key);
            _ = try txn.get(retained_failure_key);
            const pruned_event_key = try graph.graphMetricEventKeyAlloc(metric_name, 1);
            defer alloc.free(pruned_event_key);
            try std.testing.expectError(error.NotFound, txn.get(pruned_event_key));
            const retained_event_key = try graph.graphMetricEventKeyAlloc(metric_name, failed_build_count - graph_metric_recent_event_limit + 1);
            defer alloc.free(retained_event_key);
            _ = try txn.get(retained_event_key);
        }
    }
}

test "graph metric build job cleanup refuses active job namespace" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-metric-job-cleanup-active");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-metric-job-cleanup-active");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{.{
        .name = "degree",
        .kind = .degree,
        .refresh = .manual,
    }};
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    try graph.addEdge("doc-a", "doc-b", "cites", 1.0, 0, 0, "");
