    defer graph.releaseGraphMetricBuildLease("degree") catch {};

    var txn = try graph.beginReadReverseTxn();
    const job = try graph.metricBuildJob(&txn, "degree") orelse return error.TestExpectedGraphMetricBuildJob;
    txn.abort();

