    {
        var check_txn = try graph.beginReadReverseTxn();
        defer check_txn.abort();
        _ = try graph.metricBuildManifest(&check_txn, "degree", job.job_id) orelse return error.TestExpectedGraphMetricBuildManifest;
        _ = try graph.metricBuildPage(&check_txn, "degree", job.job_id, .scan_edges_and_out_degree, 0, 1) orelse return error.TestExpectedGraphMetricBuildPage;
    }
}

