    try std.testing.expectEqual(local_status.published_generation, planned_status.published_generation);
    try std.testing.expectEqual(local_status.iterations_completed, planned_status.iterations_completed);
    try std.testing.expectEqual(local_status.converged, planned_status.converged);
    try std.testing.expectApproxEqAbs(local_status.delta, planned_status.delta, 0.0000001);

    const local_top = try graph.graphMetricTopK("eigenvector_local", 10);
    defer {
        for (local_top) |*score| score.deinit(alloc);
        alloc.free(local_top);
    }
    const planned_top = try graph.graphMetricTopK("eigenvector_planned", 10);
    defer {
        for (planned_top) |*score| score.deinit(alloc);
        alloc.free(planned_top);
    }
    try std.testing.expectEqual(@as(usize, 7), local_top.len);
    try std.testing.expectEqual(local_top.len, planned_top.len);
    var norm_sq: f64 = 0.0;
    var saw_reducible_zero = false;
    for (local_top, planned_top) |local, planned| {
        try std.testing.expectEqualStrings(local.node, planned.node);
        try std.testing.expect(std.math.isFinite(local.score));
        try std.testing.expect(std.math.isFinite(planned.score));
        try std.testing.expectApproxEqAbs(local.score, planned.score, 0.0000001);
        norm_sq += local.score * local.score;
        if ((std.mem.eql(u8, local.node, "doc-f") or std.mem.eql(u8, local.node, "doc-g")) and local.score == 0.0) {
            saw_reducible_zero = true;
        }
    }
    try std.testing.expectApproxEqAbs(@as(f64, 1.0), @sqrt(norm_sq), 0.0000001);
    try std.testing.expect(saw_reducible_zero);

    var txn = try graph.beginReadReverseTxn();
    defer txn.abort();
    const job = try graph.metricBuildJob(&txn, "eigenvector_planned") orelse return error.TestExpectedGraphMetricBuildJob;
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.complete, job.phase);
}

test "graph eigenvector reclaimed scan page overwrites stale partial output" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-eigenvector-scan-reclaim");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-eigenvector-scan-reclaim");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{.{
        .name = "eigenvector",
        .kind = .eigenvector,
        .refresh = .manual,
        .max_iterations = 1,
    }};
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    try graph.addEdge("doc-a", "doc-b", "cites", 1.0, 0, 0, "");
    try graph.addEdge("doc-a", "doc-c", "cites", 1.0, 0, 0, "");
    try graph.acquireGraphMetricBuildLease("eigenvector", graph.edge_generation);
    defer graph.releaseGraphMetricBuildLease("eigenvector") catch {};

    var job_txn = try graph.beginReadReverseTxn();
    const active_job = try graph.metricBuildJob(&job_txn, "eigenvector") orelse return error.TestExpectedGraphMetricBuildJob;
    job_txn.abort();

    const prepare = try graph.runGraphMetricPlannedWorkerStep("eigenvector", metrics[0], "worker-setup");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.prepare_generation, prepare.phase);
    try std.testing.expect(prepare.completed_page);
    try std.testing.expect(prepare.advanced_phase);

    const partial_scan_claim = try graph.claimGraphMetricBuildPageAt("eigenvector", active_job.job_id, .scan_edges_and_out_degree, 0, 1, "worker-a", 2000) orelse return error.TestExpectedGraphMetricBuildPage;
    _ = try graph.executePageRankScanBuildPageWithLimit("eigenvector", metrics[0], active_job, partial_scan_claim, 1);
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "eigenvector", active_job.job_id, .scan_edges_and_out_degree, 0, 1) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, page.state);
        try std.testing.expectEqual(@as(u64, 1), page.completed_units);
        try std.testing.expect(page.cursor.len > 0);

        const partial_out_degree = try graph.aggregatePageRankOutDegreeForNode(&txn, "eigenvector", active_job.job_id, "doc-a");
        try std.testing.expectEqual(@as(u64, 0), partial_out_degree);
        const attempt_out_degree_key = try graph.graphMetricBuildAttemptPageRankOutDegreePartialKeyAlloc("eigenvector", active_job.job_id, .scan_edges_and_out_degree, 0, partial_scan_claim.page_id, partial_scan_claim.attempt, "doc-a");
        defer alloc.free(attempt_out_degree_key);
        try std.testing.expectEqual(@as(u64, 1), try GraphIndex.readU64OrZero(&txn, attempt_out_degree_key));
        const node_b_key = try graph.graphMetricBuildPageRankNodePartialKeyAlloc("eigenvector", active_job.job_id, "doc-b", 1);
        defer alloc.free(node_b_key);
        try std.testing.expectError(error.NotFound, txn.get(node_b_key));
        const attempt_node_b_key = try graph.graphMetricBuildAttemptPageRankNodePartialKeyAlloc("eigenvector", active_job.job_id, .scan_edges_and_out_degree, 0, partial_scan_claim.page_id, partial_scan_claim.attempt, "doc-b");
        defer alloc.free(attempt_node_b_key);
        try std.testing.expectEqual(@as(u64, 1), try GraphIndex.readU64OrZero(&txn, attempt_node_b_key));
    }

    const scan_expires_at = blk: {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "eigenvector", active_job.job_id, .scan_edges_and_out_degree, 0, 1) orelse return error.TestExpectedGraphMetricBuildPage;
        break :blk page.lease_expires_at_ms;
    };
    const reclaimed_scan = try graph.claimGraphMetricBuildPageAt("eigenvector", active_job.job_id, .scan_edges_and_out_degree, 0, 1, "worker-b", scan_expires_at + 1) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, reclaimed_scan.state);
    try std.testing.expectEqual(@as(u64, 2), reclaimed_scan.attempt);
    try std.testing.expectEqual(@as(u64, 0), reclaimed_scan.completed_units);
    try std.testing.expectEqualStrings("", reclaimed_scan.cursor);
    {
        var stale_out_degrees = std.StringHashMapUnmanaged(u64).empty;
        defer {
            var key_it = stale_out_degrees.keyIterator();
            while (key_it.next()) |key_ptr| alloc.free(key_ptr.*);
            stale_out_degrees.deinit(alloc);
        }
        var stale_nodes = std.StringHashMapUnmanaged(void).empty;
        defer {
            var key_it = stale_nodes.keyIterator();
            while (key_it.next()) |key_ptr| alloc.free(key_ptr.*);
            stale_nodes.deinit(alloc);
        }
        try stale_out_degrees.put(alloc, try alloc.dupe(u8, "doc-a"), 99);
        try stale_nodes.put(alloc, try alloc.dupe(u8, "doc-stale"), {});
        try std.testing.expectError(error.GraphMetricBuildPageNotLeased, graph.writePageRankScanPartialsForAttempt("eigenvector", active_job, partial_scan_claim, 0, &stale_out_degrees, &stale_nodes, false));
    }
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const stale_node_key = try graph.graphMetricBuildPageRankNodePartialKeyAlloc("eigenvector", active_job.job_id, "doc-stale", 1);
        defer alloc.free(stale_node_key);
        try std.testing.expectError(error.NotFound, txn.get(stale_node_key));
        const partial_out_degree = try graph.aggregatePageRankOutDegreeForNode(&txn, "eigenvector", active_job.job_id, "doc-a");
        try std.testing.expectEqual(@as(u64, 0), partial_out_degree);
    }

    _ = try graph.executePageRankScanBuildPageWithLimit("eigenvector", metrics[0], active_job, reclaimed_scan, null);
    try std.testing.expect(try graph.advanceGraphMetricBuildPhaseIfReady("eigenvector", active_job.job_id, .scan_edges_and_out_degree, 0));
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "eigenvector", active_job.job_id, .scan_edges_and_out_degree, 0, 1) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.complete, page.state);
        try std.testing.expectEqual(page.total_units, page.completed_units);

        const out_degree = try graph.aggregatePageRankOutDegreeForNode(&txn, "eigenvector", active_job.job_id, "doc-a");
        try std.testing.expectEqual(@as(u64, 2), out_degree);
        inline for (.{ "doc-a", "doc-b", "doc-c" }) |node| {
            const node_key = try graph.graphMetricBuildPageRankNodePartialKeyAlloc("eigenvector", active_job.job_id, node, 1);
            defer alloc.free(node_key);
            try std.testing.expectEqual(@as(u64, 1), try GraphIndex.readU64OrZero(&txn, node_key));
        }
        const job = try graph.metricBuildJob(&txn, "eigenvector") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.initialize_ranks, job.phase);
    }
}

test "graph eigenvector reclaimed initialize page overwrites stale rank output" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-eigenvector-initialize-reclaim");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-eigenvector-initialize-reclaim");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{.{
        .name = "eigenvector",
        .kind = .eigenvector,
        .refresh = .manual,
        .max_iterations = 1,
        .tolerance = 0.000001,
    }};
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    try graph.addEdge("doc-a", "doc-b", "cites", 1.0, 0, 0, "");
    try graph.addEdge("doc-c", "doc-b", "cites", 1.0, 0, 0, "");
    try graph.acquireGraphMetricBuildLease("eigenvector", graph.edge_generation);
    defer graph.releaseGraphMetricBuildLease("eigenvector") catch {};

    var job_txn = try graph.beginReadReverseTxn();
    const active_job = try graph.metricBuildJob(&job_txn, "eigenvector") orelse return error.TestExpectedGraphMetricBuildJob;
    job_txn.abort();

    inline for (.{ .prepare_generation, .scan_edges_and_out_degree }) |expected_phase| {
        const step = try graph.runGraphMetricPlannedWorkerStep("eigenvector", metrics[0], "worker-setup");
        try std.testing.expectEqual(expected_phase, step.phase);
        try std.testing.expect(step.claimed_page);
        try std.testing.expect(step.completed_page);
        try std.testing.expect(step.advanced_phase);
    }

    const initial_claim = try graph.claimNextGraphMetricBuildPageAt("eigenvector", active_job.job_id, .initialize_ranks, 0, "worker-a", 2000) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, initial_claim.state);
    try std.testing.expectEqual(@as(u64, 1), initial_claim.attempt);

    {
        var batch = try graph.beginWriteReverseBatch();
        errdefer batch.abort();
        inline for (.{ "doc-a", "doc-b", "doc-c" }) |node| {
            const rank_key = try graph.graphMetricBuildPageRankKeyAlloc("eigenvector", active_job.job_id, 0, node);
            defer alloc.free(rank_key);
            try GraphIndex.putF64(&batch, rank_key, 42.0);
        }
        try batch.commit();
    }

    const reclaimed = try graph.claimGraphMetricBuildPageAt(
        "eigenvector",
        active_job.job_id,
        .initialize_ranks,
        0,
        initial_claim.page_id,
        "worker-b",
        initial_claim.lease_expires_at_ms + 1,
    ) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, reclaimed.state);
    try std.testing.expectEqual(@as(u64, 2), reclaimed.attempt);
    try std.testing.expectEqual(@as(u64, 0), reclaimed.completed_units);
    try std.testing.expectEqualStrings("", reclaimed.cursor);
    try std.testing.expectEqual(@as(u64, 0), reclaimed.output_fingerprint);

    const stale_initialized = [_][]const u8{"doc-a"};
    try std.testing.expectError(error.GraphMetricBuildPageNotLeased, graph.writeEigenvectorInitializeOutputForAttempt("eigenvector", active_job, initial_claim, &stale_initialized, 99.0));
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const rank_key = try graph.graphMetricBuildPageRankKeyAlloc("eigenvector", active_job.job_id, 0, "doc-a");
        defer alloc.free(rank_key);
        try std.testing.expectApproxEqAbs(@as(f64, 42.0), try GraphIndex.readF64OrZero(&txn, rank_key), 0.0000001);
    }

    _ = try graph.executeEigenvectorInitializeBuildPage("eigenvector", active_job, reclaimed);
    try std.testing.expect(try graph.advanceGraphMetricBuildPhaseIfReady("eigenvector", active_job.job_id, .initialize_ranks, 0));

    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "eigenvector", active_job.job_id, .initialize_ranks, 0, initial_claim.page_id) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.complete, page.state);
        try std.testing.expectEqual(page.total_units, page.completed_units);

        const expected_rank = 1.0 / @sqrt(@as(f64, 3.0));
        inline for (.{ "doc-a", "doc-b", "doc-c" }) |node| {
            const rank_key = try graph.graphMetricBuildPageRankKeyAlloc("eigenvector", active_job.job_id, 0, node);
            defer alloc.free(rank_key);
            try std.testing.expectApproxEqAbs(expected_rank, try GraphIndex.readF64OrZero(&txn, rank_key), 0.0000001);
        }

        const job = try graph.metricBuildJob(&txn, "eigenvector") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.iterate_contributions, job.phase);
    }
}

test "graph eigenvector contribution and reduce pages resume from durable cursor after reopen" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-eigenvector-resume");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-eigenvector-resume");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{.{
        .name = "eigenvector",
        .kind = .eigenvector,
        .refresh = .manual,
        .max_iterations = 1,
        .tolerance = 0.000001,
    }};
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });

    try graph.addEdge("doc-a", "doc-b", "cites", 1.0, 0, 0, "");
    try graph.addEdge("doc-c", "doc-b", "cites", 1.0, 0, 0, "");
    try graph.acquireGraphMetricBuildLease("eigenvector", graph.edge_generation);

    var job_txn = try graph.beginReadReverseTxn();
    const active_job = try graph.metricBuildJob(&job_txn, "eigenvector") orelse return error.TestExpectedGraphMetricBuildJob;
    job_txn.abort();

    inline for (.{ .prepare_generation, .scan_edges_and_out_degree, .initialize_ranks }) |expected_phase| {
        const step = try graph.runGraphMetricPlannedWorkerStep("eigenvector", metrics[0], "worker-a");
        try std.testing.expectEqual(expected_phase, step.phase);
        try std.testing.expect(step.claimed_page);
        try std.testing.expect(step.completed_page);
        try std.testing.expect(step.advanced_phase);
    }

    const contribution_claim = try graph.claimNextGraphMetricBuildPageAt("eigenvector", active_job.job_id, .iterate_contributions, 0, "worker-a", 2000) orelse return error.TestExpectedGraphMetricBuildPage;
    _ = try graph.executeEigenvectorContributionBuildPageWithLimit("eigenvector", metrics[0], active_job, contribution_claim, 1);
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "eigenvector", active_job.job_id, .iterate_contributions, 0, contribution_claim.page_id) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, page.state);
        try std.testing.expectEqual(@as(u64, 1), page.completed_units);
        try std.testing.expect(page.cursor.len > 0);
        const partial = try graph.aggregatePageRankContributionForNode(&txn, "eigenvector", active_job.job_id, 0, "doc-b");
        try std.testing.expectApproxEqAbs(@as(f64, 0.0), partial, 0.0);
        const attempt_key = try graph.graphMetricBuildAttemptPageRankContributionKeyAlloc("eigenvector", active_job.job_id, .iterate_contributions, 0, contribution_claim.page_id, contribution_claim.attempt, "doc-b");
        defer alloc.free(attempt_key);
        try std.testing.expectApproxEqAbs(1.0 / @sqrt(@as(f64, 3.0)), try GraphIndex.readF64OrZero(&txn, attempt_key), 0.0000001);
    }
    graph.close();

    graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    const renewed_contribution = try graph.claimGraphMetricBuildPageAt("eigenvector", active_job.job_id, .iterate_contributions, 0, contribution_claim.page_id, "worker-a", 2001) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, renewed_contribution.state);
    try std.testing.expectEqual(@as(u64, 1), renewed_contribution.completed_units);
    try std.testing.expect(renewed_contribution.cursor.len > 0);
    _ = try graph.executeEigenvectorContributionBuildPageWithLimit("eigenvector", metrics[0], active_job, renewed_contribution, null);
    try std.testing.expect(try graph.advanceGraphMetricBuildPhaseIfReady("eigenvector", active_job.job_id, .iterate_contributions, 0));
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const contribution = try graph.aggregatePageRankContributionForNode(&txn, "eigenvector", active_job.job_id, 0, "doc-b");
        try std.testing.expectApproxEqAbs(2.0 / @sqrt(@as(f64, 3.0)), contribution, 0.0000001);
        const page = try graph.metricBuildPage(&txn, "eigenvector", active_job.job_id, .iterate_contributions, 0, contribution_claim.page_id) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.complete, page.state);
    }

    const reduce_claim = try graph.claimNextGraphMetricBuildPageAt("eigenvector", active_job.job_id, .reduce_ranks, 0, "worker-r", 3000) orelse return error.TestExpectedGraphMetricBuildPage;
    _ = try graph.executeEigenvectorReduceBuildPageWithLimit("eigenvector", active_job, reduce_claim, 1);
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "eigenvector", active_job.job_id, .reduce_ranks, 0, reduce_claim.page_id) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, page.state);
        try std.testing.expectEqual(@as(u64, 1), page.completed_units);
        try std.testing.expect(page.cursor.len > 0);
    }
    graph.close();

    graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();
    const renewed_reduce = try graph.claimGraphMetricBuildPageAt("eigenvector", active_job.job_id, .reduce_ranks, 0, reduce_claim.page_id, "worker-r", 3001) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, renewed_reduce.state);
    try std.testing.expectEqual(@as(u64, 1), renewed_reduce.completed_units);
    try std.testing.expect(renewed_reduce.cursor.len > 0);
    _ = try graph.executeEigenvectorReduceBuildPageWithLimit("eigenvector", active_job, renewed_reduce, null);
    try std.testing.expect(try graph.advanceGraphMetricBuildPhaseIfReady("eigenvector", active_job.job_id, .reduce_ranks, 0));
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const rank_a_key = try graph.graphMetricBuildPageRankKeyAlloc("eigenvector", active_job.job_id, 1, "doc-a");
        defer alloc.free(rank_a_key);
        const rank_b_key = try graph.graphMetricBuildPageRankKeyAlloc("eigenvector", active_job.job_id, 1, "doc-b");
        defer alloc.free(rank_b_key);
        const rank_c_key = try graph.graphMetricBuildPageRankKeyAlloc("eigenvector", active_job.job_id, 1, "doc-c");
        defer alloc.free(rank_c_key);
        try std.testing.expectApproxEqAbs(@as(f64, 0.0), try GraphIndex.readF64OrZero(&txn, rank_a_key), 0.0000001);
        try std.testing.expectApproxEqAbs(@as(f64, 1.0), try GraphIndex.readF64OrZero(&txn, rank_b_key), 0.0000001);
        try std.testing.expectApproxEqAbs(@as(f64, 0.0), try GraphIndex.readF64OrZero(&txn, rank_c_key), 0.0000001);
        const job = try graph.metricBuildJob(&txn, "eigenvector") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.check_convergence, job.phase);
    }
}

