        const attempt_key = try graph.graphMetricBuildAttemptPageRankContributionKeyAlloc("eigenvector", active_job.job_id, .iterate_contributions, 0, contribution_claim.page_id, contribution_claim.attempt, "doc-b");
        defer alloc.free(attempt_key);
        try std.testing.expectApproxEqAbs(1.0 / @sqrt(@as(f64, 3.0)), try GraphIndex.readF64OrZero(&txn, attempt_key), 0.0000001);
        break :blk page.lease_expires_at_ms;
    };

    const reclaimed_contribution = try graph.claimGraphMetricBuildPageAt("eigenvector", active_job.job_id, .iterate_contributions, 0, contribution_claim.page_id, "worker-b", contribution_expires_at + 1) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(@as(u64, 2), reclaimed_contribution.attempt);
    try std.testing.expectEqual(@as(u64, 0), reclaimed_contribution.completed_units);
    try std.testing.expectEqualStrings("", reclaimed_contribution.cursor);
    _ = try graph.executeEigenvectorContributionBuildPageWithLimit("eigenvector", metrics[0], active_job, reclaimed_contribution, null);
    try std.testing.expect(try graph.advanceGraphMetricBuildPhaseIfReady("eigenvector", active_job.job_id, .iterate_contributions, 0));
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const contribution = try graph.aggregatePageRankContributionForNode(&txn, "eigenvector", active_job.job_id, 0, "doc-b");
        try std.testing.expectApproxEqAbs(2.0 / @sqrt(@as(f64, 3.0)), contribution, 0.0000001);
    }

    const reduce_claim = try graph.claimNextGraphMetricBuildPageAt("eigenvector", active_job.job_id, .reduce_ranks, 0, "worker-a", 3000) orelse return error.TestExpectedGraphMetricBuildPage;
    _ = try graph.executeEigenvectorReduceBuildPageWithLimit("eigenvector", active_job, reduce_claim, 1);
    const reduce_expires_at = blk: {
        const stale_rank_key = try graph.graphMetricBuildPageRankKeyAlloc("eigenvector", active_job.job_id, 1, "doc-b");
        defer alloc.free(stale_rank_key);
        var batch = try graph.beginWriteReverseBatch();
        errdefer batch.abort();
        try GraphIndex.putF64(&batch, stale_rank_key, 42.0);
        try batch.commit();

        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "eigenvector", active_job.job_id, .reduce_ranks, 0, reduce_claim.page_id) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, page.state);
        try std.testing.expectEqual(@as(u64, 1), page.completed_units);
        break :blk page.lease_expires_at_ms;
    };

    const reclaimed_reduce = try graph.claimGraphMetricBuildPageAt("eigenvector", active_job.job_id, .reduce_ranks, 0, reduce_claim.page_id, "worker-b", reduce_expires_at + 1) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(@as(u64, 2), reclaimed_reduce.attempt);
    try std.testing.expectEqual(@as(u64, 0), reclaimed_reduce.completed_units);
    try std.testing.expectEqualStrings("", reclaimed_reduce.cursor);
    try std.testing.expectError(error.GraphMetricBuildPageNotLeased, graph.executeEigenvectorReduceBuildPageWithLimit("eigenvector", active_job, reduce_claim, null));
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const rank_b_key = try graph.graphMetricBuildPageRankKeyAlloc("eigenvector", active_job.job_id, 1, "doc-b");
        defer alloc.free(rank_b_key);
        try std.testing.expectApproxEqAbs(@as(f64, 42.0), try GraphIndex.readF64OrZero(&txn, rank_b_key), 0.0000001);
    }
    _ = try graph.executeEigenvectorReduceBuildPageWithLimit("eigenvector", active_job, reclaimed_reduce, null);
    try std.testing.expect(try graph.advanceGraphMetricBuildPhaseIfReady("eigenvector", active_job.job_id, .reduce_ranks, 0));
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const rank_b_key = try graph.graphMetricBuildPageRankKeyAlloc("eigenvector", active_job.job_id, 1, "doc-b");
        defer alloc.free(rank_b_key);
        try std.testing.expectApproxEqAbs(@as(f64, 1.0), try GraphIndex.readF64OrZero(&txn, rank_b_key), 0.0000001);
        const summary = try graph.metricBuildPhaseSummary(&txn, "eigenvector", active_job.job_id, .reduce_ranks, 0) orelse return error.TestExpectedGraphMetricBuildPhaseSummary;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhaseState.complete, summary.state);
    }
}

test "graph eigenvector convergence page reclaim recomputes without stale partial summary" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-eigenvector-convergence-reclaim");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-eigenvector-convergence-reclaim");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{.{
        .name = "eigenvector",
        .kind = .eigenvector,
        .refresh = .manual,
        .max_iterations = 1,
        .tolerance = 0.000001,
    }};
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    try graph.addEdge("doc-a", "doc-b", "cites", 1.0, 0, 0, "");
    try graph.addEdge("doc-c", "doc-b", "cites", 1.0, 0, 0, "");
    try graph.acquireGraphMetricBuildLease("eigenvector", graph.edge_generation);
    defer graph.releaseGraphMetricBuildLease("eigenvector") catch {};

    var job_txn = try graph.beginReadReverseTxn();
    const active_job = try graph.metricBuildJob(&job_txn, "eigenvector") orelse return error.TestExpectedGraphMetricBuildJob;
    job_txn.abort();

    inline for (.{ .prepare_generation, .scan_edges_and_out_degree, .initialize_ranks, .iterate_contributions, .reduce_ranks }) |expected_phase| {
        const step = try graph.runGraphMetricPlannedWorkerStep("eigenvector", metrics[0], "worker-a");
        try std.testing.expectEqual(expected_phase, step.phase);
        try std.testing.expect(step.claimed_page);
        try std.testing.expect(step.completed_page);
        try std.testing.expect(step.advanced_phase);
    }

    const check_claim = try graph.claimGraphMetricBuildPageAt("eigenvector", active_job.job_id, .check_convergence, 0, 5, "worker-a", 4000) orelse return error.TestExpectedGraphMetricBuildPage;
    const partial_check = try graph.executePageRankConvergenceBuildPageWithLimit("eigenvector", metrics[0], active_job, check_claim, 1);
    try std.testing.expect(!partial_check.completed_page);
    try std.testing.expect(partial_check.max_delta > 0.0);
    try std.testing.expect(partial_check.total_delta > 0.0);
    try std.testing.expectApproxEqAbs(@as(f64, 0.0), partial_check.rank_sum, 0.0);

    var expires_at: u64 = 0;
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "eigenvector", active_job.job_id, .check_convergence, 0, 5) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, page.state);
        try std.testing.expectEqual(@as(u64, 1), page.completed_units);
        try std.testing.expect(page.max_delta > 0.0);
        try std.testing.expect(page.total_delta > 0.0);
        try std.testing.expectApproxEqAbs(@as(f64, 0.0), page.rank_sum, 0.0);
        expires_at = page.lease_expires_at_ms;
    }

    const reclaimed = try graph.claimGraphMetricBuildPageAt("eigenvector", active_job.job_id, .check_convergence, 0, 5, "worker-b", expires_at + 1) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, reclaimed.state);
    try std.testing.expectEqual(@as(u64, 2), reclaimed.attempt);
    try std.testing.expectEqual(@as(u64, 0), reclaimed.completed_units);
    try std.testing.expectEqualStrings("", reclaimed.cursor);
    try std.testing.expectEqual(@as(u64, 0), reclaimed.output_fingerprint);
    try std.testing.expectApproxEqAbs(@as(f64, 0.0), reclaimed.max_delta, 0.0);
    try std.testing.expectApproxEqAbs(@as(f64, 0.0), reclaimed.total_delta, 0.0);
    try std.testing.expectApproxEqAbs(@as(f64, 0.0), reclaimed.rank_sum, 0.0);
    try std.testing.expect(!reclaimed.converged);

    try std.testing.expectError(error.GraphMetricBuildPageNotLeased, graph.updateGraphMetricBuildConvergencePageProgressForAttempt("eigenvector", active_job.job_id, 0, 5, check_claim.worker_id, check_claim.attempt, "stale-check", 1, check_claim.total_units, 99.0, 99.0, 99.0));
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "eigenvector", active_job.job_id, .check_convergence, 0, 5) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectApproxEqAbs(@as(f64, 0.0), page.max_delta, 0.0);
        try std.testing.expectApproxEqAbs(@as(f64, 0.0), page.total_delta, 0.0);
        try std.testing.expectApproxEqAbs(@as(f64, 0.0), page.rank_sum, 0.0);
    }

    const completed_check = try graph.executePageRankConvergenceBuildPageWithLimit("eigenvector", metrics[0], active_job, reclaimed, null);
    try std.testing.expect(completed_check.completed_page);
    try std.testing.expectApproxEqAbs(@as(f64, 0.5773502691896258), completed_check.max_delta, 0.0000001);
    try std.testing.expectApproxEqAbs(@as(f64, 1.5773502691896257), completed_check.total_delta, 0.0000001);
    try std.testing.expectApproxEqAbs(@as(f64, 1.0), completed_check.rank_sum, 0.0000001);
    try std.testing.expect(try graph.advanceGraphMetricBuildPhaseIfReady("eigenvector", active_job.job_id, .check_convergence, 0));
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "eigenvector", active_job.job_id, .check_convergence, 0, 5) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.complete, page.state);
        try std.testing.expectApproxEqAbs(@as(f64, 0.5773502691896258), page.max_delta, 0.0000001);
        try std.testing.expectApproxEqAbs(@as(f64, 1.5773502691896257), page.total_delta, 0.0000001);
        try std.testing.expectApproxEqAbs(@as(f64, 1.0), page.rank_sum, 0.0000001);
        const job = try graph.metricBuildJob(&txn, "eigenvector") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.publish_generation, job.phase);
    }
}

test "graph eigenvector later iteration failed pages retry and advance" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-eigenvector-later-iteration-retry");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-eigenvector-later-iteration-retry");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{.{
        .name = "eigenvector",
        .kind = .eigenvector,
        .refresh = .manual,
        .max_iterations = 2,
        .tolerance = 0.000001,
    }};
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    try graph.addEdge("doc-a", "doc-b", "cites", 1.0, 0, 0, "");
    try graph.addEdge("doc-c", "doc-b", "cites", 1.0, 0, 0, "");
    try graph.acquireGraphMetricBuildLease("eigenvector", graph.edge_generation);
    defer graph.releaseGraphMetricBuildLease("eigenvector") catch {};

    var job_txn = try graph.beginReadReverseTxn();
    const active_job = try graph.metricBuildJob(&job_txn, "eigenvector") orelse return error.TestExpectedGraphMetricBuildJob;
    job_txn.abort();

    inline for (.{ .prepare_generation, .scan_edges_and_out_degree, .initialize_ranks, .iterate_contributions, .reduce_ranks, .check_convergence }) |expected_phase| {
        const step = try graph.runGraphMetricPlannedWorkerStep("eigenvector", metrics[0], "worker-a");
        try std.testing.expectEqual(expected_phase, step.phase);
        try std.testing.expect(step.claimed_page);
        try std.testing.expect(step.completed_page);
        try std.testing.expect(step.advanced_phase);
    }

    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const job = try graph.metricBuildJob(&txn, "eigenvector") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.iterate_contributions, job.phase);
        try std.testing.expectEqual(@as(u32, 1), job.iteration);
    }

    const contribution_failed_claim = try graph.claimGraphMetricBuildPageAt("eigenvector", active_job.job_id, .iterate_contributions, 1, 3, "worker-fail-contrib", 2000) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(@as(u64, 1), contribution_failed_claim.attempt);
    const contribution_failed = try graph.failGraphMetricBuildPage("eigenvector", active_job.job_id, .iterate_contributions, 1, 3, "worker-fail-contrib", "later eigenvector contribution failed");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.failed, contribution_failed.state);
    try std.testing.expectEqualStrings("later eigenvector contribution failed", contribution_failed.last_error);
    try std.testing.expect(!(try graph.advanceGraphMetricBuildPhaseIfReady("eigenvector", active_job.job_id, .iterate_contributions, 1)));
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const summary = try graph.metricBuildPhaseSummary(&txn, "eigenvector", active_job.job_id, .iterate_contributions, 1) orelse return error.TestExpectedGraphMetricBuildPhaseSummary;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhaseState.failed, summary.state);
        try std.testing.expectEqual(@as(u64, 1), summary.failed_pages);
    }
    {
        const step = try graph.runGraphMetricPlannedWorkerStep("eigenvector", metrics[0], "worker-retry-contrib");
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.iterate_contributions, step.phase);
        try std.testing.expectEqual(@as(u64, 3), step.page_id);
        try std.testing.expect(step.claimed_page);
        try std.testing.expect(step.completed_page);
        try std.testing.expect(step.advanced_phase);
    }
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "eigenvector", active_job.job_id, .iterate_contributions, 1, 3) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.complete, page.state);
        try std.testing.expectEqual(@as(u64, 2), page.attempt);
        const summary = try graph.metricBuildPhaseSummary(&txn, "eigenvector", active_job.job_id, .iterate_contributions, 1) orelse return error.TestExpectedGraphMetricBuildPhaseSummary;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhaseState.complete, summary.state);
        const job = try graph.metricBuildJob(&txn, "eigenvector") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.reduce_ranks, job.phase);
    }

    const reduce_failed_claim = try graph.claimGraphMetricBuildPageAt("eigenvector", active_job.job_id, .reduce_ranks, 1, 4, "worker-fail-reduce", 3000) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(@as(u64, 1), reduce_failed_claim.attempt);
    const reduce_failed = try graph.failGraphMetricBuildPage("eigenvector", active_job.job_id, .reduce_ranks, 1, 4, "worker-fail-reduce", "later eigenvector reduce failed");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.failed, reduce_failed.state);
    try std.testing.expectEqualStrings("later eigenvector reduce failed", reduce_failed.last_error);
    try std.testing.expect(!(try graph.advanceGraphMetricBuildPhaseIfReady("eigenvector", active_job.job_id, .reduce_ranks, 1)));
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const summary = try graph.metricBuildPhaseSummary(&txn, "eigenvector", active_job.job_id, .reduce_ranks, 1) orelse return error.TestExpectedGraphMetricBuildPhaseSummary;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhaseState.failed, summary.state);
        try std.testing.expectEqual(@as(u64, 1), summary.failed_pages);
    }
    {
        const step = try graph.runGraphMetricPlannedWorkerStep("eigenvector", metrics[0], "worker-retry-reduce");
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.reduce_ranks, step.phase);
        try std.testing.expectEqual(@as(u64, 4), step.page_id);
        try std.testing.expect(step.claimed_page);
        try std.testing.expect(step.completed_page);
        try std.testing.expect(step.advanced_phase);
    }
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "eigenvector", active_job.job_id, .reduce_ranks, 1, 4) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.complete, page.state);
        try std.testing.expectEqual(@as(u64, 2), page.attempt);
        const summary = try graph.metricBuildPhaseSummary(&txn, "eigenvector", active_job.job_id, .reduce_ranks, 1) orelse return error.TestExpectedGraphMetricBuildPhaseSummary;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhaseState.complete, summary.state);
        const job = try graph.metricBuildJob(&txn, "eigenvector") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.check_convergence, job.phase);
    }

    const check_failed_claim = try graph.claimGraphMetricBuildPageAt("eigenvector", active_job.job_id, .check_convergence, 1, 5, "worker-fail-check", 4000) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(@as(u64, 1), check_failed_claim.attempt);
    const check_failed = try graph.failGraphMetricBuildPage("eigenvector", active_job.job_id, .check_convergence, 1, 5, "worker-fail-check", "later eigenvector check failed");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.failed, check_failed.state);
    try std.testing.expectEqualStrings("later eigenvector check failed", check_failed.last_error);
    try std.testing.expect(!(try graph.advanceGraphMetricBuildPhaseIfReady("eigenvector", active_job.job_id, .check_convergence, 1)));
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const summary = try graph.metricBuildPhaseSummary(&txn, "eigenvector", active_job.job_id, .check_convergence, 1) orelse return error.TestExpectedGraphMetricBuildPhaseSummary;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhaseState.failed, summary.state);
        try std.testing.expectEqual(@as(u64, 1), summary.failed_pages);
    }
    {
        const step = try graph.runGraphMetricPlannedWorkerStep("eigenvector", metrics[0], "worker-retry-check");
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.check_convergence, step.phase);
        try std.testing.expectEqual(@as(u64, 5), step.page_id);
        try std.testing.expect(step.claimed_page);
        try std.testing.expect(step.completed_page);
        try std.testing.expect(step.advanced_phase);
    }
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "eigenvector", active_job.job_id, .check_convergence, 1, 5) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.complete, page.state);
        try std.testing.expectEqual(@as(u64, 2), page.attempt);
        const summary = try graph.metricBuildPhaseSummary(&txn, "eigenvector", active_job.job_id, .check_convergence, 1) orelse return error.TestExpectedGraphMetricBuildPhaseSummary;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhaseState.complete, summary.state);
        const job = try graph.metricBuildJob(&txn, "eigenvector") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.publish_generation, job.phase);
        _ = try graph.metricBuildIterationSummary(&txn, "eigenvector", active_job.job_id, 1) orelse return error.TestExpectedGraphMetricBuildIterationSummary;
    }
