test "graph eigenvector later iteration exhausted page fails build and preserves prior generation" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-eigenvector-later-iteration-exhausted-preserves-published");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-eigenvector-later-iteration-exhausted-preserves-published");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{.{
        .name = "eigenvector",
        .kind = .eigenvector,
        .refresh = .manual,
        .max_iterations = 2,
        .tolerance = 0.000001,
    }};
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    try graph.addEdge("doc-a", "doc-b", "cites", 1.0, 0, 0, "");
    try graph.addEdge("doc-c", "doc-b", "cites", 1.0, 0, 0, "");
    var published = try graph.runEigenvectorMetricPlanned("eigenvector");
    defer published.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.fresh, published.state);
    const published_generation = published.published_generation;

    const before_failure_top = try graph.graphMetricTopK("eigenvector", 10);
    defer {
        for (before_failure_top) |*score| score.deinit(alloc);
        alloc.free(before_failure_top);
    }
    try std.testing.expectEqual(@as(usize, 3), before_failure_top.len);

    try graph.addEdge("doc-new", "doc-b", "cites", 1.0, 0, 0, "");
    const rebuilding_generation = graph.edge_generation;
    try std.testing.expect(rebuilding_generation > published_generation);
    var building = try graph.ensureGraphMetricPlannedBuild("eigenvector", rebuilding_generation);
    defer building.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.building, building.state);
    try std.testing.expectEqual(rebuilding_generation, building.building_generation);

    const active_job = blk: {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const job = try graph.metricBuildJob(&txn, "eigenvector") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(building.build_job_id, job.job_id);
        try std.testing.expectEqual(rebuilding_generation, job.target_generation);
        break :blk job;
    };

    inline for (.{ .prepare_generation, .scan_edges_and_out_degree, .initialize_ranks, .iterate_contributions, .reduce_ranks, .check_convergence }) |expected_phase| {
        const step = try graph.runGraphMetricPlannedWorkerStep("eigenvector", metrics[0], "worker-a");
        try std.testing.expectEqual(expected_phase, step.phase);
        try std.testing.expect(step.claimed_page);
        try std.testing.expect(step.completed_page);
        try std.testing.expect(step.advanced_phase);
    }
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const job = try graph.metricBuildJob(&txn, "eigenvector") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(active_job.job_id, job.job_id);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.iterate_contributions, job.phase);
        try std.testing.expectEqual(@as(u32, 1), job.iteration);
        _ = try graph.metricBuildPage(&txn, "eigenvector", active_job.job_id, .iterate_contributions, 1, 3) orelse return error.TestExpectedGraphMetricBuildPage;
    }

    var attempt: u64 = 0;
    while (attempt < graph_metric_build_max_page_attempts) : (attempt += 1) {
        const worker_id = switch (attempt) {
            0 => "worker-a",
            1 => "worker-b",
            else => "worker-c",
        };
        const page = try graph.claimGraphMetricBuildPageAt("eigenvector", active_job.job_id, .iterate_contributions, 1, 3, worker_id, 2000 + attempt) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(attempt + 1, page.attempt);
        _ = try graph.failGraphMetricBuildPage("eigenvector", active_job.job_id, .iterate_contributions, 1, 3, worker_id, "retryable later eigenvector contribution failure");
    }

    graph.close();
    graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "eigenvector", active_job.job_id, .iterate_contributions, 1, 3) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.failed, page.state);
        try std.testing.expectEqual(@as(u64, graph_metric_build_max_page_attempts), page.attempt);
        try std.testing.expectEqualStrings("retryable later eigenvector contribution failure", page.last_error);
        const job = try graph.metricBuildJob(&txn, "eigenvector") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(active_job.job_id, job.job_id);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.iterate_contributions, job.phase);
        try std.testing.expectEqual(@as(u32, 1), job.iteration);
    }

    const failed_step = try graph.runGraphMetricPlannedCoordinatorStepForMetric("eigenvector");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.iterate_contributions, failed_step.phase);
    try std.testing.expect(failed_step.failed_build);
    try std.testing.expect(!failed_step.advanced_phase);
    try std.testing.expect(!failed_step.published);

    var failed_status = try graph.graphMetricStatus("eigenvector");
    defer failed_status.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.failed, failed_status.state);
    try std.testing.expectEqual(published_generation, failed_status.published_generation);
    try std.testing.expectEqual(@as(u64, 0), failed_status.build_job_id);
    try std.testing.expectEqualStrings("GraphMetricBuildPageAttemptsExhausted", failed_status.last_error);
    try std.testing.expectEqual(@as(usize, 1), failed_status.recent_failures.len);
    try std.testing.expectEqual(active_job.job_id, failed_status.recent_failures[0].job_id);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.iterate_contributions, failed_status.recent_failures[0].phase);
    try std.testing.expectEqual(@as(u32, 1), failed_status.recent_failures[0].iteration);

    const after_failure_top = try graph.graphMetricTopK("eigenvector", 10);
    defer {
        for (after_failure_top) |*score| score.deinit(alloc);
        alloc.free(after_failure_top);
    }
    try std.testing.expectEqual(before_failure_top.len, after_failure_top.len);
    for (before_failure_top, after_failure_top) |before, after| {
        try std.testing.expectEqualStrings(before.node, after.node);
        try std.testing.expectApproxEqAbs(before.score, after.score, 0.0000001);
        try std.testing.expect(!std.mem.eql(u8, after.node, "doc-new"));
    }

    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const failed_job = try graph.metricBuildJob(&txn, "eigenvector") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(active_job.job_id, failed_job.job_id);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.iterate_contributions, failed_job.phase);
        try std.testing.expectEqual(@as(u32, 1), failed_job.iteration);
        try std.testing.expectEqualStrings("GraphMetricBuildPageAttemptsExhausted", failed_job.last_error);
        try std.testing.expect((try graph.metricBuildManifest(&txn, "eigenvector", active_job.job_id)) == null);
        try std.testing.expectEqual(@as(usize, 0), try graph.countGraphMetricScoreGeneration("eigenvector", active_job.score_generation));
    }
}

test "graph eigenvector cleanup page resumes after reopen with published scores visible" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-eigenvector-cleanup-cursor");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-eigenvector-cleanup-cursor");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{.{
        .name = "eigenvector",
        .kind = .eigenvector,
        .refresh = .manual,
        .max_iterations = 1,
        .tolerance = 0.000001,
    }};
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });

    try graph.addEdge("doc-a", "doc-b", "cites", 1.0, 0, 0, "");
    try graph.addEdge("doc-c", "doc-b", "cites", 1.0, 0, 0, "");
    try graph.acquireGraphMetricBuildLease("eigenvector", graph.edge_generation);

    var job_txn = try graph.beginReadReverseTxn();
    const active_job = try graph.metricBuildJob(&job_txn, "eigenvector") orelse return error.TestExpectedGraphMetricBuildJob;
    job_txn.abort();

    inline for (.{ .prepare_generation, .scan_edges_and_out_degree, .initialize_ranks, .iterate_contributions, .reduce_ranks, .check_convergence }) |expected_phase| {
        const step = try graph.runGraphMetricPlannedWorkerStep("eigenvector", metrics[0], "worker-a");
        try std.testing.expectEqual(expected_phase, step.phase);
        try std.testing.expect(step.claimed_page);
        try std.testing.expect(step.completed_page);
        try std.testing.expect(step.advanced_phase);
    }
    const publish = try graph.runGraphMetricPlannedWorkerStep("eigenvector", metrics[0], "worker-a");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.publish_generation, publish.phase);
    try std.testing.expect(publish.advanced_phase);

    const visible_before_cleanup = try graph.graphMetricTopK("eigenvector", 10);
    defer {
        for (visible_before_cleanup) |*score| score.deinit(alloc);
        alloc.free(visible_before_cleanup);
    }
    try std.testing.expectEqual(@as(usize, 3), visible_before_cleanup.len);

    const abandoned_attempt_key = try graph.graphMetricBuildAttemptPageRankContributionKeyAlloc("eigenvector", active_job.job_id, .iterate_contributions, 0, 999, 1, "doc-abandoned");
    defer alloc.free(abandoned_attempt_key);
    {
        var batch = try graph.beginWriteReverseBatch();
        errdefer batch.abort();
        try GraphIndex.putF64(&batch, abandoned_attempt_key, 123.0);
        for (0..graph_metric_build_cleanup_delete_page_units + 6) |i| {
            var node_buf: [64]u8 = undefined;
            const node = try std.fmt.bufPrint(&node_buf, "cleanup-extra-{d:0>3}", .{i});
            const key = try graph.graphMetricBuildPageRankKeyAlloc("eigenvector", active_job.job_id, 99, node);
            defer alloc.free(key);
            try GraphIndex.putF64(&batch, key, 1.0);
        }
        try batch.commit();
    }

    const first_cleanup = try graph.runGraphMetricPlannedWorkerStep("eigenvector", metrics[0], "worker-clean");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.cleanup_old_generations, first_cleanup.phase);
    try std.testing.expect(first_cleanup.claimed_page);
    try std.testing.expect(!first_cleanup.completed_page);
    try std.testing.expect(!first_cleanup.published);
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const cleanup_page = try graph.metricBuildPage(&txn, "eigenvector", active_job.job_id, .cleanup_old_generations, 0, first_cleanup.page_id) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, cleanup_page.state);
        try std.testing.expect(cleanup_page.cursor.len > 0);
        try std.testing.expect(cleanup_page.completed_units >= graph_metric_build_cleanup_delete_page_units);
        const job = try graph.metricBuildJob(&txn, "eigenvector") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.cleanup_old_generations, job.phase);
        try std.testing.expectEqualStrings(cleanup_page.cursor, job.cursor);
    }

    const visible_after_partial_cleanup = try graph.graphMetricTopK("eigenvector", 10);
    defer {
        for (visible_after_partial_cleanup) |*score| score.deinit(alloc);
        alloc.free(visible_after_partial_cleanup);
    }
    try std.testing.expectEqual(visible_before_cleanup.len, visible_after_partial_cleanup.len);
    for (visible_before_cleanup, visible_after_partial_cleanup) |before, after| {
        try std.testing.expectEqualStrings(before.node, after.node);
        try std.testing.expectApproxEqAbs(before.score, after.score, 0.0000001);
    }
    graph.close();

    graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    const visible_after_reopen = try graph.graphMetricTopK("eigenvector", 10);
    defer {
        for (visible_after_reopen) |*score| score.deinit(alloc);
        alloc.free(visible_after_reopen);
    }
    try std.testing.expectEqual(visible_before_cleanup.len, visible_after_reopen.len);
    for (visible_before_cleanup, visible_after_reopen) |before, after| {
        try std.testing.expectEqualStrings(before.node, after.node);
        try std.testing.expectApproxEqAbs(before.score, after.score, 0.0000001);
    }
    {
        var status = try graph.graphMetricStatus("eigenvector");
        defer status.deinit(alloc);
        try std.testing.expectEqual(GraphIndex.GraphMetricState.building, status.state);
        try std.testing.expectEqual(active_job.job_id, status.build_job_id);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.cleanup_old_generations, status.phase);
    }

    const final_cleanup = try graph.runGraphMetricPlannedWorkerStep("eigenvector", metrics[0], "worker-clean");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.cleanup_old_generations, final_cleanup.phase);
    try std.testing.expect(final_cleanup.claimed_page);
    try std.testing.expect(final_cleanup.completed_page);
    try std.testing.expect(final_cleanup.published);
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const completed_job = try graph.metricBuildJob(&txn, "eigenvector") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.complete, completed_job.phase);
        try std.testing.expect((try graph.metricBuildLease(&txn, "eigenvector")) == null);
        try std.testing.expect((try graph.metricBuildManifest(&txn, "eigenvector", active_job.job_id)) == null);
        try std.testing.expectError(error.NotFound, txn.get(abandoned_attempt_key));
    }

    var final_status = try graph.graphMetricStatus("eigenvector");
    defer final_status.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.fresh, final_status.state);
}

test "graph eigenvector failed planned build preserves prior published generation" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-eigenvector-planned-failure-preserves-published");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-eigenvector-planned-failure-preserves-published");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{.{
        .name = "eigenvector",
        .kind = .eigenvector,
        .refresh = .manual,
        .max_iterations = 1,
        .tolerance = 0.000001,
    }};
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    try graph.addEdge("doc-a", "doc-b", "cites", 1.0, 0, 0, "");
    try graph.addEdge("doc-c", "doc-b", "cites", 1.0, 0, 0, "");
    var published = try graph.runEigenvectorMetricPlanned("eigenvector");
    defer published.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.fresh, published.state);
    const published_generation = published.published_generation;

    const before_failure_top = try graph.graphMetricTopK("eigenvector", 10);
    defer {
        for (before_failure_top) |*score| score.deinit(alloc);
        alloc.free(before_failure_top);
    }
    try std.testing.expectEqual(@as(usize, 3), before_failure_top.len);

    try graph.addEdge("doc-new", "doc-b", "cites", 1.0, 0, 0, "");
    const rebuilding_generation = graph.edge_generation;
    try std.testing.expect(rebuilding_generation > published_generation);
    var building = try graph.ensureGraphMetricPlannedBuild("eigenvector", rebuilding_generation);
    defer building.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.building, building.state);
    try std.testing.expectEqual(rebuilding_generation, building.building_generation);

    const prepare = try graph.runGraphMetricPlannedWorkerPageStepForMetric("eigenvector", "worker-a");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.prepare_generation, prepare.phase);
    try std.testing.expect(prepare.claimed_page);
    try std.testing.expect(prepare.completed_page);
    try std.testing.expect(!prepare.advanced_phase);

    var job_id: u64 = 0;
    var score_generation: u64 = 0;
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const job = try graph.metricBuildJob(&txn, "eigenvector") orelse return error.TestExpectedGraphMetricBuildJob;
        job_id = job.job_id;
        score_generation = job.score_generation;
        try std.testing.expectEqual(building.build_job_id, job.job_id);
        try std.testing.expectEqual(rebuilding_generation, job.target_generation);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.prepare_generation, job.phase);
        _ = try graph.metricBuildManifest(&txn, "eigenvector", job_id) orelse return error.TestExpectedGraphMetricBuildManifest;
    }

    var failed = try graph.failGraphMetricPlannedBuild("eigenvector", error.InvalidGraphMetricScore);
    defer failed.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.failed, failed.state);
    try std.testing.expectEqual(published_generation, failed.published_generation);
    try std.testing.expectEqual(@as(u64, 0), failed.build_job_id);
    try std.testing.expectEqual(@as(u64, 1), failed.retry_count);
    try std.testing.expectEqualStrings("InvalidGraphMetricScore", failed.last_error);
    try std.testing.expectEqual(@as(usize, 1), failed.recent_failures.len);
    try std.testing.expectEqual(job_id, failed.recent_failures[0].job_id);

    const after_failure_top = try graph.graphMetricTopK("eigenvector", 10);
    defer {
        for (after_failure_top) |*score| score.deinit(alloc);
        alloc.free(after_failure_top);
    }
    try std.testing.expectEqual(before_failure_top.len, after_failure_top.len);
    for (before_failure_top, after_failure_top) |before, after| {
        try std.testing.expectEqualStrings(before.node, after.node);
        try std.testing.expectApproxEqAbs(before.score, after.score, 0.0000001);
        try std.testing.expect(!std.mem.eql(u8, after.node, "doc-new"));
    }

    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const failed_job = try graph.metricBuildJob(&txn, "eigenvector") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(job_id, failed_job.job_id);
        try std.testing.expectEqual(@as(u64, 1), failed_job.retry_count);
        try std.testing.expectEqualStrings("InvalidGraphMetricScore", failed_job.last_error);
        try std.testing.expect((try graph.metricBuildManifest(&txn, "eigenvector", job_id)) == null);
        try std.testing.expectEqual(@as(usize, 0), try graph.countGraphMetricScoreGeneration("eigenvector", score_generation));
    }

    try std.testing.expectError(error.GraphMetricBuildNotActive, graph.failGraphMetricPlannedBuild("eigenvector", error.InvalidGraphMetricScore));
}

