test "graph hits planned build publishes paired scores matching local runner" {
    const alloc = std.testing.allocator;
    const metrics = [_]GraphMetricConfig{
        .{
            .name = "hits_authority",
            .kind = .hits_authority,
            .refresh = .manual,
            .max_iterations = 8,
            .tolerance = 0.000001,
        },
        .{
            .name = "hits_hub",
            .kind = .hits_hub,
            .refresh = .manual,
            .max_iterations = 8,
            .tolerance = 0.000001,
        },
    };

    var local_store_buf: [256]u8 = undefined;
    const local_store_path = tmpPath(&local_store_buf, "store-hits-local-parity");
    defer cleanupTmp(local_store_path);
    var local_rev_buf: [256]u8 = undefined;
    const local_rev_path = tmpPath(&local_rev_buf, "rev-hits-local-parity");
    defer cleanupTmp(local_rev_path);

    var local_store = try docstore.DocStore.open(alloc, local_store_path, .{});
    defer local_store.close();
    var local_graph = try GraphIndex.open(alloc, &local_store, local_rev_path, "links", .{ .metric_configs = &metrics });
    defer local_graph.close();

    try local_graph.addEdge("doc-hub-a", "doc-authority", "cites", 1.0, 0, 0, "");
    try local_graph.addEdge("doc-hub-b", "doc-authority", "cites", 1.0, 0, 0, "");
    try local_graph.addEdge("doc-authority", "doc-authority", "cites", 1.0, 0, 0, "");

    var local_status = try local_graph.runGraphMetric("hits_authority");
    defer local_status.deinit(alloc);
    var local_hub_status = try local_graph.graphMetricStatus("hits_hub");
    defer local_hub_status.deinit(alloc);

    var planned_store_buf: [256]u8 = undefined;
    const planned_store_path = tmpPath(&planned_store_buf, "store-hits-planned-parity");
    defer cleanupTmp(planned_store_path);
    var planned_rev_buf: [256]u8 = undefined;
    const planned_rev_path = tmpPath(&planned_rev_buf, "rev-hits-planned-parity");
    defer cleanupTmp(planned_rev_path);

    var planned_store = try docstore.DocStore.open(alloc, planned_store_path, .{});
    defer planned_store.close();
    var planned_graph = try GraphIndex.open(alloc, &planned_store, planned_rev_path, "links", .{ .metric_configs = &metrics });
    defer planned_graph.close();

    try planned_graph.addEdge("doc-hub-a", "doc-authority", "cites", 1.0, 0, 0, "");
    try planned_graph.addEdge("doc-hub-b", "doc-authority", "cites", 1.0, 0, 0, "");
    try planned_graph.addEdge("doc-authority", "doc-authority", "cites", 1.0, 0, 0, "");

    var planned_status = try planned_graph.runHitsMetricPlanned("hits_authority");
    defer planned_status.deinit(alloc);
    var planned_hub_status = try planned_graph.graphMetricStatus("hits_hub");
    defer planned_hub_status.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.fresh, planned_status.state);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.fresh, planned_hub_status.state);
    try std.testing.expectEqual(local_status.published_generation, planned_status.published_generation);
    try std.testing.expectEqual(local_hub_status.published_generation, planned_hub_status.published_generation);
    try std.testing.expectEqual(planned_status.published_generation, planned_hub_status.published_generation);
    try std.testing.expectEqual(local_status.iterations_completed, planned_status.iterations_completed);
    try std.testing.expectEqual(local_status.converged, planned_status.converged);
    try std.testing.expectApproxEqAbs(local_status.delta, planned_status.delta, 0.0000001);
    try std.testing.expectEqual(local_hub_status.iterations_completed, planned_hub_status.iterations_completed);
    try std.testing.expectEqual(local_hub_status.converged, planned_hub_status.converged);
    try std.testing.expectApproxEqAbs(local_hub_status.delta, planned_hub_status.delta, 0.0000001);

    const local_authorities = try local_graph.graphMetricTopK("hits_authority", 10);
    defer {
        for (local_authorities) |*score| score.deinit(alloc);
        alloc.free(local_authorities);
    }
    const planned_authorities = try planned_graph.graphMetricTopK("hits_authority", 10);
    defer {
        for (planned_authorities) |*score| score.deinit(alloc);
        alloc.free(planned_authorities);
    }
    try std.testing.expectEqual(local_authorities.len, planned_authorities.len);
    for (local_authorities, planned_authorities) |local, planned| {
        try std.testing.expectEqualStrings(local.node, planned.node);
        try std.testing.expectApproxEqAbs(local.score, planned.score, 0.0000001);
    }

    const local_hubs = try local_graph.graphMetricTopK("hits_hub", 10);
    defer {
        for (local_hubs) |*score| score.deinit(alloc);
        alloc.free(local_hubs);
    }
    const planned_hubs = try planned_graph.graphMetricTopK("hits_hub", 10);
    defer {
        for (planned_hubs) |*score| score.deinit(alloc);
        alloc.free(planned_hubs);
    }
    try std.testing.expectEqual(local_hubs.len, planned_hubs.len);
    for (local_hubs, planned_hubs) |local, planned| {
        try std.testing.expectEqualStrings(local.node, planned.node);
        try std.testing.expectApproxEqAbs(local.score, planned.score, 0.0000001);
    }

    var txn = try planned_graph.beginReadReverseTxn();
    defer txn.abort();
    const job = try planned_graph.metricBuildJob(&txn, "hits_authority") orelse return error.TestExpectedGraphMetricBuildJob;
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.complete, job.phase);
}

test "graph hits active planned rebuild keeps prior published pair visible" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-hits-active-rebuild-visible-pair");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-hits-active-rebuild-visible-pair");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{
        .{
            .name = "hits_authority",
            .kind = .hits_authority,
            .refresh = .manual,
            .max_iterations = 1,
            .tolerance = 0.000001,
        },
        .{
            .name = "hits_hub",
            .kind = .hits_hub,
            .refresh = .manual,
            .max_iterations = 1,
            .tolerance = 0.000001,
        },
    };
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    try graph.addEdge("doc-hub-a", "doc-authority", "cites", 1.0, 0, 0, "");
    try graph.addEdge("doc-hub-b", "doc-authority", "cites", 1.0, 0, 0, "");
    try graph.addEdge("doc-authority", "doc-authority", "cites", 1.0, 0, 0, "");

    var published = try graph.runHitsMetricPlanned("hits_authority");
    defer published.deinit(alloc);
    var published_hub = try graph.graphMetricStatus("hits_hub");
    defer published_hub.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.fresh, published.state);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.fresh, published_hub.state);
    try std.testing.expectEqual(published.published_generation, published_hub.published_generation);
    const published_generation = published.published_generation;

    const before_authorities = try graph.graphMetricTopK("hits_authority", 10);
    defer {
        for (before_authorities) |*score| score.deinit(alloc);
        alloc.free(before_authorities);
    }
    const before_hubs = try graph.graphMetricTopK("hits_hub", 10);
    defer {
        for (before_hubs) |*score| score.deinit(alloc);
        alloc.free(before_hubs);
    }
    try std.testing.expectEqual(@as(usize, 3), before_authorities.len);
    try std.testing.expectEqual(@as(usize, 3), before_hubs.len);

    try graph.addEdge("doc-new-hub", "doc-new-authority", "cites", 1.0, 0, 0, "");
    const rebuilding_generation = graph.edge_generation;
    try std.testing.expect(rebuilding_generation > published_generation);

    var started = try graph.ensureGraphMetricPlannedBuild("hits_authority", rebuilding_generation);
    defer started.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.building, started.state);
    try std.testing.expectEqual(rebuilding_generation, started.building_generation);

    var job_id: u64 = 0;
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const job = try graph.metricBuildJob(&txn, "hits_authority") orelse return error.TestExpectedGraphMetricBuildJob;
        job_id = job.job_id;
        try std.testing.expectEqual(started.build_job_id, job.job_id);
    }

    inline for (.{ .prepare_generation, .scan_edges_and_out_degree, .initialize_ranks, .iterate_contributions, .reduce_ranks, .hits_hub_contributions, .hits_hub_reduce_ranks }) |expected_phase| {
        while (true) {
            const step = try graph.runGraphMetricPlannedWorkerStep("hits_authority", metrics[0], "worker-rebuild");
            try std.testing.expectEqual(expected_phase, step.phase);
            try std.testing.expect(step.claimed_page);
            try std.testing.expect(step.completed_page);
            try std.testing.expect(!step.published);
            if (step.advanced_phase) break;
        }
    }

    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const job = try graph.metricBuildJob(&txn, "hits_authority") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.check_convergence, job.phase);
        const new_authority_key = try graph.graphMetricBuildHitsRankKeyAlloc("hits_authority", job_id, "authority", 1, "doc-new-authority");
        defer alloc.free(new_authority_key);
        try std.testing.expect((try txn.get(new_authority_key)).len >= 8);
        const new_hub_key = try graph.graphMetricBuildHitsRankKeyAlloc("hits_authority", job_id, "hub", 1, "doc-new-hub");
        defer alloc.free(new_hub_key);
        try std.testing.expect((try txn.get(new_hub_key)).len >= 8);
    }

    var rebuilding_authority = try graph.graphMetricStatus("hits_authority");
    defer rebuilding_authority.deinit(alloc);
    var rebuilding_hub = try graph.graphMetricStatus("hits_hub");
    defer rebuilding_hub.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.building, rebuilding_authority.state);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.check_convergence, rebuilding_authority.phase);
    try std.testing.expectEqual(published_generation, rebuilding_authority.published_generation);
    try std.testing.expectEqual(published_generation, rebuilding_hub.published_generation);

    const visible_authorities = try graph.graphMetricTopK("hits_authority", 10);
    defer {
        for (visible_authorities) |*score| score.deinit(alloc);
        alloc.free(visible_authorities);
    }
    const visible_hubs = try graph.graphMetricTopK("hits_hub", 10);
    defer {
        for (visible_hubs) |*score| score.deinit(alloc);
        alloc.free(visible_hubs);
    }
    try std.testing.expectEqual(before_authorities.len, visible_authorities.len);
    for (before_authorities, visible_authorities) |before, after| {
        try std.testing.expectEqualStrings(before.node, after.node);
        try std.testing.expectApproxEqAbs(before.score, after.score, 0.0000001);
        try std.testing.expect(!std.mem.eql(u8, after.node, "doc-new-authority"));
        try std.testing.expect(!std.mem.eql(u8, after.node, "doc-new-hub"));
    }
    try std.testing.expectEqual(before_hubs.len, visible_hubs.len);
    for (before_hubs, visible_hubs) |before, after| {
        try std.testing.expectEqualStrings(before.node, after.node);
        try std.testing.expectApproxEqAbs(before.score, after.score, 0.0000001);
        try std.testing.expect(!std.mem.eql(u8, after.node, "doc-new-authority"));
        try std.testing.expect(!std.mem.eql(u8, after.node, "doc-new-hub"));
    }
}

test "graph hits reclaimed scan page overwrites stale partial output" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-hits-scan-reclaim");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-hits-scan-reclaim");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{
        .{
            .name = "hits_authority",
            .kind = .hits_authority,
            .refresh = .manual,
            .max_iterations = 1,
            .tolerance = 0.000001,
        },
        .{
            .name = "hits_hub",
            .kind = .hits_hub,
            .refresh = .manual,
            .max_iterations = 1,
            .tolerance = 0.000001,
        },
    };
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    try graph.addEdge("doc-hub", "doc-authority-a", "cites", 1.0, 0, 0, "");
    try graph.addEdge("doc-hub", "doc-authority-b", "cites", 1.0, 0, 0, "");
    try graph.acquireGraphMetricBuildLease("hits_authority", graph.edge_generation);
    defer graph.releaseGraphMetricBuildLease("hits_authority") catch {};

    var job_txn = try graph.beginReadReverseTxn();
    const active_job = try graph.metricBuildJob(&job_txn, "hits_authority") orelse return error.TestExpectedGraphMetricBuildJob;
    job_txn.abort();

    const prepare = try graph.runGraphMetricPlannedWorkerStep("hits_authority", metrics[0], "worker-setup");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.prepare_generation, prepare.phase);
    try std.testing.expect(prepare.completed_page);
    try std.testing.expect(prepare.advanced_phase);

    const partial_scan_claim = try graph.claimGraphMetricBuildPageAt("hits_authority", active_job.job_id, .scan_edges_and_out_degree, 0, 1, "worker-a", 2000) orelse return error.TestExpectedGraphMetricBuildPage;
    _ = try graph.executePageRankScanBuildPageWithLimit("hits_authority", metrics[0], active_job, partial_scan_claim, 1);
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "hits_authority", active_job.job_id, .scan_edges_and_out_degree, 0, 1) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, page.state);
        try std.testing.expectEqual(@as(u64, 1), page.completed_units);
        try std.testing.expect(page.cursor.len > 0);

        const partial_out_degree = try graph.aggregatePageRankOutDegreeForNode(&txn, "hits_authority", active_job.job_id, "doc-hub");
        try std.testing.expectEqual(@as(u64, 0), partial_out_degree);
        const attempt_out_degree_key = try graph.graphMetricBuildAttemptPageRankOutDegreePartialKeyAlloc("hits_authority", active_job.job_id, .scan_edges_and_out_degree, 0, partial_scan_claim.page_id, partial_scan_claim.attempt, "doc-hub");
        defer alloc.free(attempt_out_degree_key);
        try std.testing.expectEqual(@as(u64, 1), try GraphIndex.readU64OrZero(&txn, attempt_out_degree_key));
        const node_authority_a_key = try graph.graphMetricBuildPageRankNodePartialKeyAlloc("hits_authority", active_job.job_id, "doc-authority-a", 1);
        defer alloc.free(node_authority_a_key);
        try std.testing.expectError(error.NotFound, txn.get(node_authority_a_key));
        const attempt_node_authority_a_key = try graph.graphMetricBuildAttemptPageRankNodePartialKeyAlloc("hits_authority", active_job.job_id, .scan_edges_and_out_degree, 0, partial_scan_claim.page_id, partial_scan_claim.attempt, "doc-authority-a");
        defer alloc.free(attempt_node_authority_a_key);
        try std.testing.expectEqual(@as(u64, 1), try GraphIndex.readU64OrZero(&txn, attempt_node_authority_a_key));
    }

    const scan_expires_at = blk: {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "hits_authority", active_job.job_id, .scan_edges_and_out_degree, 0, 1) orelse return error.TestExpectedGraphMetricBuildPage;
        break :blk page.lease_expires_at_ms;
    };
    const reclaimed_scan = try graph.claimGraphMetricBuildPageAt("hits_authority", active_job.job_id, .scan_edges_and_out_degree, 0, 1, "worker-b", scan_expires_at + 1) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, reclaimed_scan.state);
    try std.testing.expectEqual(@as(u64, 2), reclaimed_scan.attempt);
    try std.testing.expectEqual(@as(u64, 0), reclaimed_scan.completed_units);
    try std.testing.expectEqualStrings("", reclaimed_scan.cursor);
    {
        var stale_out_degrees = std.StringHashMapUnmanaged(u64).empty;
        defer {
            var key_it = stale_out_degrees.keyIterator();
            while (key_it.next()) |key_ptr| alloc.free(key_ptr.*);
            stale_out_degrees.deinit(alloc);
        }
        var stale_nodes = std.StringHashMapUnmanaged(void).empty;
        defer {
            var key_it = stale_nodes.keyIterator();
            while (key_it.next()) |key_ptr| alloc.free(key_ptr.*);
            stale_nodes.deinit(alloc);
        }
        try stale_out_degrees.put(alloc, try alloc.dupe(u8, "doc-hub"), 99);
        try stale_nodes.put(alloc, try alloc.dupe(u8, "doc-stale"), {});
        try std.testing.expectError(error.GraphMetricBuildPageNotLeased, graph.writePageRankScanPartialsForAttempt("hits_authority", active_job, partial_scan_claim, 0, &stale_out_degrees, &stale_nodes, false));
    }
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const stale_node_key = try graph.graphMetricBuildPageRankNodePartialKeyAlloc("hits_authority", active_job.job_id, "doc-stale", 1);
        defer alloc.free(stale_node_key);
        try std.testing.expectError(error.NotFound, txn.get(stale_node_key));
        const partial_out_degree = try graph.aggregatePageRankOutDegreeForNode(&txn, "hits_authority", active_job.job_id, "doc-hub");
        try std.testing.expectEqual(@as(u64, 0), partial_out_degree);
    }

    _ = try graph.executePageRankScanBuildPageWithLimit("hits_authority", metrics[0], active_job, reclaimed_scan, null);
    try std.testing.expect(try graph.advanceGraphMetricBuildPhaseIfReady("hits_authority", active_job.job_id, .scan_edges_and_out_degree, 0));
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "hits_authority", active_job.job_id, .scan_edges_and_out_degree, 0, 1) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.complete, page.state);
        try std.testing.expectEqual(page.total_units, page.completed_units);

        const out_degree = try graph.aggregatePageRankOutDegreeForNode(&txn, "hits_authority", active_job.job_id, "doc-hub");
        try std.testing.expectEqual(@as(u64, 2), out_degree);
        inline for (.{ "doc-hub", "doc-authority-a", "doc-authority-b" }) |node| {
            const node_key = try graph.graphMetricBuildPageRankNodePartialKeyAlloc("hits_authority", active_job.job_id, node, 1);
            defer alloc.free(node_key);
            try std.testing.expectEqual(@as(u64, 1), try GraphIndex.readU64OrZero(&txn, node_key));
        }
        const job = try graph.metricBuildJob(&txn, "hits_authority") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.initialize_ranks, job.phase);
    }
}

