test "graph hits reduce pages only write their planned node range" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-hits-reduce-page-range");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-hits-reduce-page-range");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{
        .{
            .name = "hits_authority",
            .kind = .hits_authority,
            .refresh = .manual,
            .max_iterations = 1,
            .tolerance = 0.000001,
        },
        .{
            .name = "hits_hub",
            .kind = .hits_hub,
            .refresh = .manual,
            .max_iterations = 1,
            .tolerance = 0.000001,
        },
    };
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    var source_buf: [64]u8 = undefined;
    var source_count: usize = 0;
    while (source_count < graph_metric_build_target_reduce_page_units + 1) : (source_count += 1) {
        const source = try std.fmt.bufPrint(&source_buf, "doc-hub-{d:0>3}", .{source_count});
        try graph.addEdge(source, "doc-authority", "cites", 1.0, 0, 0, "");
    }
    try graph.addEdge("doc-hub-000", "doc-target-only", "cites", 1.0, 0, 0, "");
    try graph.addEdge("doc-authority", "doc-authority", "cites", 1.0, 0, 0, "");
    try graph.acquireGraphMetricBuildLease("hits_authority", graph.edge_generation);

    var job_txn = try graph.beginReadReverseTxn();
    const active_job = try graph.metricBuildJob(&job_txn, "hits_authority") orelse return error.TestExpectedGraphMetricBuildJob;
    job_txn.abort();

    inline for (.{ .prepare_generation, .scan_edges_and_out_degree, .initialize_ranks, .iterate_contributions }) |expected_phase| {
        while (true) {
            const step = try graph.runGraphMetricPlannedWorkerStep("hits_authority", metrics[0], "worker-a");
            try std.testing.expectEqual(expected_phase, step.phase);
            try std.testing.expect(step.claimed_page);
            try std.testing.expect(step.completed_page);
            if (step.advanced_phase) break;
        }
    }

    const first_reduce = try graph.claimNextGraphMetricBuildPageAt("hits_authority", active_job.job_id, .reduce_ranks, 0, "worker-r1", 3000) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(@as(u64, 4), first_reduce.page_id);
    var first_reduce_range_lower: []u8 = "";
    defer if (first_reduce_range_lower.len > 0) alloc.free(first_reduce_range_lower);
    var first_reduce_range_upper: []u8 = "";
    defer if (first_reduce_range_upper.len > 0) alloc.free(first_reduce_range_upper);
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const persisted_first_reduce = try graph.metricBuildPage(&txn, "hits_authority", active_job.job_id, .reduce_ranks, 0, first_reduce.page_id) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageRangeKind.nodes, persisted_first_reduce.range_kind);
        try std.testing.expect(persisted_first_reduce.range_upper.len > 0);
        if (persisted_first_reduce.range_lower.len > 0) first_reduce_range_lower = try alloc.dupe(u8, persisted_first_reduce.range_lower);
        if (persisted_first_reduce.range_upper.len > 0) first_reduce_range_upper = try alloc.dupe(u8, persisted_first_reduce.range_upper);
    }

    var nodes = std.ArrayListUnmanaged([]u8).empty;
    defer {
        for (nodes.items) |node| alloc.free(node);
        nodes.deinit(alloc);
    }
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        try graph.collectPageRankScannedNodes(&txn, "hits_authority", active_job.job_id, &nodes);
    }
    var first_page_node: []const u8 = "";
    var second_page_node: []const u8 = "";
    for (nodes.items) |node| {
        if (first_page_node.len == 0 and
            (first_reduce_range_lower.len == 0 or std.mem.order(u8, node, first_reduce_range_lower) != .lt) and
            (first_reduce_range_upper.len == 0 or std.mem.order(u8, node, first_reduce_range_upper) == .lt))
        {
            first_page_node = node;
        }
        if (second_page_node.len == 0 and first_reduce_range_upper.len > 0 and std.mem.order(u8, node, first_reduce_range_upper) != .lt) {
            second_page_node = node;
        }
    }
    try std.testing.expect(first_page_node.len > 0);
    try std.testing.expect(second_page_node.len > 0);

    _ = try graph.executeHitsReduceBuildPage("hits_authority", metrics[0], active_job, first_reduce);
    try std.testing.expect(!(try graph.advanceGraphMetricBuildPhaseIfReady("hits_authority", active_job.job_id, .reduce_ranks, 0)));
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const first_authority_key = try graph.graphMetricBuildHitsRankKeyAlloc("hits_authority", active_job.job_id, "authority", 1, first_page_node);
        defer alloc.free(first_authority_key);
        const first_hub_key = try graph.graphMetricBuildHitsRankKeyAlloc("hits_authority", active_job.job_id, "hub", 1, first_page_node);
        defer alloc.free(first_hub_key);
        const second_authority_key = try graph.graphMetricBuildHitsRankKeyAlloc("hits_authority", active_job.job_id, "authority", 1, second_page_node);
        defer alloc.free(second_authority_key);
        const second_hub_key = try graph.graphMetricBuildHitsRankKeyAlloc("hits_authority", active_job.job_id, "hub", 1, second_page_node);
        defer alloc.free(second_hub_key);
        try std.testing.expect((try txn.get(first_authority_key)).len >= 8);
        try std.testing.expectError(error.NotFound, txn.get(first_hub_key));
        try std.testing.expectError(error.NotFound, txn.get(second_authority_key));
        try std.testing.expectError(error.NotFound, txn.get(second_hub_key));

        var first_reduce_count: usize = 0;
        var first_reduce_contribution_sum: f64 = 0.0;
        var first_reduce_rank_sum: f64 = 0.0;
        for (nodes.items) |node| {
            if (first_reduce_range_lower.len > 0 and std.mem.order(u8, node, first_reduce_range_lower) == .lt) continue;
            if (first_reduce_range_upper.len > 0 and std.mem.order(u8, node, first_reduce_range_upper) != .lt) continue;
            const authority_key = try graph.graphMetricBuildHitsRankKeyAlloc("hits_authority", active_job.job_id, "authority", 1, node);
            defer alloc.free(authority_key);
            const authority = try GraphIndex.readF64OrZero(&txn, authority_key);
            first_reduce_contribution_sum += authority;
            first_reduce_rank_sum += authority;
            first_reduce_count += 1;
        }
        try std.testing.expect(first_reduce_count > 0);
        const persisted_first_reduce = try graph.metricBuildPage(&txn, "hits_authority", active_job.job_id, .reduce_ranks, 0, first_reduce.page_id) orelse return error.TestExpectedGraphMetricBuildPage;
        const generic_reduce_fingerprint = GraphIndex.graphMetricPageRankReduceFingerprint(first_reduce, first_reduce_count, first_reduce_contribution_sum, first_reduce_rank_sum);
        try std.testing.expectEqual(generic_reduce_fingerprint, persisted_first_reduce.output_fingerprint);
    }

    graph.close();
    graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });

    const second_reduce = try graph.claimNextGraphMetricBuildPageAt("hits_authority", active_job.job_id, .reduce_ranks, 0, "worker-r2", 3001) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(@as(u64, 5), second_reduce.page_id);
    _ = try graph.executeHitsReduceBuildPage("hits_authority", metrics[0], active_job, second_reduce);
    try std.testing.expect(try graph.advanceGraphMetricBuildPhaseIfReady("hits_authority", active_job.job_id, .reduce_ranks, 0));
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const second_authority_key = try graph.graphMetricBuildHitsRankKeyAlloc("hits_authority", active_job.job_id, "authority", 1, second_page_node);
        defer alloc.free(second_authority_key);
        const second_hub_key = try graph.graphMetricBuildHitsRankKeyAlloc("hits_authority", active_job.job_id, "hub", 1, second_page_node);
        defer alloc.free(second_hub_key);
        try std.testing.expect((try txn.get(second_authority_key)).len >= 8);
        try std.testing.expectError(error.NotFound, txn.get(second_hub_key));
        const job = try graph.metricBuildJob(&txn, "hits_authority") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.hits_hub_contributions, job.phase);
    }

    while (true) {
        const step = try graph.runGraphMetricPlannedWorkerStep("hits_authority", metrics[0], "worker-hub-c");
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.hits_hub_contributions, step.phase);
        try std.testing.expect(step.claimed_page);
        try std.testing.expect(step.completed_page);
        if (step.advanced_phase) break;
    }
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const first_hub_raw_key = try graph.graphMetricBuildHitsHubRawKeyAlloc("hits_authority", active_job.job_id, 0, first_page_node);
        defer alloc.free(first_hub_raw_key);
        const second_hub_raw_key = try graph.graphMetricBuildHitsHubRawKeyAlloc("hits_authority", active_job.job_id, 0, second_page_node);
        defer alloc.free(second_hub_raw_key);
        try std.testing.expect((try txn.get(first_hub_raw_key)).len >= 8);
        try std.testing.expect((try txn.get(second_hub_raw_key)).len >= 8);
        const job = try graph.metricBuildJob(&txn, "hits_authority") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.hits_hub_reduce_ranks, job.phase);
    }

    const first_hub_reduce = try graph.claimNextGraphMetricBuildPageAt("hits_authority", active_job.job_id, .hits_hub_reduce_ranks, 0, "worker-hr1", 4000) orelse return error.TestExpectedGraphMetricBuildPage;
    var first_hub_reduce_count: usize = 0;
    var first_hub_reduce_raw_sum: f64 = 0.0;
    var first_hub_reduce_rank_sum: f64 = 0.0;
    _ = try graph.executeHitsHubReduceBuildPage("hits_authority", metrics[0], active_job, first_hub_reduce);
    try std.testing.expect(!(try graph.advanceGraphMetricBuildPhaseIfReady("hits_authority", active_job.job_id, .hits_hub_reduce_ranks, 0)));
    var original_hub_raw_summary_count: usize = 0;
    var original_hub_raw_summary_norm: f64 = 0.0;
    var original_hub_raw_summary_raw_fingerprint: u64 = 0;
    var original_hub_raw_summary_fingerprint: u64 = 0;
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const first_hub_key = try graph.graphMetricBuildHitsRankKeyAlloc("hits_authority", active_job.job_id, "hub", 1, first_page_node);
        defer alloc.free(first_hub_key);
        const second_hub_key = try graph.graphMetricBuildHitsRankKeyAlloc("hits_authority", active_job.job_id, "hub", 1, second_page_node);
        defer alloc.free(second_hub_key);
        try std.testing.expect((try txn.get(first_hub_key)).len >= 8);
        try std.testing.expectError(error.NotFound, txn.get(second_hub_key));
        const summary = try graph.hitsHubRawSummary(&txn, "hits_authority", active_job.job_id, 0) orelse return error.TestExpectedGraphMetricBuildPhaseSummary;
        try std.testing.expect(summary.count > 0);
        try std.testing.expect(summary.norm > 0.0);
        try std.testing.expect(summary.raw_fingerprint != 0);
        try std.testing.expect(summary.fingerprint != 0);
        original_hub_raw_summary_count = summary.count;
        original_hub_raw_summary_norm = summary.norm;
        original_hub_raw_summary_raw_fingerprint = summary.raw_fingerprint;
        original_hub_raw_summary_fingerprint = summary.fingerprint;
        for (nodes.items) |node| {
            if (first_reduce_range_lower.len > 0 and std.mem.order(u8, node, first_reduce_range_lower) == .lt) continue;
            if (first_reduce_range_upper.len > 0 and std.mem.order(u8, node, first_reduce_range_upper) != .lt) continue;
            const raw_hub = try graph.readHitsHubRawForNode(&txn, "hits_authority", active_job.job_id, 0, node);
            const hub_key = try graph.graphMetricBuildHitsRankKeyAlloc("hits_authority", active_job.job_id, "hub", 1, node);
            defer alloc.free(hub_key);
            const hub = try GraphIndex.readF64OrZero(&txn, hub_key);
            first_hub_reduce_raw_sum += raw_hub;
            first_hub_reduce_rank_sum += hub;
            first_hub_reduce_count += 1;
        }
        const persisted_first_hub_reduce = try graph.metricBuildPage(&txn, "hits_authority", active_job.job_id, .hits_hub_reduce_ranks, 0, first_hub_reduce.page_id) orelse return error.TestExpectedGraphMetricBuildPage;
        const hits_reduce_fingerprint = GraphIndex.graphMetricHitsReduceFingerprint(first_hub_reduce, first_hub_reduce_count, first_hub_reduce_raw_sum, first_hub_reduce_rank_sum, summary);
        try std.testing.expectEqual(hits_reduce_fingerprint, persisted_first_hub_reduce.output_fingerprint);
    }
    {
        var batch = try graph.beginWriteReverseBatch();
        errdefer batch.abort();
        try graph.putHitsHubRawSummaryInBatch(&batch, "hits_authority", active_job.job_id, 0, .{
            .count = original_hub_raw_summary_count,
            .norm = original_hub_raw_summary_norm,
            .raw_fingerprint = original_hub_raw_summary_raw_fingerprint,
            .fingerprint = original_hub_raw_summary_fingerprint ^ 0xA5A5_A5A5_A5A5_A5A5,
        });
        try batch.commit();
    }
    graph.close();
    graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });

    const second_hub_reduce = try graph.claimNextGraphMetricBuildPageAt("hits_authority", active_job.job_id, .hits_hub_reduce_ranks, 0, "worker-hr2", 4001) orelse return error.TestExpectedGraphMetricBuildPage;
    _ = try graph.executeHitsHubReduceBuildPage("hits_authority", metrics[0], active_job, second_hub_reduce);
    try std.testing.expect(try graph.advanceGraphMetricBuildPhaseIfReady("hits_authority", active_job.job_id, .hits_hub_reduce_ranks, 0));
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const second_hub_key = try graph.graphMetricBuildHitsRankKeyAlloc("hits_authority", active_job.job_id, "hub", 1, second_page_node);
        defer alloc.free(second_hub_key);
        try std.testing.expect((try txn.get(second_hub_key)).len >= 8);
        const summary = try graph.hitsHubRawSummary(&txn, "hits_authority", active_job.job_id, 0) orelse return error.TestExpectedGraphMetricBuildPhaseSummary;
        try std.testing.expectEqual(original_hub_raw_summary_count, summary.count);
        try std.testing.expectApproxEqAbs(original_hub_raw_summary_norm, summary.norm, 0.0000001);
        try std.testing.expectEqual(original_hub_raw_summary_raw_fingerprint, summary.raw_fingerprint);
        try std.testing.expectEqual(original_hub_raw_summary_fingerprint, summary.fingerprint);
        const job = try graph.metricBuildJob(&txn, "hits_authority") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.check_convergence, job.phase);
    }
}

test "graph hits planned build drains partitioned paired pages across workers" {
    const alloc = std.testing.allocator;
    const metrics = [_]GraphMetricConfig{
        .{
            .name = "hits_authority",
            .kind = .hits_authority,
            .refresh = .manual,
            .max_iterations = 1,
            .tolerance = 0.000001,
        },
        .{
            .name = "hits_hub",
            .kind = .hits_hub,
            .refresh = .manual,
            .max_iterations = 1,
            .tolerance = 0.000001,
        },
    };

    var local_store_buf: [256]u8 = undefined;
    const local_store_path = tmpPath(&local_store_buf, "store-hits-local-multi-worker");
    defer cleanupTmp(local_store_path);
    var local_rev_buf: [256]u8 = undefined;
    const local_rev_path = tmpPath(&local_rev_buf, "rev-hits-local-multi-worker");
    defer cleanupTmp(local_rev_path);
    var local_store = try docstore.DocStore.open(alloc, local_store_path, .{});
    defer local_store.close();
    var local_graph = try GraphIndex.open(alloc, &local_store, local_rev_path, "links", .{ .metric_configs = &metrics });
    defer local_graph.close();

    for (0..graph_metric_build_target_scan_page_units + 1) |i| {
        var source_buf: [64]u8 = undefined;
        const source = try std.fmt.bufPrint(&source_buf, "doc-hub-{d:0>3}", .{i});
        try local_graph.addEdge(source, "doc-authority", "cites", 1.0, 0, 0, "");
    }
    try local_graph.addEdge("doc-authority", "doc-authority", "cites", 1.0, 0, 0, "");

    var local_status = try local_graph.runGraphMetric("hits_authority");
    defer local_status.deinit(alloc);
    var local_hub_status = try local_graph.graphMetricStatus("hits_hub");
    defer local_hub_status.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.fresh, local_status.state);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.fresh, local_hub_status.state);
    try std.testing.expectEqual(local_status.published_generation, local_hub_status.published_generation);

    var planned_store_buf: [256]u8 = undefined;
    const planned_store_path = tmpPath(&planned_store_buf, "store-hits-planned-multi-worker");
    defer cleanupTmp(planned_store_path);
    var planned_rev_buf: [256]u8 = undefined;
    const planned_rev_path = tmpPath(&planned_rev_buf, "rev-hits-planned-multi-worker");
    defer cleanupTmp(planned_rev_path);
    var planned_store = try docstore.DocStore.open(alloc, planned_store_path, .{});
    defer planned_store.close();
    var planned_graph = try GraphIndex.open(alloc, &planned_store, planned_rev_path, "links", .{ .metric_configs = &metrics });
    defer planned_graph.close();

    for (0..graph_metric_build_target_scan_page_units + 1) |i| {
        var source_buf: [64]u8 = undefined;
        const source = try std.fmt.bufPrint(&source_buf, "doc-hub-{d:0>3}", .{i});
        try planned_graph.addEdge(source, "doc-authority", "cites", 1.0, 0, 0, "");
    }
    try planned_graph.addEdge("doc-authority", "doc-authority", "cites", 1.0, 0, 0, "");

    try planned_graph.acquireGraphMetricBuildLease("hits_authority", planned_graph.edge_generation);
    defer planned_graph.releaseGraphMetricBuildLease("hits_authority") catch {};

    var job_txn = try planned_graph.beginReadReverseTxn();
    const active_job = try planned_graph.metricBuildJob(&job_txn, "hits_authority") orelse return error.TestExpectedGraphMetricBuildJob;
    job_txn.abort();

    {
        var txn = try planned_graph.beginReadReverseTxn();
        defer txn.abort();
        const manifest = try planned_graph.metricBuildManifest(&txn, "hits_authority", active_job.job_id) orelse return error.TestExpectedGraphMetricBuildManifest;
        try std.testing.expect(manifest.page_count > GraphIndex.graph_metric_iterative_build_phases.len);
        _ = try planned_graph.metricBuildPage(&txn, "hits_authority", active_job.job_id, .scan_edges_and_out_degree, 0, 1) orelse return error.TestExpectedGraphMetricBuildPage;
        _ = try planned_graph.metricBuildPage(&txn, "hits_authority", active_job.job_id, .scan_edges_and_out_degree, 0, 2) orelse return error.TestExpectedGraphMetricBuildPage;
        _ = try planned_graph.metricBuildPage(&txn, "hits_authority", active_job.job_id, .reduce_ranks, 0, 4) orelse return error.TestExpectedGraphMetricBuildPage;
        _ = try planned_graph.metricBuildPage(&txn, "hits_authority", active_job.job_id, .reduce_ranks, 0, 5) orelse return error.TestExpectedGraphMetricBuildPage;
    }

    var worker_a_completed: usize = 0;
    var worker_b_completed: usize = 0;
    var completed = false;
    var steps: usize = 0;
    while (steps < 240) : (steps += 1) {
        const worker_id = if (steps % 2 == 0) "worker-a" else "worker-b";
        const step = try planned_graph.runGraphMetricPlannedWorkerStep("hits_authority", metrics[0], worker_id);
        if (step.completed_page) {
            if (std.mem.eql(u8, worker_id, "worker-a")) {
                worker_a_completed += 1;
            } else {
                worker_b_completed += 1;
            }
        }
        if (step.completed_build and step.phase == .cleanup_old_generations) {
            completed = true;
            break;
        }
        if (!step.claimed_page and !step.advanced_phase and step.phase != .cleanup_old_generations) {
            return error.TestExpectedGraphMetricBuildProgress;
        }
    }
    try std.testing.expect(completed);
    try std.testing.expect(worker_a_completed > 0);
    try std.testing.expect(worker_b_completed > 0);

    var planned_status = try planned_graph.graphMetricStatus("hits_authority");
    defer planned_status.deinit(alloc);
    var planned_hub_status = try planned_graph.graphMetricStatus("hits_hub");
    defer planned_hub_status.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.fresh, planned_status.state);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.fresh, planned_hub_status.state);
    try std.testing.expectEqual(local_status.published_generation, planned_status.published_generation);
    try std.testing.expectEqual(local_hub_status.published_generation, planned_hub_status.published_generation);
    try std.testing.expectEqual(planned_status.published_generation, planned_hub_status.published_generation);
    try std.testing.expectEqual(local_status.iterations_completed, planned_status.iterations_completed);
    try std.testing.expectEqual(local_hub_status.iterations_completed, planned_hub_status.iterations_completed);
    try std.testing.expectEqual(local_status.converged, planned_status.converged);
    try std.testing.expectEqual(local_hub_status.converged, planned_hub_status.converged);
    try std.testing.expectApproxEqAbs(local_status.delta, planned_status.delta, 0.0000001);
    try std.testing.expectApproxEqAbs(local_hub_status.delta, planned_hub_status.delta, 0.0000001);

    {
        var txn = try planned_graph.beginReadReverseTxn();
        defer txn.abort();
        const completed_job = try planned_graph.metricBuildJob(&txn, "hits_authority") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(active_job.job_id, completed_job.job_id);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.complete, completed_job.phase);
        try std.testing.expect((try planned_graph.metricBuildLease(&txn, "hits_authority")) == null);
        try std.testing.expect((try planned_graph.metricBuildManifest(&txn, "hits_authority", active_job.job_id)) == null);
    }

    const top_limit: usize = @intCast(planned_graph.node_count);
    const local_authorities = try local_graph.graphMetricTopK("hits_authority", top_limit);
    defer {
        for (local_authorities) |*score| score.deinit(alloc);
        alloc.free(local_authorities);
    }
    const planned_authorities = try planned_graph.graphMetricTopK("hits_authority", top_limit);
    defer {
        for (planned_authorities) |*score| score.deinit(alloc);
        alloc.free(planned_authorities);
    }
    try std.testing.expectEqual(local_authorities.len, planned_authorities.len);
    for (local_authorities, planned_authorities) |local, planned| {
        try std.testing.expectEqualStrings(local.node, planned.node);
        try std.testing.expectApproxEqAbs(local.score, planned.score, 0.0000001);
    }

    const local_hubs = try local_graph.graphMetricTopK("hits_hub", top_limit);
    defer {
        for (local_hubs) |*score| score.deinit(alloc);
        alloc.free(local_hubs);
    }
    const planned_hubs = try planned_graph.graphMetricTopK("hits_hub", top_limit);
    defer {
        for (planned_hubs) |*score| score.deinit(alloc);
        alloc.free(planned_hubs);
    }
    try std.testing.expectEqual(local_hubs.len, planned_hubs.len);
    for (local_hubs, planned_hubs) |local, planned| {
        try std.testing.expectEqualStrings(local.node, planned.node);
        try std.testing.expectApproxEqAbs(local.score, planned.score, 0.0000001);
    }
}

fn expectGraphMetricBuildPhasePageCountAtLeastForTest(
    graph: *GraphIndex,
    txn: anytype,
    metric_name: []const u8,
    job_id: u64,
    phase: GraphIndex.GraphMetricBuildPhase,
    iteration: u32,
    min_pages: usize,
) !void {
    const prefix = try graph.graphMetricBuildPagePrefixAlloc(metric_name, job_id, phase, iteration);
    defer graph.alloc.free(prefix);
    var cursor = try txn.openCursor();
    defer cursor.close();
    var count: usize = 0;
    var entry_opt = try cursor.first();
    while (entry_opt) |entry| : (entry_opt = try cursor.next()) {
        if (std.mem.startsWith(u8, entry.key, prefix)) count += 1;
    }
    try std.testing.expect(count >= min_pages);
}

test "graph hits larger manifest resumes across reopen boundaries" {
    const alloc = std.testing.allocator;
    const metrics = [_]GraphMetricConfig{
        .{
            .name = "hits_authority",
            .kind = .hits_authority,
            .refresh = .manual,
            .max_iterations = 2,
            .tolerance = 0.0,
        },
        .{
            .name = "hits_hub",
            .kind = .hits_hub,
            .refresh = .manual,
            .max_iterations = 2,
            .tolerance = 0.0,
        },
    };

    var local_store_buf: [256]u8 = undefined;
    const local_store_path = tmpPath(&local_store_buf, "store-hits-local-large-manifest-reopen");
    defer cleanupTmp(local_store_path);
    var local_rev_buf: [256]u8 = undefined;
    const local_rev_path = tmpPath(&local_rev_buf, "rev-hits-local-large-manifest-reopen");
    defer cleanupTmp(local_rev_path);
    var local_store = try docstore.DocStore.open(alloc, local_store_path, .{});
    defer local_store.close();
    var local_graph = try GraphIndex.open(alloc, &local_store, local_rev_path, "links", .{ .metric_configs = &metrics });
    defer local_graph.close();

    for (0..graph_metric_build_target_scan_page_units + 9) |i| {
        var source_buf: [64]u8 = undefined;
        const source = try std.fmt.bufPrint(&source_buf, "doc-hub-{d:0>3}", .{i});
        try local_graph.addEdge(source, "doc-authority", "cites", 1.0, 0, 0, "");
    }
    try local_graph.addEdge("doc-authority", "doc-authority", "cites", 1.0, 0, 0, "");

    var local_status = try local_graph.runGraphMetric("hits_authority");
    defer local_status.deinit(alloc);
    var local_hub_status = try local_graph.graphMetricStatus("hits_hub");
    defer local_hub_status.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.fresh, local_status.state);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.fresh, local_hub_status.state);
    try std.testing.expectEqual(local_status.published_generation, local_hub_status.published_generation);
    try std.testing.expectEqual(@as(u32, 2), local_status.iterations_completed);
    try std.testing.expectEqual(local_status.iterations_completed, local_hub_status.iterations_completed);

    var planned_store_buf: [256]u8 = undefined;
    const planned_store_path = tmpPath(&planned_store_buf, "store-hits-planned-large-manifest-reopen");
    defer cleanupTmp(planned_store_path);
    var planned_rev_buf: [256]u8 = undefined;
    const planned_rev_path = tmpPath(&planned_rev_buf, "rev-hits-planned-large-manifest-reopen");
    defer cleanupTmp(planned_rev_path);
    var planned_store = try docstore.DocStore.open(alloc, planned_store_path, .{});
    defer planned_store.close();
    var planned_graph = try GraphIndex.open(alloc, &planned_store, planned_rev_path, "links", .{ .metric_configs = &metrics });
    defer planned_graph.close();

    for (0..graph_metric_build_target_scan_page_units + 9) |i| {
        var source_buf: [64]u8 = undefined;
        const source = try std.fmt.bufPrint(&source_buf, "doc-hub-{d:0>3}", .{i});
        try planned_graph.addEdge(source, "doc-authority", "cites", 1.0, 0, 0, "");
    }
    try planned_graph.addEdge("doc-authority", "doc-authority", "cites", 1.0, 0, 0, "");
    const target_generation = planned_graph.edge_generation;

    try planned_graph.acquireGraphMetricBuildLease("hits_authority", target_generation);
    var initial_manifest_page_count: usize = 0;
    var active_job = blk: {
        var txn = try planned_graph.beginReadReverseTxn();
        defer txn.abort();
        const job = try planned_graph.metricBuildJob(&txn, "hits_authority") orelse return error.TestExpectedGraphMetricBuildJob;
        const manifest = try planned_graph.metricBuildManifest(&txn, "hits_authority", job.job_id) orelse return error.TestExpectedGraphMetricBuildManifest;
        initial_manifest_page_count = manifest.page_count;
        try std.testing.expect(manifest.page_count >= GraphIndex.graph_metric_hits_build_phases.len + 10);
        _ = try planned_graph.metricBuildPage(&txn, "hits_authority", job.job_id, .scan_edges_and_out_degree, 0, 1) orelse return error.TestExpectedGraphMetricBuildPage;
        _ = try planned_graph.metricBuildPage(&txn, "hits_authority", job.job_id, .scan_edges_and_out_degree, 0, 2) orelse return error.TestExpectedGraphMetricBuildPage;
        _ = try planned_graph.metricBuildPage(&txn, "hits_authority", job.job_id, .initialize_ranks, 0, 2) orelse return error.TestExpectedGraphMetricBuildPage;
        _ = try planned_graph.metricBuildPage(&txn, "hits_authority", job.job_id, .reduce_ranks, 0, 4) orelse return error.TestExpectedGraphMetricBuildPage;
        break :blk job;
    };

    var worker_a_completed: usize = 0;
    var worker_b_completed: usize = 0;
    var worker_c_completed: usize = 0;
    var reopen_count: usize = 0;
    var observed_second_iteration = false;
    var observed_dynamic_manifest_growth = false;
    var observed_hub_contribution_pages = false;
    var observed_hub_reduce_pages = false;
    var completed = false;
    var steps: usize = 0;
    while (steps < 512) : (steps += 1) {
        const worker_id = switch (steps % 3) {
            0 => "worker-a",
            1 => "worker-b",
            else => "worker-c",
        };
        const step = try planned_graph.runGraphMetricPlannedWorkerStep("hits_authority", metrics[0], worker_id);
        if (step.completed_page) {
            if (std.mem.eql(u8, worker_id, "worker-a")) {
                worker_a_completed += 1;
            } else if (std.mem.eql(u8, worker_id, "worker-b")) {
                worker_b_completed += 1;
            } else {
                worker_c_completed += 1;
            }
        }
        if (step.completed_build and step.phase == .cleanup_old_generations) {
            completed = true;
            break;
        }
        if (!step.claimed_page and !step.advanced_phase and step.phase != .cleanup_old_generations) {
            return error.TestExpectedGraphMetricBuildProgress;
        }
        {
            var txn = try planned_graph.beginReadReverseTxn();
            defer txn.abort();
            if (try planned_graph.metricBuildJob(&txn, "hits_authority")) |job| {
                if (job.job_id == active_job.job_id) {
                    observed_second_iteration = observed_second_iteration or job.iteration == 1;
                    switch (job.phase) {
                        .hits_hub_contributions => {
                            try expectGraphMetricBuildPhasePageCountAtLeastForTest(&planned_graph, &txn, "hits_authority", active_job.job_id, .hits_hub_contributions, job.iteration, 2);
                            observed_hub_contribution_pages = true;
                        },
                        .hits_hub_reduce_ranks => {
                            try expectGraphMetricBuildPhasePageCountAtLeastForTest(&planned_graph, &txn, "hits_authority", active_job.job_id, .hits_hub_reduce_ranks, job.iteration, 2);
                            observed_hub_reduce_pages = true;
                        },
                        else => {},
                    }
                }
            }
        }

        if (steps % 5 == 4) {
            planned_graph.close();
            planned_graph = try GraphIndex.open(alloc, &planned_store, planned_rev_path, "links", .{ .metric_configs = &metrics });
            reopen_count += 1;
            var status = try planned_graph.graphMetricStatus("hits_authority");
            defer status.deinit(alloc);
            var hub_status = try planned_graph.graphMetricStatus("hits_hub");
            defer hub_status.deinit(alloc);
            try std.testing.expectEqual(status.published_generation, hub_status.published_generation);
            if (status.state == .building) {
                try std.testing.expectEqual(active_job.job_id, status.build_job_id);
                try std.testing.expect(status.build_pages.len <= graph_metric_status_page_limit);
            }
            var txn = try planned_graph.beginReadReverseTxn();
            defer txn.abort();
            const maybe_job = try planned_graph.metricBuildJob(&txn, "hits_authority");
            if (maybe_job) |job| {
                if (job.job_id == active_job.job_id) active_job = job;
                if (try planned_graph.metricBuildManifest(&txn, "hits_authority", active_job.job_id)) |manifest| {
                    observed_dynamic_manifest_growth = observed_dynamic_manifest_growth or manifest.page_count > initial_manifest_page_count;
                }
            }
        }
    }
    try std.testing.expect(completed);
    try std.testing.expect(reopen_count >= 3);
    try std.testing.expect(observed_second_iteration);
    try std.testing.expect(observed_dynamic_manifest_growth);
    try std.testing.expect(observed_hub_contribution_pages);
    try std.testing.expect(observed_hub_reduce_pages);
    try std.testing.expect(worker_a_completed > 0);
    try std.testing.expect(worker_b_completed > 0);
    try std.testing.expect(worker_c_completed > 0);

    var planned_status = try planned_graph.graphMetricStatus("hits_authority");
    defer planned_status.deinit(alloc);
    var planned_hub_status = try planned_graph.graphMetricStatus("hits_hub");
    defer planned_hub_status.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.fresh, planned_status.state);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.fresh, planned_hub_status.state);
    try std.testing.expectEqual(target_generation, planned_status.published_generation);
    try std.testing.expectEqual(planned_status.published_generation, planned_hub_status.published_generation);
    try std.testing.expectEqual(local_status.iterations_completed, planned_status.iterations_completed);
    try std.testing.expectEqual(local_hub_status.iterations_completed, planned_hub_status.iterations_completed);
    try std.testing.expectEqual(local_status.converged, planned_status.converged);
    try std.testing.expectEqual(local_hub_status.converged, planned_hub_status.converged);
    try std.testing.expectApproxEqAbs(local_status.delta, planned_status.delta, 0.0000001);
    try std.testing.expectApproxEqAbs(local_hub_status.delta, planned_hub_status.delta, 0.0000001);
    try std.testing.expectEqual(@as(usize, 0), planned_status.build_pages.len);
    try std.testing.expectEqual(@as(usize, 0), planned_hub_status.build_pages.len);

    {
        var txn = try planned_graph.beginReadReverseTxn();
        defer txn.abort();
        const completed_job = try planned_graph.metricBuildJob(&txn, "hits_authority") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(active_job.job_id, completed_job.job_id);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.complete, completed_job.phase);
        try std.testing.expect((try planned_graph.metricBuildLease(&txn, "hits_authority")) == null);
        try std.testing.expect((try planned_graph.metricBuildManifest(&txn, "hits_authority", active_job.job_id)) == null);
    }

    const top_limit: usize = @intCast(planned_graph.node_count);
    const local_authorities = try local_graph.graphMetricTopK("hits_authority", top_limit);
    defer {
        for (local_authorities) |*score| score.deinit(alloc);
        alloc.free(local_authorities);
    }
    const planned_authorities = try planned_graph.graphMetricTopK("hits_authority", top_limit);
    defer {
        for (planned_authorities) |*score| score.deinit(alloc);
        alloc.free(planned_authorities);
    }
    try std.testing.expectEqual(local_authorities.len, planned_authorities.len);
    for (local_authorities, planned_authorities) |local, planned| {
        try std.testing.expectEqualStrings(local.node, planned.node);
        try std.testing.expectApproxEqAbs(local.score, planned.score, 0.0000001);
    }

    const local_hubs = try local_graph.graphMetricTopK("hits_hub", top_limit);
    defer {
        for (local_hubs) |*score| score.deinit(alloc);
        alloc.free(local_hubs);
    }
    const planned_hubs = try planned_graph.graphMetricTopK("hits_hub", top_limit);
    defer {
        for (planned_hubs) |*score| score.deinit(alloc);
        alloc.free(planned_hubs);
    }
    try std.testing.expectEqual(local_hubs.len, planned_hubs.len);
    for (local_hubs, planned_hubs) |local, planned| {
        try std.testing.expectEqualStrings(local.node, planned.node);
        try std.testing.expectApproxEqAbs(local.score, planned.score, 0.0000001);
    }
}

test "graph hits planned drain runs through metric-name worker and coordinator boundary" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-hits-planned-drain");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-hits-planned-drain");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{
        .{
            .name = "hits_authority",
            .kind = .hits_authority,
            .refresh = .manual,
            .max_iterations = 1,
            .tolerance = 0.000001,
        },
        .{
            .name = "hits_hub",
            .kind = .hits_hub,
            .refresh = .manual,
            .max_iterations = 1,
            .tolerance = 0.000001,
        },
    };
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    for (0..graph_metric_build_target_scan_page_units + 1) |i| {
        var source_buf: [64]u8 = undefined;
        const source = try std.fmt.bufPrint(&source_buf, "doc-hub-{d:0>3}", .{i});
        try graph.addEdge(source, "doc-authority", "cites", 1.0, 0, 0, "");
    }
    try graph.addEdge("doc-authority", "doc-authority", "cites", 1.0, 0, 0, "");

    const target_generation = graph.edge_generation;
    const worker_ids = [_][]const u8{ "worker-a", "worker-b", "worker-c" };
    var status = try graph.runGraphMetricPlannedDrain("hits_authority", target_generation, .{
        .worker_ids = &worker_ids,
        .max_steps = 256,
    });
    defer status.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.fresh, status.state);
    try std.testing.expectEqual(target_generation, status.published_generation);
    try std.testing.expectEqual(@as(u32, 1), status.iterations_completed);
    try std.testing.expectEqual(@as(usize, 0), status.build_pages.len);

    var hub_status = try graph.graphMetricStatus("hits_hub");
    defer hub_status.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.fresh, hub_status.state);
    try std.testing.expectEqual(status.published_generation, hub_status.published_generation);
    try std.testing.expectEqual(status.iterations_completed, hub_status.iterations_completed);
    try std.testing.expectEqual(status.converged, hub_status.converged);

    const authorities = try graph.graphMetricTopK("hits_authority", 3);
    defer {
        for (authorities) |*score| score.deinit(alloc);
        alloc.free(authorities);
    }
    try std.testing.expect(authorities.len >= 2);
    try std.testing.expectEqualStrings("doc-authority", authorities[0].node);

    const hubs = try graph.graphMetricTopK("hits_hub", 3);
    defer {
        for (hubs) |*score| score.deinit(alloc);
        alloc.free(hubs);
    }
    try std.testing.expect(hubs.len >= 2);
    try std.testing.expect(hubs[0].score >= hubs[1].score);

    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const completed_job = try graph.metricBuildJob(&txn, "hits_authority") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.complete, completed_job.phase);
        try std.testing.expect((try graph.metricBuildLease(&txn, "hits_authority")) == null);
        try std.testing.expect((try graph.metricBuildManifest(&txn, "hits_authority", completed_job.job_id)) == null);
    }
}

test "graph hits later iteration failed pages retry and advance" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-hits-later-iteration-retry");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-hits-later-iteration-retry");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{
        .{
            .name = "hits_authority",
            .kind = .hits_authority,
            .refresh = .manual,
            .max_iterations = 2,
            .tolerance = 0.0,
        },
        .{
            .name = "hits_hub",
            .kind = .hits_hub,
            .refresh = .manual,
            .max_iterations = 2,
            .tolerance = 0.0,
        },
    };
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    try graph.addEdge("doc-hub-a", "doc-authority", "cites", 1.0, 0, 0, "");
    try graph.addEdge("doc-hub-b", "doc-authority", "cites", 1.0, 0, 0, "");
    try graph.addEdge("doc-authority", "doc-authority", "cites", 1.0, 0, 0, "");
    try graph.acquireGraphMetricBuildLease("hits_authority", graph.edge_generation);

    var job_txn = try graph.beginReadReverseTxn();
    const active_job = try graph.metricBuildJob(&job_txn, "hits_authority") orelse return error.TestExpectedGraphMetricBuildJob;
    job_txn.abort();

    inline for (.{ .prepare_generation, .scan_edges_and_out_degree, .initialize_ranks, .iterate_contributions, .reduce_ranks, .hits_hub_contributions, .hits_hub_reduce_ranks, .check_convergence }) |expected_phase| {
        const step = try graph.runGraphMetricPlannedWorkerStep("hits_authority", metrics[0], "worker-a");
        try std.testing.expectEqual(expected_phase, step.phase);
        try std.testing.expect(step.claimed_page);
        try std.testing.expect(step.completed_page);
        try std.testing.expect(step.advanced_phase);
    }
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const job = try graph.metricBuildJob(&txn, "hits_authority") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.iterate_contributions, job.phase);
        try std.testing.expectEqual(@as(u32, 1), job.iteration);
    }

    const contribution_failed_claim = try graph.claimGraphMetricBuildPageAt("hits_authority", active_job.job_id, .iterate_contributions, 1, 3, "worker-fail-contrib", 2000) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(@as(u64, 1), contribution_failed_claim.attempt);
    const contribution_failed = try graph.failGraphMetricBuildPage("hits_authority", active_job.job_id, .iterate_contributions, 1, 3, "worker-fail-contrib", "later hits contribution failed");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.failed, contribution_failed.state);
    try std.testing.expectEqualStrings("later hits contribution failed", contribution_failed.last_error);
    try std.testing.expect(!(try graph.advanceGraphMetricBuildPhaseIfReady("hits_authority", active_job.job_id, .iterate_contributions, 1)));
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const summary = try graph.metricBuildPhaseSummary(&txn, "hits_authority", active_job.job_id, .iterate_contributions, 1) orelse return error.TestExpectedGraphMetricBuildPhaseSummary;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhaseState.failed, summary.state);
        try std.testing.expectEqual(@as(u64, 1), summary.failed_pages);
    }
    {
        const step = try graph.runGraphMetricPlannedWorkerStep("hits_authority", metrics[0], "worker-retry-contrib");
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.iterate_contributions, step.phase);
        try std.testing.expect(step.claimed_page);
        try std.testing.expect(step.completed_page);
        try std.testing.expect(step.advanced_phase);
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "hits_authority", active_job.job_id, .iterate_contributions, 1, 3) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.complete, page.state);
        try std.testing.expectEqual(@as(u64, 2), page.attempt);
        const summary = try graph.metricBuildPhaseSummary(&txn, "hits_authority", active_job.job_id, .iterate_contributions, 1) orelse return error.TestExpectedGraphMetricBuildPhaseSummary;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhaseState.complete, summary.state);
        try std.testing.expectEqual(@as(u64, 0), summary.failed_pages);
        const job = try graph.metricBuildJob(&txn, "hits_authority") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.reduce_ranks, job.phase);
    }

    const reduce_failed_claim = try graph.claimGraphMetricBuildPageAt("hits_authority", active_job.job_id, .reduce_ranks, 1, 4, "worker-fail-reduce", 3000) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(@as(u64, 1), reduce_failed_claim.attempt);
    const reduce_failed = try graph.failGraphMetricBuildPage("hits_authority", active_job.job_id, .reduce_ranks, 1, 4, "worker-fail-reduce", "later hits reduce failed");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.failed, reduce_failed.state);
    try std.testing.expectEqualStrings("later hits reduce failed", reduce_failed.last_error);
    try std.testing.expect(!(try graph.advanceGraphMetricBuildPhaseIfReady("hits_authority", active_job.job_id, .reduce_ranks, 1)));
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const summary = try graph.metricBuildPhaseSummary(&txn, "hits_authority", active_job.job_id, .reduce_ranks, 1) orelse return error.TestExpectedGraphMetricBuildPhaseSummary;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhaseState.failed, summary.state);
        try std.testing.expectEqual(@as(u64, 1), summary.failed_pages);
    }
    {
        const step = try graph.runGraphMetricPlannedWorkerStep("hits_authority", metrics[0], "worker-retry-reduce");
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.reduce_ranks, step.phase);
        try std.testing.expect(step.claimed_page);
        try std.testing.expect(step.completed_page);
        try std.testing.expect(step.advanced_phase);
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "hits_authority", active_job.job_id, .reduce_ranks, 1, 4) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.complete, page.state);
        try std.testing.expectEqual(@as(u64, 2), page.attempt);
        const summary = try graph.metricBuildPhaseSummary(&txn, "hits_authority", active_job.job_id, .reduce_ranks, 1) orelse return error.TestExpectedGraphMetricBuildPhaseSummary;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhaseState.complete, summary.state);
        try std.testing.expectEqual(@as(u64, 0), summary.failed_pages);
        const job = try graph.metricBuildJob(&txn, "hits_authority") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.hits_hub_contributions, job.phase);
    }

    const hub_contribution_failed_claim = try graph.claimNextGraphMetricBuildPageAt("hits_authority", active_job.job_id, .hits_hub_contributions, 1, "worker-fail-hub-contrib", 3500) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(@as(u64, 1), hub_contribution_failed_claim.attempt);
    const hub_contribution_failed = try graph.failGraphMetricBuildPage("hits_authority", active_job.job_id, .hits_hub_contributions, 1, hub_contribution_failed_claim.page_id, "worker-fail-hub-contrib", "later hits hub contribution failed");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.failed, hub_contribution_failed.state);
    try std.testing.expectEqualStrings("later hits hub contribution failed", hub_contribution_failed.last_error);
    try std.testing.expect(!(try graph.advanceGraphMetricBuildPhaseIfReady("hits_authority", active_job.job_id, .hits_hub_contributions, 1)));
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const summary = try graph.metricBuildPhaseSummary(&txn, "hits_authority", active_job.job_id, .hits_hub_contributions, 1) orelse return error.TestExpectedGraphMetricBuildPhaseSummary;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhaseState.failed, summary.state);
        try std.testing.expectEqual(@as(u64, 1), summary.failed_pages);
    }
    {
        const step = try graph.runGraphMetricPlannedWorkerStep("hits_authority", metrics[0], "worker-retry-hub-contrib");
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.hits_hub_contributions, step.phase);
        try std.testing.expect(step.claimed_page);
        try std.testing.expect(step.completed_page);
        try std.testing.expect(step.advanced_phase);
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "hits_authority", active_job.job_id, .hits_hub_contributions, 1, hub_contribution_failed_claim.page_id) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.complete, page.state);
        try std.testing.expectEqual(@as(u64, 2), page.attempt);
        const summary = try graph.metricBuildPhaseSummary(&txn, "hits_authority", active_job.job_id, .hits_hub_contributions, 1) orelse return error.TestExpectedGraphMetricBuildPhaseSummary;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhaseState.complete, summary.state);
        try std.testing.expectEqual(@as(u64, 0), summary.failed_pages);
        const job = try graph.metricBuildJob(&txn, "hits_authority") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.hits_hub_reduce_ranks, job.phase);
    }

    const hub_reduce_failed_claim = try graph.claimNextGraphMetricBuildPageAt("hits_authority", active_job.job_id, .hits_hub_reduce_ranks, 1, "worker-fail-hub-reduce", 3750) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(@as(u64, 1), hub_reduce_failed_claim.attempt);
    const hub_reduce_failed = try graph.failGraphMetricBuildPage("hits_authority", active_job.job_id, .hits_hub_reduce_ranks, 1, hub_reduce_failed_claim.page_id, "worker-fail-hub-reduce", "later hits hub reduce failed");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.failed, hub_reduce_failed.state);
    try std.testing.expectEqualStrings("later hits hub reduce failed", hub_reduce_failed.last_error);
    try std.testing.expect(!(try graph.advanceGraphMetricBuildPhaseIfReady("hits_authority", active_job.job_id, .hits_hub_reduce_ranks, 1)));
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const summary = try graph.metricBuildPhaseSummary(&txn, "hits_authority", active_job.job_id, .hits_hub_reduce_ranks, 1) orelse return error.TestExpectedGraphMetricBuildPhaseSummary;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhaseState.failed, summary.state);
        try std.testing.expectEqual(@as(u64, 1), summary.failed_pages);
    }
    {
        const step = try graph.runGraphMetricPlannedWorkerStep("hits_authority", metrics[0], "worker-retry-hub-reduce");
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.hits_hub_reduce_ranks, step.phase);
        try std.testing.expect(step.claimed_page);
        try std.testing.expect(step.completed_page);
        try std.testing.expect(step.advanced_phase);
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "hits_authority", active_job.job_id, .hits_hub_reduce_ranks, 1, hub_reduce_failed_claim.page_id) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.complete, page.state);
        try std.testing.expectEqual(@as(u64, 2), page.attempt);
        const summary = try graph.metricBuildPhaseSummary(&txn, "hits_authority", active_job.job_id, .hits_hub_reduce_ranks, 1) orelse return error.TestExpectedGraphMetricBuildPhaseSummary;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhaseState.complete, summary.state);
        try std.testing.expectEqual(@as(u64, 0), summary.failed_pages);
        const job = try graph.metricBuildJob(&txn, "hits_authority") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.check_convergence, job.phase);
    }

    const check_failed_claim = try graph.claimGraphMetricBuildPageAt("hits_authority", active_job.job_id, .check_convergence, 1, 7, "worker-fail-check", 4000) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(@as(u64, 1), check_failed_claim.attempt);
    const check_failed = try graph.failGraphMetricBuildPage("hits_authority", active_job.job_id, .check_convergence, 1, 7, "worker-fail-check", "later hits check failed");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.failed, check_failed.state);
    try std.testing.expectEqualStrings("later hits check failed", check_failed.last_error);
    try std.testing.expect(!(try graph.advanceGraphMetricBuildPhaseIfReady("hits_authority", active_job.job_id, .check_convergence, 1)));
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const summary = try graph.metricBuildPhaseSummary(&txn, "hits_authority", active_job.job_id, .check_convergence, 1) orelse return error.TestExpectedGraphMetricBuildPhaseSummary;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhaseState.failed, summary.state);
        try std.testing.expectEqual(@as(u64, 1), summary.failed_pages);
    }
    {
        const step = try graph.runGraphMetricPlannedWorkerStep("hits_authority", metrics[0], "worker-retry-check");
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.check_convergence, step.phase);
        try std.testing.expect(step.claimed_page);
        try std.testing.expect(step.completed_page);
        try std.testing.expect(step.advanced_phase);
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "hits_authority", active_job.job_id, .check_convergence, 1, 7) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.complete, page.state);
        try std.testing.expectEqual(@as(u64, 2), page.attempt);
        const summary = try graph.metricBuildPhaseSummary(&txn, "hits_authority", active_job.job_id, .check_convergence, 1) orelse return error.TestExpectedGraphMetricBuildPhaseSummary;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhaseState.complete, summary.state);
        try std.testing.expectEqual(@as(u64, 0), summary.failed_pages);
        const job = try graph.metricBuildJob(&txn, "hits_authority") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.publish_generation, job.phase);
        _ = try graph.metricBuildIterationSummary(&txn, "hits_authority", active_job.job_id, 1) orelse return error.TestExpectedGraphMetricBuildIterationSummary;
    }
}

test "graph hits later iteration exhausted page fails pair and preserves prior published pair" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-hits-later-iteration-exhausted-preserves-pair");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-hits-later-iteration-exhausted-preserves-pair");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{
        .{
            .name = "hits_authority",
            .kind = .hits_authority,
            .refresh = .manual,
            .max_iterations = 2,
            .tolerance = 0.0,
        },
        .{
            .name = "hits_hub",
            .kind = .hits_hub,
            .refresh = .manual,
            .max_iterations = 2,
            .tolerance = 0.0,
        },
    };
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    try graph.addEdge("doc-hub-a", "doc-authority", "cites", 1.0, 0, 0, "");
    try graph.addEdge("doc-hub-b", "doc-authority", "cites", 1.0, 0, 0, "");
    try graph.addEdge("doc-authority", "doc-authority", "cites", 1.0, 0, 0, "");
    var published = try graph.runHitsMetricPlanned("hits_authority");
    defer published.deinit(alloc);
    var published_hub = try graph.graphMetricStatus("hits_hub");
    defer published_hub.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.fresh, published.state);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.fresh, published_hub.state);
    try std.testing.expectEqual(published.published_generation, published_hub.published_generation);
    const published_generation = published.published_generation;

    const before_authorities = try graph.graphMetricTopK("hits_authority", 10);
    defer {
        for (before_authorities) |*score| score.deinit(alloc);
        alloc.free(before_authorities);
    }
    const before_hubs = try graph.graphMetricTopK("hits_hub", 10);
    defer {
        for (before_hubs) |*score| score.deinit(alloc);
        alloc.free(before_hubs);
    }
    try std.testing.expectEqual(@as(usize, 3), before_authorities.len);
    try std.testing.expectEqual(@as(usize, 3), before_hubs.len);

    try graph.addEdge("doc-new-hub", "doc-authority", "cites", 1.0, 0, 0, "");
    const rebuilding_generation = graph.edge_generation;
    try std.testing.expect(rebuilding_generation > published_generation);
    var building = try graph.ensureGraphMetricPlannedBuild("hits_authority", rebuilding_generation);
    defer building.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.building, building.state);
    try std.testing.expectEqual(rebuilding_generation, building.building_generation);

    const active_job = blk: {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const job = try graph.metricBuildJob(&txn, "hits_authority") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(building.build_job_id, job.job_id);
        try std.testing.expectEqual(rebuilding_generation, job.target_generation);
        break :blk job;
    };

    inline for (.{ .prepare_generation, .scan_edges_and_out_degree, .initialize_ranks, .iterate_contributions, .reduce_ranks, .hits_hub_contributions, .hits_hub_reduce_ranks, .check_convergence }) |expected_phase| {
        const step = try graph.runGraphMetricPlannedWorkerStep("hits_authority", metrics[0], "worker-a");
        try std.testing.expectEqual(expected_phase, step.phase);
        try std.testing.expect(step.claimed_page);
        try std.testing.expect(step.completed_page);
        try std.testing.expect(step.advanced_phase);
    }
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const job = try graph.metricBuildJob(&txn, "hits_authority") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(active_job.job_id, job.job_id);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.iterate_contributions, job.phase);
        try std.testing.expectEqual(@as(u32, 1), job.iteration);
        _ = try graph.metricBuildPage(&txn, "hits_authority", active_job.job_id, .iterate_contributions, 1, 3) orelse return error.TestExpectedGraphMetricBuildPage;
    }

    inline for (.{ .iterate_contributions, .reduce_ranks, .hits_hub_contributions }) |expected_phase| {
        const step = try graph.runGraphMetricPlannedWorkerStep("hits_authority", metrics[0], "worker-advance-to-hub-reduce");
        try std.testing.expectEqual(expected_phase, step.phase);
        try std.testing.expect(step.claimed_page);
        try std.testing.expect(step.completed_page);
        try std.testing.expect(step.advanced_phase);
    }
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const job = try graph.metricBuildJob(&txn, "hits_authority") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(active_job.job_id, job.job_id);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.hits_hub_reduce_ranks, job.phase);
        try std.testing.expectEqual(@as(u32, 1), job.iteration);
    }

    var exhausted_hub_reduce_page_id: u64 = 0;
    var attempt: u64 = 0;
    while (attempt < graph_metric_build_max_page_attempts) : (attempt += 1) {
        const worker_id = switch (attempt) {
            0 => "worker-a",
            1 => "worker-b",
            else => "worker-c",
        };
        const page = try graph.claimNextGraphMetricBuildPageAt("hits_authority", active_job.job_id, .hits_hub_reduce_ranks, 1, worker_id, 2000 + attempt) orelse return error.TestExpectedGraphMetricBuildPage;
        if (attempt == 0) {
            exhausted_hub_reduce_page_id = page.page_id;
        } else {
            try std.testing.expectEqual(exhausted_hub_reduce_page_id, page.page_id);
        }
        try std.testing.expectEqual(attempt + 1, page.attempt);
        _ = try graph.failGraphMetricBuildPage("hits_authority", active_job.job_id, .hits_hub_reduce_ranks, 1, page.page_id, worker_id, "retryable later hits hub reduce failure");
    }

    graph.close();
    graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "hits_authority", active_job.job_id, .hits_hub_reduce_ranks, 1, exhausted_hub_reduce_page_id) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.failed, page.state);
        try std.testing.expectEqual(@as(u64, graph_metric_build_max_page_attempts), page.attempt);
        try std.testing.expectEqualStrings("retryable later hits hub reduce failure", page.last_error);
        const job = try graph.metricBuildJob(&txn, "hits_authority") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(active_job.job_id, job.job_id);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.hits_hub_reduce_ranks, job.phase);
        try std.testing.expectEqual(@as(u32, 1), job.iteration);
    }

    const failed_step = try graph.runGraphMetricPlannedCoordinatorStepForMetric("hits_authority");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.hits_hub_reduce_ranks, failed_step.phase);
    try std.testing.expect(failed_step.failed_build);
    try std.testing.expect(!failed_step.advanced_phase);
    try std.testing.expect(!failed_step.published);

    var failed_authority = try graph.graphMetricStatus("hits_authority");
    defer failed_authority.deinit(alloc);
    var failed_hub = try graph.graphMetricStatus("hits_hub");
    defer failed_hub.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.failed, failed_authority.state);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.failed, failed_hub.state);
    try std.testing.expectEqual(published_generation, failed_authority.published_generation);
    try std.testing.expectEqual(published_generation, failed_hub.published_generation);
    try std.testing.expectEqual(@as(u64, 0), failed_authority.build_job_id);
    try std.testing.expectEqual(@as(u64, 0), failed_hub.build_job_id);
    try std.testing.expectEqualStrings("GraphMetricBuildPageAttemptsExhausted", failed_authority.last_error);
    try std.testing.expectEqualStrings("GraphMetricBuildPageAttemptsExhausted", failed_hub.last_error);
    try std.testing.expectEqual(@as(usize, 1), failed_authority.recent_failures.len);
    try std.testing.expectEqual(@as(usize, 1), failed_hub.recent_failures.len);
    try std.testing.expectEqual(active_job.job_id, failed_authority.recent_failures[0].job_id);
    try std.testing.expectEqual(active_job.job_id, failed_hub.recent_failures[0].job_id);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.hits_hub_reduce_ranks, failed_authority.recent_failures[0].phase);
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.hits_hub_reduce_ranks, failed_hub.recent_failures[0].phase);
    try std.testing.expectEqual(@as(u32, 1), failed_authority.recent_failures[0].iteration);
    try std.testing.expectEqual(@as(u32, 1), failed_hub.recent_failures[0].iteration);

    const after_authorities = try graph.graphMetricTopK("hits_authority", 10);
    defer {
        for (after_authorities) |*score| score.deinit(alloc);
        alloc.free(after_authorities);
    }
    const after_hubs = try graph.graphMetricTopK("hits_hub", 10);
    defer {
        for (after_hubs) |*score| score.deinit(alloc);
        alloc.free(after_hubs);
    }
    try std.testing.expectEqual(before_authorities.len, after_authorities.len);
    for (before_authorities, after_authorities) |before, after| {
        try std.testing.expectEqualStrings(before.node, after.node);
        try std.testing.expectApproxEqAbs(before.score, after.score, 0.0000001);
        try std.testing.expect(!std.mem.eql(u8, after.node, "doc-new-hub"));
    }
    try std.testing.expectEqual(before_hubs.len, after_hubs.len);
    for (before_hubs, after_hubs) |before, after| {
        try std.testing.expectEqualStrings(before.node, after.node);
        try std.testing.expectApproxEqAbs(before.score, after.score, 0.0000001);
        try std.testing.expect(!std.mem.eql(u8, after.node, "doc-new-hub"));
    }

    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const failed_job = try graph.metricBuildJob(&txn, "hits_authority") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(active_job.job_id, failed_job.job_id);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.hits_hub_reduce_ranks, failed_job.phase);
        try std.testing.expectEqual(@as(u32, 1), failed_job.iteration);
        try std.testing.expectEqualStrings("GraphMetricBuildPageAttemptsExhausted", failed_job.last_error);
        try std.testing.expect((try graph.metricBuildManifest(&txn, "hits_authority", active_job.job_id)) == null);
        try std.testing.expectEqual(@as(usize, 0), try graph.countGraphMetricScoreGeneration("hits_authority", active_job.score_generation));
        try std.testing.expectEqual(@as(usize, 0), try graph.countGraphMetricScoreGeneration("hits_hub", active_job.score_generation));
    }
}

