        defer alloc.free(stale_hub_key);
        try std.testing.expectApproxEqAbs(@as(f64, 24.0), try GraphIndex.readF64OrZero(&txn, stale_hub_key), 0.0000001);
        break :blk page.lease_expires_at_ms;
