        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        try std.testing.expect((try graph.hitsHubRawSummary(&txn, "hits_authority", active_job.job_id, 0)) == null);
    }
    try std.testing.expectError(error.GraphMetricBuildPageNotLeased, graph.executeHitsHubReduceBuildPage("hits_authority", metrics[0], active_job, hub_reduce_claim));
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const stale_hub_key = try graph.graphMetricBuildHitsRankKeyAlloc("hits_authority", active_job.job_id, "hub", 1, "doc-hub-a");
        defer alloc.free(stale_hub_key);
        try std.testing.expectApproxEqAbs(@as(f64, 24.0), try GraphIndex.readF64OrZero(&txn, stale_hub_key), 0.0000001);
    }
    _ = try graph.executeHitsHubReduceBuildPage("hits_authority", metrics[0], active_job, reclaimed_hub_reduce);
    try std.testing.expect(try graph.advanceGraphMetricBuildPhaseIfReady("hits_authority", active_job.job_id, .hits_hub_reduce_ranks, 0));

    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const hub_a_hub_key = try graph.graphMetricBuildHitsRankKeyAlloc("hits_authority", active_job.job_id, "hub", 1, "doc-hub-a");
        defer alloc.free(hub_a_hub_key);
        const authority_hub_key = try graph.graphMetricBuildHitsRankKeyAlloc("hits_authority", active_job.job_id, "hub", 1, "doc-authority");
        defer alloc.free(authority_hub_key);
        try std.testing.expectApproxEqAbs(1.0 / @sqrt(@as(f64, 3.0)), try GraphIndex.readF64OrZero(&txn, hub_a_hub_key), 0.0000001);
        try std.testing.expectApproxEqAbs(1.0 / @sqrt(@as(f64, 3.0)), try GraphIndex.readF64OrZero(&txn, authority_hub_key), 0.0000001);
        const hub_summary = try graph.metricBuildPhaseSummary(&txn, "hits_authority", active_job.job_id, .hits_hub_reduce_ranks, 0) orelse return error.TestExpectedGraphMetricBuildPhaseSummary;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhaseState.complete, hub_summary.state);
        try std.testing.expectEqual(@as(u64, 0), hub_summary.failed_pages);
        const job = try graph.metricBuildJob(&txn, "hits_authority") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.check_convergence, job.phase);
    }
}

test "graph hits convergence page reclaim recomputes without stale partial summary" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-hits-convergence-reclaim");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-hits-convergence-reclaim");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{
        .{
            .name = "hits_authority",
            .kind = .hits_authority,
            .refresh = .manual,
            .max_iterations = 1,
            .tolerance = 0.000001,
        },
        .{
            .name = "hits_hub",
            .kind = .hits_hub,
            .refresh = .manual,
            .max_iterations = 1,
            .tolerance = 0.000001,
        },
    };
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    try graph.addEdge("doc-hub-a", "doc-authority", "cites", 1.0, 0, 0, "");
    try graph.addEdge("doc-hub-b", "doc-authority", "cites", 1.0, 0, 0, "");
    try graph.addEdge("doc-authority", "doc-authority", "cites", 1.0, 0, 0, "");
    try graph.acquireGraphMetricBuildLease("hits_authority", graph.edge_generation);
    defer graph.releaseGraphMetricBuildLease("hits_authority") catch {};

    var job_txn = try graph.beginReadReverseTxn();
    const active_job = try graph.metricBuildJob(&job_txn, "hits_authority") orelse return error.TestExpectedGraphMetricBuildJob;
    job_txn.abort();

    inline for (.{ .prepare_generation, .scan_edges_and_out_degree, .initialize_ranks, .iterate_contributions, .reduce_ranks, .hits_hub_contributions, .hits_hub_reduce_ranks }) |expected_phase| {
        const step = try graph.runGraphMetricPlannedWorkerStep("hits_authority", metrics[0], "worker-a");
        try std.testing.expectEqual(expected_phase, step.phase);
        try std.testing.expect(step.claimed_page);
        try std.testing.expect(step.completed_page);
        try std.testing.expect(step.advanced_phase);
    }

    _ = try graph.claimGraphMetricBuildPageAt("hits_authority", active_job.job_id, .check_convergence, 0, 7, "worker-a", 4000) orelse return error.TestExpectedGraphMetricBuildPage;
    var check_claim: GraphIndex.GraphMetricBuildPage = undefined;
    var check_range_lower: []u8 = "";
    defer if (check_range_lower.len > 0) alloc.free(check_range_lower);
    var check_range_upper: []u8 = "";
    defer if (check_range_upper.len > 0) alloc.free(check_range_upper);
    var check_output_prefix: []u8 = "";
    defer if (check_output_prefix.len > 0) alloc.free(check_output_prefix);
    var check_worker_id: []u8 = "";
    defer if (check_worker_id.len > 0) alloc.free(check_worker_id);
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const stored = try graph.metricBuildPage(&txn, "hits_authority", active_job.job_id, .check_convergence, 0, 7) orelse return error.TestExpectedGraphMetricBuildPage;
        check_range_lower = try alloc.dupe(u8, stored.range_lower);
        check_range_upper = try alloc.dupe(u8, stored.range_upper);
        check_output_prefix = try alloc.dupe(u8, stored.output_prefix);
        check_worker_id = try alloc.dupe(u8, stored.worker_id);
        check_claim = stored;
    }
    check_claim.range_lower = check_range_lower;
    check_claim.range_upper = check_range_upper;
    check_claim.output_prefix = check_output_prefix;
    check_claim.worker_id = check_worker_id;
    check_claim.completed_units = 1;
    check_claim.cursor = "stale-hits-check";
    check_claim.max_delta = 99.0;
    check_claim.total_delta = 99.0;
    check_claim.rank_sum = 99.0;
    check_claim.converged = true;
    {
        var batch = try graph.beginWriteReverseBatch();
        errdefer batch.abort();
        try graph.putGraphMetricBuildPageInBatch(&batch, "hits_authority", check_claim);
        try batch.commit();
    }

    var expires_at: u64 = 0;
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "hits_authority", active_job.job_id, .check_convergence, 0, 7) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, page.state);
        try std.testing.expectEqual(@as(u64, 1), page.completed_units);
        try std.testing.expectApproxEqAbs(@as(f64, 99.0), page.max_delta, 0.0);
        try std.testing.expectApproxEqAbs(@as(f64, 99.0), page.total_delta, 0.0);
        try std.testing.expectApproxEqAbs(@as(f64, 99.0), page.rank_sum, 0.0);
        try std.testing.expect(page.converged);
        expires_at = page.lease_expires_at_ms;
    }

    const reclaimed = try graph.claimGraphMetricBuildPageAt("hits_authority", active_job.job_id, .check_convergence, 0, 7, "worker-b", expires_at + 1) orelse return error.TestExpectedGraphMetricBuildPage;
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, reclaimed.state);
    try std.testing.expectEqual(@as(u64, 2), reclaimed.attempt);
    try std.testing.expectEqual(@as(u64, 0), reclaimed.completed_units);
    try std.testing.expectEqualStrings("", reclaimed.cursor);
    try std.testing.expectEqual(@as(u64, 0), reclaimed.output_fingerprint);
    try std.testing.expectApproxEqAbs(@as(f64, 0.0), reclaimed.max_delta, 0.0);
    try std.testing.expectApproxEqAbs(@as(f64, 0.0), reclaimed.total_delta, 0.0);
    try std.testing.expectApproxEqAbs(@as(f64, 0.0), reclaimed.rank_sum, 0.0);
    try std.testing.expect(!reclaimed.converged);

    const completed_check = try graph.executeHitsConvergenceBuildPage("hits_authority", metrics[0], active_job, reclaimed);
    try std.testing.expect(completed_check.completed_page);
    try std.testing.expectApproxEqAbs(1.0 / @sqrt(@as(f64, 3.0)), completed_check.max_delta, 0.0000001);
    try std.testing.expectApproxEqAbs(@as(f64, 1.0) + 1.0 / @sqrt(@as(f64, 3.0)), completed_check.total_delta, 0.0000001);
    try std.testing.expectApproxEqAbs(@as(f64, 1.0) + @sqrt(@as(f64, 3.0)), completed_check.rank_sum, 0.0000001);
    try std.testing.expect(try graph.advanceGraphMetricBuildPhaseIfReady("hits_authority", active_job.job_id, .check_convergence, 0));
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const page = try graph.metricBuildPage(&txn, "hits_authority", active_job.job_id, .check_convergence, 0, 7) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.complete, page.state);
        try std.testing.expectApproxEqAbs(completed_check.max_delta, page.max_delta, 0.0000001);
        try std.testing.expectApproxEqAbs(completed_check.total_delta, page.total_delta, 0.0000001);
        try std.testing.expectApproxEqAbs(completed_check.rank_sum, page.rank_sum, 0.0000001);
        const job = try graph.metricBuildJob(&txn, "hits_authority") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.publish_generation, job.phase);
    }
}

test "graph hits cleanup page resumes after reopen with published pair visible" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-hits-cleanup-cursor");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-hits-cleanup-cursor");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{
        .{
            .name = "hits_authority",
            .kind = .hits_authority,
            .refresh = .manual,
            .max_iterations = 1,
            .tolerance = 0.000001,
        },
        .{
            .name = "hits_hub",
            .kind = .hits_hub,
            .refresh = .manual,
            .max_iterations = 1,
            .tolerance = 0.000001,
        },
    };
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });

    try graph.addEdge("doc-hub-a", "doc-authority", "cites", 1.0, 0, 0, "");
    try graph.addEdge("doc-hub-b", "doc-authority", "cites", 1.0, 0, 0, "");
    try graph.addEdge("doc-authority", "doc-authority", "cites", 1.0, 0, 0, "");
    try graph.acquireGraphMetricBuildLease("hits_authority", graph.edge_generation);

    var job_txn = try graph.beginReadReverseTxn();
    const active_job = try graph.metricBuildJob(&job_txn, "hits_authority") orelse return error.TestExpectedGraphMetricBuildJob;
    job_txn.abort();

    inline for (.{ .prepare_generation, .scan_edges_and_out_degree, .initialize_ranks, .iterate_contributions, .reduce_ranks, .hits_hub_contributions, .hits_hub_reduce_ranks, .check_convergence }) |expected_phase| {
        const step = try graph.runGraphMetricPlannedWorkerStep("hits_authority", metrics[0], "worker-a");
        try std.testing.expectEqual(expected_phase, step.phase);
        try std.testing.expect(step.claimed_page);
        try std.testing.expect(step.completed_page);
        try std.testing.expect(step.advanced_phase);
    }
    const publish = try graph.runGraphMetricPlannedWorkerStep("hits_authority", metrics[0], "worker-a");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.publish_generation, publish.phase);
    try std.testing.expect(publish.advanced_phase);

    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const job = try graph.metricBuildJob(&txn, "hits_authority") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.cleanup_old_generations, job.phase);
        try std.testing.expectEqual(active_job.job_id, job.job_id);
        const hub_raw_cleanup = try graph.metricBuildPage(&txn, "hits_authority", active_job.job_id, .cleanup_old_generations, 0, 0) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageRangeKind.job_control, hub_raw_cleanup.range_kind);
        try std.testing.expect(hub_raw_cleanup.output_prefix.len > 0);
        const summary_cleanup = try graph.metricBuildPage(&txn, "hits_authority", active_job.job_id, .cleanup_old_generations, 0, 1) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageRangeKind.job_control, summary_cleanup.range_kind);
        try std.testing.expect(summary_cleanup.output_prefix.len > 0);
        const rank_cleanup = try graph.metricBuildPage(&txn, "hits_authority", active_job.job_id, .cleanup_old_generations, 0, 2) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageRangeKind.job_control, rank_cleanup.range_kind);
        try std.testing.expect(rank_cleanup.output_prefix.len > 0);
        const final_cleanup = try graph.metricBuildPage(&txn, "hits_authority", active_job.job_id, .cleanup_old_generations, 0, 3) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageRangeKind.job_control, final_cleanup.range_kind);
        try std.testing.expect(final_cleanup.output_prefix.len > 0);
        try std.testing.expect(!std.mem.eql(u8, hub_raw_cleanup.output_prefix, summary_cleanup.output_prefix));
        try std.testing.expect(!std.mem.eql(u8, summary_cleanup.output_prefix, rank_cleanup.output_prefix));
        try std.testing.expect(!std.mem.eql(u8, rank_cleanup.output_prefix, final_cleanup.output_prefix));
        try std.testing.expect((try graph.metricBuildPage(&txn, "hits_authority", active_job.job_id, .cleanup_old_generations, 0, 4)) == null);
    }

    const visible_authorities = try graph.graphMetricTopK("hits_authority", 10);
    defer {
        for (visible_authorities) |*score| score.deinit(alloc);
        alloc.free(visible_authorities);
    }
    const visible_hubs = try graph.graphMetricTopK("hits_hub", 10);
    defer {
        for (visible_hubs) |*score| score.deinit(alloc);
        alloc.free(visible_hubs);
    }
    try std.testing.expectEqual(@as(usize, 3), visible_authorities.len);
    try std.testing.expectEqual(@as(usize, 3), visible_hubs.len);

    const abandoned_hub_attempt_key = try graph.graphMetricBuildAttemptHitsHubRawKeyAlloc("hits_authority", active_job.job_id, .hits_hub_contributions, 0, 999, 1, "doc-hub-abandoned");
    defer alloc.free(abandoned_hub_attempt_key);
    {
        var batch = try graph.beginWriteReverseBatch();
        errdefer batch.abort();
        try GraphIndex.putF64(&batch, abandoned_hub_attempt_key, 123.0);
        for (0..graph_metric_build_cleanup_delete_page_units + 6) |i| {
            var node_buf: [64]u8 = undefined;
            const node = try std.fmt.bufPrint(&node_buf, "cleanup-extra-{d:0>3}", .{i});
            const key = try graph.graphMetricBuildHitsHubRawKeyAlloc("hits_authority", active_job.job_id, 99, node);
            defer alloc.free(key);
            try GraphIndex.putF64(&batch, key, 1.0);
        }
        try graph.putHitsHubRawSummaryInBatch(&batch, "hits_authority", active_job.job_id, 99, .{
            .count = 1,
            .norm = 1.0,
            .raw_fingerprint = 123,
            .fingerprint = 456,
        });
        const rank_key = try graph.graphMetricBuildHitsRankKeyAlloc("hits_authority", active_job.job_id, "authority", 99, "cleanup-rank-extra");
        defer alloc.free(rank_key);
        try GraphIndex.putF64(&batch, rank_key, 1.0);
        try batch.commit();
    }

    const first_cleanup = try graph.runGraphMetricPlannedWorkerStep("hits_authority", metrics[0], "worker-clean");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.cleanup_old_generations, first_cleanup.phase);
    try std.testing.expect(first_cleanup.claimed_page);
    try std.testing.expect(!first_cleanup.completed_page);
    try std.testing.expect(!first_cleanup.published);
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const cleanup_page = try graph.metricBuildPage(&txn, "hits_authority", active_job.job_id, .cleanup_old_generations, 0, first_cleanup.page_id) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.leased, cleanup_page.state);
        try std.testing.expect(cleanup_page.cursor.len > 0);
        try std.testing.expect(cleanup_page.completed_units >= graph_metric_build_cleanup_delete_page_units);
        _ = try txn.get(abandoned_hub_attempt_key);
        const job = try graph.metricBuildJob(&txn, "hits_authority") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.cleanup_old_generations, job.phase);
        try std.testing.expectEqualStrings(cleanup_page.cursor, job.cursor);
    }

    const visible_after_partial_cleanup = try graph.graphMetricTopK("hits_authority", 10);
    defer {
        for (visible_after_partial_cleanup) |*score| score.deinit(alloc);
        alloc.free(visible_after_partial_cleanup);
    }
    try std.testing.expectEqual(visible_authorities.len, visible_after_partial_cleanup.len);
    for (visible_authorities, visible_after_partial_cleanup) |before, after| {
        try std.testing.expectEqualStrings(before.node, after.node);
        try std.testing.expectApproxEqAbs(before.score, after.score, 0.0000001);
    }
    graph.close();

    graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    const visible_after_reopen = try graph.graphMetricTopK("hits_hub", 10);
    defer {
        for (visible_after_reopen) |*score| score.deinit(alloc);
        alloc.free(visible_after_reopen);
    }
    try std.testing.expectEqual(visible_hubs.len, visible_after_reopen.len);
    for (visible_hubs, visible_after_reopen) |before, after| {
        try std.testing.expectEqualStrings(before.node, after.node);
        try std.testing.expectApproxEqAbs(before.score, after.score, 0.0000001);
    }
    {
        var status = try graph.graphMetricStatus("hits_authority");
        defer status.deinit(alloc);
        try std.testing.expectEqual(GraphIndex.GraphMetricState.building, status.state);
        try std.testing.expectEqual(active_job.job_id, status.build_job_id);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.cleanup_old_generations, status.phase);
    }

    const raw_cleanup = try graph.runGraphMetricPlannedWorkerStep("hits_authority", metrics[0], "worker-clean");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.cleanup_old_generations, raw_cleanup.phase);
    try std.testing.expect(raw_cleanup.claimed_page);
    try std.testing.expect(raw_cleanup.completed_page);
    try std.testing.expect(!raw_cleanup.published);
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const hub_raw_cleanup = try graph.metricBuildPage(&txn, "hits_authority", active_job.job_id, .cleanup_old_generations, 0, raw_cleanup.page_id) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.complete, hub_raw_cleanup.state);
        const hub_raw_prefix = try graph.graphMetricBuildHitsHubRawNamespacePrefixAlloc("hits_authority", active_job.job_id);
        defer alloc.free(hub_raw_prefix);
        var cur = try txn.openCursor();
        defer cur.close();
        const maybe_raw = try cur.seekAtOrAfter(hub_raw_prefix);
        if (maybe_raw) |entry| try std.testing.expect(!std.mem.startsWith(u8, entry.key, hub_raw_prefix));
        const hub_raw_summary_prefix = try graph.graphMetricBuildHitsHubRawSummaryNamespacePrefixAlloc("hits_authority", active_job.job_id);
        defer alloc.free(hub_raw_summary_prefix);
        const maybe_summary_before = try cur.seekAtOrAfter(hub_raw_summary_prefix);
        try std.testing.expect(maybe_summary_before != null and std.mem.startsWith(u8, maybe_summary_before.?.key, hub_raw_summary_prefix));
    }

    const summary_cleanup = try graph.runGraphMetricPlannedWorkerStep("hits_authority", metrics[0], "worker-clean-summary");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.cleanup_old_generations, summary_cleanup.phase);
    try std.testing.expect(summary_cleanup.claimed_page);
    try std.testing.expect(summary_cleanup.completed_page);
    try std.testing.expect(!summary_cleanup.published);
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const hub_raw_summary_cleanup = try graph.metricBuildPage(&txn, "hits_authority", active_job.job_id, .cleanup_old_generations, 0, summary_cleanup.page_id) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.complete, hub_raw_summary_cleanup.state);
        const hub_raw_summary_prefix = try graph.graphMetricBuildHitsHubRawSummaryNamespacePrefixAlloc("hits_authority", active_job.job_id);
        defer alloc.free(hub_raw_summary_prefix);
        var cur = try txn.openCursor();
        defer cur.close();
        const maybe_summary = try cur.seekAtOrAfter(hub_raw_summary_prefix);
        if (maybe_summary) |entry| try std.testing.expect(!std.mem.startsWith(u8, entry.key, hub_raw_summary_prefix));
        const hits_rank_prefix = try graph.graphMetricBuildHitsRankNamespacePrefixAlloc("hits_authority", active_job.job_id);
        defer alloc.free(hits_rank_prefix);
        const maybe_rank_before = try cur.seekAtOrAfter(hits_rank_prefix);
        try std.testing.expect(maybe_rank_before != null and std.mem.startsWith(u8, maybe_rank_before.?.key, hits_rank_prefix));
    }

    const rank_cleanup = try graph.runGraphMetricPlannedWorkerStep("hits_authority", metrics[0], "worker-clean-rank");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.cleanup_old_generations, rank_cleanup.phase);
    try std.testing.expect(rank_cleanup.claimed_page);
    try std.testing.expect(rank_cleanup.completed_page);
    try std.testing.expect(!rank_cleanup.published);
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const hits_rank_cleanup = try graph.metricBuildPage(&txn, "hits_authority", active_job.job_id, .cleanup_old_generations, 0, rank_cleanup.page_id) orelse return error.TestExpectedGraphMetricBuildPage;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPageState.complete, hits_rank_cleanup.state);
        const hits_rank_prefix = try graph.graphMetricBuildHitsRankNamespacePrefixAlloc("hits_authority", active_job.job_id);
        defer alloc.free(hits_rank_prefix);
        var cur = try txn.openCursor();
        defer cur.close();
        const maybe_rank = try cur.seekAtOrAfter(hits_rank_prefix);
        if (maybe_rank) |entry| try std.testing.expect(!std.mem.startsWith(u8, entry.key, hits_rank_prefix));
    }

    const final_cleanup = try graph.runGraphMetricPlannedWorkerStep("hits_authority", metrics[0], "worker-clean-final");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.cleanup_old_generations, final_cleanup.phase);
    try std.testing.expect(final_cleanup.claimed_page);
    try std.testing.expect(final_cleanup.completed_page);
    try std.testing.expect(final_cleanup.published);
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const completed_job = try graph.metricBuildJob(&txn, "hits_authority") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.complete, completed_job.phase);
        try std.testing.expect((try graph.metricBuildLease(&txn, "hits_authority")) == null);
        try std.testing.expect((try graph.metricBuildManifest(&txn, "hits_authority", active_job.job_id)) == null);
        try std.testing.expectError(error.NotFound, txn.get(abandoned_hub_attempt_key));
    }

    var final_authority = try graph.graphMetricStatus("hits_authority");
    defer final_authority.deinit(alloc);
    var final_hub = try graph.graphMetricStatus("hits_hub");
    defer final_hub.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.fresh, final_authority.state);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.fresh, final_hub.state);
    try std.testing.expectEqual(final_authority.published_generation, final_hub.published_generation);
}

test "graph hits failed planned build preserves prior published pair" {
    const alloc = std.testing.allocator;
    var store_buf: [256]u8 = undefined;
    const store_path = tmpPath(&store_buf, "store-hits-planned-failure-preserves-pair");
    defer cleanupTmp(store_path);
    var rev_buf: [256]u8 = undefined;
    const rev_path = tmpPath(&rev_buf, "rev-hits-planned-failure-preserves-pair");
    defer cleanupTmp(rev_path);

    var store = try docstore.DocStore.open(alloc, store_path, .{});
    defer store.close();
    const metrics = [_]GraphMetricConfig{
        .{
            .name = "hits_authority",
            .kind = .hits_authority,
            .refresh = .manual,
            .max_iterations = 2,
            .tolerance = 0.000001,
        },
        .{
            .name = "hits_hub",
            .kind = .hits_hub,
            .refresh = .manual,
            .max_iterations = 2,
            .tolerance = 0.000001,
        },
    };
    var graph = try GraphIndex.open(alloc, &store, rev_path, "links", .{ .metric_configs = &metrics });
    defer graph.close();

    try graph.addEdge("doc-hub-a", "doc-authority", "cites", 1.0, 0, 0, "");
    try graph.addEdge("doc-hub-b", "doc-authority", "cites", 1.0, 0, 0, "");
    try graph.addEdge("doc-authority", "doc-authority", "cites", 1.0, 0, 0, "");

    var published = try graph.runHitsMetricPlanned("hits_authority");
    defer published.deinit(alloc);
    var published_hub = try graph.graphMetricStatus("hits_hub");
    defer published_hub.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.fresh, published.state);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.fresh, published_hub.state);
    try std.testing.expectEqual(published.published_generation, published_hub.published_generation);
    const published_generation = published.published_generation;

    const before_authorities = try graph.graphMetricTopK("hits_authority", 10);
    defer {
        for (before_authorities) |*score| score.deinit(alloc);
        alloc.free(before_authorities);
    }
    const before_hubs = try graph.graphMetricTopK("hits_hub", 10);
    defer {
        for (before_hubs) |*score| score.deinit(alloc);
        alloc.free(before_hubs);
    }
    try std.testing.expectEqual(@as(usize, 3), before_authorities.len);
    try std.testing.expectEqual(@as(usize, 3), before_hubs.len);

    try graph.addEdge("doc-new-hub", "doc-authority", "cites", 1.0, 0, 0, "");
    const rebuilding_generation = graph.edge_generation;
    try std.testing.expect(rebuilding_generation > published_generation);
    var building = try graph.ensureGraphMetricPlannedBuild("hits_authority", rebuilding_generation);
    defer building.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.building, building.state);
    try std.testing.expectEqual(rebuilding_generation, building.building_generation);

    const prepare = try graph.runGraphMetricPlannedWorkerPageStepForMetric("hits_authority", "worker-a");
    try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.prepare_generation, prepare.phase);
    try std.testing.expect(prepare.claimed_page);
    try std.testing.expect(prepare.completed_page);
    try std.testing.expect(!prepare.advanced_phase);

    var job_id: u64 = 0;
    var score_generation: u64 = 0;
    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const job = try graph.metricBuildJob(&txn, "hits_authority") orelse return error.TestExpectedGraphMetricBuildJob;
        job_id = job.job_id;
        score_generation = job.score_generation;
        try std.testing.expectEqual(building.build_job_id, job.job_id);
        try std.testing.expectEqual(rebuilding_generation, job.target_generation);
        try std.testing.expectEqual(GraphIndex.GraphMetricBuildPhase.prepare_generation, job.phase);
        _ = try graph.metricBuildManifest(&txn, "hits_authority", job_id) orelse return error.TestExpectedGraphMetricBuildManifest;
    }

    var failed_authority = try graph.failGraphMetricPlannedBuild("hits_authority", error.InvalidGraphMetricScore);
    defer failed_authority.deinit(alloc);
    var failed_hub = try graph.graphMetricStatus("hits_hub");
    defer failed_hub.deinit(alloc);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.failed, failed_authority.state);
    try std.testing.expectEqual(GraphIndex.GraphMetricState.failed, failed_hub.state);
    try std.testing.expectEqual(published_generation, failed_authority.published_generation);
    try std.testing.expectEqual(published_generation, failed_hub.published_generation);
    try std.testing.expectEqual(@as(u64, 0), failed_authority.build_job_id);
    try std.testing.expectEqual(@as(u64, 0), failed_hub.build_job_id);
    try std.testing.expectEqual(@as(u64, 1), failed_authority.retry_count);
    try std.testing.expectEqual(@as(u64, 1), failed_hub.retry_count);
    try std.testing.expectEqualStrings("InvalidGraphMetricScore", failed_authority.last_error);
    try std.testing.expectEqualStrings("InvalidGraphMetricScore", failed_hub.last_error);
    try std.testing.expectEqual(@as(usize, 1), failed_authority.recent_failures.len);
    try std.testing.expectEqual(@as(usize, 1), failed_hub.recent_failures.len);
    try std.testing.expectEqual(job_id, failed_authority.recent_failures[0].job_id);
    try std.testing.expectEqual(job_id, failed_hub.recent_failures[0].job_id);

    const after_authorities = try graph.graphMetricTopK("hits_authority", 10);
    defer {
        for (after_authorities) |*score| score.deinit(alloc);
        alloc.free(after_authorities);
    }
    const after_hubs = try graph.graphMetricTopK("hits_hub", 10);
    defer {
        for (after_hubs) |*score| score.deinit(alloc);
        alloc.free(after_hubs);
    }
    try std.testing.expectEqual(before_authorities.len, after_authorities.len);
    for (before_authorities, after_authorities) |before, after| {
        try std.testing.expectEqualStrings(before.node, after.node);
        try std.testing.expectApproxEqAbs(before.score, after.score, 0.0000001);
        try std.testing.expect(!std.mem.eql(u8, after.node, "doc-new-hub"));
    }
    try std.testing.expectEqual(before_hubs.len, after_hubs.len);
    for (before_hubs, after_hubs) |before, after| {
        try std.testing.expectEqualStrings(before.node, after.node);
        try std.testing.expectApproxEqAbs(before.score, after.score, 0.0000001);
        try std.testing.expect(!std.mem.eql(u8, after.node, "doc-new-hub"));
    }

    {
        var txn = try graph.beginReadReverseTxn();
        defer txn.abort();
        const failed_job = try graph.metricBuildJob(&txn, "hits_authority") orelse return error.TestExpectedGraphMetricBuildJob;
        try std.testing.expectEqual(job_id, failed_job.job_id);
        try std.testing.expectEqual(@as(u64, 1), failed_job.retry_count);
        try std.testing.expectEqualStrings("InvalidGraphMetricScore", failed_job.last_error);
        try std.testing.expect((try graph.metricBuildManifest(&txn, "hits_authority", job_id)) == null);
        try std.testing.expectEqual(@as(usize, 0), try graph.countGraphMetricScoreGeneration("hits_authority", score_generation));
        try std.testing.expectEqual(@as(usize, 0), try graph.countGraphMetricScoreGeneration("hits_hub", score_generation));
    }

    try std.testing.expectError(error.GraphMetricBuildNotActive, graph.failGraphMetricPlannedBuild("hits_authority", error.InvalidGraphMetricScore));
}

